    \end{align*}

steps.text:
Suppose for contradiction that $\bm{y} \neq \bm{y}^\prime$. Then there exists a smallest index $k \in \mathrm{domain}(\bm{x})$ such that
    \begin{align*}
        \bm{y}(k) \neq \bm{y}^\prime(k).
    \end{align*}
    By totality, either $\bm{y}(k) \prec \bm{y}^\prime(k)$ or $\bm{y}^\prime(k) \prec \bm{y}(k)$. Swapping the roles of $\bm{y}$ and $\bm{y}^\prime$ if necessary, we may assume that
    \begin{align*}
        \bm{y}(k) \prec \bm{y}^\prime(k).
    \end{align*}
    Since $\bm{y}$ and $\bm{y}^\prime$ contain the same entries with the same multiplicities, and since by minimality of $k$ they agree on $\{1,\dots,k-1\}$, their entries on $\{k,\dots,\ell(\bm{x})\}$ coincide as multisets. Hence there exists an index $m \geq k$, and in fact $m > k$ because $\bm{y}^\prime(k) \neq \bm{y}(k)$, such that
    \begin{align*}
        \bm{y}^\prime(m) = \bm{y}(k).
    \end{align*}
    However, $\bm{y}^\prime$ is sorted, so $k < m$ implies
    \begin{align*}
        \bm{y}^\prime(k) \preceq \bm{y}^\prime(m) = \bm{y}(k),
    \end{align*}
    contradicting $\bm{y}(k) \prec \bm{y}^\prime(k)$. Hence $\bm{y} = \bm{y}^\prime$. Since $\bm{x}$ was arbitrary, the sorting map is unique.

proof.text:
Existence follows from Corollary~\ref{thm:sorting-exists}. To prove uniqueness, let $\varsigma,\varsigma^\prime:\mathscr{T}(X)\to \mathscr{S}(X,\preceq)$ be sorting maps and fix $\bm{x}\in\mathscr{T}(X)$. Set
    \begin{align*}
        \bm{y} = \varsigma(\bm{x})
        \qquad \text{and} \qquad
        \bm{y}^\prime = \varsigma^\prime(\bm{x}).
    \end{align*}
    Both $\bm{y}$ and $\bm{y}^\prime$ are sorted tuples obtained from $\bm{x}$ by permutations, so they have the same length and the same entries, counted with multiplicity.

    Suppose for contradiction that $\bm{y} \neq \bm{y}^\prime$. Then there exists a smallest index $k \in \mathrm{domain}(\bm{x})$ such that
    \begin{align*}
        \bm{y}(k) \neq \bm{y}^\prime(k).
    \end{align*}
    By totality, either $\bm{y}(k) \prec \bm{y}^\prime(k)$ or $\bm{y}^\prime(k) \prec \bm{y}(k)$. Swapping the roles of $\bm{y}$ and $\bm{y}^\prime$ if necessary, we may assume that
    \begin{align*}
        \bm{y}(k) \prec \bm{y}^\prime(k).
    \end{align*}
    Since $\bm{y}$ and $\bm{y}^\prime$ contain the same entries with the same multiplicities, and since by minimality of $k$ they agree on $\{1,\dots,k-1\}$, their entries on $\{k,\dots,\ell(\bm{x})\}$ coincide as multisets. Hence there exists an index $m \geq k$, and in fact $m > k$ because $\bm{y}^\prime(k) \neq \bm{y}(k)$, such that
    \begin{align*}
        \bm{y}^\prime(m) = \bm{y}(k).
    \end{align*}
    However, $\bm{y}^\prime$ is sorted, so $k < m$ implies
    \begin{align*}
        \bm{y}^\prime(k) \preceq \bm{y}^\prime(m) = \bm{y}(k),
    \end{align*}
    contradicting $\bm{y}(k) \prec \bm{y}^\prime(k)$. Hence $\bm{y} = \bm{y}^\prime$. Since $\bm{x}$ was arbitrary, the sorting map is unique.

    For $\bm{x}\in \mathscr{S}(X,\preceq)$, the identity permutation already sorts $\bm{x}$, so the argument above gives $\varsigma(\bm{x}) = \bm{x}$; that is, $\varsigma$ acts as the identity on $\mathscr{S}(X,\preceq)$, and hence $\varsigma\circ\varsigma = \varsigma$.

    Finally, let $\rho:\mathrm{domain}(\bm{x})\to\mathrm{domain}(\bm{x})$ be a bijection. Then $\varsigma(\bm{x}\circ\rho)$ and $\varsigma(\bm{x})$ are both sorted tuples obtained from $\bm{x}$ by permutations, and the argument above shows that two such tuples coincide; hence $\varsigma(\bm{x}\circ\rho)=\varsigma(\bm{x})$.

results.statement:
\label{thm:tuple-space-metrisation}\index{tuple Hausdorff metric}
    Let $(X,d)$ be a metric space, $(\mathscr{L}(X), d_H^\ast)$ be the metric space of labelled finite sets over $X$, and let $\mathscr{d}_H:\mathscr{T}(X)\times\mathscr{T}(X) \to [0,\infty]$ be defined by
    \begin{align*}
        &\mathscr{d}_H(\bm{x}, \bm{x}^\prime) = d_H^\ast(\Gamma(\bm{x}), \Gamma(\bm{x}^\prime)),
    \end{align*}
    where $d_H^\ast$ is the metric on $\mathscr{L}(X)$ from Theorem~\ref{thm:labelled-properties} and $\Gamma$ is the graph map. Then $(\mathscr{T}(X), \mathscr{d}_H)$ is a metric space.

steps.text:
We show properties \eqref{eq:tuple-length} and \eqref{eq:tuple-collapse} in tandem. The claims are trivial if one of the tuples is empty; the distance is either $0$ if both tuples are empty or $\infty$ otherwise. Therefore, assume that $\bm{x},\bm{y}\in\mathscr{T}(X)$ are non-empty tuples. Then, by definition  
    \begin{align*}
        \mathscr{d}_H(\bm{x},\bm{y})
        &= \max\left(
        \begin{aligned}
            &\max_{(i,x) \in \Gamma(\bm{x})}
            \min_{(j,y) \in \Gamma(\bm{y})} \bigl(|i-j| + d(x,y)\bigr),\\
            &\max_{(j,y) \in \Gamma(\bm{y})}
            \min_{(i,x) \in \Gamma(\bm{x})} \bigl(|j-i| + d(y,x)\bigr)
        \end{aligned}
        \right)
    \end{align*}
    Note that
    \begin{align*}
        \mathscr{d}_H(\bm{x},\bm{y}) < 1, 
    \end{align*}
    implies that 
    \begin{align}\label{eq:bounded-by-one}
        \max_{(i,x) \in \Gamma(\bm{x})} \min_{(j,y) \in \Gamma(\bm{y})} \bigl(|i-j| + d(x,y)\bigr) < 1,
    \end{align}
    and
    \begin{align*}
        \max_{(j,y) \in \Gamma(\bm{y})} \min_{(i,x) \in \Gamma(\bm{x})} \bigl(|j-i| + d(y,x)\bigr) < 1.
    \end{align*}
    For natural numbers $i,j\in \mathbb{N}$, $|i-j| < 1$ implies $i = j$. If $\ell(\bm{x}) \neq \ell(\bm{y})$, assume without loss of generality that $\ell(\bm{x}) > \ell(\bm{y})$; then for $i = \ell(\bm{x})$, every $(j,y) \in \Gamma(\bm{y})$ satisfies
    \begin{align*}
        |i-j| + d(\bm{x}(i), y) \geq |i-j| \geq 1,
    \end{align*}
    and hence $\ell(\bm{x}) \neq \ell(\bm{y})$ implies that $\mathscr{d}_H(\bm{x},\bm{y}) \geq 1$. By contraposition, the claim follows. Moreover, by \eqref{eq:bounded-by-one}, each inner minimum is at most $\mathscr{d}_H(\bm{x},\bm{y}) < 1$, and every $j \neq i$ contributes at least $1$, so the minimum is attained at $j = i$. For each index $i$, the graph contains exactly the point $(i,\bm{x}(i))$; the same-index point of the other graph is $(i,\bm{y}(i))$. Hence,
    \begin{align*}
        &\max_{(i,x) \in \Gamma(\bm{x})} \min_{(j,y) \in \Gamma(\bm{y})} \bigl(|i-j| + d(x,y)\bigr) < 1 \implies \\
        &\max_{(i,x) \in \Gamma(\bm{x})} \min_{(j,y) \in \Gamma(\bm{y})} \bigl(|i-j| + d(x,y)\bigr) = \max_{i \in \{1,\dots, n\}} d(\bm{x}(i),\bm{y}(i)) < 1,
    \end{align*}
    where $n = \ell(\bm{x}) = \ell(\bm{y})$. A similar argument shows that 
    \begin{align*}
        &\max_{(j,y) \in \Gamma(\bm{y})} \min_{(i,x) \in \Gamma(\bm{x})} \bigl(|j-i| + d(y,x)\bigr) < 1 \implies\\
        &\max_{(j,y) \in \Gamma(\bm{y})} \min_{(i,x) \in \Gamma(\bm{x})} \bigl(|j-i| + d(y,x)\bigr) = \max_{i \in \{1,\dots, n\}} d(\bm{x}(i),\bm{y}(i)) < 1,
    \end{align*}
    which proves the claims \eqref{eq:tuple-length} and \eqref{eq:tuple-collapse}, except the final inequality of \eqref{eq:tuple-collapse}. For the latter, if $\ell(\bm{x}) = \ell(\bm{y}) > 0$, taking $j = i$ in each inner minimum bounds both terms of $\mathscr{d}_H(\bm{x},\bm{y})$ by $\max_{i} d(\bm{x}(i),\bm{y}(i))$.

To prove \eqref{eq:tuple-complete}, let $(\bm{x}_n)_{n\in\mathbb{N}}$ be a Cauchy sequence in $\mathscr{T}(X)$. That is, for every $\varepsilon > 0$ there exists an $N\in\mathbb{N}$ such that 
    \begin{align*}
        m,n\geq N \implies \mathscr{d}_H(\bm{x}_m, \bm{x}_n) < \varepsilon.
    \end{align*}
    In particular, there is $N_0 \in \mathbb{N}$ such that
    \begin{align*}
        m,n\geq N_0 \implies \mathscr{d}_H(\bm{x}_m, \bm{x}_n) < 1, 
    \end{align*}
    and notice that by \eqref{eq:tuple-length} we have that $n \geq N_0$ implies $\ell(\bm{x}_n) = k \in \mathbb{N}_0$. If $k=0$, then the tail of the sequence is constantly the empty tuple and hence converges. Assume therefore that $k>0$. By \eqref{eq:tuple-collapse} it follows that
    \begin{align*}
        \mathscr{d}_H(\bm{x}_m, \bm{x}_n) < 1 \implies \mathscr{d}_H(\bm{x}_m, \bm{x}_n) = \max_{i \in \{1,\dots, k\}} d(\bm{x}_m(i),\bm{x}_n(i)).
    \end{align*}
    The sequence $(\bm{x}_n)_{n = N_0}^\infty$ is Cauchy in $(X^k,d_\infty^{(k)})$, with $d_\infty^{(k)}(\bm{x},\bm{y}) = \max_{i} d(\bm{x}(i),\bm{y}(i))$, which is complete and hence has a limit $\bm{x} \in (X^k, d_\infty^{(k)})$. Since $X^k \subseteq \mathscr{T}(X)$, we have $\bm{x} \in \mathscr{T}(X)$. By the final inequality of \eqref{eq:tuple-collapse}, $\mathscr{d}_H(\bm{x}_n,\bm{x}) \leq d_\infty^{(k)}(\bm{x}_n,\bm{x})$, so $\bm{x}_n$ converges to $\bm{x} \in \mathscr{T}(X)$, as desired.

If $(X,d)$ is separable, then so is $(\mathscr{L}(X), d_H^\ast)$ by Theorem~\ref{thm:labelled-properties}. Since
    \begin{align*}
        \Gamma(\mathscr{T}(X)) \subseteq \mathscr{L}(X),
    \end{align*}
    $(\Gamma(\mathscr{T}(X)),d_H^\ast)$ is separable, as it is a subset of a separable metric space. As $\Gamma:(\mathscr{T}(X),\mathscr{d}_H) \to (\Gamma(\mathscr{T}(X)),d_H^\ast)$ is a bijective isometry, $(\mathscr{T}(X),\mathscr{d}_H)$ is separable as well.

