        &\max_{(j,y) \in \Gamma(\bm{y})} \min_{(i,x) \in \Gamma(\bm{x})} \bigl(|j-i| + d(y,x)\bigr) = \max_{i \in \{1,\dots, n\}} d(\bm{x}(i),\bm{y}(i)) < 1,
    \end{align*}
    which proves the claims \eqref{eq:tuple-length} and \eqref{eq:tuple-collapse}, except the final inequality of \eqref{eq:tuple-collapse}. For the latter, if $\ell(\bm{x}) = \ell(\bm{y}) > 0$, taking $j = i$ in each inner minimum bounds both terms of $\mathscr{d}_H(\bm{x},\bm{y})$ by $\max_{i} d(\bm{x}(i),\bm{y}(i))$.

    To prove \eqref{eq:tuple-complete}, let $(\bm{x}_n)_{n\in\mathbb{N}}$ be a Cauchy sequence in $\mathscr{T}(X)$. That is, for every $\varepsilon > 0$ there exists an $N\in\mathbb{N}$ such that 
    \begin{align*}
        m,n\geq N \implies \mathscr{d}_H(\bm{x}_m, \bm{x}_n) < \varepsilon.
    \end{align*}
    In particular, there is $N_0 \in \mathbb{N}$ such that
    \begin{align*}
        m,n\geq N_0 \implies \mathscr{d}_H(\bm{x}_m, \bm{x}_n) < 1, 
    \end{align*}
    and notice that by \eqref{eq:tuple-length} we have that $n \geq N_0$ implies $\ell(\bm{x}_n) = k \in \mathbb{N}_0$. If $k=0$, then the tail of the sequence is constantly the empty tuple and hence converges. Assume therefore that $k>0$. By \eqref{eq:tuple-collapse} it follows that
    \begin{align*}
        \mathscr{d}_H(\bm{x}_m, \bm{x}_n) < 1 \implies \mathscr{d}_H(\bm{x}_m, \bm{x}_n) = \max_{i \in \{1,\dots, k\}} d(\bm{x}_m(i),\bm{x}_n(i)).
    \end{align*}
    The sequence $(\bm{x}_n)_{n = N_0}^\infty$ is Cauchy in $(X^k,d_\infty^{(k)})$, with $d_\infty^{(k)}(\bm{x},\bm{y}) = \max_{i} d(\bm{x}(i),\bm{y}(i))$, which is complete and hence has a limit $\bm{x} \in (X^k, d_\infty^{(k)})$. Since $X^k \subseteq \mathscr{T}(X)$, we have $\bm{x} \in \mathscr{T}(X)$. By the final inequality of \eqref{eq:tuple-collapse}, $\mathscr{d}_H(\bm{x}_n,\bm{x}) \leq d_\infty^{(k)}(\bm{x}_n,\bm{x})$, so $\bm{x}_n$ converges to $\bm{x} \in \mathscr{T}(X)$, as desired.

    For \eqref{eq:tuple-separable} and \eqref{eq:sorted-tuple-separable}, it remains to show that $(\mathscr{T}(X), \mathscr{d}_H)$ is separable, provided $(X,d)$ is separable; if $(X, \preceq, d)$ is a partially ordered metric space, then $\mathscr{S}(X,\preceq) \subseteq \mathscr{T}(X)$ and if $\mathscr{T}(X)$ is separable, then $\mathscr{S}(X,\preceq)$ will also be separable, since metric subspaces of separable metric spaces are separable.

    If $(X,d)$ is separable, then so is $(\mathscr{L}(X), d_H^\ast)$ by Theorem~\ref{thm:labelled-properties}. Since
    \begin{align*}
        \Gamma(\mathscr{T}(X)) \subseteq \mathscr{L}(X),
    \end{align*}
    $(\Gamma(\mathscr{T}(X)),d_H^\ast)$ is separable, as it is a subset of a separable metric space. As $\Gamma:(\mathscr{T}(X),\mathscr{d}_H) \to (\Gamma(\mathscr{T}(X)),d_H^\ast)$ is a bijective isometry, $(\mathscr{T}(X),\mathscr{d}_H)$ is separable as well.

results.statement:
\label{thm:tuple-space-properties}\index{tuple space!metrisation}
    Let $(X,d)$ be a metric space. Then, for every $\bm{x}, \bm{x}^\prime \in \mathscr{T}(X)$ it holds that
    \begin{enumerate}[(i)]
        \item $\mathscr{d}_H(\bm{x}, \bm{x}^\prime) < 1$ implies $\ell(\bm{x}) = \ell(\bm{x}^\prime)$. \label{eq:tuple-length}
        \item $\mathscr{d}_H(\bm{x}, \bm{x}^\prime) < 1$ and $\ell(\bm{x}) > 0$ implies $\mathscr{d}_H(\bm{x},\bm{x}^\prime) = \max_{i\in\{1,\dots, \ell(\bm{x})\}} d(\bm{x}(i), \bm{x}^\prime(i))$; without the restriction $\mathscr{d}_H(\bm{x},\bm{x}^\prime) < 1$, $\ell(\bm{x}) = \ell(\bm{x}^\prime) > 0$ implies $\mathscr{d}_H(\bm{x},\bm{x}^\prime) \leq \max_{i\in\{1,\dots, \ell(\bm{x})\}} d(\bm{x}(i), \bm{x}^\prime(i))$. \label{eq:tuple-collapse}
    \end{enumerate}
    Moreover:
    \begin{enumerate}[(i)]
        \setcounter{enumi}{2}
        \item if $(X,d)$ is a complete metric space, then $(\mathscr{T}(X),\mathscr{d}_H)$ is a complete metric space; \label{eq:tuple-complete}
        \item if $(X,d)$ is a separable metric space, then $(\mathscr{T}(X),\mathscr{d}_H)$ is a separable metric space;\label{eq:tuple-separable}
        \item if $(X,d)$ is a separable metric space and $\preceq$ is any partial order on $X$, then $(\mathscr{S}(X, \preceq),\mathscr{d}_H)$ is a separable metric subspace of $(\mathscr{T}(X),\mathscr{d}_H)$. \label{eq:sorted-tuple-separable}
    \end{enumerate}

\label{cor:tuple-metrisation}
    Let $(X,d)$ be a metric space, and let $\mathscr{T}(X)$ be the associated tuple space. Define the mapping $\mathscr{d}_\infty : \mathscr{T}(X) \times \mathscr{T}(X) \to [0,\infty]$ by 
    \begin{align*}
        \mathscr{d}_\infty(\bm{x},\bm{x}^\prime) = \begin{cases}
            0 & \ell(\bm{x}) = \ell(\bm{x}^\prime) = 0\\
            \max_{i \in \{1,\dots, \ell(\bm{x})\}} d(\bm{x}(i), \bm{x}^\prime(i)) & \ell(\bm{x}) = \ell(\bm{x}^\prime) > 0\\
            \infty & \ell(\bm{x})\neq\ell(\bm{x}^\prime). 
        \end{cases}
    \end{align*}
    Then $(\mathscr{T}(X), \mathscr{d}_\infty)$ is a metric space. Moreover, if $(X,d)$ is separable, then $(\mathscr{T}(X), \mathscr{d}_\infty)$ is separable. Similarly, if $(X,d)$ is complete, then $(\mathscr{T}(X), \mathscr{d}_\infty)$ is complete.

\label{prop:truncated-metric-equivalent-topology}\index{truncated metric}
    Let $(X,d)$ be a metric space and let $\bar{d}:X\times X \to [0,1]$ be the metric defined by 
    \begin{align*}
        \bar{d}(x,x^\prime)=\min(d(x,x^\prime), 1).
    \end{align*}
    Then $(X,d)$ and $(X,\bar{d})$ are topologically equivalent.

steps.text:
For property \eqref{property:identity-homeomorphic}, notice that 
    \begin{align*}
        \min(\mathscr{d}_H(\bm{x}, \bm{x}^\prime),1) = \min(\mathscr{d}_\infty(\bm{x},\bm{x}^\prime), 1),
    \end{align*}
    which proves the claim, as the two spaces are consequently topologically equivalent by Proposition~\ref{prop:truncated-metric-equivalent-topology}.

Next, we prove properties \eqref{property:continuous-iff} and \eqref{property:measurable-iff} in tandem. By \eqref{property:identity-homeomorphic}, $\mathscr{d}_H$ and $\mathscr{d}_\infty$ induce the same topology on $\mathscr{T}(X)$, and hence the same continuous maps into $(E,\rho)$ and the same Borel $\sigma$-algebra, which proves both properties. Notice moreover that by construction, one has 
    \begin{align*}
        \mathscr{T}(X) \cong \bigsqcup_{n\in\mathbb{N}_0} X^n,
    \end{align*}
    and in particular the spaces $(\mathscr{T}(X), \mathscr{d}_H)$ and $(\mathscr{T}(X), \mathscr{d}_\infty)$ are homeomorphic to the space $\left(\bigsqcup_{n\in\mathbb{N}_0} X^n, d_\sqcup\right)$, where $d_\sqcup$ is the disjoint-union metric. Indeed, let 
    \begin{align*}
        \zeta :\mathscr{T}(X) \to \bigsqcup_{n\in\mathbb{N}_0} X^n\\
        \zeta(\bm{x}) = (\bm{x}, \ell(\bm{x}));
    \end{align*}
    then $\zeta$ is an isometry from $(\mathscr{T}(X),\mathscr{d}_\infty)$ onto $(\bigsqcup_{n\in\mathbb{N}_0} X^n, d_\sqcup)$ and hence, by \eqref{property:identity-homeomorphic}, a homeomorphism from $(\mathscr{T}(X),\mathscr{d}_H)$ as well, because on each fixed layer it is the identity and the disjoint-union metric separates different layers by distance $\infty$. Properties~\eqref{property:continuous-iff-restricted} and \eqref{property:measurable-iff-restricted} then follow from the pasting lemmas for disjoint unions, Theorems~\ref{thm:pasting-lemma} and~\ref{thm:pasting-lemma-measurable}. By these lemmas, a map on $\bigsqcup_{n\in\mathbb{N}_0} X^n$ is continuous, respectively measurable, if and only if each of its restrictions to the layers is, and composing with $\zeta$ transfers this to $\mathscr{T}(X)$.

proof.text:
For property \eqref{property:identity-homeomorphic}, notice that 
    \begin{align*}
        \min(\mathscr{d}_H(\bm{x}, \bm{x}^\prime),1) = \min(\mathscr{d}_\infty(\bm{x},\bm{x}^\prime), 1),
    \end{align*}
    which proves the claim, as the two spaces are consequently topologically equivalent by Proposition~\ref{prop:truncated-metric-equivalent-topology}. 

    Next, we prove properties \eqref{property:continuous-iff} and \eqref{property:measurable-iff} in tandem. By \eqref{property:identity-homeomorphic}, $\mathscr{d}_H$ and $\mathscr{d}_\infty$ induce the same topology on $\mathscr{T}(X)$, and hence the same continuous maps into $(E,\rho)$ and the same Borel $\sigma$-algebra, which proves both properties. Notice moreover that by construction, one has 
    \begin{align*}
        \mathscr{T}(X) \cong \bigsqcup_{n\in\mathbb{N}_0} X^n,
    \end{align*}
    and in particular the spaces $(\mathscr{T}(X), \mathscr{d}_H)$ and $(\mathscr{T}(X), \mathscr{d}_\infty)$ are homeomorphic to the space $\left(\bigsqcup_{n\in\mathbb{N}_0} X^n, d_\sqcup\right)$, where $d_\sqcup$ is the disjoint-union metric. Indeed, let 
    \begin{align*}
        \zeta :\mathscr{T}(X) \to \bigsqcup_{n\in\mathbb{N}_0} X^n\\
        \zeta(\bm{x}) = (\bm{x}, \ell(\bm{x}));
    \end{align*}
    then $\zeta$ is an isometry from $(\mathscr{T}(X),\mathscr{d}_\infty)$ onto $(\bigsqcup_{n\in\mathbb{N}_0} X^n, d_\sqcup)$ and hence, by \eqref{property:identity-homeomorphic}, a homeomorphism from $(\mathscr{T}(X),\mathscr{d}_H)$ as well, because on each fixed layer it is the identity and the disjoint-union metric separates different layers by distance $\infty$. Properties~\eqref{property:continuous-iff-restricted} and \eqref{property:measurable-iff-restricted} then follow from the pasting lemmas for disjoint unions, Theorems~\ref{thm:pasting-lemma} and~\ref{thm:pasting-lemma-measurable}. By these lemmas, a map on $\bigsqcup_{n\in\mathbb{N}_0} X^n$ is continuous, respectively measurable, if and only if each of its restrictions to the layers is, and composing with $\zeta$ transfers this to $\mathscr{T}(X)$.

    Finally, for property \eqref{property:layers-clopen-borel}, each layer $X^n$ is open, since by Theorem~\ref{thm:tuple-space-properties}\eqref{eq:tuple-length} it is the union of the open balls of radius $1$ about its elements, and closed, since its complement is the union of the other layers. Moreover, $A\subseteq\mathscr{T}(X)$ is Borel if and only if its indicator function $\ind_A:\mathscr{T}(X)\to\mathbb{R}$ is $\mathcal{B}(\mathscr{T}(X))/\mathcal{B}(\mathbb{R})$-measurable, which by \eqref{property:measurable-iff-restricted} holds if and only if each restriction $\ind_A\restriction_{X^n}=\ind_{A\cap X^n}$ is $\mathcal{B}(X^n,d_\infty^{(n)})/\mathcal{B}(\mathbb{R})$-measurable, that is, if and only if $A\cap X^n\in\mathcal{B}(X^n,d_\infty^{(n)})$ for every $n\in\mathbb{N}_0$.

results.statement:
\label{thm:the-standard-machinery}
    Let $(X,d)$ be a metric space, and let $\mathscr{T}(X)$ be the associated tuple space. Let $\mathscr{d}_H:\mathscr{T}(X)\times \mathscr{T}(X) \to [0,\infty]$ be the tuple Hausdorff metric and $\mathscr{d}_\infty$ be the metric defined in Corollary~\ref{cor:tuple-metrisation}. For each $n \in \mathbb{N}_0$, let $X^n \subseteq\mathscr{T}(X)$ be the subset of tuples with length $n$ and let $d_\infty^{(n)}:X^n\times X^n \to [0,\infty]$ be the maximum product metric, with $d_\infty^{(0)}=0$ on the singleton empty layer and $d_\infty^{(n)}(\bm{x}, \bm{x}^\prime) = \max_{i \in \{1,\dots, n\}} d(\bm{x}(i), \bm{x}^\prime(i))$ for $n>0$. Let $(E,\rho)$ be a metric space, with $E$ non-empty, and let $\Sigma \subseteq \wp(E)$ be a $\sigma$-algebra on $E$. Then,
    \begin{enumerate}[(i)]
        \item The identity mapping $\mathrm{id}:(\mathscr{T}(X),\mathscr{d}_H)\to(\mathscr{T}(X),\mathscr{d}_\infty)$ is a homeomorphism. \label{property:identity-homeomorphic}
        \item Any mapping $f:\mathscr{T}(X) \to E$ is continuous from $(\mathscr{T}(X),\mathscr{d}_H)$ into $(E,\rho)$ if and only if it is continuous from $(\mathscr{T}(X),\mathscr{d}_\infty)$ into $(E,\rho)$. \label{property:continuous-iff}
        \item Any mapping $f:\mathscr{T}(X) \to E$ is continuous from $(\mathscr{T}(X), \mathscr{d}_H)$ into $(E,\rho)$ if and only if each restricted map $f\restriction_{X^n}:X^n \to E$ is continuous from $(X^n, d_\infty^{(n)})$ into $(E,\rho)$. \label{property:continuous-iff-restricted}
        \item Any mapping $f:\mathscr{T}(X) \to E$ is $\mathcal{B}(\mathscr{T}(X),\mathscr{d}_H) / \Sigma$-measurable if and only if it is $\mathcal{B}(\mathscr{T}(X),\mathscr{d}_\infty) / \Sigma$-measurable.
        \label{property:measurable-iff}
        \item Any mapping $f:\mathscr{T}(X) \to E$ is $\mathcal{B}(\mathscr{T}(X))/\Sigma$-measurable if and only if, for any $n \in \mathbb{N}_0$, the restricted map $f\restriction_{X^n}:X^n \to E$ is $\mathcal{B}(X^n, d_\infty^{(n)})/\Sigma$-measurable.\label{property:measurable-iff-restricted}
        \item Each layer $X^n$, $n\in\mathbb{N}_0$, is open and closed in $(\mathscr{T}(X),\mathscr{d}_H)$, and a set $A\subseteq\mathscr{T}(X)$ belongs to $\mathcal{B}(\mathscr{T}(X))$ if and only if $A\cap X^n\in\mathcal{B}(X^n,d_\infty^{(n)})$ for every $n\in\mathbb{N}_0$.\label{property:layers-clopen-borel}
    \end{enumerate}

\label{defn:index-comparable}
Let $(X,\preceq)$ be a partially ordered set and let $\bm{x}\in\mathscr{T}(X)$. We define the relation $\overset{\bm{x}}{\leftrightsquigarrow}$ on $\mathrm{domain}(\bm{x})$ by
\begin{align*}
    i \overset{\bm{x}}{\leftrightsquigarrow} j
\iff (\bm{x}(i)\preceq \bm{x}(j))\ \lor\ (\bm{x}(j)\preceq \bm{x}(i)).
\end{align*}

\label{defn:reflexive-transitive-closure}
    Let $X$ be a set and let $R \subseteq X \times X$ be a relation on $X$. Then, the reflexive transitive closure of $R$ is the relation $\overline{R} \subseteq X \times X$ defined by
    \begin{align*}
        \overline{R} = \Delta_X \cup \bigcup_{n\in\mathbb{N}} R^n,
    \end{align*}
    where $R^1 = R$ and $R^{n+1} = R^n \circ R$ for $n \in \mathbb{N}$, and $\Delta_X = \{(x,x) \mid x \in X\}$ is the diagonal relation on $X$.

We define the composition of two relations $R$ and $S$ on $X$ by
    \begin{align*}
        R \circ S = \{(x,z) \in X \times X \mid \exists y \in X: (x,y) \in R \land (y,z) \in S\},
    \end{align*}
    which, unlike composition of functions, is read diagrammatically, first $R$ and then $S$.

steps.text:
Suppose for contradiction that $m \ge |X|$. Then the sequence $x_1, \dots, x_{m+1}$ contains $m + 1 > |X|$ terms in $X$. By the pigeonhole principle, there exist indices $i, j \in \{1, \dots, m+1\}$ with $i < j$ such that $x_i = x_j$. Since $x_1 = x \neq z = x_{m+1}$, we cannot have both $i = 1$ and $j = m+1$. Consequently, omitting the intermediate terms $x_{i+1}, \dots, x_j$ yields a shorter chain
    \begin{align*}
        x = x_1, \dots, x_i, x_{j+1}, \dots, x_{m+1} = z
    \end{align*}
    of length $m^\prime = m - (j - i) \in \{1, \dots, m-1\}$ in which every consecutive pair belongs to $R$. Hence $(x, z) \in R^{m^\prime}$, contradicting the minimality of $m$. Therefore $m \le |X| - 1$, as desired.

results.statement:
\label{prop:transitive-closure-finite}
    Let $X$ be a non-empty finite set and let $R \subseteq X \times X$ be a relation on $X$. Then, 
    \begin{align*}
        \overline{R} = \Delta_X \cup \bigcup_{n=1}^{|X| - 1} R^n.
    \end{align*}

\label{defn:connectivity-relation}
Let $(X,\preceq)$ be a partially ordered set, $\bm{x}\in\mathscr{T}(X)$, and $\overset{\bm{x}}{\leftrightsquigarrow}$ be as in Definition~\ref{defn:index-comparable}. The connectivity relation $\overset{\bm{x}}{\sim}$ on $\mathrm{domain}(\bm{x})$ is the reflexive transitive closure of
$\overset{\bm{x}}{\leftrightsquigarrow}$.

\label{defn:comparability-components}
Let $(X,\preceq)$ be a partially ordered set and let $\bm{x}\in\mathscr{T}(X)$. Let $\mathrm{domain}(\bm{x})/\overset{\bm{x}}{\sim}$ be the set of equivalence classes of $\overset{\bm{x}}{\sim}$ and let $\kappa$ be the cardinality of $\mathrm{domain}(\bm{x})/\overset{\bm{x}}{\sim}$. If $\kappa=0$, there are no comparability components. If $\kappa>0$, let $(C_k)_{k=1}^{\kappa}$ be an enumeration of the equivalence classes ordered by first appearance, that is,
\begin{align*}
k \leq k^\prime \iff \min C_k \leq \min C_{k^\prime}.
\end{align*}
For each $k\in\{1,\dots,\kappa\}$, define a subset of the tuple graph $\Gamma(\bm{x})\subseteq \mathbb{N}\times X$ by
\begin{align*}
K_k = \{(i,\bm{x}(i))\in \Gamma(\bm{x}) \mid i\in C_k\}.
\end{align*}
We call $(K_k)_{k=1}^{\kappa}$ the comparability components of $\bm{x}$ and set
\begin{align*}
\mathcal{K}(\bm{x}) = \{K_k \mid k \in \{1,\dots, \kappa\}\}.
\end{align*}

steps.text:
First, we show (i). We must show that $\bigcup_{k=1}^{\kappa} K_k = \Gamma(\bm{x})$ and that $K_k \cap K_{k^\prime} = \emptyset$ for all $k, k^\prime \in \{1,\dots,\kappa\}$ with $k \neq k^\prime$. By Proposition~\ref{prop:sim-equivalence}, the connectivity relation $\overset{\bm{x}}{\sim}$ is an equivalence relation on $\mathrm{domain}(\bm{x})$, so its equivalence classes $C_1,\dots,C_\kappa$ form a partition of $\mathrm{domain}(\bm{x})$. Consequently,
    \begin{align*}
        \bigcup_{k=1}^{\kappa} K_k
        = \bigcup_{k=1}^{\kappa} \{(i,\bm{x}(i)) \in \Gamma(\bm{x}) \mid i \in C_k\}
        = \left\{(i,\bm{x}(i)) \in \Gamma(\bm{x}) \;\middle|\; i \in \bigcup_{k=1}^{\kappa} C_k\right\}
        = \Gamma(\bm{x}).
    \end{align*}
    Moreover, if $k \neq k^\prime$, then $C_k \cap C_{k^\prime} = \emptyset$, and since the first coordinate of any element in $K_k$ lies in $C_k$, it follows that $K_k \cap K_{k^\prime} = \emptyset$.

proof.text:
If $\bm{x} = \bm{e}$, then $\Gamma(\bm{x}) = \emptyset$ and $\kappa = 0$, so both claims hold vacuously. Suppose therefore that $\ell(\bm{x}) > 0$.

    First, we show (i). We must show that $\bigcup_{k=1}^{\kappa} K_k = \Gamma(\bm{x})$ and that $K_k \cap K_{k^\prime} = \emptyset$ for all $k, k^\prime \in \{1,\dots,\kappa\}$ with $k \neq k^\prime$. By Proposition~\ref{prop:sim-equivalence}, the connectivity relation $\overset{\bm{x}}{\sim}$ is an equivalence relation on $\mathrm{domain}(\bm{x})$, so its equivalence classes $C_1,\dots,C_\kappa$ form a partition of $\mathrm{domain}(\bm{x})$. Consequently,
    \begin{align*}
        \bigcup_{k=1}^{\kappa} K_k
        = \bigcup_{k=1}^{\kappa} \{(i,\bm{x}(i)) \in \Gamma(\bm{x}) \mid i \in C_k\}
        = \left\{(i,\bm{x}(i)) \in \Gamma(\bm{x}) \;\middle|\; i \in \bigcup_{k=1}^{\kappa} C_k\right\}
        = \Gamma(\bm{x}).
    \end{align*}
    Moreover, if $k \neq k^\prime$, then $C_k \cap C_{k^\prime} = \emptyset$, and since the first coordinate of any element in $K_k$ lies in $C_k$, it follows that $K_k \cap K_{k^\prime} = \emptyset$.

    Next, we show (ii). Let $k, k^\prime \in \{1,\dots,\kappa\}$ with $k \neq k^\prime$, and let $(i,\bm{x}(i)) \in K_k$ and $(j,\bm{x}(j)) \in K_{k^\prime}$ be arbitrary. We must show that $\neg(\bm{x}(i) \preceq \bm{x}(j))$ and $\neg(\bm{x}(j) \preceq \bm{x}(i))$. Suppose for contradiction that $\bm{x}(i) \preceq \bm{x}(j)$ or $\bm{x}(j) \preceq \bm{x}(i)$. By Definition~\ref{defn:index-comparable}, this means that $i \overset{\bm{x}}{\leftrightsquigarrow} j$, and hence $i \overset{\bm{x}}{\sim} j$ by Definition~\ref{defn:connectivity-relation}. Since $i \in C_k$ and $j \in C_{k^\prime}$, it follows that $C_k = C_{k^\prime}$, which contradicts $k \neq k^\prime$. Therefore, $\bm{x}(i)$ and $\bm{x}(j)$ are incomparable in $X$, as desired.

results.statement:
\label{prop:components-partition-incomp}
Let $(X,\preceq)$ be a partially ordered set and let $\bm{x}\in\mathscr{T}(X)$ with comparability components
$\mathcal{K}(\bm{x})=\{K_1,\dots,K_\kappa\}$. Then:
\begin{enumerate}[(i)]
\item The family $(K_k)_{k=1}^{\kappa}$ is a partition of the graph of $\bm{x}$, i.e.
\begin{align*}
\Gamma(\bm{x}) = \bigcup_{k=1}^{\kappa} K_k,
\end{align*}
with $K_k \cap K_{k^\prime} = \emptyset$ for all $k\neq k^\prime$.
\item If $k\neq k^\prime$, then for all $(i,\bm{x}(i))\in K_k$ and $(j,\bm{x}(j))\in K_{k^\prime}$ we have that $\bm{x}(i)$ and $\bm{x}(j)$ are incomparable in $X$.
\end{enumerate}

\label{defn:tau}
Let $(X,\preceq)$ be a partially ordered set and let $\bm{x}\in\mathscr{T}(X)$. Define the arrival-index map $\operatorname{arr}_{\bm{x}}:\mathcal{K}(\bm{x})\to\mathbb{N}$ by
\begin{align*}
\operatorname{arr}_{\bm{x}}(K) = \min\{i\in\mathbb{N} \mid (i,\bm{x}(i))\in K\}.
\end{align*}

\label{cor:components-totally-ordered-by-arrival-index}
    Let $(X, \preceq)$ be a partially ordered set and let $\bm{x} \in \mathscr{T}(X)$ be a tuple. Then, the set of comparability components $\mathcal{K}(\bm{x})$ is totally ordered by the relation 
    \begin{align*}
    K \leq K^\prime \iff \operatorname{arr}_{\bm{x}}(K) \leq \operatorname{arr}_{\bm{x}}(K^\prime).
    \end{align*}

steps.text:
Recall that by definition we have 
    \begin{align*}
        \mathscr{L}(X) = \{\xi \in \mathscr{F}(\mathbb{N} \times X) \mid \forall n \in \mathbb{N}: |(\{n\} \times X) \cap \xi| \leq 1\},
    \end{align*}
    which means that for any $n \in \mathbb{N}$, there is at most one element of $\xi$ whose first coordinate is $n$. Therefore, if $(n,x)$ and $(n,y)$ are both in $\xi$, then we must have $x = y$, and hence the restriction of $\Pi_{\mathbb{N}}$ to $\xi$ is injective.

proof.text:
Recall that by definition we have 
    \begin{align*}
        \mathscr{L}(X) = \{\xi \in \mathscr{F}(\mathbb{N} \times X) \mid \forall n \in \mathbb{N}: |(\{n\} \times X) \cap \xi| \leq 1\},
    \end{align*}
    which means that for any $n \in \mathbb{N}$, there is at most one element of $\xi$ whose first coordinate is $n$. Therefore, if $(n,x)$ and $(n,y)$ are both in $\xi$, then we must have $x = y$, and hence the restriction of $\Pi_{\mathbb{N}}$ to $\xi$ is injective.

results.statement:
\label{defn:sorting-finite-sets}
Let $(X,\preceq)$ be a partially ordered set and let $\prec$ denote its strict part. Lift $\prec$ to a strict partial order on $\mathbb{N} \times X$ by defining
\begin{align*}
    (n, x) \prec (m,y) \iff x \prec y.  
\end{align*}
Moreover, let $\mathscr{L}(X)$ be the set of labelled finite sets. Let $\varsigma^\ast : \mathscr{L}(X) \to \mathscr{T}(\mathbb{N} \times X)$ be defined recursively, with $\varsigma^\ast(\emptyset) = \bm{e}$. If $\xi \neq \emptyset$, set $\xi^{(1)} = \xi$ and, for $n \in \{1, \dots, |\xi|\}$, define
\begin{align*}
    M^{(n)} &= \{(i,x) \in \xi^{(n)} \mid \not\exists (j,y) \in \xi^{(n)}: (j,y) \prec  (i,x)\}
\end{align*}
and
\begin{align*}
    \varsigma^\ast(\xi)(n) &= \argmin_{(i,x) \in M^{(n)}} i,
\end{align*}
with 
\begin{align*}
    \xi^{(n+1)} = \xi^{(n)} \setminus \{\varsigma^\ast(\xi)(n)\}.
\end{align*}
The set $M^{(n)}$ is non-empty because every finite non-empty partially ordered set has a minimal element, and the displayed $\argmin$ is taken over the finite non-empty set of natural indices appearing in $M^{(n)}$; it is a single element by Lemma~\ref{lem:labelled-finite-set-natural-projection-injective}. The output is sorted. Indeed, if $p < q$ and $\varsigma^\ast(\xi)(q) \prec \varsigma^\ast(\xi)(p)$, then at step $p$ the element chosen at step $q$ was still available and strictly below the element chosen at step $p$, contradicting the minimality of that choice. We call $\varsigma^\ast$ the sorting map for labelled finite sets. Likewise, let $\Pi_X$ and $\Pi_{\mathbb{N}}$ be the projections onto $X$ and $\mathbb{N}$ respectively. Then define the mapping $\varsigma:\mathscr{L}(X) \to \mathscr{S}(X, \preceq)$ by
\begin{align*}
    \varsigma(\xi)(n) = \Pi_X(\varsigma^\ast(\xi)(n)),
\end{align*}
and likewise, we define the mapping $\pi:\mathscr{L}(X) \to \mathscr{T}(\mathbb{N})$ by
\begin{align*}
    \pi(\xi)(n) = \Pi_{\mathbb{N}}(\varsigma^\ast(\xi)(n)).
\end{align*}

\label{defn:minimum-sorting-rule}\index{minimum sorting map}
    Let $(X, \preceq)$ be a partially ordered set and let $\bm{x} \in \mathscr{T}(X)$ be a tuple. Then, we define the mapping $\varsigma_{\mathrm{min}}:\mathscr{T}(X) \to \mathscr{T}(X)$ by 
    \begin{align*}
        \varsigma_{\mathrm{min}}(\bm{x}) = \begin{cases}
            \bm{e} & \ell(\bm{x}) = 0\\
            \bigoplus_{i = 1}^{|\mathcal{K}(\bm{x})|} \varsigma(K_i) & \ell(\bm{x}) > 0,
        \end{cases}
    \end{align*}
    where $K_i$ is the $i^{\mathrm{th}}$ component in the total order of $\mathcal{K}(\bm{x})$. We call $\varsigma_{\mathrm{min}}$ the minimum sorting map for tuples.

Note that we use 
    \begin{align*}
        \bigoplus_{i = 1}^{j} \bm{x}_i = \bm{x}_1 \oplus \dots \oplus \bm{x}_j,
    \end{align*}
    as a shorthand for the concatenation of the tuples $\bm{x}_1, \dots, \bm{x}_j$, where $\oplus$ is the concatenation operator for tuples ($\bm{x}\oplus\bm{y}$ lists the entries of $\bm{x}$ followed by those of $\bm{y}$; formally, see Definition~\ref{defn:concat-tuple}). Here, the order is important, as the operation is not commutative.

steps.text:
First, note that $\varsigma_{\mathrm{min}}(\bm{e}) = \bm{e}$, which is sorted by definition. Let $\bm{x} \in \mathscr{T}(X)$ with $\ell(\bm{x}) > 0$, and write
    \begin{align*}
        \mathcal{K}(\bm{x}) = \{K_1,\dots,K_\kappa\},
    \end{align*}
    where the components are ordered by first appearance. Since each $K_r$ is a labelled finite set, the tuple $\varsigma(K_r)$ is well-defined by Definition~\ref{defn:sorting-finite-sets}, and so is the concatenation
    \begin{align*}
        \varsigma_{\mathrm{min}}(\bm{x}) = \bigoplus_{r=1}^{\kappa} \varsigma(K_r).
    \end{align*}

It remains to verify the permutation property. For each component $K_r$, the tuple $\pi(K_r)$ produced in Definition~\ref{defn:sorting-finite-sets} lists exactly the indices appearing in $K_r$, in the order used by $\varsigma(K_r)$. In particular, by Lemma~\ref{lem:labelled-finite-set-natural-projection-injective}, $\pi(K_r)$ is a bijection from $\{1,\dots,|K_r|\}$ onto the index set
    \begin{align*}
        I_r = \Pi_{\mathbb{N}}(K_r).
    \end{align*}
    Since the family $\mathcal{K}(\bm{x})$ is a partition of $\Gamma(\bm{x})$, the sets $I_1,\dots,I_\kappa$ form a partition of $\mathrm{domain}(\bm{x})$. Consequently, the concatenation
    \begin{align*}
        \sigma = \bigoplus_{r = 1}^{\kappa} \pi(K_r)
    \end{align*}
    has length $\ell(\bm{x})$ and image $\mathrm{domain}(\bm{x})$. Because the images of the blocks are pairwise disjoint, $\sigma:\mathrm{domain}(\bm{x}) \to \mathrm{domain}(\bm{x})$ is bijective.

By construction, the tuple $\bm{x}\circ \sigma$ first lists the entries from $K_1$ in the order prescribed by $\varsigma(K_1)$, then the entries from $K_2$ in the order prescribed by $\varsigma(K_2)$, and so on. Hence
    \begin{align*}
        \bm{x}\circ\sigma = \bigoplus_{r=1}^{\kappa} \varsigma(K_r) = \varsigma_{\mathrm{min}}(\bm{x}),
    \end{align*}
    which proves that $\varsigma_{\mathrm{min}}$ is a sorting map.

