\label{thm:measurable-partition}
    Let $(X,\mathcal{F})$ and $(Y, \mathcal{G})$ be measurable spaces. Let $(X_n)_{n\in\mathbb{N}}$ be a measurable partition\index{measurable partition} of $X$. That is, for each $n\in \mathbb{N}$ one has $X_n \in \mathcal{F}$, and for $n,m \in\mathbb{N}$ with $n \neq m$ it holds that $X_n \cap X_m =\emptyset$, and  
    \begin{align*}
        \bigcup_{n\in\mathbb{N}} X_n =X. 
    \end{align*}
    Then any function $f:X \to Y$ is $\mathcal{F}/\mathcal{G}$-measurable if and only if $f\restriction_{X_n} :X_n \to Y$ is $\mathcal{F}_n/\mathcal{G}$-measurable for all $n \in \mathbb{N}$, where $\mathcal{F}_n = \{ B \cap X_n \mid B \in \mathcal{F}\}$ is the trace $\sigma$-algebra.

\label{defn:permutation-map}\index{permutation maps}
    Let $X$ be a set, $\mathscr{T}(X)$ the associated tuple space, and $\mathscr{P}$ the set of all finite permutations. Define the map from $\mathscr{T}(X)\times \mathscr{P}$ into $\mathscr{T}(X)$ by 
    \begin{align*}
        \bm{x}[\pi] = \begin{cases}
            \bm{x} \circ \pi & \ell(\bm{x}) = \ell(\pi)\\
            \bm{e} & \ell(\bm{x}) \neq \ell(\pi).
        \end{cases}
    \end{align*}
    We call $(\bm{x}, \pi) \mapsto \bm{x}[\pi]$ the permutation map.

steps.text:
We must show that for any $(\bm{x}_0, \pi_0) \in \mathscr{T}(X) \times \mathscr{P}$ and $\varepsilon > 0$ there exists a $\delta > 0$ such that 
    \begin{align*}
        \max(\mathscr{d}_H(\bm{x}, \bm{x}_0), \mathscr{d}_H^{\mathbb{N}}(\pi, \pi_0)) < \delta \implies \mathscr{d}_H(\bm{x}[\pi], \bm{x}_0[\pi_0]) < \varepsilon.
    \end{align*}
    If $\ell(\bm{x}_0)=0$, a neighbourhood of radius less than $1$ fixes $\bm{x}=\bm{e}$, so both outputs equal $\bm{e}$. We may therefore assume $\ell(\bm{x}_0)>0$. By the \hyperref[thm:the-standard-machinery]{standard machinery} and the uniform discreteness of $(\mathscr{P},\mathscr{d}_H^{\mathbb{N}})$,
    \begin{align*}
        &\max\bigl(\mathscr{d}_H(\bm{x}, \bm{x}_0),
        \mathscr{d}_H^{\mathbb{N}}(\pi, \pi_0)\bigr) < 1
        \\
        &\implies
        \begin{aligned}
            \ell(\bm{x})&=\ell(\bm{x}_0),
            &\qquad \pi&=\pi_0,\\
            \mathscr{d}_H(\bm{x},\bm{x}_0)
            &=\max_{i \in \mathrm{domain}(\bm{x}_0)}
            d(\bm{x}(i),\bm{x}_0(i)).
        \end{aligned}
    \end{align*}
    Now suppose the bound above holds. If $\ell(\bm{x}_0) \neq \ell(\pi_0)$, the result is trivial, since $\bm{x}[\pi] = \bm{e} = \bm{x}_0[\pi_0]$. Therefore, assume that $\ell(\bm{x}_0) = \ell(\pi_0)$. Under the bound by $1$, this implies that $\ell(\bm{x}) = \ell(\pi) =\ell(\bm{x}_0) = \ell(\pi_0)$. Hence, whenever $\delta < \min(1,\varepsilon)$, it holds that
    \begin{align*}
        \mathscr{d}_H(\bm{x}[\pi], \bm{x}_0[\pi_0]) = \mathscr{d}_H(\bm{x}[\pi_0], \bm{x}_0[\pi_0]) = \mathscr{d}_H(\bm{x}, \bm{x}_0) < \delta < \min(1,\varepsilon) \leq \varepsilon,
    \end{align*}
    as desired.

proof.text:
We must show that for any $(\bm{x}_0, \pi_0) \in \mathscr{T}(X) \times \mathscr{P}$ and $\varepsilon > 0$ there exists a $\delta > 0$ such that 
