\label{defn:sorting-valid-elements}
    Let $(X, \preceq)$ be a partially ordered set and let $\pi \in \mathscr{P}$. Define
    \begin{align*}
        \mathscr{V}_\pi = \{\bm{x} \in \mathscr{T}(X) \mid \ell(\bm{x}) = \ell(\pi) \text{ and } \bm{x} \circ \pi \in \mathscr{S}(X, \preceq)\}.
    \end{align*}
    We call $\mathscr{V}_\pi$ the set of sorting-valid elements for the permutation $\pi$.

\label{cor:tuple-space-covered-by-sorting-valid-elements}
     Let $(X, \preceq)$ be a partially ordered set and $\mathscr{T}(X)$ the associated tuple space. Then for every $\bm{x}\in \mathscr{T}(X)$ there exists a $\pi \in \mathscr{P}$ such that 
     \begin{align*}
         \bm{x} \in \mathscr{V}_\pi,
     \end{align*}
     and, consequently, 
     \begin{align*}
         \mathscr{T}(X) = \bigcup_{\pi \in \mathscr{P}} \mathscr{V}_\pi. 
     \end{align*}

\label{cor:local-continuity-sorting}
    Let $(X, \preceq, d)$ be a partially ordered metric space. Let $(\mathscr{T}(X),\mathscr{d}_H)$ be the associated tuple Hausdorff space. For each $\pi \in \mathscr{P}$ the mapping 
    \begin{align*}
        \varsigma_\pi &: \mathscr{V}_\pi \to \mathscr{S}(X, \preceq),\\
         \bm{x}&\mapsto \bm{x}[\pi],
    \end{align*}
    is continuous, where both domain and codomain carry the subspace topologies inherited from $(\mathscr{T}(X),\mathscr{d}_H)$.

\label{lem:permutations-inherit-order}
    For any bijective map $\varphi :\mathscr{P} \to \mathbb{N}$, define the order $\leq_\varphi$ on $\mathscr{P}$ by 
    \begin{align*}
        \pi \leq_\varphi \pi^\prime \iff \varphi(\pi) \leq \varphi(\pi^\prime),
    \end{align*}
    where the order on the right-hand side is the usual order on the natural numbers. Then, $(\mathscr{P}, \leq_{\varphi})$ is a totally ordered set.

steps.text:
First, since $\mathscr{U}_n \subseteq \mathscr{V}_{\pi_{(n)}} \subseteq \mathscr{T}(X)$ for every $n \in \mathbb{N}$, it holds that $\bigcup_{n \in \mathbb{N}} \mathscr{U}_n \subseteq \mathscr{T}(X)$. For the reverse inclusion, let $\bm{x} \in \mathscr{T}(X)$ be arbitrary. By Corollary~\ref{cor:tuple-space-covered-by-sorting-valid-elements}, the family $(\mathscr{V}_\pi)_{\pi \in \mathscr{P}}$ covers $\mathscr{T}(X)$, and since $\varphi : \mathscr{P} \to \mathbb{N}$ is bijective, the set of indices
    \begin{align*}
        I_{\bm{x}} = \big\{k \in \mathbb{N} \;\big|\; \bm{x} \in \mathscr{V}_{\pi_{(k)}}\big\}
    \end{align*}
    is a non-empty subset of $\mathbb{N}$. By the well-ordering principle on $\mathbb{N}$, the set $I_{\bm{x}}$ has a least element $n = \min I_{\bm{x}}$. By definition of $n$, we have $\bm{x} \in \mathscr{V}_{\pi_{(n)}}$ and $\bm{x} \notin \mathscr{V}_{\pi_{(m)}}$ for every $m < n$. Consequently,
    \begin{align*}
        \bm{x} \in \mathscr{V}_{\pi_{(n)}} \setminus \bigcup_{m < n} \mathscr{V}_{\pi_{(m)}} = \mathscr{U}_n \subseteq \bigcup_{k \in \mathbb{N}} \mathscr{U}_k,
    \end{align*}
    which proves that $\mathscr{T}(X) = \bigcup_{n \in \mathbb{N}} \mathscr{U}_n$.

proof.text:
We must show that $\bigcup_{n \in \mathbb{N}} \mathscr{U}_n = \mathscr{T}(X)$ and that $\mathscr{U}_n \cap \mathscr{U}_k = \emptyset$ for all $n, k \in \mathbb{N}$ with $n \neq k$.

    First, since $\mathscr{U}_n \subseteq \mathscr{V}_{\pi_{(n)}} \subseteq \mathscr{T}(X)$ for every $n \in \mathbb{N}$, it holds that $\bigcup_{n \in \mathbb{N}} \mathscr{U}_n \subseteq \mathscr{T}(X)$. For the reverse inclusion, let $\bm{x} \in \mathscr{T}(X)$ be arbitrary. By Corollary~\ref{cor:tuple-space-covered-by-sorting-valid-elements}, the family $(\mathscr{V}_\pi)_{\pi \in \mathscr{P}}$ covers $\mathscr{T}(X)$, and since $\varphi : \mathscr{P} \to \mathbb{N}$ is bijective, the set of indices
    \begin{align*}
        I_{\bm{x}} = \big\{k \in \mathbb{N} \;\big|\; \bm{x} \in \mathscr{V}_{\pi_{(k)}}\big\}
    \end{align*}
    is a non-empty subset of $\mathbb{N}$. By the well-ordering principle on $\mathbb{N}$, the set $I_{\bm{x}}$ has a least element $n = \min I_{\bm{x}}$. By definition of $n$, we have $\bm{x} \in \mathscr{V}_{\pi_{(n)}}$ and $\bm{x} \notin \mathscr{V}_{\pi_{(m)}}$ for every $m < n$. Consequently,
    \begin{align*}
        \bm{x} \in \mathscr{V}_{\pi_{(n)}} \setminus \bigcup_{m < n} \mathscr{V}_{\pi_{(m)}} = \mathscr{U}_n \subseteq \bigcup_{k \in \mathbb{N}} \mathscr{U}_k,
    \end{align*}
    which proves that $\mathscr{T}(X) = \bigcup_{n \in \mathbb{N}} \mathscr{U}_n$.

    Next, let $n, k \in \mathbb{N}$ with $n \neq k$, and assume without loss of generality that $m = k < n$. By construction, $\mathscr{U}_k \subseteq \mathscr{V}_{\pi_{(k)}}$, whereas $\mathscr{U}_n$ is disjoint from $\bigcup_{m < n} \mathscr{V}_{\pi_{(m)}}$ and hence disjoint from $\mathscr{V}_{\pi_{(k)}}$. It follows that $\mathscr{U}_n \cap \mathscr{U}_k = \emptyset$, as desired.

results.statement:
\label{lem:sorting-valid-first-choice-partition-covers}
    Let $(X, \preceq)$ be a partially ordered set, and let $\varphi:\mathscr{P} \to \mathbb{N}$ be a bijection. Define $(\mathscr{U}_n)_{n\in\mathbb{N}}$ by 
    \begin{align*}
        \mathscr{U}_n = \mathscr{V}_{\pi_{(n)}} \setminus \bigcup_{\substack{m \in \mathbb{N}\\ m < n}} \mathscr{V}_{\pi_{(m)}},
    \end{align*}
    where $\pi_{(n)}$ is defined by $\varphi^{-1}(n)$. Then, 
    \begin{align*}
        \mathscr{T}(X) = \bigcup_{n\in \mathbb{N}} \mathscr{U}_n,
    \end{align*}
    and the sets $\mathscr{U}_n$ are pairwise disjoint.

steps.text:
Next, fix $\bm{x} \in \mathscr{T}(X)$ and let $n \in \mathbb{N}$ be the unique index such that $\bm{x} \in \mathscr{U}_n$. By definition of $\mathscr{U}_n$ and Definition~\ref{defn:sorting-valid-elements}, we have $\bm{x} \in \mathscr{U}_n \subseteq \mathscr{V}_{\pi_{(n)}}$, which implies that $\ell(\bm{x}) = \ell(\pi_{(n)})$ and $\bm{x} \circ \pi_{(n)} \in \mathscr{S}(X,\preceq)$. By Definition~\ref{defn:permutation-map}, it follows that
    \begin{align*}
        \varsigma(\bm{x}) = \varsigma_{\pi_{(n)}}(\bm{x}) = \bm{x}[\pi_{(n)}] = \bm{x} \circ \pi_{(n)} \in \mathscr{S}(X,\preceq),
    \end{align*}
    with $\pi_{(n)} \in \mathscr{P}_{\ell(\bm{x})}$. Therefore, $\varsigma$ is a sorting map, as desired.

results.statement:
\label{prop:induced-sorting}
 Let $(X, \preceq)$ be a partially ordered set, and let $\varphi:\mathscr{P} \to \mathbb{N}$ be a bijection. Then, the function $\varsigma:\mathscr{T}(X) \to \mathscr{S}(X,\preceq)$ defined by 
 \begin{align*}
     \varsigma(\bm{x}) = \begin{cases}
         \varsigma_{\pi_{(1)}}(\bm{x}) & \bm{x} \in \mathscr{U}_1 \\
         ~~~~\vdots ~~~~ &~~~~\vdots \\ 
         \varsigma_{\pi_{(n)}}(\bm{x}) & \bm{x} \in \mathscr{U}_n \\ 
         ~~~~\vdots ~~~~ &~~~~\vdots \\ 
     \end{cases}
 \end{align*}
    is a sorting map, where $\pi_{(n)} = \varphi^{-1}(n)$, $\varsigma_{\pi_{(i)}} : \mathscr{U}_i \to \mathscr{S}(X, \preceq)$ are defined by $\varsigma_{\pi_{(i)}}(\bm{x}) = \bm{x}[\pi_{(i)}]$, and $\mathscr{U}_i = \mathscr{V}_{\pi_{(i)}} \setminus \bigcup_{j < i} \mathscr{V}_{\pi_{(j)}}$.

steps.text:
Note that by construction we have 
    \begin{align*}
        \bigcup_{n \in \mathbb{N}} \mathscr{U}_n = \bigcup_{\pi \in \mathscr{P}} \mathscr{V}_\pi = \mathscr{T}(X),
    \end{align*}
    and $\mathscr{U}_n \cap \mathscr{U}_m = \emptyset$ for all $n,m\in \mathbb{N}: n \neq m$. Therefore, it suffices to show that each $\mathscr{U}_n$ is measurable. To this end, note that it is enough to show that each $\mathscr{V}_\pi$ for $\pi \in \mathscr{P}$ is measurable, since the union over $m<n$ in the definition of $\mathscr{U}_n$ is finite.

Notice that, by definition, we have 
    \begin{align*}
        \mathscr{V}_\pi = \{\bm{x} \in \mathscr{T}(X) \mid \ell(\bm{x}) = \ell(\pi) \text{ and } \bm{x} \circ \pi \in \mathscr{S}(X, \preceq)\} \subseteq X^{\ell(\pi)}.
    \end{align*}
    Let $N = \ell(\pi)$ and note that by the \hyperref[thm:the-standard-machinery]{standard machinery}, it suffices to show that $\mathscr{V}_\pi$ is measurable in $X^N$ endowed with the maximum product metric and the associated Borel $\sigma$-algebra. Since $X$ is metric, the diagonal is closed, and hence the strict order relation $\prec=\preceq\setminus\Delta_X$ is Borel whenever $\preceq$ is Borel. Thus the set
    \begin{align*}
        A_{i,j} =\{\bm{x}:\{1,\dots,N\} \to X \mid \bm{x}(\pi(j)) \prec \bm{x}(\pi(i))\}
    \end{align*}
    is Borel, for each $i,j \in \{1,\dots,N\}$, being the preimage of the Borel set $\prec\, \subseteq X \times X$ under the continuous coordinate map $\bm{x} \mapsto (\bm{x}(\pi(j)),\bm{x}(\pi(i)))$ from $X^N$ to $X\times X$. Consequently, the complement, $A_{i,j}^{\mathtt{C}}$, is measurable, and
    \begin{align*}
        \mathscr{V}_{\pi} &= \{ \bm{x} \in \mathscr{T}(X) \mid N=\ell(\bm{x}) \text{ and } \bm{x}\circ\pi \in \mathscr{S}(X,\preceq)\} \\
        &= \{\bm{x} \in X^{N} \mid \forall i,j \in \{1,\dots, N\}: i \leq j \implies \neg(\bm{x}(\pi(j)) \prec \bm{x}(\pi(i)))\}\\
        &=\bigcap_{\substack{i,j\in \{1,\dots,N\}\\i \leq j}} \{\bm{x} \in X^{N} \mid \neg(\bm{x}(\pi(j)) \prec \bm{x}(\pi(i)))\}
        \\
        &=\bigcap_{\substack{i,j \in \{1,\dots,N\}: \\ i \leq j}} A_{i,j}^{\mathtt{C}}
    \end{align*}
    is therefore a finite intersection of measurable sets and hence measurable.

