By Proposition~\ref{prop:permuting-continuous}, this map is continuous, hence measurable. Therefore, by Theorem~\ref{thm:measurable-partition}, the restriction of $\varsigma_{\mathrm{min}}$ to $X^n$ is measurable.

    Since $n$ was arbitrary, another application of the \hyperref[thm:the-standard-machinery]{standard machinery} yields that $\varsigma_{\mathrm{min}}:\mathscr{T}(X) \to \mathscr{S}(X,\preceq)$ is Borel measurable.

results.statement:
\label{defn:concat-tuple}\index{concatenation}
    Let $X$ be a non-empty set, and let $\mathscr{T}(X)$ be the associated tuple space. The binary operation $\oplus: \mathscr{T}(X)\times \mathscr{T}(X) \to \mathscr{T}(X)$ given by
    \begin{align*}
      \begin{aligned}
        &\bm{x} \oplus \bm{y}: \{1, \dots, \ell(\bm{x}) + \ell(\bm{y})\} \to X, \\
        &i \mapsto \begin{cases}
            \bm{x}(i) & i \in \mathrm{domain}(\bm{x}) \\
            \bm{y}(i - \ell(\bm{x})) & i \in \{j +\ell(\bm{x}) \mid j \in \mathrm{domain}(\bm{y})\}
        \end{cases}
      \end{aligned}
    \end{align*}
    is called the concatenation operator.

\label{defn:sorted-tuple-add}\index{sorted tuple addition}
    Let $(X, \preceq)$ be a non-empty partially ordered set, $\mathscr{S}(X, \preceq)$ be the sorted tuple space, and $\varsigma:\mathscr{T}(X) \to \mathscr{S}(X, \preceq)$ be a fixed sorting map. The binary operation $+: \mathscr{T}(X)\times \mathscr{T}(X) \to \mathscr{S}(X, \preceq)$ given by 
    \begin{align*}
        \bm{x} + \bm{y} = \varsigma(\bm{x} \oplus \bm{y})
    \end{align*}
    is called the sorted addition operator.

steps.text:
We must show that, for all $\bm{x},\bm{x}^\prime, \bm{x}^\ast \in \mathscr{S}(X, \preceq)$, the operation satisfies
    \begin{enumerate}[(i)]
        \item $(\bm{x} + \bm{x}^\prime) + \bm{x}^\ast = \bm{x} + (\bm{x}^\prime + \bm{x}^\ast)$ (associativity). \label{property:associative}
        \item $\bm{x} + \bm{e} = \bm{x}$ (identity element).  \label{property:identity}
        \item $\bm{x} + \bm{x}^\prime = \bm{x}^\prime + \bm{x}$ (commutativity). \label{property:commutative}
        \item $\bm{x} + \bm{x}^\prime = \bm{x}^\ast + \bm{x}^\prime \text{ implies } \bm{x} = \bm{x}^\ast$ (right cancellation).  \label{property:right-cancel}
        \item $\bm{x}^\prime + \bm{x} = \bm{x}^\prime + \bm{x}^\ast \text{ implies } \bm{x} = \bm{x}^\ast$ (left cancellation).  \label{property:left-cancel}
    \end{enumerate}
    The identity property \eqref{property:identity} is immediate. Since $\bm{x}\oplus \bm{e} = \bm{x}$ and $\bm{x}$ is already sorted, idempotency of the sorting map on $\mathscr{S}(X,\preceq)$ yields $\bm{x} + \bm{e} = \bm{x}$.

For each $a \in X$ and each tuple $\bm{z}\in \mathscr{T}(X)$ define the multiplicity
    \begin{align*}
        N_a(\bm{z}) = |\{i \in \mathrm{domain}(\bm{z}) \mid \bm{z}(i) = a\}|.
    \end{align*}
    Sorting does not change multiplicities, and concatenation adds them, i.e., for every $a \in X$ and $\bm{x},\bm{y} \in \mathscr{T}(X)$,
    \begin{align*}
        N_a(\bm{x}+\bm{y}) = N_a(\bm{x}) + N_a(\bm{y}).
    \end{align*}

proof.text:
We must show that, for all $\bm{x},\bm{x}^\prime, \bm{x}^\ast \in \mathscr{S}(X, \preceq)$, the operation satisfies
    \begin{enumerate}[(i)]
        \item $(\bm{x} + \bm{x}^\prime) + \bm{x}^\ast = \bm{x} + (\bm{x}^\prime + \bm{x}^\ast)$ (associativity). \label{property:associative}
        \item $\bm{x} + \bm{e} = \bm{x}$ (identity element).  \label{property:identity}
        \item $\bm{x} + \bm{x}^\prime = \bm{x}^\prime + \bm{x}$ (commutativity). \label{property:commutative}
        \item $\bm{x} + \bm{x}^\prime = \bm{x}^\ast + \bm{x}^\prime \text{ implies } \bm{x} = \bm{x}^\ast$ (right cancellation).  \label{property:right-cancel}
        \item $\bm{x}^\prime + \bm{x} = \bm{x}^\prime + \bm{x}^\ast \text{ implies } \bm{x} = \bm{x}^\ast$ (left cancellation).  \label{property:left-cancel}
    \end{enumerate}
    The identity property \eqref{property:identity} is immediate. Since $\bm{x}\oplus \bm{e} = \bm{x}$ and $\bm{x}$ is already sorted, idempotency of the sorting map on $\mathscr{S}(X,\preceq)$ yields $\bm{x} + \bm{e} = \bm{x}$.

    For each $a \in X$ and each tuple $\bm{z}\in \mathscr{T}(X)$ define the multiplicity
    \begin{align*}
        N_a(\bm{z}) = |\{i \in \mathrm{domain}(\bm{z}) \mid \bm{z}(i) = a\}|.
    \end{align*}
    Sorting does not change multiplicities, and concatenation adds them, i.e., for every $a \in X$ and $\bm{x},\bm{y} \in \mathscr{T}(X)$,
    \begin{align*}
        N_a(\bm{x}+\bm{y}) = N_a(\bm{x}) + N_a(\bm{y}).
    \end{align*}

    For \eqref{property:associative}, notice that both $(\bm{x} + \bm{x}^\prime) + \bm{x}^\ast=\varsigma(\varsigma(\bm{x} \oplus \bm{x}^\prime) \oplus \bm{x}^\ast)$ and $\bm{x} + (\bm{x}^\prime + \bm{x}^\ast)=\varsigma(\bm{x} \oplus \varsigma(\bm{x}^\prime \oplus \bm{x}^\ast))$ are sorted tuples containing every $a\in X$ exactly $N_a(\bm{x})+N_a(\bm{x}^\prime)+N_a(\bm{x}^\ast)$ times. Under a total order, a sorted tuple is non-decreasing (Proposition~\ref{prop:totally-ordered-tuple-sorted-iff-monotone}), so its $i^{\mathrm{th}}$ entry is the smallest of its entries $a$ with $\sum_{b\preceq a}N_b\geq i$; hence two sorted tuples with equal multiplicities coincide, and both expressions are the same tuple. The same argument proves \eqref{property:commutative}.

    From \eqref{property:commutative} it suffices to show \eqref{property:right-cancel}, as \eqref{property:left-cancel} then follows immediately. If $\bm{x} + \bm{x}^\prime = \bm{x}^\ast + \bm{x}^\prime$, then for every $a \in X$,
    \begin{align*}
        N_a(\bm{x}) + N_a(\bm{x}^\prime)
        = N_a(\bm{x}+\bm{x}^\prime)
        = N_a(\bm{x}^\ast+\bm{x}^\prime)
        = N_a(\bm{x}^\ast) + N_a(\bm{x}^\prime),
    \end{align*}
    and hence $N_a(\bm{x}) = N_a(\bm{x}^\ast)$. Since both $\bm{x}$ and $\bm{x}^\ast$ are sorted in the same total order, equality of all multiplicities implies $\bm{x} = \bm{x}^\ast$, as shown in the proof of \eqref{property:associative}. This proves right cancellation.

results.statement:
\label{defn:pairing}\index{pairing}
    Let $(X, \preceq)$ be a totally ordered set. Define for each $\xi \in \mathscr{F}(X)$ the associated tuple $\xi^\dagger : \{i \in \mathbb{N} \mid i \leq |\xi|\} \to X$ by the recursive expression
    \begin{align*}
        \xi^\dagger(i) = \min \{x \in \xi \mid x \notin \{\xi^\dagger(j) \mid j <i\}\},
    \end{align*}
    where the minimum is taken with respect to the total order, $\preceq$.

\label{defn:reindex}\index{reindexing}
    Let $X$ be a non-empty set and let $\mathscr{T}(X)$ be the associated space of tuples. Moreover, let $\mathscr{F}(\mathbb{N})$ be the set of finite subsets of the natural numbers. Then, for any tuple $\bm{x}\in \mathscr{T}(X)$ and $\eta \in \mathscr{F}(\mathbb{N})$ we define 
    \begin{align*}
\bm{x}[\eta] : \{1,\dots,|\eta \cap \mathrm{domain}(\bm{x})|\}\to X,\qquad i \mapsto \bm{x}((\eta \cap \mathrm{domain}(\bm{x}))^\dagger(i)).
    \end{align*}

\label{defn:cancel}
    Let $X$ be a non-empty set and $\mathscr{T}(X)$ be the associated tuple space. Let $\mathscr{F}(\mathbb{N})$ denote the set of finite subsets of $\mathbb{N}$. Define the operation $\ominus: \mathscr{T}(X)\times \mathscr{F}(\mathbb{N}) \to \mathscr{T}(X)$ by  
    \begin{align*}
        \bm{x} \ominus \eta = \bm{x}[\mathrm{domain}(\bm{x})\setminus\eta]. 
    \end{align*}

\label{exmp:identifier-coordinates}\index{identifier}
    Let $(Y,d_Y)$ be a metric space and let $(I,\leq)$ be a countable, totally ordered set. On $X=Y\times I$, consider the metric
    \begin{align*}
        d\bigl((y,i),(y^\prime,j)\bigr)=\max\bigl(d_Y(y,y^\prime),d_I(i,j)\bigr),
        \qquad
        d_I(i,j)=\mathbbm{1}(i\neq j),
    \end{align*}
    and the projections $\mathrm{id} : X \to I$ defined by $\mathrm{id}(y,i)=i$ and $\varpi: X \to Y$ defined by $\varpi(y,i)=y$. We call $\mathrm{id}(x)$ the \emph{identifier} of $x\in X$. 

    Since $d_I\leq d$, the map $\mathrm{id}:X\to(I,d_I)$ is $1$-Lipschitz and hence locally constant. Since $(I,d_I)$ is countable and discrete, $X$ is Polish whenever $Y$ is. We write $\mathscr{T}_{\neq}(X) = \{\bm{x} \in \mathscr{T}(X) \mid\mathrm{id}\circ\bm{x} \text{ is injective}\}.$

\label{defn:identifier-cancel}\index{cancellation!identifier-based}
    Let $Y$ be a set, let $I$ be a countable, totally ordered set, let $X=Y\times I$ with $\mathrm{id}(y,i)=i$, and let $\mathscr{F}(I)$ denote the set of finite subsets of $I$. For $\bm{x}\in\mathscr{T}(X)$ and $J\in\mathscr{F}(I)$, let
    \begin{align*}
        \eta_J(\bm{x})=\{k\in\mathrm{domain}(\bm{x})\mid\mathrm{id}(\bm{x}(k))\in J\}
    \end{align*}
    be the indices of the entries whose identifiers lie in $J$. Define the operation $\ominus_I:\mathscr{T}(X)\times\mathscr{F}(I)\to\mathscr{T}(X)$ by
    \begin{align*}
        \bm{x}\ominus_I J=\bm{x}\ominus\eta_J(\bm{x}).
    \end{align*}

\label{rem:identifier-coordinates}
    Identifiers do not change when entries are removed. Unlike its index-based counterpart, identifier-based cancellation therefore composes, in the sense that for all $J,J^\prime\in\mathscr{F}(I)$,
    \begin{align*}
        (\bm{x}\ominus_I J)\ominus_I J^\prime=\bm{x}\ominus_I(J\cup J^\prime).
    \end{align*}
    In the metric setting of Example~\ref{exmp:identifier-coordinates}, the identifier carries no metric information beyond equality. Under the pseudometric $\bar{d}((y,i),(y^\prime,j))=d_Y(y,y^\prime)$, elements that differ only in their identifiers lie at distance $0$, and identifying such elements recovers $(Y,d_Y)$ through $\varpi$; the maps that disregard identifiers are precisely those that factor through $\varpi$. The metric $d$ instead separates distinct identifiers by $1$, which makes $\mathrm{id}$ continuous. Had we indexed a disjoint union $\bigsqcup_{i\in I}Y$ (Definition~\ref{defn:disjoint-union}) by the identifiers instead, elements with distinct identifiers would lie at distance $\infty$ (Definition~\ref{defn:disjoint-union-metrisation}) and be incomparable under the induced partial order (Proposition~\ref{prop:disjoint-partial-order}), so that no sorting could rank them against each other. In the product, identifiers can instead break ties (Proposition~\ref{prop:identifier-tie-breaking}).

\label{defn:sorted-cancel}
    Let $(X,\preceq)$ be a non-empty partially ordered set, let $\mathscr{T}(X)$ be the associated tuple space, and let $\mathscr{S}(X,\preceq)$ be the subspace of sorted tuples. Let $\varsigma :\mathscr{T}(X) \to \mathscr{S}(X,\preceq)$ be a fixed sorting map. Finally, let $\mathscr{F}(\mathbb{N})$ denote the set of finite subsets of $\mathbb{N}$. Define the operation $-:\mathscr{T}(X)\times \mathscr{F}(\mathbb{N}) \to \mathscr{S}(X, \preceq)$ by
    \begin{align*}
        \bm{x} - \eta = \varsigma(\bm{x} \ominus \eta).
    \end{align*}

\label{cor:cancel-closure-sorted}
    Let $(X,\preceq)$ be a totally ordered set and $\mathscr{S}(X,\preceq)$ be the associated sorted tuple space. Then, 
    \begin{align*}
        \bm{x} - \eta = \bm{x}\ominus\eta
    \end{align*}
    for every $\bm{x} \in \mathscr{S}(X,\preceq)$ and $\eta \in \mathscr{F}(\mathbb{N})$.

steps.text:
Now let $\bm{x} \in \mathscr{T}_{\neq}(X)$ and let $k, l \in \mathrm{domain}(\bm{x})$. If $k = l$, then $\bm{x}(k) = \bm{x}(l)$ and hence $\bm{x}(k) \preceq_I \bm{x}(l)$. If $k \neq l$, then injectivity of $\mathrm{id} \circ \bm{x}$ implies that $\mathrm{id}(\bm{x}(k)) \neq \mathrm{id}(\bm{x}(l))$, and consequently
    \begin{align*}
        H(\bm{x}(k)) = \bigl(h(\varpi(\bm{x}(k))), \mathrm{id}(\bm{x}(k))\bigr) \neq \bigl(h(\varpi(\bm{x}(l))), \mathrm{id}(\bm{x}(l))\bigr) = H(\bm{x}(l)).
    \end{align*}
    Because $\sqsubset$ is a strict total order on $K \times I$, either $H(\bm{x}(k)) \sqsubset H(\bm{x}(l))$ or $H(\bm{x}(l)) \sqsubset H(\bm{x}(k))$, which implies that either $\bm{x}(k) \preceq_I \bm{x}(l)$ or $\bm{x}(l) \preceq_I \bm{x}(k)$.

Next, we prove \eqref{property:tie-break-unique}. We must show that for every $\bm{x} \in \mathscr{T}_{\neq}(X)$, there exists a unique sorted tuple $\bm{y} \in \mathscr{S}(X, \preceq_I)$ of the form $\bm{y} = \bm{x} \circ \pi$ with $\pi \in \mathscr{P}_{\ell(\bm{x})}$. If $\bm{x} = \bm{e}$, the unique sorted rearrangement is $\bm{e}$. Suppose therefore that $n = \ell(\bm{x}) > 0$. By \eqref{property:tie-break-order} and the injectivity of $H$ on the entries of $\bm{x}$, the image $\{\bm{x}(1), \dots, \bm{x}(n)\}$ consists of $n$ distinct elements that are strictly totally ordered by $\prec_I$. Consequently, any permutation $\pi \in \mathscr{P}_n$ for which $\bm{x} \circ \pi \in \mathscr{S}(X, \preceq_I)$ must satisfy
    \begin{align*}
        \bm{x}(\pi(1)) \prec_I \bm{x}(\pi(2)) \prec_I \dots \prec_I \bm{x}(\pi(n)),
    \end{align*}
    which uniquely determines $\pi(r)$ for every $r \in \{1, \dots, n\}$. Therefore, $\bm{x}$ admits a unique sorted rearrangement, and every sorting map $\varsigma : \mathscr{T}(X) \to \mathscr{S}(X, \preceq_I)$ returns it, as desired.

proof.text:
First, we prove \eqref{property:tie-break-order}. We must show that $\preceq_I$ is reflexive, antisymmetric, and transitive on $X$, and that for every $\bm{x} \in \mathscr{T}_{\neq}(X)$ and all $k, l \in \mathrm{domain}(\bm{x})$, either $\bm{x}(k) \preceq_I \bm{x}(l)$ or $\bm{x}(l) \preceq_I \bm{x}(k)$.

    For reflexivity, note that $x = x$ implies $x \preceq_I x$ for every $x \in X$ by definition. For antisymmetry, suppose that $x \preceq_I x^\prime$ and $x^\prime \preceq_I x$ for some $x, x^\prime \in X$. If $x \neq x^\prime$, then the definition of $\preceq_I$ requires both $H(x) \sqsubset H(x^\prime)$ and $H(x^\prime) \sqsubset H(x)$, which is impossible because the strict lexicographic order $\sqsubset$ on $K \times I$ is asymmetric. Hence $x = x^\prime$. For transitivity, suppose that $x \preceq_I x^\prime$ and $x^\prime \preceq_I x^{\prime\prime}$. If $x = x^\prime$ or $x^\prime = x^{\prime\prime}$, then $x \preceq_I x^{\prime\prime}$ holds immediately; otherwise, $H(x) \sqsubset H(x^\prime)$ and $H(x^\prime) \sqsubset H(x^{\prime\prime})$, and the transitivity of $\sqsubset$ yields $H(x) \sqsubset H(x^{\prime\prime})$, whence $x \preceq_I x^{\prime\prime}$. Thus $(X, \preceq_I)$ is a partially ordered set.

    Now let $\bm{x} \in \mathscr{T}_{\neq}(X)$ and let $k, l \in \mathrm{domain}(\bm{x})$. If $k = l$, then $\bm{x}(k) = \bm{x}(l)$ and hence $\bm{x}(k) \preceq_I \bm{x}(l)$. If $k \neq l$, then injectivity of $\mathrm{id} \circ \bm{x}$ implies that $\mathrm{id}(\bm{x}(k)) \neq \mathrm{id}(\bm{x}(l))$, and consequently
    \begin{align*}
        H(\bm{x}(k)) = \bigl(h(\varpi(\bm{x}(k))), \mathrm{id}(\bm{x}(k))\bigr) \neq \bigl(h(\varpi(\bm{x}(l))), \mathrm{id}(\bm{x}(l))\bigr) = H(\bm{x}(l)).
    \end{align*}
    Because $\sqsubset$ is a strict total order on $K \times I$, either $H(\bm{x}(k)) \sqsubset H(\bm{x}(l))$ or $H(\bm{x}(l)) \sqsubset H(\bm{x}(k))$, which implies that either $\bm{x}(k) \preceq_I \bm{x}(l)$ or $\bm{x}(l) \preceq_I \bm{x}(k)$.

    Next, we prove \eqref{property:tie-break-unique}. We must show that for every $\bm{x} \in \mathscr{T}_{\neq}(X)$, there exists a unique sorted tuple $\bm{y} \in \mathscr{S}(X, \preceq_I)$ of the form $\bm{y} = \bm{x} \circ \pi$ with $\pi \in \mathscr{P}_{\ell(\bm{x})}$. If $\bm{x} = \bm{e}$, the unique sorted rearrangement is $\bm{e}$. Suppose therefore that $n = \ell(\bm{x}) > 0$. By \eqref{property:tie-break-order} and the injectivity of $H$ on the entries of $\bm{x}$, the image $\{\bm{x}(1), \dots, \bm{x}(n)\}$ consists of $n$ distinct elements that are strictly totally ordered by $\prec_I$. Consequently, any permutation $\pi \in \mathscr{P}_n$ for which $\bm{x} \circ \pi \in \mathscr{S}(X, \preceq_I)$ must satisfy
    \begin{align*}
        \bm{x}(\pi(1)) \prec_I \bm{x}(\pi(2)) \prec_I \dots \prec_I \bm{x}(\pi(n)),
    \end{align*}
    which uniquely determines $\pi(r)$ for every $r \in \{1, \dots, n\}$. Therefore, $\bm{x}$ admits a unique sorted rearrangement, and every sorting map $\varsigma : \mathscr{T}(X) \to \mathscr{S}(X, \preceq_I)$ returns it, as desired.

results.statement:
\label{prop:identifier-tie-breaking}
    Let $Y$ be a set, let $(I,\leq)$ be a countable, totally ordered set, let $X=Y\times I$ with $\mathrm{id}(y,i)=i$, and let $\mathscr{T}_{\neq}(X)=\{\bm{x}\in\mathscr{T}(X)\mid\mathrm{id}\circ\bm{x}\text{ is injective}\}$. Let $(K,<)$ be a strictly totally ordered set, let $h:Y\to K$ be a map, and let $H:X\to K\times I$ be given by $H(y,i)=(h(y),i)$. Let $\sqsubset$ be the strict lexicographic order on $K\times I$,
    \begin{align*}
        (a,i)\sqsubset(b,j)\iff a<b\ \lor\ \bigl(a=b\land i<j\bigr),
    \end{align*}
    and define the relation $\preceq_I$ on $X$ by
    \begin{align*}
        x\preceq_I x^\prime\iff x=x^\prime\ \lor\ H(x)\sqsubset H(x^\prime).
    \end{align*}
    Then
    \begin{enumerate}[(i)]
        \item $(X,\preceq_I)$ is a partially ordered set, and the restriction of $\preceq_I$ to the entries of any $\bm{x}\in\mathscr{T}_{\neq}(X)$ is total, and\label{property:tie-break-order}
        \item each $\bm{x}\in\mathscr{T}_{\neq}(X)$ has exactly one sorted rearrangement, so all sorting maps $\varsigma:\mathscr{T}(X)\to\mathscr{S}(X,\preceq_I)$ agree on $\mathscr{T}_{\neq}(X)$.\label{property:tie-break-unique}
    \end{enumerate}

steps.text:
We must show that the relation ${\preceq_I} = \{(x, x^\prime) \in X \times X \mid x \preceq_I x^\prime\}$ belongs to the Borel $\sigma$-algebra $\mathcal{B}(X \times X)$. Let $H$ and $\sqsubset$ be as in Proposition~\ref{prop:identifier-tie-breaking}. By definition of the lexicographic order, we may decompose ${\sqsubset} \subseteq (K \times I) \times (K \times I)$ as
    \begin{align*}
        {\sqsubset}
        =\bigl\{((a,i),(b,j)) \in (K\times I)^2 \bigm| a<b\bigr\}
        \cup\bigl\{((a,i),(b,j)) \in (K\times I)^2 \bigm| a=b \land i<j\bigr\}.
    \end{align*}
    The first set is the preimage of the Borel set ${<} \in \mathcal{B}(K \times K)$ under the continuous coordinate projection $((a,i),(b,j))\mapsto(a,b)$, and the second is the intersection of the closed set $\{((a,i),(b,j)) \mid a=b\}$ with the clopen set $\{((a,i),(b,j)) \mid i<j\}$. Hence ${\sqsubset}\in\mathcal{B}((K\times I)^2)$.

Since $K$ is separable and $(I, d_I)$ is countable, the product space $K\times I$ is separable, so that $\mathcal{B}((K\times I)^2)=\mathcal{B}(K\times I)\otimes\mathcal{B}(K\times I)$. Moreover, the map $H:X \to K \times I$ is Borel measurable because $h:Y \to K$ is Borel measurable and the coordinate projections $\varpi:X \to Y$ and $\mathrm{id}:X \to I$ are continuous. Therefore, the product map $H \times H : X \times X \to (K \times I)^2$ satisfies
    \begin{align*}
        (H\times H)^{-1}(\sqsubset)\in\mathcal{B}(X)\otimes\mathcal{B}(X)\subseteq\mathcal{B}(X\times X).
    \end{align*}
    Finally, since $(X, d)$ is a metric space, the diagonal $\Delta_X = \{(x,x) \mid x \in X\}$ is closed in $X \times X$ and hence Borel. Consequently,
    \begin{align*}
        {\preceq_I} = \Delta_X \cup (H \times H)^{-1}(\sqsubset) \in \mathcal{B}(X \times X),
    \end{align*}
    as desired.

proof.text:
We must show that the relation ${\preceq_I} = \{(x, x^\prime) \in X \times X \mid x \preceq_I x^\prime\}$ belongs to the Borel $\sigma$-algebra $\mathcal{B}(X \times X)$. Let $H$ and $\sqsubset$ be as in Proposition~\ref{prop:identifier-tie-breaking}. By definition of the lexicographic order, we may decompose ${\sqsubset} \subseteq (K \times I) \times (K \times I)$ as
    \begin{align*}
        {\sqsubset}
        =\bigl\{((a,i),(b,j)) \in (K\times I)^2 \bigm| a<b\bigr\}
        \cup\bigl\{((a,i),(b,j)) \in (K\times I)^2 \bigm| a=b \land i<j\bigr\}.
    \end{align*}
    The first set is the preimage of the Borel set ${<} \in \mathcal{B}(K \times K)$ under the continuous coordinate projection $((a,i),(b,j))\mapsto(a,b)$, and the second is the intersection of the closed set $\{((a,i),(b,j)) \mid a=b\}$ with the clopen set $\{((a,i),(b,j)) \mid i<j\}$. Hence ${\sqsubset}\in\mathcal{B}((K\times I)^2)$.

    Since $K$ is separable and $(I, d_I)$ is countable, the product space $K\times I$ is separable, so that $\mathcal{B}((K\times I)^2)=\mathcal{B}(K\times I)\otimes\mathcal{B}(K\times I)$. Moreover, the map $H:X \to K \times I$ is Borel measurable because $h:Y \to K$ is Borel measurable and the coordinate projections $\varpi:X \to Y$ and $\mathrm{id}:X \to I$ are continuous. Therefore, the product map $H \times H : X \times X \to (K \times I)^2$ satisfies
    \begin{align*}
        (H\times H)^{-1}(\sqsubset)\in\mathcal{B}(X)\otimes\mathcal{B}(X)\subseteq\mathcal{B}(X\times X).
    \end{align*}
    Finally, since $(X, d)$ is a metric space, the diagonal $\Delta_X = \{(x,x) \mid x \in X\}$ is closed in $X \times X$ and hence Borel. Consequently,
    \begin{align*}
        {\preceq_I} = \Delta_X \cup (H \times H)^{-1}(\sqsubset) \in \mathcal{B}(X \times X),
    \end{align*}
    as desired.

results.statement:
\label{prop:identifier-tie-breaking-borel}
    Let $(Y,d_Y)$ be a metric space, let $(I,\leq)$ be a countable, totally ordered set, and let $X=Y\times I$ be endowed with the metric
    \begin{align*}
        d\bigl((y,i),(y^\prime,j)\bigr)=\max\bigl(d_Y(y,y^\prime),d_I(i,j)\bigr),
        \qquad
        d_I(i,j)=\mathbbm{1}(i\neq j).
    \end{align*}
    Let $(K,d_K)$ be a separable metric space with a strict total order $<$ such that ${<}\in\mathcal{B}(K\times K)$, and let $h:Y\to K$ be Borel measurable. Then the relation $\preceq_I$ of Proposition~\ref{prop:identifier-tie-breaking} is a Borel partial order on $X$, that is, ${\preceq_I}\in\mathcal{B}(X\times X)$.

\label{defn:modification}\index{modification}
    Let $X$ be a non-empty set, let $\mathscr{T}(X)$ be the associated set of tuples, and let $\mathscr{L}(X)$ be the set of labelled finite sets over $X$. Let $\circledast:\mathscr{T}(X) \times \mathscr{L}(X)\to \mathscr{T}(X)$ be the map defined by
    \begin{align*}
        \bm{x} \circledast \xi &: \mathrm{domain}(\bm{x}) \to X\\
        i &\mapsto \begin{cases}
            \bm{x}(i) & i \in \mathrm{domain}(\bm{x}) \text{ and } i \notin \{j \mid \exists z \in X: (j,z) \in \xi\}\\
            z & (i, z) \in \xi \text{ and } i \in \mathrm{domain}(\bm{x}).
        \end{cases}
    \end{align*}
    Moreover, if $(X, \preceq)$ is a partially ordered set, and $\mathscr{S}(X,\preceq)$ is the space of sorted tuples, and $\varsigma:\mathscr{T}(X) \to \mathscr{S}(X,\preceq)$ is a fixed sorting map, then we define $\ast: \mathscr{T}(X)\times \mathscr{L}(X) \to \mathscr{S}(X,\preceq)$ by
    \begin{align*}
        \bm{x} \ast \xi = \varsigma(\bm{x} \circledast \xi).
    \end{align*}

steps.text:
For \eqref{property:concat-continuous}, suppose that
    \begin{align*}
        \max(\mathscr{d}_H(\bm{x}, \bm{x}_0), \mathscr{d}_H(\bm{y}, \bm{y}_0)) < \delta.
    \end{align*}
    Since $\delta < 1$, the \hyperref[thm:the-standard-machinery]{standard machinery} (Theorem~\ref{thm:the-standard-machinery}) implies
    \begin{align*}
        m \overset{\mathrm{def}}{=} \ell(\bm{x}) = \ell(\bm{x}_0)
        \qquad \text{and} \qquad
        n \overset{\mathrm{def}}{=} \ell(\bm{y}) = \ell(\bm{y}_0),
    \end{align*}
    and, since $\min(\mathscr{d}_H,1)=\min(d_\infty,1)$ on each layer, where $d_\infty$ is the maximum pointwise metric, the two distances coincide on each layer whenever either is below $1$. If $m+n = 0$, then both outputs are empty tuples and there is nothing to show. Otherwise,
    \begin{align*}
        \mathscr{d}_H(\bm{x}\oplus\bm{y}, \bm{x}_0\oplus\bm{y}_0)
        = \max_{i \in \{1,\dots,m+n\}} d\big((\bm{x}\oplus\bm{y})(i),(\bm{x}_0\oplus\bm{y}_0)(i)\big)
        < \delta < \varepsilon.
    \end{align*}
    Hence $\oplus$ is continuous.

For \eqref{property:cancel-continuous}, suppose that
    \begin{align*}
        \max(\mathscr{d}_H(\bm{x}, \bm{x}_0), d_H(\eta,\eta_0)) < \delta.
    \end{align*}
    Again, $\delta < 1$ implies $\ell(\bm{x}) = \ell(\bm{x}_0)$ and
    \begin{align*}
        d_H(\eta,\eta_0) < 1 \implies \eta = \eta_0
    \end{align*}
    because $(\mathbb{N},|\cdot|)$ is uniformly discrete and hence so is $(\mathscr{F}(\mathbb{N}),d_H)$ by Proposition~\ref{prop:finite-hausdorff-uniformly-discrete}. Let
    \begin{align*}
        I = \mathrm{domain}(\bm{x}_0)\setminus \eta_0.
    \end{align*}
    If $I = \emptyset$, then both $\bm{x}\ominus\eta$ and $\bm{x}_0\ominus\eta_0$ are empty tuples, so the distance is $0$. Otherwise, if
    \begin{align*}
        I = \{i_1 < \dots < i_k\},
    \end{align*}
    then reindexing simply produces the tuples
    \begin{align*}
        \bm{x}\ominus\eta &= r \mapsto \bm{x}(i_r),\\
        \bm{x}_0\ominus\eta_0 &= r \mapsto \bm{x}_0(i_r),
    \end{align*}
    and therefore
    \begin{align*}
        \mathscr{d}_H(\bm{x}\ominus\eta, \bm{x}_0\ominus\eta_0)
        &= \max_{r\in\{1,\dots,k\}} d(\bm{x}(i_r), \bm{x}_0(i_r))\\
        &\leq \max_{i \in \mathrm{domain}(\bm{x}_0)} d(\bm{x}(i), \bm{x}_0(i))\\
        &< \delta < \varepsilon.
    \end{align*}
    Hence $\ominus$ is continuous.

Finally, consider \eqref{property:modification-continuous} and suppose that
    \begin{align*}
        \max(\mathscr{d}_H(\bm{x}, \bm{x}_0), d_H^\ast(\xi,\xi_0)) < \delta.
    \end{align*}
    Since $\delta < 1$, the tuple part gives $\ell(\bm{x}) = \ell(\bm{x}_0)$, and as $d_H^\ast(\xi,\xi_0)<1$, Lemma~\ref{lem:helpful-labelled} shows that $\xi$ and $\xi_0$ have exactly the same set of indices. Denote this common finite index set by
    \begin{align*}
        D = \{n\in\mathbb{N}\mid \exists z\in X:(n,z)\in\xi\} = \{n\in\mathbb{N}\mid \exists z\in X:(n,z)\in\xi_0\}.
    \end{align*}
    Moreover, for every $n \in D$ there are unique elements $\xi(n), \xi_0(n) \in X$ with
    \begin{align*}
        (n,\xi(n)) \in \xi
        \qquad \text{and} \qquad
        (n,\xi_0(n)) \in \xi_0,
    \end{align*}
    and they satisfy
    \begin{align*}
        d(\xi(n),\xi_0(n)) < \delta.
    \end{align*}

If $\ell(\bm{x}_0)=0$, then both $\bm{x}\circledast\xi$ and $\bm{x}_0\circledast\xi_0$ are empty tuples, so their tuple Hausdorff distance is $0$. We may therefore assume that $\ell(\bm{x}_0)>0$.
    Now let $m = \ell(\bm{x}_0) = \ell(\bm{x})$. For each $i \in \{1,\dots,m\}$ there are two cases. If $i \notin D$, then
    \begin{align*}
        (\bm{x}\circledast \xi)(i) = \bm{x}(i)
        \qquad \text{and} \qquad
        (\bm{x}_0\circledast \xi_0)(i) = \bm{x}_0(i).
    \end{align*}
    If $i \in D$, then
    \begin{align*}
        (\bm{x}\circledast \xi)(i) = \xi(i)
        \qquad \text{and} \qquad
        (\bm{x}_0\circledast \xi_0)(i) = \xi_0(i).
    \end{align*}
    Hence, for every $i \in \{1,\dots,m\}$,
    \begin{align*}
        d\big((\bm{x}\circledast \xi)(i), (\bm{x}_0\circledast \xi_0)(i)\big) < \delta.
    \end{align*}
    By the \hyperref[thm:the-standard-machinery]{standard machinery}, the output tuples lie on the same length layer, so
    \begin{align*}
        \mathscr{d}_H(\bm{x}\circledast \xi, \bm{x}_0\circledast \xi_0)
        = \max_{i\in\{1,\dots,m\}} d\big((\bm{x}\circledast \xi)(i), (\bm{x}_0\circledast \xi_0)(i)\big)
        < \delta < \varepsilon.
    \end{align*}
    Therefore, $\circledast$ is continuous.

proof.text:
Let $\varepsilon > 0$ and fix $\delta \in (0,\min(1,\varepsilon))$.

    For \eqref{property:concat-continuous}, suppose that
    \begin{align*}
        \max(\mathscr{d}_H(\bm{x}, \bm{x}_0), \mathscr{d}_H(\bm{y}, \bm{y}_0)) < \delta.
    \end{align*}
    Since $\delta < 1$, the \hyperref[thm:the-standard-machinery]{standard machinery} (Theorem~\ref{thm:the-standard-machinery}) implies
    \begin{align*}
        m \overset{\mathrm{def}}{=} \ell(\bm{x}) = \ell(\bm{x}_0)
        \qquad \text{and} \qquad
        n \overset{\mathrm{def}}{=} \ell(\bm{y}) = \ell(\bm{y}_0),
    \end{align*}
    and, since $\min(\mathscr{d}_H,1)=\min(d_\infty,1)$ on each layer, where $d_\infty$ is the maximum pointwise metric, the two distances coincide on each layer whenever either is below $1$. If $m+n = 0$, then both outputs are empty tuples and there is nothing to show. Otherwise,
    \begin{align*}
        \mathscr{d}_H(\bm{x}\oplus\bm{y}, \bm{x}_0\oplus\bm{y}_0)
        = \max_{i \in \{1,\dots,m+n\}} d\big((\bm{x}\oplus\bm{y})(i),(\bm{x}_0\oplus\bm{y}_0)(i)\big)
        < \delta < \varepsilon.
    \end{align*}
    Hence $\oplus$ is continuous.

    For \eqref{property:cancel-continuous}, suppose that
    \begin{align*}
        \max(\mathscr{d}_H(\bm{x}, \bm{x}_0), d_H(\eta,\eta_0)) < \delta.
    \end{align*}
    Again, $\delta < 1$ implies $\ell(\bm{x}) = \ell(\bm{x}_0)$ and
    \begin{align*}
        d_H(\eta,\eta_0) < 1 \implies \eta = \eta_0
    \end{align*}
    because $(\mathbb{N},|\cdot|)$ is uniformly discrete and hence so is $(\mathscr{F}(\mathbb{N}),d_H)$ by Proposition~\ref{prop:finite-hausdorff-uniformly-discrete}. Let
    \begin{align*}
        I = \mathrm{domain}(\bm{x}_0)\setminus \eta_0.
    \end{align*}
    If $I = \emptyset$, then both $\bm{x}\ominus\eta$ and $\bm{x}_0\ominus\eta_0$ are empty tuples, so the distance is $0$. Otherwise, if
    \begin{align*}
        I = \{i_1 < \dots < i_k\},
    \end{align*}
    then reindexing simply produces the tuples
    \begin{align*}
        \bm{x}\ominus\eta &= r \mapsto \bm{x}(i_r),\\
        \bm{x}_0\ominus\eta_0 &= r \mapsto \bm{x}_0(i_r),
    \end{align*}
    and therefore
    \begin{align*}
        \mathscr{d}_H(\bm{x}\ominus\eta, \bm{x}_0\ominus\eta_0)
        &= \max_{r\in\{1,\dots,k\}} d(\bm{x}(i_r), \bm{x}_0(i_r))\\
        &\leq \max_{i \in \mathrm{domain}(\bm{x}_0)} d(\bm{x}(i), \bm{x}_0(i))\\
        &< \delta < \varepsilon.
    \end{align*}
    Hence $\ominus$ is continuous.

    Finally, consider \eqref{property:modification-continuous} and suppose that
    \begin{align*}
        \max(\mathscr{d}_H(\bm{x}, \bm{x}_0), d_H^\ast(\xi,\xi_0)) < \delta.
    \end{align*}
    Since $\delta < 1$, the tuple part gives $\ell(\bm{x}) = \ell(\bm{x}_0)$, and as $d_H^\ast(\xi,\xi_0)<1$, Lemma~\ref{lem:helpful-labelled} shows that $\xi$ and $\xi_0$ have exactly the same set of indices. Denote this common finite index set by
    \begin{align*}
        D = \{n\in\mathbb{N}\mid \exists z\in X:(n,z)\in\xi\} = \{n\in\mathbb{N}\mid \exists z\in X:(n,z)\in\xi_0\}.
    \end{align*}
    Moreover, for every $n \in D$ there are unique elements $\xi(n), \xi_0(n) \in X$ with
    \begin{align*}
        (n,\xi(n)) \in \xi
        \qquad \text{and} \qquad
        (n,\xi_0(n)) \in \xi_0,
    \end{align*}
    and they satisfy
    \begin{align*}
        d(\xi(n),\xi_0(n)) < \delta.
    \end{align*}

If $\ell(\bm{x}_0)=0$, then both $\bm{x}\circledast\xi$ and $\bm{x}_0\circledast\xi_0$ are empty tuples, so their tuple Hausdorff distance is $0$. We may therefore assume that $\ell(\bm{x}_0)>0$.
    Now let $m = \ell(\bm{x}_0) = \ell(\bm{x})$. For each $i \in \{1,\dots,m\}$ there are two cases. If $i \notin D$, then
    \begin{align*}
        (\bm{x}\circledast \xi)(i) = \bm{x}(i)
        \qquad \text{and} \qquad
        (\bm{x}_0\circledast \xi_0)(i) = \bm{x}_0(i).
    \end{align*}
    If $i \in D$, then
    \begin{align*}
        (\bm{x}\circledast \xi)(i) = \xi(i)
        \qquad \text{and} \qquad
        (\bm{x}_0\circledast \xi_0)(i) = \xi_0(i).
    \end{align*}
    Hence, for every $i \in \{1,\dots,m\}$,
    \begin{align*}
        d\big((\bm{x}\circledast \xi)(i), (\bm{x}_0\circledast \xi_0)(i)\big) < \delta.
    \end{align*}
    By the \hyperref[thm:the-standard-machinery]{standard machinery}, the output tuples lie on the same length layer, so
    \begin{align*}
        \mathscr{d}_H(\bm{x}\circledast \xi, \bm{x}_0\circledast \xi_0)
        = \max_{i\in\{1,\dots,m\}} d\big((\bm{x}\circledast \xi)(i), (\bm{x}_0\circledast \xi_0)(i)\big)
        < \delta < \varepsilon.
    \end{align*}
    Therefore, $\circledast$ is continuous.

results.statement:
\label{thm:analytic-properties-actions}
    Let $(X,d)$ be a metric space, and let
    \begin{enumerate}[-]
        \item $(\mathscr{T}(X), \mathscr{d}_H)$ be the tuple space over $X$ endowed with the tuple Hausdorff distance, 
        \item $(\mathscr{F}(\mathbb{N}), d_H)$ be the set of finite subsets of the natural numbers, endowed with the Hausdorff distance induced by the Euclidean distance, and 
        \item $(\mathscr{L}(X), d_H^\ast)$ be the set of labelled finite sets over $X$, endowed with the index-augmented Hausdorff distance.
    \end{enumerate}
    If all product spaces are endowed with the product metrics, then 
    \begin{enumerate}[(i)]
        \item $\oplus:\mathscr{T}(X) \times \mathscr{T}(X) \to \mathscr{T}(X)$ as defined in Definition~\ref{defn:concat-tuple} is continuous\index{continuity!primitive actions},\label{property:concat-continuous}
        \item $\ominus:\mathscr{T}(X)\times \mathscr{F}(\mathbb{N})\to\mathscr{T}(X)$ as defined in Definition~\ref{defn:cancel} is continuous, and \label{property:cancel-continuous}
        \item $\circledast:\mathscr{T}(X) \times \mathscr{L}(X) \to \mathscr{T}(X)$ as defined in Definition~\ref{defn:modification} is continuous. \label{property:modification-continuous}
    \end{enumerate}

steps.text:
To prove \eqref{property:identifier-cancel-continuous}, we must show that for every $(\bm{x}_0, J_0) \in \mathscr{T}(X) \times \mathscr{F}(I)$ and every $\varepsilon > 0$, there exists a $\delta > 0$ such that
    \begin{align*}
        \max\bigl(\mathscr{d}_H(\bm{x}, \bm{x}_0), d_H(J, J_0)\bigr) < \delta \implies \mathscr{d}_H(\bm{x} \ominus_I J, \bm{x}_0 \ominus_I J_0) < \varepsilon.
    \end{align*}
    Fix $\varepsilon > 0$ and choose $\delta \in (0, \min(1, \varepsilon))$. Suppose that $\max(\mathscr{d}_H(\bm{x},\bm{x}_0),d_H(J,J_0))<\delta < 1$. By the \hyperref[thm:the-standard-machinery]{standard machinery} (Theorem~\ref{thm:the-standard-machinery}), we have $\ell(\bm{x})=\ell(\bm{x}_0)$ and, whenever $\ell(\bm{x}_0) > 0$,
    \begin{align*}
        d(\bm{x}(k),\bm{x}_0(k)) < \delta < 1 \qquad \forall k \in \mathrm{domain}(\bm{x}_0).
    \end{align*}
    By the definition of $d$ and $d_I$, the inequality $d(\bm{x}(k),\bm{x}_0(k)) < 1$ implies $\mathrm{id}(\bm{x}(k))=\mathrm{id}(\bm{x}_0(k))$ for every $k \in \mathrm{domain}(\bm{x}_0)$. Furthermore, since $(I,d_I)$ is uniformly discrete with bound $1$, so is $(\mathscr{F}(I),d_H)$ by Proposition~\ref{prop:finite-hausdorff-uniformly-discrete}, whence $d_H(J, J_0) < 1$ implies $J=J_0$. Consequently, the index sets of matching identifiers coincide:
    \begin{align*}
        \eta_J(\bm{x}) &= \{k \in \mathrm{domain}(\bm{x}) \mid \mathrm{id}(\bm{x}(k)) \in J\}\\
        &= \{k \in \mathrm{domain}(\bm{x}_0) \mid \mathrm{id}(\bm{x}_0(k)) \in J_0\} = \eta_{J_0}(\bm{x}_0).
    \end{align*}
    On this neighbourhood, we therefore have $\bm{x}\ominus_I J=\bm{x}\ominus\eta_{J_0}(\bm{x}_0)$ and $\bm{x}_0 \ominus_I J_0 = \bm{x}_0 \ominus \eta_{J_0}(\bm{x}_0)$, so the proof of Theorem~\ref{thm:analytic-properties-actions}\eqref{property:cancel-continuous} yields
    \begin{align*}
        \mathscr{d}_H(\bm{x} \ominus_I J, \bm{x}_0 \ominus_I J_0) = \mathscr{d}_H\bigl(\bm{x} \ominus \eta_{J_0}(\bm{x}_0), \bm{x}_0 \ominus \eta_{J_0}(\bm{x}_0)\bigr) < \delta < \varepsilon,
    \end{align*}
    which proves that $\ominus_I$ is continuous.

Next, we prove \eqref{property:identifier-distinct-clopen}. By the \hyperref[thm:the-standard-machinery]{standard machinery}, each fixed-length layer $X^n$ is clopen in $\mathscr{T}(X)$. For $n \in \{0, 1\}$, we have $\mathscr{T}_{
eq}(X) \cap X^n = X^n$, which is clopen. For $n \geq 2$, the intersection of $\mathscr{T}_{
eq}(X)$ with $X^n$ is given by
     egin{align*}
        \mathscr{T}_{
eq}(X) \cap X^n =  igcap_{1 \leq k < l \leq n}  igl\{ m{x} \in X^n  igm| \mathrm{id}( m{x}(k)) 
eq \mathrm{id}( m{x}(l)) igr\}.
    \end{align*}
    Because $\mathrm{id}:X 	o (I, d_I)$ is locally constant, each comparison set in the intersection is clopen in $X^n$, so $\mathscr{T}_{
eq}(X) \cap X^n$ is clopen in $X^n$ for every $n \in \mathbb{N}_0$, and hence $\mathscr{T}_{
eq}(X)$ is clopen in $\mathscr{T}(X)$. By the same argument on the clopen product layers $X^n 	imes X^m$, the set of pairs
     egin{align*}
         igl\{( m{x},  m{y}) \in \mathscr{T}_{
eq}(X)^2  igm|  orall k \in \mathrm{domain}( m{x})\,  orall l \in \mathrm{domain}( m{y}) : \mathrm{id}( m{x}(k)) 
eq \mathrm{id}( m{y}(l)) igr\}
    \end{align*}
    is clopen in $\mathscr{T}_{
