    \end{align*}
    is continuous and hence Borel measurable. Now, notice that 
    \begin{align*}
        I_n = \bigcap_{i =2}^n \Delta_{i, i-1}^{-1}([0,\infty)),
    \end{align*}
    which is a finite intersection of Borel measurable sets and hence Borel measurable. Likewise, 
    \begin{align*}
        D_n = \bigcap_{i=2}^n \Delta_{i, i-1}^{-1}((-\infty,0])
    \end{align*}
    is a finite intersection of Borel measurable sets and hence Borel measurable, as desired.

results.statement:
\label{lem:increasing-decreasing-measurable}
    For any $n \in \mathbb{N}$, the sets 
    \begin{align*}
        I_n = \{\bm{x}\in \mathbb{R}^n \mid \bm{x}(1) \leq \dots \leq \bm{x}(n)\},
    \end{align*}
    and 
    \begin{align*}
        D_n =\{\bm{x}\in \mathbb{R}^n \mid \bm{x}(1) \geq \dots \geq \bm{x}(n)\}
    \end{align*}
    are Borel measurable sets in $\mathbb{R}^n$.

steps.text:
We must show that $L^{i,j}_{n,m} \in \mathcal{B}(\mathbb{R}^n \times \mathbb{R}^m)$ and $G^{i,j}_{n,m} \in \mathcal{B}(\mathbb{R}^n \times \mathbb{R}^m)$. Analogously to the proof of Lemma~\ref{lem:increasing-decreasing-measurable}, define the function $\Lambda_{i,j} : \mathbb{R}^n \times \mathbb{R}^m \to \mathbb{R}$ by
    \begin{align*}
        \Lambda_{i,j}(\bm{x},\bm{y}) = \bm{y}(j) - \bm{x}(i),
    \end{align*}
    which for each $i \in \{1,\dots, n\}$ and $j \in \{1,\dots,m\}$ is a continuous function and hence Borel measurable. Then
    \begin{align*}
        L_{n,m}^{i,j} = \Lambda_{i,j}^{-1}([0,\infty)) \cap (I_n\times D_m),
    \end{align*}
    and likewise
    \begin{align*}
        G_{n,m}^{i,j} = \Lambda_{i,j}^{-1}((-\infty,0)) \cap (I_n \times D_m).
    \end{align*}
    Both sets are Borel measurable, since $(I_n \times D_m) \in \mathcal{B}(\mathbb{R}^n)\otimes\mathcal{B}(\mathbb{R}^m) =\mathcal{B}(\mathbb{R}^n \times \mathbb{R}^m)$ by Lemma~\ref{lem:increasing-decreasing-measurable}, and each $\Lambda_{i,j}$ is continuous and hence Borel measurable. Because the intersection of two Borel measurable sets is Borel measurable, the claim follows, as desired.

