    which proves \eqref{eq:lem-helpful-point-process-1}. 

    \textbf{Proof of \eqref{eq:lem-helpful-point-process-3}:} Apply \eqref{eq:lem-helpful-point-process-1} and \eqref{eq:lem-helpful-point-process-2} with $B=X$. Since $X^\varepsilon = X$, we obtain
    \begin{align*}
        \xi(X) \leq \eta(X) \quad \text{and} \quad \eta(X) \leq \xi(X),
