    which implies that $\xi(X) = \eta(X)$.

results.statement:
\label{lem:helpful-point-process}
    Let $(X,d)$ be a complete and separable metric space, endowed with its Borel $\sigma$-algebra, $\mathcal{B}(X)$, and let $(\mathcal{N}(X),\rho)$ be the associated space of finite integer-valued measures endowed with the Prokhorov metric. Then, for all $\xi,\eta\in\mathcal{N}(X)$ and $\varepsilon\in(0,1)$ with $\rho(\xi,\eta)<\varepsilon$, we have
    \begin{enumerate}[(i)]
        \item for all $B \in \Sigma$, $\xi(B) \leq \eta(B^\varepsilon)$;\label{eq:lem-helpful-point-process-1} 
        \item for all $B \in \Sigma$, $\eta(B) \leq \xi(B^\varepsilon)$; and\label{eq:lem-helpful-point-process-2}
        \item $\xi(X) = \eta(X)$. \label{eq:lem-helpful-point-process-3} 
    \end{enumerate}

steps.text:
The result follows from \eqref{eq:lem-helpful-point-process-3} of Lemma~\ref{lem:helpful-point-process}, since 
    \begin{align*}
        \xi(X) = \sum_{k\leq \kappa} \beta_k = \sum_{l \leq \lambda} \alpha_l = \eta(X). 
    \end{align*}

proof.text:
The result follows from \eqref{eq:lem-helpful-point-process-3} of Lemma~\ref{lem:helpful-point-process}, since 
    \begin{align*}
        \xi(X) = \sum_{k\leq \kappa} \beta_k = \sum_{l \leq \lambda} \alpha_l = \eta(X). 
    \end{align*}

results.statement:
\label{cor:measures-coincide}
    Let $(X,d)$ be a complete and separable metric space, set $\Sigma=\mathcal{B}(X)$, and let $(\mathcal{N}(X),\rho)$ be the associated space of finite integer-valued measures endowed with the Prokhorov metric. Let $\xi,\eta\in\mathcal{N}(X)$ and suppose that $\xi$ and $\eta$ admit the atomic decompositions
    \begin{align*}
        \xi &= \sum_{k\leq \kappa} \beta_k \delta_{x_k},\\
        \eta &= \sum_{l \leq \lambda} \alpha_l \delta_{y_l}.
    \end{align*}
    If $\rho(\xi, \eta) < 1$, then
    \begin{align*}
        \sum_{k \leq \kappa} \beta_k = \sum_{l\leq \lambda} \alpha_l. 
    \end{align*}

steps.text:
We prove the properties simultaneously; let $k \in \{1,\dots, \kappa\}$ be arbitrary, and note that 
    \begin{align*}
        \{x_k\} \in \mathcal{B}(X)
    \end{align*}
    and
    \begin{align*}
        \{x_k\}^\varepsilon = B_\varepsilon(x_k) \in \mathcal{B}(X).
    \end{align*}
    Recall that $\rho(\xi, \eta) < \varepsilon < 1$ implies that 
    \begin{align*}
        \xi(B) \leq \eta(B^\varepsilon),
    \end{align*}
     by Lemma~\ref{lem:helpful-point-process}. In particular, the above yields the bound  
    \begin{align*}
        \xi(\{x_k\}) = \beta_k \leq \eta(B_\varepsilon(x_k)),
    \end{align*} 
    for all $k \leq \kappa$. In addition, since $\varepsilon < \gamma$ it holds that
    \begin{align*}
        \eta(B_\varepsilon(x_k)) \leq \xi((B_{\varepsilon}(x_k))^{\varepsilon}) \leq \xi(B_{2\varepsilon}(x_k)) = \beta_k, 
    \end{align*}
    where the first inequality is \eqref{eq:lem-helpful-point-process-2} of Lemma~\ref{lem:helpful-point-process}, the second follows from $(B_{\varepsilon}(x_k))^{\varepsilon}\subseteq B_{2\varepsilon}(x_k)$ by the triangle inequality, and the equality holds because $2\varepsilon<2\gamma\leq d(x_k,x_{k^\prime})$ for every $k^\prime\neq k$;
    and hence
    \begin{align*}
        \beta_k = \eta(B_\varepsilon(x_k)). 
    \end{align*}
    Consequently, 
    \begin{align*}
        \beta_k = \sum_{l \leq \lambda}\alpha_l \delta_{y_l}(B_\varepsilon(x_k)),
    \end{align*}
    and hence, we may define 
    \begin{align*}
        L_k = \{l \in \{1,\dots, \lambda\} \mid \delta_{y_l}(B_\varepsilon(x_k)) = 1 \}. 
    \end{align*}
    Note that by construction,   
    \begin{align*}
        \delta_{y_l}(B_\varepsilon(x_k)) = 1 \iff d(y_l, x_k) < \varepsilon,
    \end{align*}
    as desired. Next, let $k \in \{1,\dots, \kappa\}$ and $l \in L_k$. Then
    \begin{align*}
        d(x_k, y_l) < \varepsilon.
    \end{align*}
    If $k^\prime \neq k$, then by the triangle inequality and the definition of $\gamma$ we have 
    \begin{align*}
        d(x_{k^\prime}, y_l) \geq d(x_k, x_{k^\prime}) - d(x_k, y_l) > 2\gamma - \varepsilon > \varepsilon,
    \end{align*}
    which implies $l \notin L_{k^\prime}$ for $k^\prime \neq k$.

proof.text:
First, note that since $(X,d)$ is a metric space, the Borel $\sigma$-algebra contains all singletons as well as all open balls $B_\varepsilon(x) = \{x^\prime \in X \mid d(x,x^\prime) < \varepsilon\}$. 

    We prove the properties simultaneously; let $k \in \{1,\dots, \kappa\}$ be arbitrary, and note that 
    \begin{align*}
        \{x_k\} \in \mathcal{B}(X)
    \end{align*}
    and
    \begin{align*}
        \{x_k\}^\varepsilon = B_\varepsilon(x_k) \in \mathcal{B}(X).
    \end{align*}
    Recall that $\rho(\xi, \eta) < \varepsilon < 1$ implies that 
    \begin{align*}
        \xi(B) \leq \eta(B^\varepsilon),
    \end{align*}
     by Lemma~\ref{lem:helpful-point-process}. In particular, the above yields the bound  
    \begin{align*}
        \xi(\{x_k\}) = \beta_k \leq \eta(B_\varepsilon(x_k)),
    \end{align*} 
    for all $k \leq \kappa$. In addition, since $\varepsilon < \gamma$ it holds that
    \begin{align*}
        \eta(B_\varepsilon(x_k)) \leq \xi((B_{\varepsilon}(x_k))^{\varepsilon}) \leq \xi(B_{2\varepsilon}(x_k)) = \beta_k, 
    \end{align*}
    where the first inequality is \eqref{eq:lem-helpful-point-process-2} of Lemma~\ref{lem:helpful-point-process}, the second follows from $(B_{\varepsilon}(x_k))^{\varepsilon}\subseteq B_{2\varepsilon}(x_k)$ by the triangle inequality, and the equality holds because $2\varepsilon<2\gamma\leq d(x_k,x_{k^\prime})$ for every $k^\prime\neq k$;
    and hence
    \begin{align*}
        \beta_k = \eta(B_\varepsilon(x_k)). 
    \end{align*}
    Consequently, 
    \begin{align*}
        \beta_k = \sum_{l \leq \lambda}\alpha_l \delta_{y_l}(B_\varepsilon(x_k)),
    \end{align*}
    and hence, we may define 
    \begin{align*}
        L_k = \{l \in \{1,\dots, \lambda\} \mid \delta_{y_l}(B_\varepsilon(x_k)) = 1 \}. 
    \end{align*}
    Note that by construction,   
    \begin{align*}
        \delta_{y_l}(B_\varepsilon(x_k)) = 1 \iff d(y_l, x_k) < \varepsilon,
    \end{align*}
    as desired. Next, let $k \in \{1,\dots, \kappa\}$ and $l \in L_k$. Then
    \begin{align*}
        d(x_k, y_l) < \varepsilon.
    \end{align*}
    If $k^\prime \neq k$, then by the triangle inequality and the definition of $\gamma$ we have 
    \begin{align*}
        d(x_{k^\prime}, y_l) \geq d(x_k, x_{k^\prime}) - d(x_k, y_l) > 2\gamma - \varepsilon > \varepsilon,
    \end{align*}
    which implies $l \notin L_{k^\prime}$ for $k^\prime \neq k$.

    It remains to show that the sets $L_k$ cover all atoms of $\eta$. By the first conclusion and disjointness,
    \begin{align*}
        \sum_{k\leq \kappa}\beta_k
        = \sum_{k\leq \kappa}\sum_{l\in L_k}\alpha_l
        = \sum_{l\in \cup_{k\leq \kappa} L_k}\alpha_l.
    \end{align*}
    Since $\rho(\xi,\eta)<\varepsilon<1$, Lemma~\ref{lem:helpful-point-process} gives $\xi(X)=\eta(X)$, equivalently $\sum_{k\leq\kappa}\beta_k=\sum_{l\leq\lambda}\alpha_l$ as in Corollary~\ref{cor:measures-coincide}. All multiplicities $\alpha_l$ are positive, so no index $l\in\{1,\dots,\lambda\}$ can be missing from $\cup_{k\leq\kappa}L_k$.

results.statement:
\label{lem:disintegration-lemma}
    Let $(X,d)$ be a complete and separable metric space, and let $(\mathcal{N}(X), \rho)$ be the associated Prokhorov space of finite integer-valued measures on $(X, \mathcal{B}(X))$. Let $\xi \in \mathcal{N}(X)$ be a non-zero measure with atomic decomposition 
    \begin{align*}
        \xi = \sum_{k\leq \kappa} \beta_k \delta_{x_k}.
    \end{align*}
    Let 
    \begin{align*}
        \gamma = \begin{cases}
            1, & \kappa = 1,\\
            \min\left(\frac{1}{2} \min_{\substack{k, k^\prime \leq \kappa \\ k \neq k^\prime}} d(x_k, x_{k^\prime}), 1 \right), & \kappa \geq 2,
        \end{cases}
    \end{align*}
    and $0 < \varepsilon < \gamma$. Let $\eta \in \mathcal{N}(X)$ be another measure with atomic decomposition 
    \begin{align*}
        \eta = \sum_{l\leq \lambda} \alpha_l \delta_{y_l}.
    \end{align*}
    If $\rho(\xi, \eta) < \varepsilon$, then $\eta\neq0$ by \eqref{eq:lem-helpful-point-process-3} of Lemma~\ref{lem:helpful-point-process}, and the sets $L_k = \{l\in\{1,\dots,\lambda\} \mid d(x_k,y_l)<\varepsilon\}$, $k\in\{1,\dots,\kappa\}$, satisfy:
    \begin{enumerate}[(i)]
        \item for every $k \in \{1,\dots,\kappa\}$, $\beta_k = \sum_{l \in L_k} \alpha_l$; 
        \item for all distinct $k, k^\prime \in \{1,\dots, \kappa\}$, $L_k \cap L_{k^\prime} = \emptyset$;
        \item for every $k \in \{1,\dots, \kappa\}$, it holds that $\max_{l \in L_k} d(x_k, y_l) < \varepsilon$; and 
        \item the sets $(L_k)_{k\leq \kappa}$ cover the atoms of $\eta$, i.e.
        \begin{align*}
            \bigcup_{k\leq \kappa} L_k = \{1,\dots,\lambda\}.
        \end{align*}
    \end{enumerate}

\label{defn:permutative-equality}\index{permutative equality}
    Let $X$ be a set. Let $\overset{\pi}{\sim} \subseteq \mathscr{T}(X)\times \mathscr{T}(X)$ be the relation defined by 
    \begin{align*}
        \bm{x} \overset{\pi}{\sim} \bm{x}^\prime \iff \ell(\bm{x}) =\ell(\bm{x}^\prime) \land \exists \sigma \in \mathscr{P}_{\ell(\bm{x})} : \bm{x} = \bm{x}^\prime\circ\sigma.
    \end{align*}
    For any two elements $\bm{x} \overset{\pi}{\sim} \bm{x}^\prime$, we say that $\bm{x}$ and $\bm{x}^{\prime}$ are equal up to a permutation, and we call the property permutative equality.

steps.text:
For any $\bm{x},\bm{x}^\prime, \bm{x}^\ast \in \mathscr{T}(X)$ we must show that 
    \begin{enumerate}
        \item $\bm{x} \overset{\pi}{\sim} \bm{x}$. \label{property:permutation-reflexive}
        \item $\bm{x} \overset{\pi}{\sim} \bm{x}^\prime$ if and only if $\bm{x}^\prime\overset{\pi}{\sim} \bm{x}$.\label{property:permutation-symmetry}
        \item If $\bm{x}\overset{\pi}{\sim} \bm{x}^\prime $ and $\bm{x}^\prime \overset{\pi}{\sim}  \bm{x}^\ast$, then $\bm{x} \overset{\pi}{\sim} \bm{x}^\ast$. \label{property:permutation-transitivity}
    \end{enumerate}
    For \eqref{property:permutation-reflexive}, notice that for any $\bm{x} \in \mathscr{T}(X)$ the mapping $\sigma:\mathrm{domain}(\bm{x}) \to \mathrm{domain}(\bm{x})$ defined by $\sigma(i) = i$ is a permutation, from which the result follows.

Finally, notice that if $\bm{x}\overset{\pi}{\sim} \bm{x}^\prime $ and $\bm{x}^\prime \overset{\pi}{\sim}  \bm{x}^\ast$, then we immediately have $\ell(\bm{x}) =\ell(\bm{x}^\prime) =\ell(\bm{x}^\ast)$. There exist $\sigma,\sigma^\prime \in \mathscr{P}_{\ell(\bm{x})}$ such that
    \begin{align*}
        \bm{x} = \bm{x}^\prime \circ \sigma \quad \text{and}\quad \bm{x}^\prime = \bm{x}^\ast \circ \sigma^\prime.
    \end{align*}
    Then
    \begin{align*}
        \bm{x} = \bm{x}^\ast \circ \sigma^{\prime} \circ \sigma,
    \end{align*}
    and moreover $\sigma^{\prime}\circ \sigma \in \mathscr{P}_{\ell(\bm{x})}$ as desired. Hence, the relation is transitive.

proof.text:
For any $\bm{x},\bm{x}^\prime, \bm{x}^\ast \in \mathscr{T}(X)$ we must show that 
    \begin{enumerate}
        \item $\bm{x} \overset{\pi}{\sim} \bm{x}$. \label{property:permutation-reflexive}
        \item $\bm{x} \overset{\pi}{\sim} \bm{x}^\prime$ if and only if $\bm{x}^\prime\overset{\pi}{\sim} \bm{x}$.\label{property:permutation-symmetry}
        \item If $\bm{x}\overset{\pi}{\sim} \bm{x}^\prime $ and $\bm{x}^\prime \overset{\pi}{\sim}  \bm{x}^\ast$, then $\bm{x} \overset{\pi}{\sim} \bm{x}^\ast$. \label{property:permutation-transitivity}
    \end{enumerate}
    For \eqref{property:permutation-reflexive}, notice that for any $\bm{x} \in \mathscr{T}(X)$ the mapping $\sigma:\mathrm{domain}(\bm{x}) \to \mathrm{domain}(\bm{x})$ defined by $\sigma(i) = i$ is a permutation, from which the result follows. 

    For \eqref{property:permutation-symmetry}, notice that if $\bm{x} \overset{\pi}{\sim} \bm{x}^\prime$, then there exists a $\sigma \in \mathscr{P}_{\ell(\bm{x})}$ such that $\bm{x} = \bm{x}^\prime \circ \sigma$. Since $\sigma$ is bijective, it is invertible, and $\bm{x} \circ \sigma^{-1} = \bm{x}^\prime \circ \sigma \circ \sigma^{-1} = \bm{x}^\prime$. Moreover, it is clear that $\sigma^{-1} \in \mathscr{P}_{\ell(\bm{x})} = \mathscr{P}_{\ell(\bm{x}^\prime)}$ as $\ell(\bm{x}) = \ell(\bm{x}^\prime)$ by assumption. Hence, the relation is symmetric. 

    Finally, notice that if $\bm{x}\overset{\pi}{\sim} \bm{x}^\prime $ and $\bm{x}^\prime \overset{\pi}{\sim}  \bm{x}^\ast$, then we immediately have $\ell(\bm{x}) =\ell(\bm{x}^\prime) =\ell(\bm{x}^\ast)$. There exist $\sigma,\sigma^\prime \in \mathscr{P}_{\ell(\bm{x})}$ such that
    \begin{align*}
        \bm{x} = \bm{x}^\prime \circ \sigma \quad \text{and}\quad \bm{x}^\prime = \bm{x}^\ast \circ \sigma^\prime.
    \end{align*}
    Then
    \begin{align*}
        \bm{x} = \bm{x}^\ast \circ \sigma^{\prime} \circ \sigma,
    \end{align*}
    and moreover $\sigma^{\prime}\circ \sigma \in \mathscr{P}_{\ell(\bm{x})}$ as desired. Hence, the relation is transitive.

results.statement:
\label{defn:permuted-tuple-quotient-space}
    For any set $X$ and tuple $\bm{x} \in \mathscr{T}(X)$, we define
    \begin{align*}
        \bm{x}^\pi = \{\bm{x}^\prime \in \mathscr{T}(X) \mid \bm{x} \overset{\pi}{\sim} \bm{x}^\prime\} 
    \end{align*}
     as the equivalence class induced by $\bm{x}$; any $\bm{x}^\prime \in \bm{x}^\pi$ is said to be equal to $\bm{x}$ up to a permutation. Moreover, we define 
     \begin{align*}
         \mathscr{T}^\pi(X) = \{\bm{x}^\pi \mid \bm{x} \in \mathscr{T}(X)\}
     \end{align*}
    as the quotient space\index{permuted tuple quotient space}, and call it the space of permuted tuples.

steps.text:
We must show that for every $\bm{y} \in \bm{x}^\pi$, the set of permutations
    \begin{align*}
        S(\bm{y}) = \{\sigma \in \mathscr{P}_n \mid \bm{x} \circ \sigma = \bm{y}\}
    \end{align*}
    has cardinality $|S(\bm{y})| = m_1! \cdots m_\kappa!$, and consequently that $|\bm{x}^\pi| = n! / (m_1! \cdots m_\kappa!)$. If $n = 0$, then $\bm{x} = \bm{e}$, $\mathscr{P}_0$ is a singleton, $\kappa = 0$, and the empty product equals $1$, so the claim holds immediately. Suppose therefore that $n > 0$, and let $a_1, \dots, a_\kappa \in X$ denote the distinct entries of $\bm{x}$. For each $j \in \{1, \dots, \kappa\}$, define the level set
    \begin{align*}
        I_j = \{i \in \{1, \dots, n\} \mid \bm{x}(i) = a_j\},
    \end{align*}
    which has cardinality $|I_j| = m_j$. A permutation $\sigma \in \mathscr{P}_n$ satisfies $\bm{x} \circ \sigma = \bm{x}$ if and only if $\bm{x}(\sigma(i)) = \bm{x}(i)$ for every $i \in \{1, \dots, n\}$, which holds if and only if $\sigma(I_j) = I_j$ for every $j \in \{1, \dots, \kappa\}$. Since the sets $I_1, \dots, I_\kappa$ partition $\{1, \dots, n\}$, choosing such a permutation $\sigma$ is equivalent to independently choosing a bijection of each $I_j$ onto itself. Therefore,
    \begin{align*}
        |S(\bm{x})| = m_1! \cdots m_\kappa!.
    \end{align*}

Now let $\bm{y} \in \bm{x}^\pi$ be arbitrary. By Definition~\ref{defn:permutative-equality}, there exists a permutation $\sigma_0 \in \mathscr{P}_n$ such that $\bm{y} = \bm{x} \circ \sigma_0$. For any $\sigma \in \mathscr{P}_n$, we have
    \begin{align*}
        \bm{x} \circ \sigma = \bm{y} = \bm{x} \circ \sigma_0 \iff \bm{x} \circ (\sigma \circ \sigma_0^{-1}) = \bm{x} \iff \sigma \circ \sigma_0^{-1} \in S(\bm{x}).
    \end{align*}
    Because the right-multiplication map $\sigma \mapsto \sigma \circ \sigma_0^{-1}$ is a bijection from $\mathscr{P}_n$ onto itself, it restricts to a bijection from $S(\bm{y})$ onto $S(\bm{x})$, whence $|S(\bm{y})| = |S(\bm{x})| = m_1! \cdots m_\kappa!$. Finally, since the sets $(S(\bm{y}))_{\bm{y} \in \bm{x}^\pi}$ form a partition of $\mathscr{P}_n$ into $|\bm{x}^\pi|$ subsets of equal cardinality $m_1! \cdots m_\kappa!$, we obtain
    \begin{align*}
        n! = |\mathscr{P}_n| = \sum_{\bm{y} \in \bm{x}^\pi} |S(\bm{y})| = |\bm{x}^\pi|\, m_1! \cdots m_\kappa!,
    \end{align*}
    which yields $|\bm{x}^\pi| = n! / (m_1! \cdots m_\kappa!) \leq n!$, as desired.

proof.text:
We must show that for every $\bm{y} \in \bm{x}^\pi$, the set of permutations
    \begin{align*}
        S(\bm{y}) = \{\sigma \in \mathscr{P}_n \mid \bm{x} \circ \sigma = \bm{y}\}
    \end{align*}
    has cardinality $|S(\bm{y})| = m_1! \cdots m_\kappa!$, and consequently that $|\bm{x}^\pi| = n! / (m_1! \cdots m_\kappa!)$. If $n = 0$, then $\bm{x} = \bm{e}$, $\mathscr{P}_0$ is a singleton, $\kappa = 0$, and the empty product equals $1$, so the claim holds immediately. Suppose therefore that $n > 0$, and let $a_1, \dots, a_\kappa \in X$ denote the distinct entries of $\bm{x}$. For each $j \in \{1, \dots, \kappa\}$, define the level set
    \begin{align*}
        I_j = \{i \in \{1, \dots, n\} \mid \bm{x}(i) = a_j\},
    \end{align*}
    which has cardinality $|I_j| = m_j$. A permutation $\sigma \in \mathscr{P}_n$ satisfies $\bm{x} \circ \sigma = \bm{x}$ if and only if $\bm{x}(\sigma(i)) = \bm{x}(i)$ for every $i \in \{1, \dots, n\}$, which holds if and only if $\sigma(I_j) = I_j$ for every $j \in \{1, \dots, \kappa\}$. Since the sets $I_1, \dots, I_\kappa$ partition $\{1, \dots, n\}$, choosing such a permutation $\sigma$ is equivalent to independently choosing a bijection of each $I_j$ onto itself. Therefore,
    \begin{align*}
        |S(\bm{x})| = m_1! \cdots m_\kappa!.
    \end{align*}

    Now let $\bm{y} \in \bm{x}^\pi$ be arbitrary. By Definition~\ref{defn:permutative-equality}, there exists a permutation $\sigma_0 \in \mathscr{P}_n$ such that $\bm{y} = \bm{x} \circ \sigma_0$. For any $\sigma \in \mathscr{P}_n$, we have
    \begin{align*}
        \bm{x} \circ \sigma = \bm{y} = \bm{x} \circ \sigma_0 \iff \bm{x} \circ (\sigma \circ \sigma_0^{-1}) = \bm{x} \iff \sigma \circ \sigma_0^{-1} \in S(\bm{x}).
    \end{align*}
    Because the right-multiplication map $\sigma \mapsto \sigma \circ \sigma_0^{-1}$ is a bijection from $\mathscr{P}_n$ onto itself, it restricts to a bijection from $S(\bm{y})$ onto $S(\bm{x})$, whence $|S(\bm{y})| = |S(\bm{x})| = m_1! \cdots m_\kappa!$. Finally, since the sets $(S(\bm{y}))_{\bm{y} \in \bm{x}^\pi}$ form a partition of $\mathscr{P}_n$ into $|\bm{x}^\pi|$ subsets of equal cardinality $m_1! \cdots m_\kappa!$, we obtain
    \begin{align*}
        n! = |\mathscr{P}_n| = \sum_{\bm{y} \in \bm{x}^\pi} |S(\bm{y})| = |\bm{x}^\pi|\, m_1! \cdots m_\kappa!,
    \end{align*}
    which yields $|\bm{x}^\pi| = n! / (m_1! \cdots m_\kappa!) \leq n!$, as desired.

results.statement:
\label{prop:finite-equivalence-classes}
    Let $X$ be a set, and let $\bm{x} \in \mathscr{T}(X)$ have length $n$ and distinct entries occurring $m_1,\dots,m_\kappa$ times (for the empty tuple, $\kappa=0$ and the empty product is $1$). Then every element of $\bm{x}^\pi$ equals $\bm{x}\circ\sigma$ for exactly $m_1!\cdots m_\kappa!$ permutations $\sigma\in\mathscr{P}_n$. In particular,
    \begin{align*}
        |\bm{x}^\pi| = \frac{n!}{m_1!\cdots m_\kappa!} \leq n!.
    \end{align*}

\label{defn:permuted-tuple-hausdorff-distance}
    Let $(X,d)$ be a metric space and put $\bar{d}(x,y)=\min\{d(x,y),1\}$. Define $\mathscr{d}_\pi : \mathscr{T}^\pi(X) \times \mathscr{T}^\pi(X) \to [0,1]$ by
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}^\pi,\bm{y}^\pi)
        =
        \begin{cases}
            1, & \ell(\bm{x})\neq\ell(\bm{y}),\\
            0, & \ell(\bm{x})=\ell(\bm{y})=0,\\
            \displaystyle\min_{\sigma\in\mathscr{P}_n}
            \max_{i\in\{1,\dots,n\}}
            \bar{d}\big(\bm{x}(i),\bm{y}(\sigma(i))\big),
            & \ell(\bm{x})=\ell(\bm{y})=n>0.
        \end{cases}
    \end{align*}
    We call $\mathscr{d}_\pi$ the permuted-tuple matching distance.

steps.text:
For (a), suppose first that $\mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) = 0$. By definition of $\mathscr{d}_\pi$, we must have $\ell(\bm{x}) = \ell(\bm{y}) = n$ for some $n \in \mathbb{N}_0$, since otherwise $\mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) = 1$. If $n = 0$, then $\bm{x} = \bm{e} = \bm{y}$, and hence $\bm{x}^\pi = \bm{y}^\pi$. If $n > 0$, then because $\mathscr{P}_n$ is finite, there exists a permutation $\sigma \in \mathscr{P}_n$ attaining the minimum, so that
    \begin{align*}
        \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{x}(i), \bm{y}(\sigma(i))\big) = 0.
    \end{align*}
    Since $\bar{d}$ is a metric on $X$, this implies that $\bm{x}(i) = \bm{y}(\sigma(i))$ for every $i \in \{1, \dots, n\}$, that is, $\bm{x} = \bm{y} \circ \sigma$. By Definition~\ref{defn:permutative-equality}, it follows that $\bm{x} \overset{\pi}{\sim} \bm{y}$, and hence $\bm{x}^\pi = \bm{y}^\pi$. Conversely, if $\bm{x}^\pi = \bm{y}^\pi$, we may choose the same representative $\bm{x}$ for both classes and take $\sigma = \mathrm{id}$ to obtain $\mathscr{d}_\pi(\bm{x}^\pi, \bm{x}^\pi) = 0$.

To prove (1), suppose that $(X,d)$ is separable, and let $D\subseteq X$ be a countable dense subset. Define the subset
    \begin{align*}
        \mathscr{D}^\pi = \{\bm{q}^\pi \in \mathscr{T}^\pi(X) \mid \bm{q} \in \mathscr{T}(D)\}.
    \end{align*}
    Because $\mathscr{T}(D) = \bigcup_{n \in \mathbb{N}_0} D^n$ is a countable union of countable sets, $\mathscr{D}^\pi$ is countable. Moreover, for any $\bm{x}^\pi \in \mathscr{T}^\pi(X)$ and $\varepsilon > 0$, if $\ell(\bm{x}) = 0$, then $\bm{x}^\pi = \bm{e}^\pi \in \mathscr{D}^\pi$; if $\ell(\bm{x}) = n > 0$, density of $D$ in $X$ provides elements $q_1, \dots, q_n \in D$ such that $d(\bm{x}(i), q_i) < \varepsilon$ for every $i \in \{1, \dots, n\}$. Setting $\bm{q} = (q_1, \dots, q_n) \in \mathscr{T}(D)$ and taking $\sigma = \mathrm{id} \in \mathscr{P}_n$ gives
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}^\pi, \bm{q}^\pi) \leq \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{x}(i), \bm{q}(i)\big) < \varepsilon,
    \end{align*}
    which proves that $\mathscr{D}^\pi$ is dense in $\mathscr{T}^\pi(X)$ and hence that $(\mathscr{T}^\pi(X), \mathscr{d}_\pi)$ is separable.

To prove (2), suppose that $(X,d)$ is complete, equivalently that $(X,\bar{d})$ is complete, and let $(\bm{x}_n^\pi)_{n\in\mathbb{N}}$ be a Cauchy sequence in $(\mathscr{T}^\pi(X), \mathscr{d}_\pi)$. Since $\mathscr{d}_\pi(\bm{u}^\pi, \bm{v}^\pi) = 1$ whenever $\ell(\bm{u}) \neq \ell(\bm{v})$, there exists an $N \in \mathbb{N}$ and a common length $r \in \mathbb{N}_0$ such that $\ell(\bm{x}_n) = r$ for all $n \geq N$. If $r = 0$, then $\bm{x}_n^\pi = \bm{e}^\pi$ for all $n \geq N$, and the sequence converges to $\bm{e}^\pi$. Assume therefore that $r > 0$. By passing to the tail $n \geq N$, we may extract a subsequence $(\bm{x}_{n_k}^\pi)_{k\in\mathbb{N}}$ such that
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}_{n_k}^\pi,\bm{x}_{n_{k+1}}^\pi)<2^{-k} \qquad \forall k \in \mathbb{N}.
    \end{align*}
    Choose an arbitrary representative $\bm{y}_1\in\bm{x}_{n_1}^\pi$. Proceeding inductively for $k \in \mathbb{N}$, given $\bm{y}_k \in \bm{x}_{n_k}^\pi$ and an arbitrary initial representative $\widetilde{\bm{y}}_{k+1} \in \bm{x}_{n_{k+1}}^\pi$, let $\sigma_k \in \mathscr{P}_r$ attain the minimum in $\mathscr{d}_\pi(\bm{x}_{n_k}^\pi,\bm{x}_{n_{k+1}}^\pi)$ and set $\bm{y}_{k+1} = \widetilde{\bm{y}}_{k+1} \circ \sigma_k \in \bm{x}_{n_{k+1}}^\pi$. Then
    \begin{align*}
        \max_{i \in \{1, \dots, r\}}\bar{d}\big(\bm{y}_k(i),\bm{y}_{k+1}(i)\big) = \mathscr{d}_\pi(\bm{x}_{n_k}^\pi,\bm{x}_{n_{k+1}}^\pi) < 2^{-k}.
    \end{align*}
    Consequently, for each coordinate $i \in \{1, \dots, r\}$, the sequence $(\bm{y}_k(i))_{k\in\mathbb{N}}$ is Cauchy in $(X, \bar{d})$ and therefore converges to a limit $y(i)\in X$. Defining $\bm{y}=(y(1),\dots,y(r)) \in \mathscr{T}(X)$ and taking the identity permutation in Definition~\ref{defn:permuted-tuple-hausdorff-distance} yields
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}_{n_k}^\pi, \bm{y}^\pi) \leq \max_{i \in \{1, \dots, r\}} \bar{d}\big(\bm{y}_k(i), \bm{y}(i)\big) \xrightarrow{k \to \infty} 0.
    \end{align*}
    Because $(\bm{x}_n^\pi)_{n\in\mathbb{N}}$ is Cauchy and possesses a subsequence converging to $\bm{y}^\pi$, the entire sequence converges to $\bm{y}^\pi$. This proves that $(\mathscr{T}^\pi(X), \mathscr{d}_\pi)$ is complete, as desired.

proof.text:
First, we verify that $\mathscr{d}_\pi$ is well-defined on the quotient space $\mathscr{T}^\pi(X)$. Let $\bm{x}, \bm{x}^\prime \in \bm{x}^\pi$ and $\bm{y}, \bm{y}^\prime \in \bm{y}^\pi$ be representatives of two equivalence classes. If $\ell(\bm{x}) \neq \ell(\bm{y})$, then $\ell(\bm{x}^\prime) = \ell(\bm{x}) \neq \ell(\bm{y}) = \ell(\bm{y}^\prime)$, so both evaluations yield $1$. If $\ell(\bm{x}) = \ell(\bm{y}) = 0$, both evaluations yield $0$. Suppose therefore that $\ell(\bm{x}) = \ell(\bm{y}) = n > 0$. By Definition~\ref{defn:permutative-equality}, there exist permutations $\alpha, \beta \in \mathscr{P}_n$ such that $\bm{x}^\prime = \bm{x} \circ \alpha$ and $\bm{y}^\prime = \bm{y} \circ \beta$. For any candidate matching $\sigma \in \mathscr{P}_n$, reindexing $j = \alpha(i)$ yields
    \begin{align*}
        \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{x}^\prime(i), \bm{y}^\prime(\sigma(i))\big)
        &= \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{x}(\alpha(i)), \bm{y}(\beta(\sigma(i)))\big)\\
        &= \max_{j \in \{1, \dots, n\}} \bar{d}\big(\bm{x}(j), \bm{y}((\beta \circ \sigma \circ \alpha^{-1})(j))\big).
    \end{align*}
    Since $\sigma \mapsto \beta \circ \sigma \circ \alpha^{-1}$ is a bijection of $\mathscr{P}_n$ onto itself, taking the minimum over $\sigma \in \mathscr{P}_n$ yields the same value for $(\bm{x}^\prime, \bm{y}^\prime)$ as for $(\bm{x}, \bm{y})$. Thus $\mathscr{d}_\pi$ does not depend on the chosen representatives.

    Next, we must show that $\mathscr{d}_\pi : \mathscr{T}^\pi(X) \times \mathscr{T}^\pi(X) \to [0, 1]$ satisfies the three criteria of a metric for all $\bm{x}^\pi, \bm{y}^\pi, \bm{z}^\pi \in \mathscr{T}^\pi(X)$:
    \begin{enumerate}[(a)]
        \item $\mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) = 0$ if and only if $\bm{x}^\pi = \bm{y}^\pi$.
        \item $\mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) = \mathscr{d}_\pi(\bm{y}^\pi, \bm{x}^\pi)$.
        \item $\mathscr{d}_\pi(\bm{x}^\pi, \bm{z}^\pi) \leq \mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) + \mathscr{d}_\pi(\bm{y}^\pi, \bm{z}^\pi)$.
    \end{enumerate}

    For (a), suppose first that $\mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) = 0$. By definition of $\mathscr{d}_\pi$, we must have $\ell(\bm{x}) = \ell(\bm{y}) = n$ for some $n \in \mathbb{N}_0$, since otherwise $\mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) = 1$. If $n = 0$, then $\bm{x} = \bm{e} = \bm{y}$, and hence $\bm{x}^\pi = \bm{y}^\pi$. If $n > 0$, then because $\mathscr{P}_n$ is finite, there exists a permutation $\sigma \in \mathscr{P}_n$ attaining the minimum, so that
    \begin{align*}
        \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{x}(i), \bm{y}(\sigma(i))\big) = 0.
    \end{align*}
    Since $\bar{d}$ is a metric on $X$, this implies that $\bm{x}(i) = \bm{y}(\sigma(i))$ for every $i \in \{1, \dots, n\}$, that is, $\bm{x} = \bm{y} \circ \sigma$. By Definition~\ref{defn:permutative-equality}, it follows that $\bm{x} \overset{\pi}{\sim} \bm{y}$, and hence $\bm{x}^\pi = \bm{y}^\pi$. Conversely, if $\bm{x}^\pi = \bm{y}^\pi$, we may choose the same representative $\bm{x}$ for both classes and take $\sigma = \mathrm{id}$ to obtain $\mathscr{d}_\pi(\bm{x}^\pi, \bm{x}^\pi) = 0$.

    For (b), the claim is immediate when $\ell(\bm{x}) \neq \ell(\bm{y})$ or $\ell(\bm{x}) = \ell(\bm{y}) = 0$. For $\ell(\bm{x}) = \ell(\bm{y}) = n > 0$, symmetry of $\bar{d}$ and the bijection $\sigma \mapsto \sigma^{-1}$ on $\mathscr{P}_n$ give
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi)
        &= \min_{\sigma \in \mathscr{P}_n} \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{x}(i), \bm{y}(\sigma(i))\big)\\
        &= \min_{\sigma \in \mathscr{P}_n} \max_{j \in \{1, \dots, n\}} \bar{d}\big(\bm{y}(j), \bm{x}(\sigma^{-1}(j))\big)
        = \mathscr{d}_\pi(\bm{y}^\pi, \bm{x}^\pi).
    \end{align*}

    For (c), if $\ell(\bm{x}) = \ell(\bm{y}) = \ell(\bm{z}) = n > 0$, let $\sigma, \sigma^\prime \in \mathscr{P}_n$ attain the minima defining $\mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi)$ and $\mathscr{d}_\pi(\bm{y}^\pi, \bm{z}^\pi)$, respectively. Since $\sigma^\prime \circ \sigma \in \mathscr{P}_n$, the triangle inequality for $\bar{d}$ yields
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}^\pi,\bm{z}^\pi)
        &\leq \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{x}(i),\bm{z}(\sigma^\prime(\sigma(i)))\big)\\
        &\leq \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{x}(i),\bm{y}(\sigma(i))\big) + \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{y}(\sigma(i)),\bm{z}(\sigma^\prime(\sigma(i)))\big)\\
        &= \mathscr{d}_\pi(\bm{x}^\pi,\bm{y}^\pi) + \mathscr{d}_\pi(\bm{y}^\pi,\bm{z}^\pi).
    \end{align*}
    If $\ell(\bm{x}) \neq \ell(\bm{z})$, then $\mathscr{d}_\pi(\bm{x}^\pi, \bm{z}^\pi) = 1$, while either $\ell(\bm{x}) \neq \ell(\bm{y})$ or $\ell(\bm{y}) \neq \ell(\bm{z})$, so at least one of $\mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi)$ or $\mathscr{d}_\pi(\bm{y}^\pi, \bm{z}^\pi)$ equals $1$. If $\ell(\bm{x}) = \ell(\bm{z})$ but $\ell(\bm{y}) \neq \ell(\bm{x})$, then $\mathscr{d}_\pi(\bm{x}^\pi, \bm{z}^\pi) \leq 1 < 2 = \mathscr{d}_\pi(\bm{x}^\pi, \bm{y}^\pi) + \mathscr{d}_\pi(\bm{y}^\pi, \bm{z}^\pi)$. Finally, if $\ell(\bm{x}) = \ell(\bm{y}) = \ell(\bm{z}) = 0$, all three distances are $0$. Therefore, $(\mathscr{T}^\pi(X), \mathscr{d}_\pi)$ is a metric space.

    To prove (1), suppose that $(X,d)$ is separable, and let $D\subseteq X$ be a countable dense subset. Define the subset
    \begin{align*}
        \mathscr{D}^\pi = \{\bm{q}^\pi \in \mathscr{T}^\pi(X) \mid \bm{q} \in \mathscr{T}(D)\}.
    \end{align*}
    Because $\mathscr{T}(D) = \bigcup_{n \in \mathbb{N}_0} D^n$ is a countable union of countable sets, $\mathscr{D}^\pi$ is countable. Moreover, for any $\bm{x}^\pi \in \mathscr{T}^\pi(X)$ and $\varepsilon > 0$, if $\ell(\bm{x}) = 0$, then $\bm{x}^\pi = \bm{e}^\pi \in \mathscr{D}^\pi$; if $\ell(\bm{x}) = n > 0$, density of $D$ in $X$ provides elements $q_1, \dots, q_n \in D$ such that $d(\bm{x}(i), q_i) < \varepsilon$ for every $i \in \{1, \dots, n\}$. Setting $\bm{q} = (q_1, \dots, q_n) \in \mathscr{T}(D)$ and taking $\sigma = \mathrm{id} \in \mathscr{P}_n$ gives
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}^\pi, \bm{q}^\pi) \leq \max_{i \in \{1, \dots, n\}} \bar{d}\big(\bm{x}(i), \bm{q}(i)\big) < \varepsilon,
    \end{align*}
    which proves that $\mathscr{D}^\pi$ is dense in $\mathscr{T}^\pi(X)$ and hence that $(\mathscr{T}^\pi(X), \mathscr{d}_\pi)$ is separable.

    To prove (2), suppose that $(X,d)$ is complete, equivalently that $(X,\bar{d})$ is complete, and let $(\bm{x}_n^\pi)_{n\in\mathbb{N}}$ be a Cauchy sequence in $(\mathscr{T}^\pi(X), \mathscr{d}_\pi)$. Since $\mathscr{d}_\pi(\bm{u}^\pi, \bm{v}^\pi) = 1$ whenever $\ell(\bm{u}) \neq \ell(\bm{v})$, there exists an $N \in \mathbb{N}$ and a common length $r \in \mathbb{N}_0$ such that $\ell(\bm{x}_n) = r$ for all $n \geq N$. If $r = 0$, then $\bm{x}_n^\pi = \bm{e}^\pi$ for all $n \geq N$, and the sequence converges to $\bm{e}^\pi$. Assume therefore that $r > 0$. By passing to the tail $n \geq N$, we may extract a subsequence $(\bm{x}_{n_k}^\pi)_{k\in\mathbb{N}}$ such that
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}_{n_k}^\pi,\bm{x}_{n_{k+1}}^\pi)<2^{-k} \qquad \forall k \in \mathbb{N}.
    \end{align*}
    Choose an arbitrary representative $\bm{y}_1\in\bm{x}_{n_1}^\pi$. Proceeding inductively for $k \in \mathbb{N}$, given $\bm{y}_k \in \bm{x}_{n_k}^\pi$ and an arbitrary initial representative $\widetilde{\bm{y}}_{k+1} \in \bm{x}_{n_{k+1}}^\pi$, let $\sigma_k \in \mathscr{P}_r$ attain the minimum in $\mathscr{d}_\pi(\bm{x}_{n_k}^\pi,\bm{x}_{n_{k+1}}^\pi)$ and set $\bm{y}_{k+1} = \widetilde{\bm{y}}_{k+1} \circ \sigma_k \in \bm{x}_{n_{k+1}}^\pi$. Then
    \begin{align*}
        \max_{i \in \{1, \dots, r\}}\bar{d}\big(\bm{y}_k(i),\bm{y}_{k+1}(i)\big) = \mathscr{d}_\pi(\bm{x}_{n_k}^\pi,\bm{x}_{n_{k+1}}^\pi) < 2^{-k}.
    \end{align*}
    Consequently, for each coordinate $i \in \{1, \dots, r\}$, the sequence $(\bm{y}_k(i))_{k\in\mathbb{N}}$ is Cauchy in $(X, \bar{d})$ and therefore converges to a limit $y(i)\in X$. Defining $\bm{y}=(y(1),\dots,y(r)) \in \mathscr{T}(X)$ and taking the identity permutation in Definition~\ref{defn:permuted-tuple-hausdorff-distance} yields
    \begin{align*}
        \mathscr{d}_\pi(\bm{x}_{n_k}^\pi, \bm{y}^\pi) \leq \max_{i \in \{1, \dots, r\}} \bar{d}\big(\bm{y}_k(i), \bm{y}(i)\big) \xrightarrow{k \to \infty} 0.
    \end{align*}
    Because $(\bm{x}_n^\pi)_{n\in\mathbb{N}}$ is Cauchy and possesses a subsequence converging to $\bm{y}^\pi$, the entire sequence converges to $\bm{y}^\pi$. This proves that $(\mathscr{T}^\pi(X), \mathscr{d}_\pi)$ is complete, as desired.

results.statement:
\label{thm:permuted-tuple-hausdorff-metric-complete-separable}
    Let $(X,d)$ be a metric space and let $\mathscr{d}_\pi$ be the matching distance of Definition~\ref{defn:permuted-tuple-hausdorff-distance}. Then $(\mathscr{T}^\pi(X),\mathscr{d}_\pi)$ is a metric space. Moreover:
    \begin{enumerate}
        \item if $(X,d)$ is separable, then $(\mathscr{T}^\pi(X), \mathscr{d}_\pi)$ is separable;
        \item if $(X,d)$ is complete, then $(\mathscr{T}^\pi(X), \mathscr{d}_\pi)$ is complete.
    \end{enumerate}

\label{defn:tuple-induced-integer-valued-measure}
    Let $X$ be a measurable space, $\mathscr{T}(X)$ be the tuple space over $X$, and $\mathcal{N}(X)$ be the finite integer-valued measures on $X$. Define the mapping $\mathfrak{m} :\mathscr{T}(X) \to \mathcal{N}(X)$ by 
    \begin{align*}
        \mathfrak{m}(\bm{x}) = B \mapsto \sum_{i \in \mathrm{domain}(\bm{x})} \delta_{\bm{x}(i)}(B).
    \end{align*}
    We call $\mathfrak{m}(\bm{x})$ the integer-valued measure, or simply measure, induced by\index{tuple-induced measure} $\bm{x}\in\mathscr{T}(X)$.

steps.text:
We must show that for every $\varepsilon > 0$ and $\bm{x}_0$ there exists a $\theta > 0 $ such that
    \begin{align*}
        \mathscr{d}_H(\bm{x}, \bm{x}_0) < \theta \implies \rho(\mathfrak{m}(\bm{x}), \mathfrak{m}(\bm{x}_0)) < \varepsilon.
    \end{align*}
Choose $0<\theta < \min\{\varepsilon,1\}$. First, recall that by Theorem~\ref{thm:tuple-space-properties} we have that
    \begin{align*}
        \mathscr{d}_H(\bm{x}, \bm{x}_0) < \theta < 1
    \end{align*}
    implies that $\ell(\bm{x}) = \ell(\bm{x}_0)$. If $\bm{x}_0$ is the empty tuple, then $\bm{x}$ is also the empty tuple, and therefore
    \begin{align*}
        \rho(\mathfrak{m}(\bm{x}),\mathfrak{m}(\bm{x}_0)) = 0 < \varepsilon.
    \end{align*}
    Assume therefore that $\bm{x}_0 \neq \bm{e}$. Then, we additionally have 
    \begin{align*}
        \mathscr{d}_H(\bm{x},\bm{x}_0) = \max_{i \in \mathrm{domain}(\bm{x}_0)} d(\bm{x}(i), \bm{x}_0(i)) < \theta < 1.
    \end{align*}
    Consequently, for any Borel set $B$ and every index $i \in \mathrm{domain}(\bm{x}_0)$,
    \begin{align*}
        \bm{x}_0(i)\in B \implies \bm{x}(i)\in B^\theta.
    \end{align*}
    Therefore,
    \begin{align*}
        \mathfrak{m}(\bm{x}_0)(B) \leq \mathfrak{m}(\bm{x})(B^\theta).
    \end{align*}
    By symmetry,
    \begin{align*}
        \mathfrak{m}(\bm{x})(B) \leq \mathfrak{m}(\bm{x}_0)(B^\theta).
    \end{align*}
    Hence, by the definition of the Prokhorov metric,
    \begin{align*}
        \rho(\mathfrak{m}(\bm{x}), \mathfrak{m}(\bm{x}_0)) \leq \theta < \varepsilon,
    \end{align*}
    as desired.

