results.statement:
\label{thm:point-process-tuple}
    Let $(\Omega, \mathcal{F},\mathbb{P})$ be a probability space, and let $(X,d)$ be a complete and separable metric space. Let $\xi :\Omega \to \mathcal{N}(X)$ be a point process. Let $\tau:\mathcal{N}(X) \to \mathscr{T}(X)$ be a measurable enumeration as in Lemma~\ref{lem:measurable-enumeration}. Define the mapping $\mathsf{K}_{\mathrm{perm}} :\Omega \times \mathcal{B}(\mathscr{T}(X)) \to [0,1]$ by
    \begin{align*}
        \mathsf{K}_{\mathrm{perm}}(\omega, B) = \frac{1}{N(\omega)!} \sum_{\sigma \in \mathscr{P}_{N(\omega)}} \mathbbm{1}_B(\tau(\xi(\omega))\circ \sigma),
    \end{align*}
    where $N(\omega) = \xi(\omega)(X)$ is the total number of points of the realisation $\xi(\omega)$. Then, $\mathsf{K}_{\mathrm{perm}}$ is a Markov kernel from $(\Omega, \mathcal{F})$ to $(\mathscr{T}(X), \mathcal{B}(\mathscr{T}(X)))$. Moreover,
    \begin{align*}
        \mathsf{K}_{\mathrm{perm}}(\omega,\mathfrak{m}^{-1}(\{\xi(\omega)\}))=1,
    \end{align*}
    and $\mathsf{K}_{\mathrm{perm}}(\omega,\cdot)$ is the uniform distribution on the class $(\mathfrak{m}^\pi)^{-1}(\xi(\omega))$; in particular, it does not depend on the choice of $\tau$.

\label{defn:weak-linear-operator}\index{weakly linear operators}
    Let $X$ be a non-empty set and let $V$ be a vector space over some field $\mathbb{K}$. Then, any operator $\varphi: X \to V$ is said to be weakly linear if, for every $\alpha , \beta\in \mathbb{K}$ and $x, x^\prime \in X$, there exists an $x^\ast \in X$ such that 
    \begin{align*}
        \varphi(x^\ast) = \alpha \varphi(x) + \beta \varphi(x^\prime). 
    \end{align*}

\label{defn:convex-cone}
    Let $(V, +, \cdot)$ be a real vector space. A subset $C \subseteq V$ is said to be a convex cone if for all $c,c^\prime \in C$ and $\alpha, \beta \geq 0$
    \begin{align*}
        \alpha c + \beta c^\prime \in C. 
    \end{align*}

\label{defn:weakly-convex-operator}\index{weakly convex operators}
    Let $X$ be a non-empty set and let $V$ be a real vector space. Then any operator $\varphi:X \to V$ is said to be weakly convex if, for every $\alpha, \beta \geq 0$ and $x, x^\prime \in X$, there exists an $x^\ast \in X$ such that 
    \begin{align*}
        \varphi(x^\ast) = \alpha \varphi(x) + \beta \varphi(x^\prime).
    \end{align*}

\label{prop:phi-extends}
    Let $X$ and $Y$ be non-empty sets and $\varphi : X \to Y$ be a function. Let $\overset{\varphi}{\sim}$ be a relation on $X$ defined by 
    \begin{align}
        x \overset{\varphi}{\sim} x^\prime \iff \varphi(x) = \varphi(x^\prime).
    \end{align}
    Then $\overset{\varphi}{\sim}$ is an equivalence relation.

\label{defn:function-kernel-quotient-space}
    Let $X$ and $Y$ be non-empty sets and $\varphi : X \to Y$ a function. Endow $X$ with the equivalence relation $\overset{\varphi}{\sim} \subseteq X \times X$ defined by 
    \begin{align}
        x \overset{\varphi}{\sim} x^\prime \iff \varphi(x) = \varphi(x^\prime).
    \end{align}
    Then the quotient set $X_{\overset{\varphi}{\sim}} = \{[x]_{\overset{\varphi}{\sim}} \mid x \in X\}$ is called the kernel quotient of $\varphi$, and for simplicity, we denote it by $X_\varphi$. Likewise, we denote by $x_\varphi$ the equivalence class of $x$ under $\overset{\varphi}{\sim}$, i.e. $x_\varphi = [x]_{\overset{\varphi}{\sim}}$.

steps.text:
We now show injectivity. We must show that 
    \begin{align*}
        \Phi(x_\varphi) = \Phi(x^\prime_\varphi) \implies x_\varphi = x^\prime_\varphi.
    \end{align*}
    Let $x_\varphi, x^\prime_\varphi \in X_\varphi$ be arbitrary. By the definition of $\Phi$, we have that $\Phi(x_\varphi) = \Phi(x^\prime_\varphi)$ implies that $\varphi(x) = \varphi(x^\prime)$, which implies that $x \overset{\varphi}{\sim} x^\prime$, and hence $x_\varphi = x^\prime_\varphi$, as desired.

proof.text:
First, we show that $\Phi$ is well-defined. If $[x]_{\overset{\varphi}{\sim}} = [x']_{\overset{\varphi}{\sim}}$, then $x \overset{\varphi}{\sim} x'$, hence $\varphi(x)=\varphi(x')$. Therefore the value $\Phi([x]_{\overset{\varphi}{\sim}})$ does not depend on the chosen representative.

    We now show injectivity. We must show that 
    \begin{align*}
        \Phi(x_\varphi) = \Phi(x^\prime_\varphi) \implies x_\varphi = x^\prime_\varphi.
    \end{align*}
    Let $x_\varphi, x^\prime_\varphi \in X_\varphi$ be arbitrary. By the definition of $\Phi$, we have that $\Phi(x_\varphi) = \Phi(x^\prime_\varphi)$ implies that $\varphi(x) = \varphi(x^\prime)$, which implies that $x \overset{\varphi}{\sim} x^\prime$, and hence $x_\varphi = x^\prime_\varphi$, as desired.

results.statement:
\label{thm:weak-linear-transport-vector-space-structure}
    Let $X$ be a non-empty set, $V$ a vector space over some field $\mathbb{K}$, and $\varphi : X \to V$ a weakly linear operator. Then, $X_\varphi$ is a vector space over $\mathbb{K}$ when endowed with the operations $+:X_\varphi \times X_\varphi \to X_\varphi$ and $\cdot:\mathbb{K} \times X_\varphi  \to X_{\varphi}$ defined by
    \begin{align*}
        x_\varphi + x^\prime_\varphi = \Phi^{-1}(\Phi(x_\varphi) + \Phi(x^\prime_\varphi)),
    \end{align*}
    and 
    \begin{align*}
        \alpha \cdot x_\varphi = \Phi^{-1}(\alpha \Phi(x_\varphi)),
    \end{align*}
    for $x_\varphi, x^\prime_\varphi \in X_\varphi$ and $\alpha\in\mathbb{K}$, where $\Phi^{-1}$ denotes the inverse of the bijection $\Phi:X_\varphi\to\varphi(X)$.

\label{cor:weak-convex-transport-convex-cone-structure}
    Let $X$ be a non-empty set, $V$ a real vector space, and $\varphi : X \to V$ a weakly convex operator. Then, $X_\varphi$ is a convex cone when endowed with the operations $+:X_\varphi \times X_\varphi \to X_\varphi$ and $\cdot:[0,\infty) \times X_\varphi  \to X_{\varphi}$ defined by
    \begin{align*}
        x_\varphi + x^\prime_\varphi = \Phi^{-1}(\Phi(x_\varphi) + \Phi(x^\prime_\varphi)),
    \end{align*}
    and 
    \begin{align*}
        \alpha \cdot x_\varphi = \Phi^{-1}(\alpha \Phi(x_\varphi)),
    \end{align*}
    for $x_\varphi, x^\prime_\varphi \in X_\varphi$ and $\alpha\geq0$, where $\Phi^{-1}$ denotes the inverse of the bijection $\Phi:X_\varphi\to\varphi(X)$.

steps.text:
By construction (Theorem~\ref{thm:weak-linear-transport-vector-space-structure}), $\Phi:X_\varphi\to\varphi(X)$ is a linear bijection, and
    \begin{align*}
        \llangle \vphantom{.}x_\varphi, x^\prime_\varphi \rrangle = \langle \vphantom{.}\Phi(x_\varphi), \Phi(x^\prime_\varphi) \rangle = \langle \varphi(x), \varphi(x^\prime)\rangle.
    \end{align*}
    Since $(V, \langle \cdot, \cdot \rangle)$ is an inner product space over $\mathbb{R}$, and the pullback of an inner product along an injective linear map is an inner product, the claim follows.

proof.text:
By construction (Theorem~\ref{thm:weak-linear-transport-vector-space-structure}), $\Phi:X_\varphi\to\varphi(X)$ is a linear bijection, and
    \begin{align*}
        \llangle \vphantom{.}x_\varphi, x^\prime_\varphi \rrangle = \langle \vphantom{.}\Phi(x_\varphi), \Phi(x^\prime_\varphi) \rangle = \langle \varphi(x), \varphi(x^\prime)\rangle.
    \end{align*}
    Since $(V, \langle \cdot, \cdot \rangle)$ is an inner product space over $\mathbb{R}$, and the pullback of an inner product along an injective linear map is an inner product, the claim follows.

results.statement:
\label{prop:weak-linear-kernel-inner-product-space}
    Let $X$ be a non-empty set, $(V, \langle \cdot,\cdot\rangle)$ be a real inner product space, and $\varphi : X \to V$ be a weakly linear operator. Define  $\llangle \cdot, \cdot \rrangle : X_\varphi \times X_\varphi \to \mathbb{R}$ by
    \begin{align*}
        \llangle \vphantom{.}x_\varphi, x^\prime_\varphi \rrangle = \langle \varphi(x), \varphi(x^\prime)\rangle,
    \end{align*}
    for $x_\varphi, x^\prime_\varphi \in X_\varphi$. Then, $(X_\varphi, \llangle \cdot, \cdot \rrangle)$, endowed with the vector-space structure of Theorem~\ref{thm:weak-linear-transport-vector-space-structure}, is an inner product space.

\label{defn:inner-product-kernel-space}
    Let $X$ be a non-empty set, $(V, \langle \cdot,\cdot\rangle)$ be a real inner product space, and $\varphi : X \to V$ be a weakly linear operator.  Define  $\llangle \cdot, \cdot \rrangle : X_\varphi \times X_\varphi \to \mathbb{R}$ by
     \begin{align*}
        \llangle \vphantom{.}x_\varphi, x^\prime_\varphi \rrangle = \langle \varphi(x), \varphi(x^\prime)\rangle,
    \end{align*}
    for $x_\varphi, x^\prime_\varphi \in X_\varphi$. Then, we call the pair $(X_\varphi, \llangle \cdot, \cdot \rrangle)$, endowed with the vector-space structure of Theorem~\ref{thm:weak-linear-transport-vector-space-structure}, the kernel space induced by $\varphi$.

steps.text:
By Proposition~\ref{prop:phi-subspace}, the image $\varphi(X)$ is a subspace of $V$, and by Proposition~\ref{prop:function-kernel-quotient-injective-extension} the map $\Phi:X_\varphi \to \varphi(X)$ is bijective. Moreover, for $x_\varphi, y_\varphi \in X_\varphi$, the transported inner product satisfies
    \begin{align*}
        \llangle x_\varphi, y_\varphi \rrangle = \langle \Phi(x_\varphi), \Phi(y_\varphi)\rangle.
    \end{align*}
    Hence $\Phi$ is an isometric linear isomorphism between $(X_\varphi,\llangle \cdot,\cdot \rrangle)$ and the separable inner product space $\varphi(X)$. Therefore $(X_\varphi,\llangle \cdot,\cdot \rrangle)$ is separable.

proof.text:
Since $V$ is separable, every subset of $V$ endowed with the subspace topology is separable. In particular, $\varphi(X) \subseteq V$ is separable.

    By Proposition~\ref{prop:phi-subspace}, the image $\varphi(X)$ is a subspace of $V$, and by Proposition~\ref{prop:function-kernel-quotient-injective-extension} the map $\Phi:X_\varphi \to \varphi(X)$ is bijective. Moreover, for $x_\varphi, y_\varphi \in X_\varphi$, the transported inner product satisfies
    \begin{align*}
        \llangle x_\varphi, y_\varphi \rrangle = \langle \Phi(x_\varphi), \Phi(y_\varphi)\rangle.
    \end{align*}
    Hence $\Phi$ is an isometric linear isomorphism between $(X_\varphi,\llangle \cdot,\cdot \rrangle)$ and the separable inner product space $\varphi(X)$. Therefore $(X_\varphi,\llangle \cdot,\cdot \rrangle)$ is separable.

results.statement:
\label{defn:completed-kernel-space}
    Let $X$ be a non-empty set, $(\mathcal{H}, \langle \cdot, \cdot \rangle)$ a separable Hilbert space, and $\varphi : X \to \mathcal{H}$ a weakly linear operator. Let $(X_\varphi, \llangle \cdot , \cdot \rrangle)$ be the kernel space induced by $\varphi$. Then, we call the completion of $(X_\varphi, \llangle \cdot , \cdot \rrangle)$ the completed kernel space and denote it by
    \begin{align}
        (\mathscr{G}(X, \mathcal{H}, \varphi), \llangle \cdot, \cdot \rrangle).
    \end{align}

\label{thm:closed-convex-cone-closure-projection}
     Let $(\mathcal{H}, \langle \cdot, \cdot \rangle)$ be a real Hilbert space and let $C \subseteq \mathcal{H}$ be a non-empty convex cone. Then,
     \begin{enumerate}[(i)]
         \item the closure of $C$, denoted by $\overline{C}$, is a convex cone and a complete subset of $\mathcal{H}$; 
         \item if $C$ is a closed convex cone, then the metric projection $P:\mathcal{H} \to C$ defined by 
         \begin{align*}
             P(v) = \argmin_{c \in C} \lVert v - c\rVert,
         \end{align*}
         is well-defined, that is, $\lVert v-c\rVert$ has a unique minimiser over $c\in C$ for every $v\in\mathcal{H}$; and 
         \item if $C$ is a closed convex cone, then the metric projection $P:\mathcal{H} \to C$ satisfies 
         \begin{enumerate}
             \item $P$ is idempotent, that is, $P \circ P = P$;
             \item for all $\alpha \geq  0$ and $v \in \mathcal{H}$,  the relation $P(\alpha v) = \alpha P(v)$ holds. 
         \end{enumerate}
     \end{enumerate}

steps.text:
For simplicity, we will write $x$ instead of $x_\varphi$ and $z$ instead of $z_\varphi$. First, we verify that $\sim$ is indeed an equivalence relation. For all $(x,z),(x^\prime,z^\prime), (x^\ast, z^\ast) \in X_\varphi \times X_\varphi$, we show that 
    \begin{enumerate}
        \item $(x,z) \sim (x,z)$; 
        \item $(x,z) \sim (x^\prime, z^\prime)$ if and only if $(x^\prime, z^\prime)\sim (x,z)$; and
        \item $(x, z) \sim (x^\prime, z^\prime)$ and $(x^\prime, z^\prime) \sim (x^\ast, z^\ast)$ implies $(x, z) \sim (x^\ast, z^\ast)$.
    \end{enumerate}

First, for all $x,z \in X_\varphi$, 
    \begin{align*}
        x+z = x+z,
    \end{align*}
    and so $(x,z) \sim (x,z)$. Thus $\sim$ is reflexive.

Next, suppose that $(x,z) \sim (x^\prime, z^\prime)$. Then, by definition,
    \begin{align*}
        x + z^\prime = x^\prime + z.
    \end{align*}
    By symmetry of equality, this gives
    \begin{align*}
        x^\prime + z = x + z^\prime.
    \end{align*}
    Therefore $(x^\prime,z^\prime)\sim (x,z)$. The converse follows analogously, and hence $\sim$ is symmetric.

For the third criterion, we first note that $X_\varphi$ is cancellative. Indeed, the convex cone structure on $X_\varphi$ is obtained by transporting the cone structure of $\varphi(X)\subseteq V$ along the bijection
    \begin{align*}
        \Phi:X_\varphi \to \varphi(X)\subseteq V.
    \end{align*}
    Thus, for all $a,c \in X_\varphi$, the transported addition satisfies
    \begin{align*}
        \Phi(a+c)=\Phi(a)+\Phi(c).
    \end{align*}
    Now suppose that $a+c=b+c$ in $X_\varphi$. Applying $\Phi$ yields
    \begin{align*}
        \Phi(a+c)=\Phi(b+c).
    \end{align*}
    Using the compatibility of $\Phi$ with the transported addition, we obtain
    \begin{align*}
        \Phi(a)+\Phi(c)=\Phi(b)+\Phi(c).
    \end{align*}
    Since $V$ is a vector space, addition in $V$ is cancellative, and hence
    \begin{align*}
        \Phi(a)=\Phi(b).
    \end{align*}
    By injectivity of $\Phi$, it follows that
    \begin{align*}
        a=b.
    \end{align*}
    Therefore $X_\varphi$ is cancellative. Now suppose that $(x, z) \sim (x^\prime, z^\prime)$ and $(x^\prime, z^\prime) \sim (x^\ast, z^\ast)$. Then
    \begin{align}\label{eq:non-prime-and-prime}
        x + z^\prime = x^\prime + z,
    \end{align}
    and
    \begin{align}\label{eq:prime-and-ast}
        x^\prime + z^\ast = x^\ast + z^\prime.
    \end{align}
    Using associativity and commutativity of addition in $X_\varphi$, together with equations \eqref{eq:non-prime-and-prime} and \eqref{eq:prime-and-ast}, we have
    \begin{align*}
        (x+z^\ast)+z^\prime 
        &= (x+z^\prime)+z^\ast \\
        &= (x^\prime+z)+z^\ast \\
        &= z+(x^\prime+z^\ast) \\
        &= z+(x^\ast+z^\prime) \\
        &= (x^\ast+z)+z^\prime.
    \end{align*}
    Since $X_\varphi$ is cancellative, we may cancel the common term $z^\prime$, obtaining
    \begin{align*}
        x+z^\ast = x^\ast+z.
    \end{align*}
    Therefore $(x,z)\sim (x^\ast,z^\ast)$, from which it follows that $\sim$ is transitive. Hence $\sim$ is an equivalence relation on $X_\varphi \times X_\varphi$.

Next, we show that addition and scalar multiplication are well-defined; for addition, suppose that $(x,y) \sim (x^\prime, y^\prime)$ and $(z,w) \sim (z^\prime, w^\prime)$. We will show that the choice of representatives from the equivalence classes is irrelevant. That is, we will show that 
    \begin{align*}
        [(x + z, y + w)] = [(x^\prime + z^\prime, y^\prime + w^\prime)].
    \end{align*}
    By definition of $\sim$, we have
    \begin{align*}
        x+y^\prime = x^\prime+y
    \end{align*}
    and
    \begin{align*}
        z+w^\prime = z^\prime+w.
    \end{align*}
    We must show that
    \begin{align*}
        (x+z,y+w)\sim(x^\prime+z^\prime,y^\prime+w^\prime).
    \end{align*}
    By definition of $\sim$, this is equivalent to showing that
    \begin{align*}
        (x+z)+(y^\prime+w^\prime)
        =
        (x^\prime+z^\prime)+(y+w).
    \end{align*}
    Using associativity and commutativity of addition in $X_\varphi$, we obtain
    \begin{align*}
        (x+z)+(y^\prime+w^\prime)
        &= (x+y^\prime)+(z+w^\prime) \\
        &= (x^\prime+y)+(z^\prime+w) \\
        &= (x^\prime+z^\prime)+(y+w).
    \end{align*}
    Therefore
    \begin{align*}
        (x+z,y+w)\sim(x^\prime+z^\prime,y^\prime+w^\prime).
    \end{align*}
    Hence
    \begin{align*}
        [(x+z,y+w)]
        =
        [(x^\prime+z^\prime,y^\prime+w^\prime)].
    \end{align*}
    Thus addition is independent of the representatives chosen. Next, we show that scalar multiplication is well-defined. Suppose that
    \begin{align*}
        (x,z)\sim(x^\prime,z^\prime).
    \end{align*}
    Then by definition of $\sim$, we have
    \begin{align*}
        x+z^\prime=x^\prime+z.
    \end{align*}
    Let $\alpha\in\mathbb{R}$. We must show that
    \begin{align*}
        \alpha[(x,z)]=\alpha[(x^\prime,z^\prime)].
    \end{align*}

First, suppose that $\alpha\geq 0$. Then
    \begin{align*}
        \alpha[(x,z)] = [(\alpha x,\alpha z)]
    \end{align*}
    and
    \begin{align*}
        \alpha[(x^\prime,z^\prime)] = [(\alpha x^\prime,\alpha z^\prime)].
    \end{align*}
    Thus, it suffices to show that
    \begin{align*}
        (\alpha x,\alpha z)\sim(\alpha x^\prime,\alpha z^\prime).
    \end{align*}
    By definition of $\sim$, this is equivalent to showing that
    \begin{align*}
        \alpha x+\alpha z^\prime = \alpha x^\prime+\alpha z.
    \end{align*}
    Using compatibility of the transported cone structure with non-negative scalar multiplication, we have
    \begin{align*}
        \alpha x+\alpha z^\prime &= \alpha(x+z^\prime) \\
        &= \alpha(x^\prime+z) \\
        &= \alpha x^\prime+\alpha z.
    \end{align*}
    Therefore
    \begin{align*}
        (\alpha x,\alpha z) \sim (\alpha x^\prime,\alpha z^\prime),
    \end{align*}
    and hence
    \begin{align*}
        [(\alpha x,\alpha z)] = [(\alpha x^\prime,\alpha z^\prime)].
    \end{align*}
    So scalar multiplication is independent of representatives when $\alpha\geq 0$.

Now suppose that $\alpha<0$. Let
    \begin{align*}
        \beta=|\alpha|.
    \end{align*}
    Then $\beta>0$, and
    \begin{align*}
        \alpha[(x,z)] = [(\beta z,\beta x)]
    \end{align*}
    while
    \begin{align*}
        \alpha[(x^\prime,z^\prime)] = [(\beta z^\prime,\beta x^\prime)].
    \end{align*}
    Thus, it suffices to show that
    \begin{align*}
        (\beta z,\beta x)\sim(\beta z^\prime,\beta x^\prime).
    \end{align*}
    By definition of $\sim$, this is equivalent to showing that
    \begin{align*}
        \beta z+\beta x^\prime
        =
        \beta z^\prime+\beta x.
    \end{align*}
    Since $(x,z)\sim(x^\prime,z^\prime)$, we have
    \begin{align*}
        x+z^\prime=x^\prime+z.
    \end{align*}
    Multiplying by $\beta$ and using compatibility with non-negative scalar multiplication gives
    \begin{align*}
        \beta x+\beta z^\prime
        &= \beta(x+z^\prime) \\
        &= \beta(x^\prime+z) \\
        &= \beta x^\prime+\beta z.
    \end{align*}
    Using commutativity of addition in $X_\varphi$, this gives
    \begin{align*}
        \beta z^\prime+\beta x
        =
        \beta z+\beta x^\prime.
    \end{align*}
    By symmetry of equality,
    \begin{align*}
        \beta z+\beta x^\prime
        =
        \beta z^\prime+\beta x.
    \end{align*}
    Therefore
    \begin{align*}
        (\beta z,\beta x)\sim(\beta z^\prime,\beta x^\prime).
    \end{align*}
    Since $\beta=|\alpha|$, this means that
    \begin{align*}
        (|\alpha|z,|\alpha|x)\sim(|\alpha|z^\prime,|\alpha|x^\prime),
    \end{align*}
    and hence
    \begin{align*}
        [(\left|\alpha\right|z,\left|\alpha\right|x)]
        =
        [(\left|\alpha\right|z^\prime,\left|\alpha\right|x^\prime)].
    \end{align*}
    So scalar multiplication is independent of representatives when $\alpha<0$.

We now proceed to show that $(\mathscr{V}(X, \varphi), +, \cdot)$ is a real vector space. To do so, we define the auxiliary map $T:\mathscr{V}(X, \varphi) \to \mathrm{span}~\varphi(X)$ by 
    \begin{align*}
        T([(x,z)]) \overset{\mathrm{def}}{=} \Phi(x) - \Phi(z).
    \end{align*}
    First, let us verify that $T$ is well-defined. Note that 
    \begin{align*}
        [(x,z)] &= \{ (x^\prime, z^\prime) \in X_\varphi \times X_\varphi \mid x + z^\prime = z + x^\prime\}\\
        &=\{ (x^\prime, z^\prime) \in X_\varphi \times X_\varphi \mid \Phi(x) + \Phi(z^\prime) = \Phi(z) + \Phi(x^\prime)\}\\
        &=\{ (x^\prime, z^\prime) \in X_\varphi \times X_\varphi \mid \Phi(x) - \Phi(z) = \Phi(x^\prime) - \Phi(z^\prime)\}.
    \end{align*}
    Hence, $T$ is well-defined, as its value is constant on each equivalence class. Moreover, $\Phi(x)-\Phi(z)\in \mathrm{span}~\varphi(X)$ by construction. We now claim that $T$ is a bijection. Injectivity follows from the property that if
    \begin{align*}
        T([(x,z)]) = \Phi(x) - \Phi(z) = \Phi(x^\prime) - \Phi(z^\prime) = T([(x^\prime, z^\prime)]) 
    \end{align*}
    then $(x,z) \sim (x^\prime, z^\prime)$ and so $[(x,z)] = [(x^\prime,z^\prime)]$. For surjectivity, let $v \in \mathrm{span}\,\varphi(X)$ and write
    \begin{align*}
        v = \sum_{i=1}^n \alpha_i \varphi(u_i),
    \end{align*}
    for $(u_i)_{i=1}^n \subseteq X$ and $(\alpha_i)_{i=1}^n \subseteq \mathbb{R}$. Define 
    \begin{align*}
        \alpha^+_i =\max(\alpha_i, 0), \quad \alpha^-_i =-\min(\alpha_i, 0),
    \end{align*}
    and set 
    \begin{align*}
        v^+ = \sum_{i=1}^n \alpha^+_i \varphi(u_i), \quad v^- = \sum_{i=1}^n \alpha^-_i \varphi(u_i).
    \end{align*}
    Since $\varphi(X)$ is a convex cone, and hence, by induction on $n$, closed under non-negative combinations of $n$ elements, and $\Phi : X_\varphi \to \varphi(X)$ is bijective, there exist $x,z \in X_\varphi$ such that $\Phi(x)=v^+$ and $\Phi(z)=v^-$. By construction,
    \begin{align*}
        T([(x,z)]) = v^+ - v^- = v,
    \end{align*}
    so $T$ is surjective.

We now claim that
    \begin{align*}
        T([(x,z)] + [(x^\prime, z^\prime)]) = T([(x,z)]) + T([(x^\prime, z^\prime)])
    \end{align*}
    and 
    \begin{align*}
        T(\alpha [(x, z)]) = \alpha T([(x,z)]).
    \end{align*}
    Indeed, 
    \begin{align*}
        T([(x,z)] + [(x^\prime, z^\prime)]) &= T([(x + x^\prime, z + z^\prime)])\\
        &= \Phi(x + x^\prime) - \Phi(z + z^\prime) \\ 
        &= \Phi(\Phi^{-1}(\Phi(x) + \Phi(x^\prime))) - \Phi(\Phi^{-1}(\Phi(z) + \Phi(z^\prime)))\\
        &= \Phi(x) - \Phi(z) + \Phi(x^\prime) - \Phi(z^\prime)\\
        &= T([(x,z)]) + T([(x^\prime, z^\prime)]),
    \end{align*}
    and 
    \begin{align*}
        T(\alpha [(x, z)]) = \begin{cases}
            T([(\alpha x, \alpha z)]) & \alpha \geq 0,\\ 
            T([(|\alpha| z, |\alpha| x)]) & \alpha < 0.
        \end{cases}
    \end{align*}
    For the case $\alpha \geq 0$ notice that 
    \begin{align*}
        T([(\alpha x, \alpha z)]) &= \Phi(\alpha x) - \Phi(\alpha z)\\
        &= \alpha \Phi(x) - \alpha \Phi(z) \\
        &= \alpha T([(x,z)]). 
    \end{align*}
    Likewise, the case $\alpha < 0$ yields 
    \begin{align*}
        T([(|\alpha| z, |\alpha| x)]) &= \Phi(|\alpha| z) - \Phi(|\alpha| x)\\
        &=|\alpha| \Phi(z) - |\alpha| \Phi(x)\\
        &=-\alpha \Phi(z) + \alpha \Phi(x)\\
        &=\alpha T([(x,z)]),
    \end{align*}
    by commutativity in $\mathrm{span}~\varphi(X)$. As $\mathrm{span} ~\varphi(X)$ is naturally a vector space, the claim follows via the bijection $T$ and the fact that $T$ preserves the algebraic structure.

