    For the third criterion, we first note that $X_\varphi$ is cancellative. Indeed, the convex cone structure on $X_\varphi$ is obtained by transporting the cone structure of $\varphi(X)\subseteq V$ along the bijection
    \begin{align*}
        \Phi:X_\varphi \to \varphi(X)\subseteq V.
    \end{align*}
    Thus, for all $a,c \in X_\varphi$, the transported addition satisfies
    \begin{align*}
        \Phi(a+c)=\Phi(a)+\Phi(c).
    \end{align*}
    Now suppose that $a+c=b+c$ in $X_\varphi$. Applying $\Phi$ yields
    \begin{align*}
        \Phi(a+c)=\Phi(b+c).
    \end{align*}
    Using the compatibility of $\Phi$ with the transported addition, we obtain
    \begin{align*}
        \Phi(a)+\Phi(c)=\Phi(b)+\Phi(c).
    \end{align*}
    Since $V$ is a vector space, addition in $V$ is cancellative, and hence
    \begin{align*}
        \Phi(a)=\Phi(b).
    \end{align*}
    By injectivity of $\Phi$, it follows that
    \begin{align*}
        a=b.
    \end{align*}
    Therefore $X_\varphi$ is cancellative. Now suppose that $(x, z) \sim (x^\prime, z^\prime)$ and $(x^\prime, z^\prime) \sim (x^\ast, z^\ast)$. Then
    \begin{align}\label{eq:non-prime-and-prime}
        x + z^\prime = x^\prime + z,
    \end{align}
    and
    \begin{align}\label{eq:prime-and-ast}
        x^\prime + z^\ast = x^\ast + z^\prime.
    \end{align}
    Using associativity and commutativity of addition in $X_\varphi$, together with equations \eqref{eq:non-prime-and-prime} and \eqref{eq:prime-and-ast}, we have
    \begin{align*}
        (x+z^\ast)+z^\prime 
        &= (x+z^\prime)+z^\ast \\
        &= (x^\prime+z)+z^\ast \\
        &= z+(x^\prime+z^\ast) \\
        &= z+(x^\ast+z^\prime) \\
        &= (x^\ast+z)+z^\prime.
    \end{align*}
    Since $X_\varphi$ is cancellative, we may cancel the common term $z^\prime$, obtaining
    \begin{align*}
        x+z^\ast = x^\ast+z.
    \end{align*}
    Therefore $(x,z)\sim (x^\ast,z^\ast)$, from which it follows that $\sim$ is transitive. Hence $\sim$ is an equivalence relation on $X_\varphi \times X_\varphi$.

    Next, we show that addition and scalar multiplication are well-defined; for addition, suppose that $(x,y) \sim (x^\prime, y^\prime)$ and $(z,w) \sim (z^\prime, w^\prime)$. We will show that the choice of representatives from the equivalence classes is irrelevant. That is, we will show that 
    \begin{align*}
        [(x + z, y + w)] = [(x^\prime + z^\prime, y^\prime + w^\prime)].
    \end{align*}
    By definition of $\sim$, we have
    \begin{align*}
        x+y^\prime = x^\prime+y
    \end{align*}
    and
    \begin{align*}
        z+w^\prime = z^\prime+w.
    \end{align*}
    We must show that
    \begin{align*}
        (x+z,y+w)\sim(x^\prime+z^\prime,y^\prime+w^\prime).
    \end{align*}
    By definition of $\sim$, this is equivalent to showing that
    \begin{align*}
        (x+z)+(y^\prime+w^\prime)
        =
        (x^\prime+z^\prime)+(y+w).
    \end{align*}
    Using associativity and commutativity of addition in $X_\varphi$, we obtain
    \begin{align*}
        (x+z)+(y^\prime+w^\prime)
        &= (x+y^\prime)+(z+w^\prime) \\
        &= (x^\prime+y)+(z^\prime+w) \\
        &= (x^\prime+z^\prime)+(y+w).
    \end{align*}
    Therefore
    \begin{align*}
        (x+z,y+w)\sim(x^\prime+z^\prime,y^\prime+w^\prime).
    \end{align*}
    Hence
    \begin{align*}
        [(x+z,y+w)]
        =
        [(x^\prime+z^\prime,y^\prime+w^\prime)].
    \end{align*}
    Thus addition is independent of the representatives chosen. Next, we show that scalar multiplication is well-defined. Suppose that
    \begin{align*}
        (x,z)\sim(x^\prime,z^\prime).
    \end{align*}
    Then by definition of $\sim$, we have
    \begin{align*}
        x+z^\prime=x^\prime+z.
    \end{align*}
    Let $\alpha\in\mathbb{R}$. We must show that
    \begin{align*}
        \alpha[(x,z)]=\alpha[(x^\prime,z^\prime)].
    \end{align*}

    First, suppose that $\alpha\geq 0$. Then
    \begin{align*}
        \alpha[(x,z)] = [(\alpha x,\alpha z)]
    \end{align*}
    and
    \begin{align*}
        \alpha[(x^\prime,z^\prime)] = [(\alpha x^\prime,\alpha z^\prime)].
    \end{align*}
    Thus, it suffices to show that
    \begin{align*}
        (\alpha x,\alpha z)\sim(\alpha x^\prime,\alpha z^\prime).
    \end{align*}
    By definition of $\sim$, this is equivalent to showing that
    \begin{align*}
        \alpha x+\alpha z^\prime = \alpha x^\prime+\alpha z.
    \end{align*}
    Using compatibility of the transported cone structure with non-negative scalar multiplication, we have
    \begin{align*}
        \alpha x+\alpha z^\prime &= \alpha(x+z^\prime) \\
        &= \alpha(x^\prime+z) \\
        &= \alpha x^\prime+\alpha z.
    \end{align*}
    Therefore
    \begin{align*}
        (\alpha x,\alpha z) \sim (\alpha x^\prime,\alpha z^\prime),
    \end{align*}
    and hence
    \begin{align*}
        [(\alpha x,\alpha z)] = [(\alpha x^\prime,\alpha z^\prime)].
    \end{align*}
    So scalar multiplication is independent of representatives when $\alpha\geq 0$.

    Now suppose that $\alpha<0$. Let
    \begin{align*}
        \beta=|\alpha|.
    \end{align*}
    Then $\beta>0$, and
    \begin{align*}
        \alpha[(x,z)] = [(\beta z,\beta x)]
    \end{align*}
    while
    \begin{align*}
        \alpha[(x^\prime,z^\prime)] = [(\beta z^\prime,\beta x^\prime)].
    \end{align*}
    Thus, it suffices to show that
    \begin{align*}
        (\beta z,\beta x)\sim(\beta z^\prime,\beta x^\prime).
    \end{align*}
    By definition of $\sim$, this is equivalent to showing that
    \begin{align*}
        \beta z+\beta x^\prime
        =
        \beta z^\prime+\beta x.
    \end{align*}
    Since $(x,z)\sim(x^\prime,z^\prime)$, we have
    \begin{align*}
        x+z^\prime=x^\prime+z.
    \end{align*}
    Multiplying by $\beta$ and using compatibility with non-negative scalar multiplication gives
    \begin{align*}
        \beta x+\beta z^\prime
        &= \beta(x+z^\prime) \\
        &= \beta(x^\prime+z) \\
        &= \beta x^\prime+\beta z.
    \end{align*}
    Using commutativity of addition in $X_\varphi$, this gives
    \begin{align*}
        \beta z^\prime+\beta x
        =
        \beta z+\beta x^\prime.
    \end{align*}
    By symmetry of equality,
    \begin{align*}
        \beta z+\beta x^\prime
        =
        \beta z^\prime+\beta x.
    \end{align*}
    Therefore
    \begin{align*}
        (\beta z,\beta x)\sim(\beta z^\prime,\beta x^\prime).
    \end{align*}
    Since $\beta=|\alpha|$, this means that
    \begin{align*}
        (|\alpha|z,|\alpha|x)\sim(|\alpha|z^\prime,|\alpha|x^\prime),
    \end{align*}
    and hence
    \begin{align*}
        [(\left|\alpha\right|z,\left|\alpha\right|x)]
        =
        [(\left|\alpha\right|z^\prime,\left|\alpha\right|x^\prime)].
    \end{align*}
    So scalar multiplication is independent of representatives when $\alpha<0$.

    We now proceed to show that $(\mathscr{V}(X, \varphi), +, \cdot)$ is a real vector space. To do so, we define the auxiliary map $T:\mathscr{V}(X, \varphi) \to \mathrm{span}~\varphi(X)$ by 
    \begin{align*}
        T([(x,z)]) \overset{\mathrm{def}}{=} \Phi(x) - \Phi(z).
    \end{align*}
    First, let us verify that $T$ is well-defined. Note that 
    \begin{align*}
        [(x,z)] &= \{ (x^\prime, z^\prime) \in X_\varphi \times X_\varphi \mid x + z^\prime = z + x^\prime\}\\
        &=\{ (x^\prime, z^\prime) \in X_\varphi \times X_\varphi \mid \Phi(x) + \Phi(z^\prime) = \Phi(z) + \Phi(x^\prime)\}\\
        &=\{ (x^\prime, z^\prime) \in X_\varphi \times X_\varphi \mid \Phi(x) - \Phi(z) = \Phi(x^\prime) - \Phi(z^\prime)\}.
    \end{align*}
    Hence, $T$ is well-defined, as its value is constant on each equivalence class. Moreover, $\Phi(x)-\Phi(z)\in \mathrm{span}~\varphi(X)$ by construction. We now claim that $T$ is a bijection. Injectivity follows from the property that if
    \begin{align*}
        T([(x,z)]) = \Phi(x) - \Phi(z) = \Phi(x^\prime) - \Phi(z^\prime) = T([(x^\prime, z^\prime)]) 
    \end{align*}
    then $(x,z) \sim (x^\prime, z^\prime)$ and so $[(x,z)] = [(x^\prime,z^\prime)]$. For surjectivity, let $v \in \mathrm{span}\,\varphi(X)$ and write
    \begin{align*}
        v = \sum_{i=1}^n \alpha_i \varphi(u_i),
    \end{align*}
    for $(u_i)_{i=1}^n \subseteq X$ and $(\alpha_i)_{i=1}^n \subseteq \mathbb{R}$. Define 
    \begin{align*}
        \alpha^+_i =\max(\alpha_i, 0), \quad \alpha^-_i =-\min(\alpha_i, 0),
    \end{align*}
    and set 
    \begin{align*}
        v^+ = \sum_{i=1}^n \alpha^+_i \varphi(u_i), \quad v^- = \sum_{i=1}^n \alpha^-_i \varphi(u_i).
    \end{align*}
    Since $\varphi(X)$ is a convex cone, and hence, by induction on $n$, closed under non-negative combinations of $n$ elements, and $\Phi : X_\varphi \to \varphi(X)$ is bijective, there exist $x,z \in X_\varphi$ such that $\Phi(x)=v^+$ and $\Phi(z)=v^-$. By construction,
    \begin{align*}
        T([(x,z)]) = v^+ - v^- = v,
    \end{align*}
    so $T$ is surjective.

    We now claim that
    \begin{align*}
        T([(x,z)] + [(x^\prime, z^\prime)]) = T([(x,z)]) + T([(x^\prime, z^\prime)])
    \end{align*}
    and 
    \begin{align*}
        T(\alpha [(x, z)]) = \alpha T([(x,z)]).
    \end{align*}
    Indeed, 
    \begin{align*}
        T([(x,z)] + [(x^\prime, z^\prime)]) &= T([(x + x^\prime, z + z^\prime)])\\
        &= \Phi(x + x^\prime) - \Phi(z + z^\prime) \\ 
        &= \Phi(\Phi^{-1}(\Phi(x) + \Phi(x^\prime))) - \Phi(\Phi^{-1}(\Phi(z) + \Phi(z^\prime)))\\
        &= \Phi(x) - \Phi(z) + \Phi(x^\prime) - \Phi(z^\prime)\\
        &= T([(x,z)]) + T([(x^\prime, z^\prime)]),
    \end{align*}
    and 
    \begin{align*}
        T(\alpha [(x, z)]) = \begin{cases}
            T([(\alpha x, \alpha z)]) & \alpha \geq 0,\\ 
            T([(|\alpha| z, |\alpha| x)]) & \alpha < 0.
        \end{cases}
    \end{align*}
    For the case $\alpha \geq 0$ notice that 
    \begin{align*}
        T([(\alpha x, \alpha z)]) &= \Phi(\alpha x) - \Phi(\alpha z)\\
        &= \alpha \Phi(x) - \alpha \Phi(z) \\
        &= \alpha T([(x,z)]). 
    \end{align*}
    Likewise, the case $\alpha < 0$ yields 
    \begin{align*}
        T([(|\alpha| z, |\alpha| x)]) &= \Phi(|\alpha| z) - \Phi(|\alpha| x)\\
        &=|\alpha| \Phi(z) - |\alpha| \Phi(x)\\
        &=-\alpha \Phi(z) + \alpha \Phi(x)\\
        &=\alpha T([(x,z)]),
    \end{align*}
    by commutativity in $\mathrm{span}~\varphi(X)$. As $\mathrm{span} ~\varphi(X)$ is naturally a vector space, the claim follows via the bijection $T$ and the fact that $T$ preserves the algebraic structure.

results.statement:
\label{thm:grothendieck-vector-space-from-convex-cone}\index{Grothendieck vectorisation}
    Let $X$ be a non-empty set, $V$ a real vector space, and $\varphi :X \to V$ a weakly convex operator. Endow $X_\varphi$ with the convex cone structure of Corollary~\ref{cor:weak-convex-transport-convex-cone-structure}. Define the relation $\sim$ on $X_\varphi \times X_\varphi$ by 
    \begin{align*}
        (x_\varphi, z_\varphi) \sim (x^\prime_\varphi, z^\prime_\varphi) \iff x_\varphi + z^\prime_\varphi = x^\prime_\varphi + z_\varphi,
    \end{align*}
    and let $\mathscr{V}(X, \varphi)$ denote the quotient set $(X_\varphi \times X_\varphi)/{\sim}$. Define addition $+:\mathscr{V}(X,\varphi) \times \mathscr{V}(X,\varphi) \to \mathscr{V}(X,\varphi)$ and scalar multiplication $\cdot : \mathbb{R} \times \mathscr{V}(X, \varphi) \to \mathscr{V}(X,\varphi)$ by 
    \begin{align*}
        [(x_\varphi,z_\varphi)] + [(x^\prime_\varphi, z^\prime_\varphi)] = [(x_\varphi + x^\prime_\varphi, z_\varphi + z^\prime_\varphi)],
    \end{align*}
    and 
    \begin{align*}
        \alpha [(x_\varphi,z_\varphi)] = \begin{cases}
            [(\alpha x_\varphi, \alpha z_\varphi)], & \text{if }\alpha \geq 0,\\ 
            [(|\alpha| z_\varphi, |\alpha| x_\varphi)], & \text{if }\alpha < 0.
        \end{cases}
    \end{align*}
    Then $(\mathscr{V}(X,\varphi), +, \cdot)$ is a real vector space.

\label{thm:grothendieck-vectorization-is-span}
    Let $X$ be a non-empty set, $V$ a real vector space, and $\varphi : X \to V$ a weakly convex operator. Then, 
    \begin{align*}
        \mathscr{V}(X, \varphi) \cong \mathrm{span}~\varphi(X).
    \end{align*}
    More precisely, the mapping 
    \begin{align*}
        T &: \mathscr{V}(X,\varphi) \to \mathrm{span}~\varphi(X)\\
        [(x_\varphi,z_\varphi)] & \mapsto \Phi(x_\varphi) - \Phi(z_\varphi)
    \end{align*}
    is a linear isomorphism.

\label{cor:grothendieck-vectorization-inner-product-space}
    Let $X$ be a non-empty set, $(V, \langle \cdot, \cdot \rangle)$ a real inner product space, and $\varphi : X \to V$ a weakly convex operator. Let $T:\mathscr{V}(X,\varphi) \to \mathrm{span}~\varphi(X)$ be the linear isomorphism 
    \begin{align*}
        T([(x_\varphi,z_\varphi)]) = \Phi(x_\varphi) - \Phi(z_\varphi).
    \end{align*}
    Endow $\mathscr{V}(X,\varphi)$ with the bilinear form $\llangle \cdot, \cdot \rrangle_{\mathscr{V}} :\mathscr{V}(X,\varphi) \times \mathscr{V}(X,\varphi) \to \mathbb{R}$ defined by
    \begin{align*}
        \llangle [(x_\varphi,z_\varphi)], [(x^\prime_\varphi, z^\prime_\varphi)] \rrangle_{\mathscr{V}} &= \langle T([(x_\varphi,z_\varphi)]), T([(x^\prime_\varphi, z^\prime_\varphi)])\rangle \\ &= \langle \Phi(x_\varphi) - \Phi(z_\varphi), \Phi(x^\prime_\varphi) - \Phi(z^\prime_\varphi) \rangle. 
    \end{align*}
    Then $(\mathscr{V}(X,\varphi), \llangle \cdot, \cdot \rrangle_{\mathscr{V}})$ is an inner product space, and $T$ is an isometric linear isomorphism. In addition,
    \begin{enumerate}
        \item The completion of $\mathscr{V}(X,\varphi)$ and the completion of $\mathrm{span}~\varphi(X)$ are isometrically isomorphic. 
        \item The operator $T$ extends to a linear isometric isomorphism between the completion of $\mathscr{V}(X,\varphi)$ and the completion of ${\mathrm{span}~\varphi(X)}$. 
        \item The map $x_\varphi\mapsto[(x_\varphi,0_\varphi)]$, where $0_\varphi$ denotes the cone zero induced by the transported cone structure, is an isometric embedding of the convex cone $X_\varphi$ into $\mathscr{V}(X,\varphi)$; here $X_\varphi$ carries the metric $(x_\varphi,x^\prime_\varphi)\mapsto\lVert\Phi(x_\varphi)-\Phi(x^\prime_\varphi)\rVert$ pulled back from $V$. The closure of the embedded image is a closed convex cone in the completion of $\mathscr{V}(X,\varphi)$.
        \item There is a unique metric projection from the completion of $\mathscr{V}(X,\varphi)$ onto the closure of the embedded cone.
    \end{enumerate}

\label{defn:supply-and-demand-curves}
    Let $\mathcal{P}=[-500,\overline{p}]\subset\mathbb{R}$ be a compact interval, let $O=\mathcal{P}\times[0,\infty)\times\{\mathrm{buy},\mathrm{sell}\}$, and let $\bm{m}\in\mathscr{T}(O)$ be a market state with sorted sell tuple $\bm{s}=(\bm{p}^{\bm{s}}(i),\bm{q}^{\bm{s}}(i))_{i=1}^{\ell(\bm{s})}$ and sorted buy tuple $\bm{b}=(\bm{p}^{\bm{b}}(j),\bm{q}^{\bm{b}}(j))_{j=1}^{\ell(\bm{b})}$. Set $\bm{p}^{\bm{s}}(0)=-500$, $\bm{p}^{\bm{b}}(0)=\overline{p}$, $\bm{Q}^{\bm{s}}(i)=\sum_{k=1}^i\bm{q}^{\bm{s}}(k)$ for $i\in\{0,\dots,\ell(\bm{s})\}$, $\bm{Q}^{\bm{b}}(j)=\sum_{k=1}^j\bm{q}^{\bm{b}}(k)$ for $j\in\{0,\dots,\ell(\bm{b})\}$, $s_*=\bm{Q}^{\bm{s}}(\ell(\bm{s}))$, and $b_*=\bm{Q}^{\bm{b}}(\ell(\bm{b}))$. If $\bm{s}$ is non-empty, the \emph{supply curve} $S^{\bm{m}}:[0,s_*]\to\mathcal{P}$ is defined by $S^{\bm{m}}(0)=-500$ and
    \begin{align*}
        S^{\bm{m}}(q) = \frac{(\bm{Q}^{\bm{s}}(i)-q)\,\bm{p}^{\bm{s}}(i-1)+(q-\bm{Q}^{\bm{s}}(i-1))\,\bm{p}^{\bm{s}}(i)}{\bm{Q}^{\bm{s}}(i)-\bm{Q}^{\bm{s}}(i-1)},
        \quad \bm{Q}^{\bm{s}}(i-1)<q\leq\bm{Q}^{\bm{s}}(i),
    \end{align*}
    for each $i\in\{1,\dots,\ell(\bm{s})\}$ with $\bm{q}^{\bm{s}}(i)>0$. Likewise, if $\bm{b}$ is non-empty, the \emph{demand curve} $D^{\bm{m}}:[0,b_*]\to\mathcal{P}$ is defined by $D^{\bm{m}}(0)=\overline{p}$ and
    \begin{align*}
        D^{\bm{m}}(q) = \frac{(\bm{Q}^{\bm{b}}(j)-q)\,\bm{p}^{\bm{b}}(j-1)+(q-\bm{Q}^{\bm{b}}(j-1))\,\bm{p}^{\bm{b}}(j)}{\bm{Q}^{\bm{b}}(j)-\bm{Q}^{\bm{b}}(j-1)},
        \quad \bm{Q}^{\bm{b}}(j-1)<q\leq\bm{Q}^{\bm{b}}(j),
    \end{align*}
    for each $j\in\{1,\dots,\ell(\bm{b})\}$ with $\bm{q}^{\bm{b}}(j)>0$.

\label{defn:excess-supply-and-completed-graph}
    Let $\bm{m}\in\mathscr{T}(O)$ be a market state with supply curve $S^{\bm{m}}:[0,s_*]\to\mathcal{P}$ and demand curve $D^{\bm{m}}:[0,b_*]\to\mathcal{P}$, where $\mathcal{P}=[-500,\overline{p}]$. The \emph{excess supply function} $E^{\bm{m}}:\mathbb{R}\to[-b_*,s_*]$ is defined by
    \begin{align*}
        E^{\bm{m}}(p)
        &=\sup\bigl(\{0\}\cup\{q\in(0,s_*]\mid S^{\bm{m}}(q)\leq p\}\bigr)\\
        &\quad-\sup\bigl(\{0\}\cup\{q\in(0,b_*]\mid D^{\bm{m}}(q)\geq p\}\bigr).
    \end{align*}
    The \emph{completed graph} of $E^{\bm{m}}$ over $\mathcal{P}$ is the set of points $(p,e)\in\mathcal{P}\times\mathbb{R}$ satisfying $E^{\bm{m}}(p-)\leq e\leq E^{\bm{m}}(p+)$, and for each level $q\in[-b_*,s_*]$, the corresponding level set is
    \begin{align*}
        J_{\bm{m}}(q)=\bigl\{p\in\mathcal{P}\bigm| E^{\bm{m}}(p-)\leq q\leq E^{\bm{m}}(p+)\bigr\}.
    \end{align*}

\label{defn:crossing-price-and-equilibrium-operator}
    Let $\bm{m}\in\mathscr{T}(O)$ be a market state with supply curve $S^{\bm{m}}:[0,s_*]\to\mathcal{P}$, demand curve $D^{\bm{m}}:[0,b_*]\to\mathcal{P}$, and level sets $J_{\bm{m}}(q)\subseteq\mathcal{P}$ for $q\in[-b_*,s_*]$. The \emph{crossing price} of $\bm{m}$ is defined by
    \begin{align*}
        P(\bm{m})=\frac{1}{2}\bigl(\min J_{\bm{m}}(0)+\max J_{\bm{m}}(0)\bigr),
    \end{align*}
    and the \emph{equilibrium quantity} of $\bm{m}$ is defined by
    \begin{align*}
        Q(\bm{m})=\max\bigl(\{0\}\cup\{q\in(0,\min(s_*,b_*)]\mid S^{\bm{m}}(q)\leq P(\bm{m})\leq D^{\bm{m}}(q)\}\bigr).
    \end{align*}
    The \emph{equilibrium operator} is the map
    \begin{align*}
        \mathcal{E} : \mathscr{T}(O) &\to \mathbb{R} \times [0,\infty)\\
        \bm{m} &\mapsto (P(\bm{m}), Q(\bm{m})).
    \end{align*}

\label{defn:positively-matched-state-space-and-price-impact-curve}
    Let $O$ be the order space of \eqref{eq:da-order-space} with price interval $\mathcal{P}=[-500,\overline{p}]$, and let $Q:\mathscr{T}(O)\to[0,\infty)$ and $J_{\bm{m}}(q)\subseteq\mathcal{P}$ be as in Definitions~\ref{defn:excess-supply-and-completed-graph} and~\ref{defn:crossing-price-and-equilibrium-operator}. The \emph{positively matched state space} is the subset
    \begin{align*}
        \mathscr{M}_+=\{\bm{m}\in\mathscr{T}(O)\mid Q(\bm{m})>0\}.
    \end{align*}
    For each $\bm{m}\in\mathscr{M}_+$ with total sell volume $s_*$ and total buy volume $b_*$, the \emph{available-depth interval} is $D_{\bm{m}}=[-b_*,s_*]$, and the \emph{price-impact curve} of $\bm{m}$ is the map
    \begin{align*}
        P_{\bm{m}}:D_{\bm{m}}&\to\mathcal{P}\\
        q&\mapsto\frac{1}{2}\bigl(\min J_{\bm{m}}(q)+\max J_{\bm{m}}(q)\bigr).
    \end{align*}

steps.text:
Next, since $E^{\bm{m}}$ is non-decreasing, $p<p^\prime$ implies $E^{\bm{m}}(p+)\leq E^{\bm{m}}(p^\prime-)$. If $p<p^{\prime\prime}<p^\prime$ with $p,p^\prime\in J_{\bm{m}}(q)$, then
\begin{align*}
    E^{\bm{m}}(p^{\prime\prime}-)\leq E^{\bm{m}}(p^\prime-)\leq q\leq E^{\bm{m}}(p+)\leq E^{\bm{m}}(p^{\prime\prime}+),
\end{align*}
so $p^{\prime\prime}\in J_{\bm{m}}(q)$. Thus $J_{\bm{m}}(q)$ is a non-empty closed interval, and $P_{\bm{m}}$ is well-defined on $D_{\bm{m}}$.

To establish \eqref{claim:increasing}, let $q,q^\prime\in D_{\bm{m}}$ satisfy $q<q^\prime$, and let $p\in J_{\bm{m}}(q)$ and $p^\prime\in J_{\bm{m}}(q^\prime)$. Then $p\leq p^\prime$, because $p^\prime<p$ would yield $q^\prime\leq E^{\bm{m}}(p^\prime+)\leq E^{\bm{m}}(p-)\leq q$, a contradiction. Taking the maximum over $p\in J_{\bm{m}}(q)$ and the minimum over $p^\prime\in J_{\bm{m}}(q^\prime)$ gives
\begin{align*}
    P_{\bm{m}}(q)\leq\max J_{\bm{m}}(q)\leq\min J_{\bm{m}}(q^\prime)\leq P_{\bm{m}}(q^\prime),
\end{align*}
which proves that $P_{\bm{m}}$ is increasing.

proof.text:
We must show that for every $\bm{m}\in\mathscr{M}_+$, the level set $J_{\bm{m}}(q)$ is a non-empty closed interval for each $q\in D_{\bm{m}}$, so that $P_{\bm{m}}$ is well-defined, and that $P_{\bm{m}}$ satisfies properties \eqref{claim:compact-dom}--\eqref{claim:zero-is-contained}. First, note that because $b_*,s_*\geq0$, the definition $D_{\bm{m}}=[-b_*,s_*]$ immediately yields \eqref{claim:compact-dom} and \eqref{claim:zero-is-contained} once $P_{\bm{m}}$ is shown to be well-defined on $D_{\bm{m}}$.

To show that $J_{\bm{m}}(q)$ is a non-empty closed interval for every $q\in D_{\bm{m}}$, let $x_0<x_1<\dots<x_K$ be the distinct elements of $\{-500,\overline{p}\}$ together with the order prices of $\bm{m}$, so that $x_0=-500$ and $x_K=\overline{p}$. No order price lies in $(x_{k-1},x_k)$, so the volumes offered and bid, and hence $E^{\bm{m}}$, are affine there. The completed graph of $E^{\bm{m}}$ is therefore the union of the segments from $(x_{k-1},E^{\bm{m}}(x_{k-1}+))$ to $(x_k,E^{\bm{m}}(x_k-))$, for $k=1,\dots,K$, and the vertical segments $\{x_k\}\times[E^{\bm{m}}(x_k-),E^{\bm{m}}(x_k+)]$, for $k=0,\dots,K$, where $E^{\bm{m}}(x_0-)=-b_*$ and $E^{\bm{m}}(x_K+)=s_*$. Taken in their order along the graph, consecutive segments share an endpoint, and their ranges of levels are closed intervals that cover $[-b_*,s_*]$ and overlap only at their endpoints. Consequently, $J_{\bm{m}}(q)$ is non-empty for every $q\in D_{\bm{m}}$, and it is closed because the completed graph is a finite union of closed segments.

Next, since $E^{\bm{m}}$ is non-decreasing, $p<p^\prime$ implies $E^{\bm{m}}(p+)\leq E^{\bm{m}}(p^\prime-)$. If $p<p^{\prime\prime}<p^\prime$ with $p,p^\prime\in J_{\bm{m}}(q)$, then
\begin{align*}
    E^{\bm{m}}(p^{\prime\prime}-)\leq E^{\bm{m}}(p^\prime-)\leq q\leq E^{\bm{m}}(p+)\leq E^{\bm{m}}(p^{\prime\prime}+),
\end{align*}
so $p^{\prime\prime}\in J_{\bm{m}}(q)$. Thus $J_{\bm{m}}(q)$ is a non-empty closed interval, and $P_{\bm{m}}$ is well-defined on $D_{\bm{m}}$.

To establish \eqref{claim:increasing}, let $q,q^\prime\in D_{\bm{m}}$ satisfy $q<q^\prime$, and let $p\in J_{\bm{m}}(q)$ and $p^\prime\in J_{\bm{m}}(q^\prime)$. Then $p\leq p^\prime$, because $p^\prime<p$ would yield $q^\prime\leq E^{\bm{m}}(p^\prime+)\leq E^{\bm{m}}(p-)\leq q$, a contradiction. Taking the maximum over $p\in J_{\bm{m}}(q)$ and the minimum over $p^\prime\in J_{\bm{m}}(q^\prime)$ gives
\begin{align*}
    P_{\bm{m}}(q)\leq\max J_{\bm{m}}(q)\leq\min J_{\bm{m}}(q^\prime)\leq P_{\bm{m}}(q^\prime),
\end{align*}
which proves that $P_{\bm{m}}$ is increasing.

Finally, to establish \eqref{claim:pw-affine}, we remove from $D_{\bm{m}}$ the finitely many levels $E^{\bm{m}}(x_k\pm)$. Every remaining level $q$ lies in the interior of the range of levels of exactly one segment, and no other segment reaches $q$, since the endpoints of these ranges have been removed. If the segment is the $k$th non-vertical one, then $E^{\bm{m}}$ is affine with positive slope on $(x_{k-1},x_k)$, the set $J_{\bm{m}}(q)$ consists of the single price at which $E^{\bm{m}}$ takes the value $q$, and $P_{\bm{m}}$ agrees with the affine inverse of $E^{\bm{m}}$ on the interior of the range. If it is the vertical segment at $x_k$, then $J_{\bm{m}}(q)=\{x_k\}$, and $P_{\bm{m}}$ equals $x_k$ on the interior of the range. Hence $D_{\bm{m}}$ is the disjoint union of finitely many open intervals, on each of which $P_{\bm{m}}$ is affine, and finitely many singletons, which establishes \eqref{claim:pw-affine}, as desired.

results.statement:
\label{prop:price-impact-curve-properties}
    Let $\bm{m}\in\mathscr{M}_+$ be a positively matched market state with total sell volume $s_*$, total buy volume $b_*$, available-depth interval $D_{\bm{m}}=[-b_*,s_*]$, and price-impact curve $P_{\bm{m}}:D_{\bm{m}}\to\mathcal{P}$. Then $P_{\bm{m}}$ has the following properties.
\begin{enumerate}[(i)]
    \item $\operatorname{domain}(P_{\bm{m}})=D_{\bm{m}}=[-b_*,s_*]$.\label{claim:compact-dom}
    \item The function $P_{\bm{m}}$ is piecewise affine over finitely many disjoint intervals, some of which may be singletons.\label{claim:pw-affine}
    \item The function $P_{\bm{m}}$ is increasing (that is, non-decreasing). \label{claim:increasing}
    \item $0 \in \mathrm{domain}(P_{\bm{m}})$. \label{claim:zero-is-contained}
\end{enumerate}

\label{defn:space-of-price-curves}
    The \emph{space of price curves} is defined by
    \begin{align*}
        \mathpzc{P}
        =
        \bigcup_{\substack{a,b \in \mathbb{R}\\ a\leq 0\leq b}}
        \{f:[a,b] \to \mathbb{R}\mid f\text{ is increasing and piecewise affine}\},
    \end{align*}
    where \emph{increasing} means non-decreasing, and \emph{piecewise affine} means affine on each of finitely many pairwise disjoint intervals, singletons included. A price curve $f\in\mathpzc{P}$ is called \emph{simple} if it is constant on each of these intervals.

Let $U$ and $X$ be sets. A parametrisation of $X$ by $U$ is a surjective function
    \begin{align*}
        \vartheta:U\to X.
    \end{align*}

\label{defn:admissible-price-curve-parametrisation}
    Let $\mathpzc{P}$ be the space of price curves of Definition~\ref{defn:space-of-price-curves}, and for each $f\in\mathpzc{P}$, let $\Gamma(f)=\{(x,f(x))\mid x\in\mathrm{domain}(f)\}\subseteq\mathbb{R}^2$ denote its graph. Let $\Theta$ be an operator from $\mathpzc{P}$ to $\mathcal{L}^2([-1,1]; \mathbb{R}^2)$ such that, for each $f \in \mathpzc{P}$,
    \begin{align*}
        \Theta f \equiv \Theta(f) : [-1, 1] \to \Gamma(f),
    \end{align*}
    and suppose that
    \begin{align*}
        \Theta f(t) = (\vartheta_f(t), (f \circ \vartheta_f)(t))
    \end{align*}
    for an increasing, continuous, and surjective function $\vartheta_f : [-1,1] \to \mathrm{domain}(f)$ satisfying $\vartheta_f(0) = 0$. We call $\Theta$ an \emph{admissible parametrisation operator} and $\vartheta_f$ the parametriser of $f$.

\label{defn:linear-parametrisation-operator}
    Let $\mathpzc{P}$ be the space of price curves. For each $f\in\mathpzc{P}$ with $\mathrm{domain}(f)=[l_f,r_f]$, the \emph{volume-proportional (linear) parametrisation} $\lambda_f:[-1,1]\to[l_f,r_f]$ is defined by
    \begin{align*}
        \lambda_f(u)=
        \begin{cases}
            -l_f u & u\in[-1,0),\\
            \phantom{-}r_f u & u\in[0,1].
        \end{cases}
    \end{align*}
    The pointwise and Hilbert-valued \emph{linear parametrisation operators} $\Lambda:\mathpzc{P}\to\mathcal{L}^2([-1,1];\mathbb{R}^2)$ and $\overline{\Lambda}:\mathpzc{P}\to L^2([-1,1];\mathbb{R}^2)$ are defined for each $f\in\mathpzc{P}$ and $u\in[-1,1]$ by
    \begin{align*}
        \Lambda(f)(u)
        &=\bigl(\lambda_f(u),f(\lambda_f(u))\bigr),\\
        \overline{\Lambda}(f)
        &=[\Lambda(f)]\in L^2([-1,1];\mathbb{R}^2).
    \end{align*}

steps.text:
By Definition~\ref{defn:weakly-convex-operator}, we must show that for all $f,g\in\mathpzc{P}$ and all $\alpha,\beta\geq0$, there exists a price curve $h\in\mathpzc{P}$ such that $\alpha\Lambda(f)+\beta\Lambda(g)=\Lambda(h)$. Fix $f,g\in\mathpzc{P}$ and $\alpha,\beta\geq0$. The first and second coordinate functions of $\alpha\Lambda(f)+\beta\Lambda(g)$ are given by
    \begin{align*}
        q&=\alpha\lambda_f+\beta\lambda_g,\\
        p&=\alpha f\circ\lambda_f+\beta g\circ\lambda_g.
    \end{align*}
    On $[-1,0]$ and $[0,1]$, respectively, the first component satisfies
    \begin{align*}
        q(u)=-(\alpha l_f+\beta l_g)u,
        \qquad
        q(u)=(\alpha r_f+\beta r_g)u.
    \end{align*}
    Hence $q$ is the linear parametrisation of the interval
    \begin{align*}
        [\alpha l_f+\beta l_g,\,\alpha r_f+\beta r_g].
    \end{align*}
    Next, suppose that $u,v\in[-1,1]$ satisfy $u<v$ and $q(u)=q(v)$. Then
    \begin{align*}
        0
        &=q(v)-q(u)\\
        &=\alpha\bigl(\lambda_f(v)-\lambda_f(u)\bigr)
          +\beta\bigl(\lambda_g(v)-\lambda_g(u)\bigr).
    \end{align*}
    Because $\lambda_f$ and $\lambda_g$ are increasing, both differences on the right-hand side are non-negative. Hence each difference with a strictly positive coefficient vanishes, so $f\circ\lambda_f$ (respectively $g\circ\lambda_g$) is constant on $[u,v]$ whenever $\alpha>0$ (respectively $\beta>0$). It follows that $p(u)=p(v)$.

Consequently, the rule
    \begin{align*}
        h(x)=p(u)
        \qquad\text{for any }u\in[-1,1]\text{ such that }q(u)=x
    \end{align*}
    defines a well-defined, increasing, piecewise-affine function $h\in\mathpzc{P}$ on $\mathrm{image}(q)$, which is simple whenever $f$ and $g$ are simple, since on each half of $[-1,1]$ the map $q$ is linear and $p$ is piecewise affine in $u$. Moreover, by construction, $q=\lambda_h$ and $p=h\circ\lambda_h$, which yields
    \begin{align*}
        \alpha\Lambda(f)+\beta\Lambda(g)=\Lambda(h).
    \end{align*}
    Thus $\Lambda$ is weakly convex, as desired.

proof.text:
By Definition~\ref{defn:weakly-convex-operator}, we must show that for all $f,g\in\mathpzc{P}$ and all $\alpha,\beta\geq0$, there exists a price curve $h\in\mathpzc{P}$ such that $\alpha\Lambda(f)+\beta\Lambda(g)=\Lambda(h)$. Fix $f,g\in\mathpzc{P}$ and $\alpha,\beta\geq0$. The first and second coordinate functions of $\alpha\Lambda(f)+\beta\Lambda(g)$ are given by
    \begin{align*}
        q&=\alpha\lambda_f+\beta\lambda_g,\\
        p&=\alpha f\circ\lambda_f+\beta g\circ\lambda_g.
    \end{align*}
    On $[-1,0]$ and $[0,1]$, respectively, the first component satisfies
    \begin{align*}
        q(u)=-(\alpha l_f+\beta l_g)u,
        \qquad
        q(u)=(\alpha r_f+\beta r_g)u.
    \end{align*}
    Hence $q$ is the linear parametrisation of the interval
    \begin{align*}
        [\alpha l_f+\beta l_g,\,\alpha r_f+\beta r_g].
    \end{align*}
    Next, suppose that $u,v\in[-1,1]$ satisfy $u<v$ and $q(u)=q(v)$. Then
    \begin{align*}
        0
        &=q(v)-q(u)\\
        &=\alpha\bigl(\lambda_f(v)-\lambda_f(u)\bigr)
          +\beta\bigl(\lambda_g(v)-\lambda_g(u)\bigr).
    \end{align*}
    Because $\lambda_f$ and $\lambda_g$ are increasing, both differences on the right-hand side are non-negative. Hence each difference with a strictly positive coefficient vanishes, so $f\circ\lambda_f$ (respectively $g\circ\lambda_g$) is constant on $[u,v]$ whenever $\alpha>0$ (respectively $\beta>0$). It follows that $p(u)=p(v)$.

    Consequently, the rule
    \begin{align*}
        h(x)=p(u)
        \qquad\text{for any }u\in[-1,1]\text{ such that }q(u)=x
    \end{align*}
    defines a well-defined, increasing, piecewise-affine function $h\in\mathpzc{P}$ on $\mathrm{image}(q)$, which is simple whenever $f$ and $g$ are simple, since on each half of $[-1,1]$ the map $q$ is linear and $p$ is piecewise affine in $u$. Moreover, by construction, $q=\lambda_h$ and $p=h\circ\lambda_h$, which yields
    \begin{align*}
        \alpha\Lambda(f)+\beta\Lambda(g)=\Lambda(h).
    \end{align*}
    Thus $\Lambda$ is weakly convex, as desired.

results.statement:
\label{defn:sided-essential-decomposition}\index{sided decomposition}
    Let $f\in\mathpzc{P}$ be a simple price curve with minimal representation \eqref{eq:minimal-representation} and cells and levels $(I_i,f_i)_{i=1}^n$. Define the negative-side and positive-side cell counts by
    \begin{align*}
        L_f
        &=\left|\left\{i\in\{1,\dots,n\}\mid I_i\cap(-\infty,0)\neq\emptyset\right\}\right|,\\
        U_f
        &=\left|\left\{i\in\{1,\dots,n\}\mid I_i\cap(0,\infty)\neq\emptyset\right\}\right|,
    \end{align*}
    and index the cells and levels relative to zero by setting
    \begin{align*}
        V_j&=
        \begin{cases}
            I_{j+L_f+1}\cap(-\infty,0) & j\in\{-L_f,\dots,-1\},\\
            \{0\} & j=0,\\
            I_{n-U_f+j}\cap(0,\infty) & j\in\{1,\dots,U_f\},
        \end{cases}\\
        g_j&=
        \begin{cases}
            f_{j+L_f+1} & j\in\{-L_f,\dots,-1\},\\
            f(0) & j=0,\\
            f_{n-U_f+j} & j\in\{1,\dots,U_f\}.
        \end{cases}
    \end{align*}
    The family $(V_j,g_j)_{j=-L_f}^{U_f}$, which satisfies
    \begin{align*}
        f(x)=\sum_{j=-L_f}^{U_f}g_j\mathbbm{1}_{V_j}(x),
    \end{align*}
    is called the \emph{sided essential decomposition} of $f$. The \emph{inducing knots} $(x_j,u_j)_{j=-L_f}^{U_f}$ are defined by
    \begin{align}\label{eq:inducing-points}
        x_j&=
        \begin{cases}
            \inf V_j & j<0,\\
            0 & j=0,\\
            \sup V_j & j>0,
        \end{cases}\\
        u_j&=
        \begin{cases}
            j/L_f & j\in\{-L_f,\dots,-1\},\\
            0 & j=0,\\
            j/U_f & j\in\{1,\dots,U_f\},
        \end{cases}
    \end{align}
    where the corresponding case involving division is understood to be empty when $L_f=0$ or $U_f=0$. Finally, the \emph{sided parametriser} $\psi_f:[-1,1]\to\mathrm{domain}(f)$ is the function that interpolates the knots $(u_j,x_j)$ linearly and vanishes on any side whose count is zero.

\label{defn:parametrisation-operator}\index{sided parametrisation operator}
    Let $\mathpzc{P}_{\mathrm{s}}\subseteq\mathpzc{P}$ denote the set of simple price curves, and for each $f\in\mathpzc{P}_{\mathrm{s}}$, let $\psi_f:[-1,1]\to\mathrm{domain}(f)$ be the sided parametriser of Definition~\ref{defn:sided-essential-decomposition}. The pointwise and Hilbert-valued \emph{sided parametrisation operators} $\Psi:\mathpzc{P}_{\mathrm{s}}\to\mathcal{L}^2([-1,1];\mathbb{R}^2)$ and $\overline{\Psi}:\mathpzc{P}_{\mathrm{s}}\to L^2([-1,1];\mathbb{R}^2)$ are defined for each $f\in\mathpzc{P}_{\mathrm{s}}$ and $u\in[-1,1]$ by
    \begin{align*}
        \Psi(f)(u)
        &=\bigl(\psi_f(u),f(\psi_f(u))\bigr),\\
        \overline{\Psi}(f)
        &=[\Psi(f)]\in L^2([-1,1];\mathbb{R}^2).
    \end{align*}

\label{defn:graph-tracing-pairs}
    The \emph{family of graph-tracing pairs}, denoted by $\mathcal{A}\subseteq\mathcal{L}^2([-1,1];\mathbb{R}^2)$, consists of all pairs $(q,p)\in\mathcal{L}^2([-1,1];\mathbb{R}^2)$ such that
    \begin{enumerate}
        \item $q$ is continuous, increasing, and piecewise affine, and satisfies $q(0)=0$;
        \item $p$ is increasing and piecewise affine;
        \item $q(u)=q(v)$ implies $p(u)=p(v)$ for all $u,v\in[-1,1]$; and
        \item $p$ is right-continuous on $[-1,1)$ and, writing $\tau_q=\inf q^{-1}(\{q(1)\})$, satisfies $p(\tau_q)=\lim_{u\uparrow\tau_q}p(u)$ whenever $\tau_q>-1$.
    \end{enumerate}

\label{prop:admissible-parametrisations-cone}
    Let $\mathcal{A}\subseteq\mathcal{L}^2([-1,1];\mathbb{R}^2)$ be the family of graph-tracing pairs of Definition~\ref{defn:graph-tracing-pairs}, and let $\mathpzc{P}$ be the space of price curves. Then $\mathcal{A}$ is a convex cone, and there is a well-defined \emph{graph-wise decoder} $D:\mathcal{A}\to\mathpzc{P}$ that assigns to each $(q,p)\in\mathcal{A}$ a unique curve $D(q,p)\in\mathpzc{P}$ on $\mathrm{image}(q)$ via
    \begin{align}\label{eq:graph-wise-decoder}
        D(q,p)(x)
        =p(u)\qquad\text{for any }u\in[-1,1]\text{ such that }q(u)=x.
    \end{align}

\label{exmp:sided-average-not-canonical}
    Consider the increasing simple curves
    \begin{align*}
        f:[0,2]&\to\mathbb{R},
        &f(x)&=
        \begin{cases}
            0 & 0\leq x<1,\\
            2 & 1\leq x\leq2,
        \end{cases}\\
        g:[0,3]&\to\mathbb{R},
        &g(x)&=
        \begin{cases}
            0 & 0\leq x<1,\\
            1 & 1\leq x<2,\\
            3 & 2\leq x\leq3.
        \end{cases}
    \end{align*}
    On $[0,1]$, the sided parametrising functions are $\psi_f(u)=2u$ and $\psi_g(u)=3u$. Hence the first component of the pointwise average
    \begin{align*}
        z=\frac{1}{2}\Psi(f)+\frac{1}{2}\Psi(g)
    \end{align*}
    is
    \begin{align*}
        q(u)=\frac{5}{2}u.
    \end{align*}
    The second component has four levels and changes at
    \begin{align*}
        u=\frac{1}{3},\qquad u=\frac{1}{2},\qquad u=\frac{2}{3}.
    \end{align*}
    The pair $z$ belongs to $\mathcal{A}$. Its decoded curve $h$ has four blocks on $[0,5/2]$, with endpoints
    \begin{align*}
        \frac{5}{6},\qquad \frac{5}{4},\qquad \frac{5}{3},\qquad \frac{5}{2}.
    \end{align*}
    Because $h$ has four positive-side blocks, its canonical sided parametrisation assigns its first endpoint $5/6$ to parameter value $1/4$. Consequently,
    \begin{align*}
        \psi_h\left(\frac{1}{4}\right)=\frac{5}{6},
        \qquad
        q\left(\frac{1}{4}\right)=\frac{5}{8}.
    \end{align*}
    Thus $\Psi(h)\neq z$. Since $z$ traces the graph of the uniquely decoded curve $h$, it cannot equal $\Psi(k)$ for any other $k\in\mathpzc{P}$. Therefore $z\notin\Psi(\mathpzc{P})$.

    We must also rule out equality after passage to $L^2$ equivalence classes. Suppose, to the contrary, that $\overline{\Psi}(k)=[z]$ for some $k\in\mathpzc{P}$. The first components $\psi_k$ and $q$ are continuous and equal almost everywhere, and are therefore equal everywhere. On $[0,1]$, the function $q$ is strictly increasing. Equality of the second components almost everywhere therefore implies that $k$ has the same four positive-length blocks and the same block endpoints as $h$. Its block-based sided parametriser must consequently satisfy
    \begin{align*}
        \psi_k\left(\frac{1}{4}\right)=\frac{5}{6}.
    \end{align*}
    This contradicts $\psi_k=q$ and $q(1/4)=5/8$. Hence $[z]\notin\overline{\Psi}(\mathpzc{P})$, so the Hilbert-valued image is not convex either.

steps.text:
To establish Borel measurability, we decompose each fixed-length layer of $\mathscr{L}$ into a finite Borel partition on whose cells every stage of the construction coincides with a fixed continuous map; Theorem~\ref{thm:measurable-partition} then yields global Borel measurability. By the \hyperref[thm:the-standard-machinery]{standard machinery} (Theorem~\ref{thm:the-standard-machinery}), the fixed-length layers
\begin{align*}
    \mathscr{L}_{n,n^\prime}=\mathscr{L}\cap\bigl((\mathbb{R}\times[0,\infty))^{n}\times(\mathbb{R}\times[0,\infty))^{n^\prime}\bigr),\qquad n,n^\prime\in\mathbb{N},
\end{align*}
form a countable Borel partition of $\mathscr{L}$ in its subspace topology, because the fixed-length product layers are clopen and hence Borel in the ambient product of tuple spaces. Since every comparison set below is defined relative to $\mathscr{L}_{n,n^\prime}$ and therefore belongs to the subspace Borel $\sigma$-algebra $\mathcal{B}(\mathscr{L}_{n,n^\prime})$, it suffices to fix $(n,n^\prime)\in\mathbb{N}^2$ and to construct a finite Borel partition of $\mathscr{L}_{n,n^\prime}$ on each cell of which $Z$ and $\bm{m}\mapsto P_{\bm{m}}(0)$ are continuous.

First, we partition $\mathscr{L}_{n,n^\prime}$ according to the sorting permutations of the sell and buy lists. The sell list $\bm{s}$ is sorted by increasing price and, within a price, by increasing volume, while the buy list $\bm{b}$ is sorted by decreasing price and, within a price, by increasing volume. Both relations are total orders on $\mathbb{R}\times[0,\infty)$, and both are Borel in the sense of Section~\ref{sec:sorting-properties} because their graphs are Borel subsets of $(\mathbb{R}\times[0,\infty))^2$. Let $\varsigma_{\mathrm{sell}}$ and $\varsigma_{\mathrm{buy}}$ denote the corresponding minimal sorting operators of Theorem~\ref{thm:minimal-sorting-measurable}. By Proposition~\ref{prop:measurable-partition-sorting} and Corollary~\ref{cor:local-continuity-sorting}, for each pair of permutations $(\pi_s,\pi_b)\in\mathcal{P}_n\times\mathcal{P}_{n^\prime}$, the set
\begin{align*}
    \mathscr{S}_{\pi_s,\pi_b}
    =\bigl\{\bm{m}=(\bm{s},\bm{b})\in\mathscr{L}_{n,n^\prime}\bigm| \varsigma_{\mathrm{sell}}(\bm{s})=\bm{s}[\pi_s]\;\land\;\varsigma_{\mathrm{buy}}(\bm{b})=\bm{b}[\pi_b]\bigr\}
\end{align*}
is Borel measurable in $\mathscr{L}_{n,n^\prime}$, and on $\mathscr{S}_{\pi_s,\pi_b}$ the sorting maps coincide with the continuous coordinate permutations $\bm{s}\mapsto\bm{s}[\pi_s]$ and $\bm{b}\mapsto\bm{b}[\pi_b]$. Because distinct permutations can produce the same sorted tuple when entries coincide, we fix a total ordering of the finite product $\mathcal{P}_n\times\mathcal{P}_{n^\prime}$ and replace each $\mathscr{S}_{\pi_s,\pi_b}$ by its set difference from the union of all preceding cells; retaining the notation $\mathscr{S}_{\pi_s,\pi_b}$ for these disjoint Borel sets yields a finite Borel partition of $\mathscr{L}_{n,n^\prime}$ on each cell of which the same continuous sorting formula holds. Furthermore, because the pointwise maximum of finitely many continuous functions is continuous, the running maxima of the sorted volumes depend continuously on $\bm{m}\in\mathscr{S}_{\pi_s,\pi_b}$.

Second, to formalise the dependence of the excess supply on the order prices, let $N_p=n+n^\prime+2$ and define the combined price-extraction map $\bm{\pi}:\mathscr{L}_{n,n^\prime}\to\mathcal{P}^{N_p}$ by concatenating the lower price limit, the sorted sell prices, the sorted buy prices, and the upper price limit:
\begin{align*}
    \bm{\pi}(\bm{s},\bm{b})=(-500)\oplus\bm{P}_{\mathrm{price}}\bigl(\varsigma_{\mathrm{sell}}(\bm{s})\bigr)\oplus\bm{P}_{\mathrm{price}}\bigl(\varsigma_{\mathrm{buy}}(\bm{b})\bigr)\oplus(\overline{p}).
\end{align*}
Since $\varsigma_{\mathrm{sell}}$ and $\varsigma_{\mathrm{buy}}$ are continuous on each cell $\mathscr{S}_{\pi_s,\pi_b}$, and coordinate projections and concatenation are continuous by Proposition~\ref{prop:tuple-projection-continuous} and Theorem~\ref{thm:analytic-properties-actions}, the map $\bm{\pi}$ is continuous on $\mathscr{S}_{\pi_s,\pi_b}$. For every pair of indices $u,v\in\{1,\dots,N_p\}$, define the elementary comparison sets
\begin{align*}
    E_{u,v}&=\bigl\{\bm{m}\in\mathscr{L}_{n,n^\prime}\bigm|\bm{\pi}(\bm{m})(u)=\bm{\pi}(\bm{m})(v)\bigr\},\\
    L_{u,v}&=\bigl\{\bm{m}\in\mathscr{L}_{n,n^\prime}\bigm|\bm{\pi}(\bm{m})(u)<\bm{\pi}(\bm{m})(v)\bigr\}.
\end{align*}
Because the diagonal is closed in $\mathbb{R}^2$ and the strict order relation is open in $\mathbb{R}^2$, each $E_{u,v}$ and each $L_{u,v}$ has a Borel intersection with $\mathscr{S}_{\pi_s,\pi_b}$. Any total preorder on the finite index set $\{1,\dots,N_p\}$ is specified by an ordered partition $\mathcal{C}=(C_1,\dots,C_r)$ of $\{1,\dots,N_p\}$ into non-empty equivalence classes. For each such ordered partition $\mathcal{C}$, define the cell
\begin{align*}
    \mathscr{W}(\mathcal{C})=\left(\bigcap_{k=1}^r\bigcap_{u,v\in C_k}E_{u,v}\right)\cap\left(\bigcap_{1\leq k<l\leq r}\bigcap_{u\in C_k,\,v\in C_l}L_{u,v}\right).
\end{align*}
As $\mathcal{C}$ ranges over the finitely many ordered partitions of $\{1,\dots,N_p\}$, the sets $\mathscr{S}_{\pi_s,\pi_b}\cap\mathscr{W}(\mathcal{C})$ form a finite Borel refinement of $\mathscr{S}_{\pi_s,\pi_b}$. On each non-empty cell of this refinement, the number $r$ of distinct prices is constant, and choosing the minimum index $u_k=\min C_k$ in each equivalence class yields the strictly increasing distinct price coordinates
\begin{align*}
    x_k(\bm{m})=\bm{\pi}(\bm{m})(u_k),\qquad k\in\{1,\dots,r\},
\end{align*}
which satisfy $-500=x_1(\bm{m})<x_2(\bm{m})<\dots<x_r(\bm{m})=\overline{p}$ and depend continuously on $\bm{m}$. Furthermore, on each such cell, the position of $x_k(\bm{m})$ relative to the sorted sell and buy prices is fixed, so the one-sided limits at $x_k(\bm{m})$ of the offered and bid volumes are given by fixed expressions, namely $0$, a running maximum of the sorted volumes, or the linear interpolation at $x_k(\bm{m})$ between two consecutive list entries whose price difference is strictly positive on the cell. Consequently, the maps $\bm{m}\mapsto E^{\bm{m}}(x_k(\bm{m})-)$ and $\bm{m}\mapsto E^{\bm{m}}(x_k(\bm{m})+)$ are continuous on the cell for every $k\in\{1,\dots,r\}$.

Third, we refine each cell according to the jump structure of $E^{\bm{m}}$ and the location of zero quantity. For each $k\in\{1,\dots,r\}$, define the Borel set
\begin{align*}
    J_k=\bigl\{\bm{m}\in\mathscr{L}_{n,n^\prime}\bigm| E^{\bm{m}}(x_k(\bm{m})-)=E^{\bm{m}}(x_k(\bm{m})+)\bigr\},
\end{align*}
and for each subset $K\subseteq\{1,\dots,r\}$, set
\begin{align*}
    \mathscr{J}(K)=\left(\bigcap_{k\in K}J_k\right)\cap\left(\bigcap_{k\in\{1,\dots,r\}\setminus K}J_k^{\mathrm{c}}\right).
\end{align*}
Intersecting the previous cells with $\mathscr{J}(K)$ fixes the number $N=2r-\lvert K\rvert$ of distinct vertices of the completed graph of $E^{\bm{m}}$. Interchanging the price and excess-supply coordinates then yields a continuous vertex path $\bm{m}\mapsto\bigl((q_1(\bm{m}),p_1(\bm{m})),\allowbreak\dots,\allowbreak(q_N(\bm{m}),p_N(\bm{m}))\bigr)$ of $P_{\bm{m}}$, running from $(-b_*,x_1)$ to $(s_*,\overline{p})$ with $q_1(\bm{m})\leq\dots\leq q_N(\bm{m})$. To extract the crossing price and the one-sided limits at zero, define for each $i\in\{1,\dots,N\}$ the sign sets
\begin{align*}
    Z_i^-=\bigl\{\bm{m}\bigm| q_i(\bm{m})<0\bigr\},\qquad
    Z_i^0=\bigl\{\bm{m}\bigm| q_i(\bm{m})=0\bigr\},\qquad
    Z_i^+=\bigl\{\bm{m}\bigm| q_i(\bm{m})>0\bigr\}.
\end{align*}
For every sign assignment $\bm{\sigma}=(\sigma_1,\dots,\sigma_N)\in\{-,0,+\}^N$, the intersection $\mathscr{Z}(\bm{\sigma})=\bigcap_{i=1}^N Z_i^{\sigma_i}$ is Borel measurable. On each non-empty cell intersected with $\mathscr{Z}(\bm{\sigma})$, the index sets $I_-=\{i\mid\sigma_i=-\}$, $I_0=\{i\mid\sigma_i=0\}$, and $I_+=\{i\mid\sigma_i=+\}$ are fixed. If $I_0\neq\emptyset$ with $i_{\min}=\min I_0$ and $i_{\max}=\max I_0$, then $P_{\bm{m}}(0)=\frac{1}{2}(p_{i_{\min}}(\bm{m})+p_{i_{\max}}(\bm{m}))$, $P_{\bm{m}}(0-)=p_{i_{\min}}(\bm{m})$, and $P_{\bm{m}}(0+)=p_{i_{\max}}(\bm{m})$. If $I_0=\emptyset$, then there is a unique index $i_*\in I_-$ such that $i_*+1\in I_+$, and $P_{\bm{m}}(0)=P_{\bm{m}}(0-)=P_{\bm{m}}(0+)$ coincides with the linear interpolation of $p_{i_*}(\bm{m})$ and $p_{i_*+1}(\bm{m})$ at $0$, whose denominator $q_{i_*+1}(\bm{m})-q_{i_*}(\bm{m})$ is strictly positive on the cell. In either case, $P_{\bm{m}}(0)$, $P_{\bm{m}}(0-)$, and $P_{\bm{m}}(0+)$ depend continuously on $\bm{m}$.

Fourth, we partition each resulting cell to fix the breakpoints of $P_{\bm{m}}$ on the positive and negative sides. We write out the positive side; the negative side is partitioned identically after replacing $q$ with $-q$. On each cell of the current refinement, the positive-side vertex path $(q_1^+(\bm{m}),p_1^+(\bm{m})),\dots,(q_{n_+}^+(\bm{m}),p_{n_+}^+(\bm{m}))$, starting at $(0,P_{\bm{m}}(0+))$ and continuing through the vertices with $i\in I_+$, has a fixed length $n_+$ and depends continuously on $\bm{m}$. For each $k\in\{1,\dots,n_+-1\}$, define the equality sets
\begin{align*}
    Q_k^+=\bigl\{\bm{m}\bigm| q_k^+(\bm{m})=q_{k+1}^+(\bm{m})\bigr\},\qquad
    P_k^+=\bigl\{\bm{m}\bigm| p_k^+(\bm{m})=p_{k+1}^+(\bm{m})\bigr\}.
\end{align*}
Intersecting the current cell with each combination of $Q_k^+,(Q_k^+)^{\mathrm{c}}$ and $P_k^+,(P_k^+)^{\mathrm{c}}$ over $k\in\{1,\dots,n_+-1\}$ yields a finite Borel refinement on which the indices of repeated vertices, vertical segments, and segments of positive width are constant. After omitting repeated vertices, let $(\tilde{q}_1^+(\bm{m}),\tilde{p}_1^+(\bm{m})),\allowbreak\dots,\allowbreak(\tilde{q}_{\tilde{n}_+}^+(\bm{m}),\tilde{p}_{\tilde{n}_+}^+(\bm{m}))$ denote the reduced positive-side vertex path. For each interior index $k\in\{2,\dots,\tilde{n}_+-1\}$ that joins two segments of positive width, define the collinearity set
\begin{align*}
    A_k^+=\bigl\{\bm{m}\bigm|\bigl(\tilde{q}_k^+(\bm{m})-\tilde{q}_{k-1}^+(\bm{m})\bigr)\bigl(\tilde{p}_{k+1}^+(\bm{m})-\tilde{p}_k^+(\bm{m})\bigr)\\
    =\bigl(\tilde{p}_k^+(\bm{m})-\tilde{p}_{k-1}^+(\bm{m})\bigr)\bigl(\tilde{q}_{k+1}^+(\bm{m})-\tilde{q}_k^+(\bm{m})\bigr)\bigr\}.
\end{align*}
Because $\tilde{q}_k^+$ and $\tilde{p}_k^+$ are continuous on the current cell, each $A_k^+$ is closed in the cell and hence Borel measurable. Intersecting with $\bigl(\bigcap_{k\in B}A_k^+\bigr)\cap\bigl(\bigcap_{k\notin B}(A_k^+)^{\mathrm{c}}\bigr)$ for each subset $B$ of such interior indices fixes the positive-side breakpoints, the number $U$ of pieces of positive width on the positive side, and the endpoints of every piece as fixed continuous vertex coordinates of the path. Performing the analogous finite intersection on the negative side fixes the number $L$ of negative-side pieces of positive width and their continuous endpoints.

proof.text:
We must show first that the maps $Z:\mathscr{L}\to\allowbreak L^2([-1,1];\mathbb{R}^2)$ and $\bm{m}\mapsto P_{\bm{m}}(0)$ are Borel measurable with respect to $\mathcal{B}(\mathscr{L})$, and second that $\mathbb{E}\bigl[\lVert Z(\bm{M})\rVert_{L^2([-1,1];\mathbb{R}^2)}^2\bigr]<\infty$ whenever $\mathbb{E}[D(\bm{M})^2]<\infty$.

To establish Borel measurability, we decompose each fixed-length layer of $\mathscr{L}$ into a finite Borel partition on whose cells every stage of the construction coincides with a fixed continuous map; Theorem~\ref{thm:measurable-partition} then yields global Borel measurability. By the \hyperref[thm:the-standard-machinery]{standard machinery} (Theorem~\ref{thm:the-standard-machinery}), the fixed-length layers
\begin{align*}
    \mathscr{L}_{n,n^\prime}=\mathscr{L}\cap\bigl((\mathbb{R}\times[0,\infty))^{n}\times(\mathbb{R}\times[0,\infty))^{n^\prime}\bigr),\qquad n,n^\prime\in\mathbb{N},
\end{align*}
form a countable Borel partition of $\mathscr{L}$ in its subspace topology, because the fixed-length product layers are clopen and hence Borel in the ambient product of tuple spaces. Since every comparison set below is defined relative to $\mathscr{L}_{n,n^\prime}$ and therefore belongs to the subspace Borel $\sigma$-algebra $\mathcal{B}(\mathscr{L}_{n,n^\prime})$, it suffices to fix $(n,n^\prime)\in\mathbb{N}^2$ and to construct a finite Borel partition of $\mathscr{L}_{n,n^\prime}$ on each cell of which $Z$ and $\bm{m}\mapsto P_{\bm{m}}(0)$ are continuous.

First, we partition $\mathscr{L}_{n,n^\prime}$ according to the sorting permutations of the sell and buy lists. The sell list $\bm{s}$ is sorted by increasing price and, within a price, by increasing volume, while the buy list $\bm{b}$ is sorted by decreasing price and, within a price, by increasing volume. Both relations are total orders on $\mathbb{R}\times[0,\infty)$, and both are Borel in the sense of Section~\ref{sec:sorting-properties} because their graphs are Borel subsets of $(\mathbb{R}\times[0,\infty))^2$. Let $\varsigma_{\mathrm{sell}}$ and $\varsigma_{\mathrm{buy}}$ denote the corresponding minimal sorting operators of Theorem~\ref{thm:minimal-sorting-measurable}. By Proposition~\ref{prop:measurable-partition-sorting} and Corollary~\ref{cor:local-continuity-sorting}, for each pair of permutations $(\pi_s,\pi_b)\in\mathcal{P}_n\times\mathcal{P}_{n^\prime}$, the set
\begin{align*}
    \mathscr{S}_{\pi_s,\pi_b}
    =\bigl\{\bm{m}=(\bm{s},\bm{b})\in\mathscr{L}_{n,n^\prime}\bigm| \varsigma_{\mathrm{sell}}(\bm{s})=\bm{s}[\pi_s]\;\land\;\varsigma_{\mathrm{buy}}(\bm{b})=\bm{b}[\pi_b]\bigr\}
\end{align*}
is Borel measurable in $\mathscr{L}_{n,n^\prime}$, and on $\mathscr{S}_{\pi_s,\pi_b}$ the sorting maps coincide with the continuous coordinate permutations $\bm{s}\mapsto\bm{s}[\pi_s]$ and $\bm{b}\mapsto\bm{b}[\pi_b]$. Because distinct permutations can produce the same sorted tuple when entries coincide, we fix a total ordering of the finite product $\mathcal{P}_n\times\mathcal{P}_{n^\prime}$ and replace each $\mathscr{S}_{\pi_s,\pi_b}$ by its set difference from the union of all preceding cells; retaining the notation $\mathscr{S}_{\pi_s,\pi_b}$ for these disjoint Borel sets yields a finite Borel partition of $\mathscr{L}_{n,n^\prime}$ on each cell of which the same continuous sorting formula holds. Furthermore, because the pointwise maximum of finitely many continuous functions is continuous, the running maxima of the sorted volumes depend continuously on $\bm{m}\in\mathscr{S}_{\pi_s,\pi_b}$.

Second, to formalise the dependence of the excess supply on the order prices, let $N_p=n+n^\prime+2$ and define the combined price-extraction map $\bm{\pi}:\mathscr{L}_{n,n^\prime}\to\mathcal{P}^{N_p}$ by concatenating the lower price limit, the sorted sell prices, the sorted buy prices, and the upper price limit:
\begin{align*}
    \bm{\pi}(\bm{s},\bm{b})=(-500)\oplus\bm{P}_{\mathrm{price}}\bigl(\varsigma_{\mathrm{sell}}(\bm{s})\bigr)\oplus\bm{P}_{\mathrm{price}}\bigl(\varsigma_{\mathrm{buy}}(\bm{b})\bigr)\oplus(\overline{p}).
\end{align*}
Since $\varsigma_{\mathrm{sell}}$ and $\varsigma_{\mathrm{buy}}$ are continuous on each cell $\mathscr{S}_{\pi_s,\pi_b}$, and coordinate projections and concatenation are continuous by Proposition~\ref{prop:tuple-projection-continuous} and Theorem~\ref{thm:analytic-properties-actions}, the map $\bm{\pi}$ is continuous on $\mathscr{S}_{\pi_s,\pi_b}$. For every pair of indices $u,v\in\{1,\dots,N_p\}$, define the elementary comparison sets
\begin{align*}
    E_{u,v}&=\bigl\{\bm{m}\in\mathscr{L}_{n,n^\prime}\bigm|\bm{\pi}(\bm{m})(u)=\bm{\pi}(\bm{m})(v)\bigr\},\\
    L_{u,v}&=\bigl\{\bm{m}\in\mathscr{L}_{n,n^\prime}\bigm|\bm{\pi}(\bm{m})(u)<\bm{\pi}(\bm{m})(v)\bigr\}.
\end{align*}
Because the diagonal is closed in $\mathbb{R}^2$ and the strict order relation is open in $\mathbb{R}^2$, each $E_{u,v}$ and each $L_{u,v}$ has a Borel intersection with $\mathscr{S}_{\pi_s,\pi_b}$. Any total preorder on the finite index set $\{1,\dots,N_p\}$ is specified by an ordered partition $\mathcal{C}=(C_1,\dots,C_r)$ of $\{1,\dots,N_p\}$ into non-empty equivalence classes. For each such ordered partition $\mathcal{C}$, define the cell
\begin{align*}
    \mathscr{W}(\mathcal{C})=\left(\bigcap_{k=1}^r\bigcap_{u,v\in C_k}E_{u,v}\right)\cap\left(\bigcap_{1\leq k<l\leq r}\bigcap_{u\in C_k,\,v\in C_l}L_{u,v}\right).
\end{align*}
As $\mathcal{C}$ ranges over the finitely many ordered partitions of $\{1,\dots,N_p\}$, the sets $\mathscr{S}_{\pi_s,\pi_b}\cap\mathscr{W}(\mathcal{C})$ form a finite Borel refinement of $\mathscr{S}_{\pi_s,\pi_b}$. On each non-empty cell of this refinement, the number $r$ of distinct prices is constant, and choosing the minimum index $u_k=\min C_k$ in each equivalence class yields the strictly increasing distinct price coordinates
\begin{align*}
    x_k(\bm{m})=\bm{\pi}(\bm{m})(u_k),\qquad k\in\{1,\dots,r\},
\end{align*}
which satisfy $-500=x_1(\bm{m})<x_2(\bm{m})<\dots<x_r(\bm{m})=\overline{p}$ and depend continuously on $\bm{m}$. Furthermore, on each such cell, the position of $x_k(\bm{m})$ relative to the sorted sell and buy prices is fixed, so the one-sided limits at $x_k(\bm{m})$ of the offered and bid volumes are given by fixed expressions, namely $0$, a running maximum of the sorted volumes, or the linear interpolation at $x_k(\bm{m})$ between two consecutive list entries whose price difference is strictly positive on the cell. Consequently, the maps $\bm{m}\mapsto E^{\bm{m}}(x_k(\bm{m})-)$ and $\bm{m}\mapsto E^{\bm{m}}(x_k(\bm{m})+)$ are continuous on the cell for every $k\in\{1,\dots,r\}$.

Third, we refine each cell according to the jump structure of $E^{\bm{m}}$ and the location of zero quantity. For each $k\in\{1,\dots,r\}$, define the Borel set
\begin{align*}
    J_k=\bigl\{\bm{m}\in\mathscr{L}_{n,n^\prime}\bigm| E^{\bm{m}}(x_k(\bm{m})-)=E^{\bm{m}}(x_k(\bm{m})+)\bigr\},
\end{align*}
and for each subset $K\subseteq\{1,\dots,r\}$, set
\begin{align*}
    \mathscr{J}(K)=\left(\bigcap_{k\in K}J_k\right)\cap\left(\bigcap_{k\in\{1,\dots,r\}\setminus K}J_k^{\mathrm{c}}\right).
\end{align*}
Intersecting the previous cells with $\mathscr{J}(K)$ fixes the number $N=2r-\lvert K\rvert$ of distinct vertices of the completed graph of $E^{\bm{m}}$. Interchanging the price and excess-supply coordinates then yields a continuous vertex path $\bm{m}\mapsto\bigl((q_1(\bm{m}),p_1(\bm{m})),\allowbreak\dots,\allowbreak(q_N(\bm{m}),p_N(\bm{m}))\bigr)$ of $P_{\bm{m}}$, running from $(-b_*,x_1)$ to $(s_*,\overline{p})$ with $q_1(\bm{m})\leq\dots\leq q_N(\bm{m})$. To extract the crossing price and the one-sided limits at zero, define for each $i\in\{1,\dots,N\}$ the sign sets
\begin{align*}
    Z_i^-=\bigl\{\bm{m}\bigm| q_i(\bm{m})<0\bigr\},\qquad
    Z_i^0=\bigl\{\bm{m}\bigm| q_i(\bm{m})=0\bigr\},\qquad
    Z_i^+=\bigl\{\bm{m}\bigm| q_i(\bm{m})>0\bigr\}.
\end{align*}
For every sign assignment $\bm{\sigma}=(\sigma_1,\dots,\sigma_N)\in\{-,0,+\}^N$, the intersection $\mathscr{Z}(\bm{\sigma})=\bigcap_{i=1}^N Z_i^{\sigma_i}$ is Borel measurable. On each non-empty cell intersected with $\mathscr{Z}(\bm{\sigma})$, the index sets $I_-=\{i\mid\sigma_i=-\}$, $I_0=\{i\mid\sigma_i=0\}$, and $I_+=\{i\mid\sigma_i=+\}$ are fixed. If $I_0\neq\emptyset$ with $i_{\min}=\min I_0$ and $i_{\max}=\max I_0$, then $P_{\bm{m}}(0)=\frac{1}{2}(p_{i_{\min}}(\bm{m})+p_{i_{\max}}(\bm{m}))$, $P_{\bm{m}}(0-)=p_{i_{\min}}(\bm{m})$, and $P_{\bm{m}}(0+)=p_{i_{\max}}(\bm{m})$. If $I_0=\emptyset$, then there is a unique index $i_*\in I_-$ such that $i_*+1\in I_+$, and $P_{\bm{m}}(0)=P_{\bm{m}}(0-)=P_{\bm{m}}(0+)$ coincides with the linear interpolation of $p_{i_*}(\bm{m})$ and $p_{i_*+1}(\bm{m})$ at $0$, whose denominator $q_{i_*+1}(\bm{m})-q_{i_*}(\bm{m})$ is strictly positive on the cell. In either case, $P_{\bm{m}}(0)$, $P_{\bm{m}}(0-)$, and $P_{\bm{m}}(0+)$ depend continuously on $\bm{m}$.

Fourth, we partition each resulting cell to fix the breakpoints of $P_{\bm{m}}$ on the positive and negative sides. We write out the positive side; the negative side is partitioned identically after replacing $q$ with $-q$. On each cell of the current refinement, the positive-side vertex path $(q_1^+(\bm{m}),p_1^+(\bm{m})),\dots,(q_{n_+}^+(\bm{m}),p_{n_+}^+(\bm{m}))$, starting at $(0,P_{\bm{m}}(0+))$ and continuing through the vertices with $i\in I_+$, has a fixed length $n_+$ and depends continuously on $\bm{m}$. For each $k\in\{1,\dots,n_+-1\}$, define the equality sets
\begin{align*}
    Q_k^+=\bigl\{\bm{m}\bigm| q_k^+(\bm{m})=q_{k+1}^+(\bm{m})\bigr\},\qquad
    P_k^+=\bigl\{\bm{m}\bigm| p_k^+(\bm{m})=p_{k+1}^+(\bm{m})\bigr\}.
\end{align*}
Intersecting the current cell with each combination of $Q_k^+,(Q_k^+)^{\mathrm{c}}$ and $P_k^+,(P_k^+)^{\mathrm{c}}$ over $k\in\{1,\dots,n_+-1\}$ yields a finite Borel refinement on which the indices of repeated vertices, vertical segments, and segments of positive width are constant. After omitting repeated vertices, let $(\tilde{q}_1^+(\bm{m}),\tilde{p}_1^+(\bm{m})),\allowbreak\dots,\allowbreak(\tilde{q}_{\tilde{n}_+}^+(\bm{m}),\tilde{p}_{\tilde{n}_+}^+(\bm{m}))$ denote the reduced positive-side vertex path. For each interior index $k\in\{2,\dots,\tilde{n}_+-1\}$ that joins two segments of positive width, define the collinearity set
\begin{align*}
    A_k^+=\bigl\{\bm{m}\bigm|\bigl(\tilde{q}_k^+(\bm{m})-\tilde{q}_{k-1}^+(\bm{m})\bigr)\bigl(\tilde{p}_{k+1}^+(\bm{m})-\tilde{p}_k^+(\bm{m})\bigr)\\
    =\bigl(\tilde{p}_k^+(\bm{m})-\tilde{p}_{k-1}^+(\bm{m})\bigr)\bigl(\tilde{q}_{k+1}^+(\bm{m})-\tilde{q}_k^+(\bm{m})\bigr)\bigr\}.
\end{align*}
Because $\tilde{q}_k^+$ and $\tilde{p}_k^+$ are continuous on the current cell, each $A_k^+$ is closed in the cell and hence Borel measurable. Intersecting with $\bigl(\bigcap_{k\in B}A_k^+\bigr)\cap\bigl(\bigcap_{k\notin B}(A_k^+)^{\mathrm{c}}\bigr)$ for each subset $B$ of such interior indices fixes the positive-side breakpoints, the number $U$ of pieces of positive width on the positive side, and the endpoints of every piece as fixed continuous vertex coordinates of the path. Performing the analogous finite intersection on the negative side fixes the number $L$ of negative-side pieces of positive width and their continuous endpoints.

Finally, on each cell of the combined finite Borel partition of $\mathscr{L}_{n,n^\prime}$, the numbers $L$ and $U$ are constant, and $\Psi(P_{\bm{m}})$ linearly interpolates the endpoints of the $j$th positive-width piece over $[(j-1)/U,j/U]$ on the positive side and over $[j/L,(j+1)/L]$ on the negative side. Recording the quantity endpoints and the one-sided price endpoints of every piece (retaining both price endpoints at a jump) yields a continuous finite-dimensional vector of endpoint coordinates on the cell. Because the map from this finite-dimensional vector of endpoint coordinates to the equivalence class of the corresponding piecewise-affine interpolant in $L^2([-1,1];\mathbb{R}^2)$ is linear and continuous, both $Z$ and $\bm{m}\mapsto P_{\bm{m}}(0)$ are continuous on every cell of the partition. Since the countable union of these finite partitions over $(n,n^\prime)\in\mathbb{N}^2$ forms a countable Borel partition of $\mathscr{L}$, Theorem~\ref{thm:measurable-partition} implies that $Z$ and $\bm{m}\mapsto P_{\bm{m}}(0)$ are Borel measurable on $\mathscr{L}$.

To prove the second claim, let $\bm{M}$ be a measurable random state in $\mathscr{L}$ with $\mathbb{E}[D(\bm{M})^2]<\infty$, and set $M_p=\max(500,\overline{p})$. Since every point of $\Psi(P_{\bm{M}})(u)$ lies on the completed graph of $P_{\bm{M}}$, we have $\lvert\psi_{P_{\bm{M}}}(u)\rvert\leq D(\bm{M})$ and $\lvert P_{\bm{M}}(\psi_{P_{\bm{M}}}(u))\rvert\leq M_p$ for all $u\in[-1,1]$. Integrating over $u\in[-1,1]$ yields
\begin{align*}
    \lVert Z(\bm{M})\rVert_{L^2([-1,1];\mathbb{R}^2)}^2
    =\int_{-1}^1\Bigl(\bigl\lvert\psi_{P_{\bm{M}}}(u)\bigr\rvert^2+\bigl\lvert P_{\bm{M}}\bigl(\psi_{P_{\bm{M}}}(u)\bigr)\bigr\rvert^2\Bigr)\,\mathrm{d}u
    \leq 2D(\bm{M})^2+2M_p^2.
\end{align*}
Taking expectations gives $\mathbb{E}[\lVert Z(\bm{M})\rVert_{L^2([-1,1];\mathbb{R}^2)}^2]\leq 2\mathbb{E}[D(\bm{M})^2]+2M_p^2<\infty$. Because $L^2([-1,1];\mathbb{R}^2)$ is separable, Borel measurability of $Z(\bm{M})$ implies strong measurability by Pettis's measurability theorem, so $Z(\bm{M})$ is a square-integrable Hilbert-valued random element, as desired.

results.statement:
\label{prop:pl-encoding-measurable}
    Fix $\overline{p}\in\{3000,4000\}$, and let $\mathcal{P}=[-500,\overline{p}]$. Let $\mathscr{L}$ be the set of pairs $\bm{m}=(\bm{s},\bm{b})\in\mathscr{T}(\mathbb{R}\times[0,\infty))\times\allowbreak\mathscr{T}(\mathbb{R}\times[0,\infty))$ of non-empty tuples whose first coordinates lie in $\mathcal{P}$, whose maximum first coordinate over both tuples equals $\overline{p}$, and whose maximum second coordinates are strictly positive in both tuples. Restrict $\mathscr{L}$ further to those pairs for which the construction below has strictly positive equilibrium quantity $Q(\bm{m})>0$, and endow $\mathscr{L}$ with the subspace metric inherited from the product of the tuple Hausdorff metrics. For each $\bm{m}\in\mathscr{L}$, let $P_{\bm{m}}:D_{\bm{m}}\to\mathcal{P}$ be the price-impact curve of Definition~\ref{defn:positively-matched-state-space-and-price-impact-curve} constructed from $\bm{s}$ and $\bm{b}$ after replacing the second coordinates of each tuple by their running maxima along the sorted orderings of increasing first coordinate for $\bm{s}$ and decreasing first coordinate for $\bm{b}$, and let $\overline{\Psi}:\mathpzc{P}\to L^2([-1,1];\mathbb{R}^2)$ denote the breakpoint-based sided parametrisation operator. Then the maps
    \begin{align*}
        \bm{m}\mapsto Z(\bm{m}):=\overline{\Psi}(P_{\bm{m}})\in L^2([-1,1];\mathbb{R}^2),\qquad \bm{m}\mapsto P_{\bm{m}}(0),
    \end{align*}
    are Borel measurable on $\mathscr{L}$. Moreover, if $\bm{M}$ is a measurable random element taking values in $\mathscr{L}$ and $D(\bm{M})=\max(b_*,s_*)$ denotes the larger of its terminal cumulative volumes, then $\mathbb{E}[D(\bm{M})^2]<\infty$ implies $\mathbb{E}[\lVert Z(\bm{M})\rVert_{L^2([-1,1];\mathbb{R}^2)}^2]<\infty$.

\label{defn:expected-hilbert}\index{expected value}
    Let $(\Omega,\mathcal{F},\mathbb{P})$ be a probability space, let $(\mathcal{H},\langle\cdot,\cdot\rangle)$ be a real separable Hilbert space, and let $X : \Omega \to \mathcal{H}$ be a random element with $\mathbb{E}[\lVert X\rVert] < \infty$. Then the expected value of $X$ is given by the Bochner integral
    \begin{align*}
        \mathbb{E}[X] = \int_\Omega X \, \mathrm{d}\mathbb{P}.
    \end{align*}

\label{defn:tensor-product}
    Let $(\mathcal{H}, \langle \cdot, \cdot \rangle)$ be a real separable Hilbert space. Define $\otimes:\mathcal{H} \times \mathcal{H} \to \mathcal{L}(\mathcal{H})$ by
    \begin{align*}
        (u \otimes v)(w) = \langle u, w\rangle v.
    \end{align*}

\label{defn:covariance-operator}\index{covariance operator}
    Let $(\Omega,\mathcal{F},\mathbb{P})$ be a probability space, let $(\mathcal{H},\langle\cdot,\cdot\rangle)$ be a real separable Hilbert space, and let $X : \Omega \to \mathcal{H}$ be a random element for which $\mathbb{E}[\lVert X\rVert^2] < \infty$, with mean $\mu = \mathbb{E}[X]$. Then the covariance operator of $X$ is the Bochner integral in $\mathcal{L}(\mathcal{H})$ given by
    \begin{align*}
        \mathbb{E}[(X - \mu) \otimes (X - \mu)] = \int_\Omega (X - \mu) \otimes (X - \mu) \, \mathrm{d}\mathbb{P}.
    \end{align*}

\label{thm:spectral-thm}
    Let $(\mathcal{H}, \langle \cdot, \cdot \rangle)$ be a real separable Hilbert space and let $A\in\mathcal{L}(\mathcal{H})$ be self-adjoint and compact. Then there exists a finite or countable orthonormal eigenbasis $(e_n)_{n \in I}$ for $\overline{\mathrm{image}(A)}$ such that
    \begin{align*}
        A = \sum_{n \in I} \lambda_n e_n \otimes e_n,
    \end{align*}
    with convergence in operator norm when $I$ is infinite. Each element $e_n$ is called an eigenvector of $A$, and the corresponding $\lambda_n \in \mathbb{R}$ is called the eigenvalue associated with $e_n$.

We order the eigenvalues, as is customary, so that
    \begin{align*}
        \forall n,m \in I: n \leq m \implies |\lambda_n| \geq |\lambda_m|.
    \end{align*}
A proof is given by \citet{hsing2015theoretical}. Since $A$ is self-adjoint, $\overline{\mathrm{image}(A)}=\ker(A)^\perp$ and $\mathcal{H}=\overline{\mathrm{image}(A)}\oplus\ker(A)$, with $A$ equal to zero on its kernel. Adjoining an orthonormal basis for $\ker(A)$ therefore extends this eigenbasis to a basis of the whole Hilbert space. The individual eigenvectors are not canonical, because a simple-eigenvalue eigenvector is determined only up to sign and an eigenspace of dimension greater than one admits many orthonormal bases. Only the eigenspaces and their orthogonal projections are invariant.

\label{thm:lln-clt-mean}\index{law of large numbers}\index{central limit theorem}
    Let $(\mathcal{H},\langle\cdot,\cdot\rangle)$ be a real separable Hilbert space, and let $X:\Omega \to \mathcal{H}$ be a random element with $\mathbb{E}[\lVert X\rVert] < \infty$ and mean $\mu$. Moreover, let $(X_i)_{i \in \mathbb{N}}$ be independent copies of $X$. Then, as $n \to \infty$,
    \begin{align}
        \frac{1}{n} \sum_{i=1}^n X_i \overset{\text{a.s.}}{\to} \mu.
    \end{align}
    Further, if $\mathbb{E}[\lVert X\rVert^2] < \infty$, then as $n \to \infty$,
    \begin{align}
        \sqrt{n}\left(\frac{1}{n} \sum_{i=1}^n X_i - \mu\right) \overset{d}{\to} \xi,
    \end{align}
    where $\xi$ is an $\mathcal{H}$-valued Gaussian random element with mean $0$ and covariance operator $\Sigma=\mathbb{E}[(X - \mu) \otimes (X - \mu)]$; that is, $\langle\xi,u\rangle$ is normally distributed with mean $0$ and variance $\langle\Sigma u,u\rangle$ for every $u\in\mathcal{H}$.

\label{thm:lln-covariance}
    Let $(\mathcal{H},\langle\cdot,\cdot\rangle)$ be a real separable Hilbert space, let $X:\Omega \to \mathcal{H}$ be a random element with $\mathbb{E}[\lVert X\rVert^2] < \infty$, and let $(X_i)_{i \in \mathbb{N}}$ be independent copies of $X$. Write $\mu = \mathbb{E}[X]$ and, for $n\geq2$,
    \begin{align*}
        \bar{X}_n = \frac{1}{n} \sum_{i=1}^n X_i.
    \end{align*}
    Then, as $n \to \infty$,
    \begin{align}\label{eq:covariance-operator-estimate}
        \frac{1}{n-1}\sum_{i=1}^n (X_i - \bar{X}_n) \otimes (X_i - \bar{X}_n) \overset{\text{a.s.}}{\to}  \mathbb{E}[(X - \mu) \otimes (X - \mu)]
    \end{align}
    in operator norm.

steps.text:
We must show that the partial sums of the series $\sum_{n\in\mathbb{N}}\mathbb{E}[\theta_n\mid\mathcal{G}]e_n$ converge in $\mathcal{H}$ almost surely to $\mathbb{E}[X\mid\mathcal{G}]$. For almost every $\omega\in\Omega$, the orthonormal basis expansion gives
    \begin{align*}
        X(\omega) = \sum_{n \in \mathbb{N}} \theta_n(\omega) e_n,
    \end{align*}
    where $\theta_n(\omega)=\langle X(\omega),e_n\rangle$. Define the partial sums
    \begin{align*}
        S_N(\omega) = \sum_{n = 1}^N \theta_n(\omega) e_n,\qquad N\in\mathbb{N}.
    \end{align*}
    By the linearity of conditional expectation\index{conditional expectation} and the property that $\mathbb{E}[\theta_n e_n\mid\mathcal{G}]=\mathbb{E}[\theta_n\mid\mathcal{G}]e_n$ for a fixed deterministic basis vector $e_n$, it follows that
    \begin{align*}
        \mathbb{E}[S_N \mid \mathcal{G}] = \sum_{n=1}^N \mathbb{E}[\theta_n \mid \mathcal{G}] e_n\qquad\text{almost surely.}
    \end{align*}
    Moreover, because $S_N$ is the orthogonal projection of $X$ onto $\mathrm{span}\{e_1,\dots,e_N\}$, we have
    \begin{align*}
        S_N\to X,
        \qquad
        \lVert S_N\rVert\leq\lVert X\rVert,
        \quad\text{almost surely.}
    \end{align*}
    Since $\mathbb{E}[\lVert X\rVert]<\infty$ by the square-integrability hypothesis, the conditional dominated convergence theorem yields, almost surely,
    \begin{align*}
        \mathbb{E}[X \mid \mathcal{G}] = \lim_{N \to \infty} \mathbb{E}[S_N \mid \mathcal{G}] = \lim_{N \to \infty} \sum_{n = 1}^N \mathbb{E}[\theta_n \mid \mathcal{G}] e_n = \sum_{n=1}^\infty \mathbb{E}[\theta_n \mid \mathcal{G}] e_n,
    \end{align*}
    which establishes the coordinatewise representation of $\mathbb{E}[X\mid\mathcal{G}]$, as desired.

