\label{thm:scores-sigma-algebra}
Let $(\Omega, \mathcal{F}, \mathbb{P})$ be a probability space, let $(\mathcal{H}, \langle \cdot, \cdot\rangle)$ be a real separable Hilbert space with a fixed orthonormal basis $(e_n)_{n\in\mathbb{N}}$, and let $X:\Omega \to \mathcal{H}$ be an $\mathcal{F}$-measurable random element. Define the $\sigma$-algebras generated by the first $N$ scores and by all scores by
    \begin{align*}
        \mathcal{G}_N = \sigma(\theta_1, \theta_2, \dots, \theta_N),\qquad \mathcal{G}_\infty=\sigma(\theta_n, n\in\mathbb{N}),
    \end{align*}
    where $\theta_n = \langle X, e_n\rangle$ for all $n \in \mathbb{N}$. Then
    \begin{align*}
        \sigma(X) = \mathcal{G}_\infty.
    \end{align*}
    Consequently, for every $Y \in L^1(\Omega,\mathcal{F},\mathbb{P})$,
    \begin{align*}
        \mathbb{E}[Y \mid \mathcal{G}_N] \to \mathbb{E}[Y \mid \sigma(X)]
    \end{align*}
    almost surely and in $L^1$ as $N \to \infty$, and in $L^2$ if $Y\in L^2(\Omega,\mathcal{F},\mathbb{P})$.

\label{defn:empirical-coordinate-scales}\index{empirical mean}
    Let $T$ be a finite non-empty index set, let $(Z_t)_{t\in T}$ be a family in $L^2([-1,1];\mathbb{R}^2)$, and let $\operatorname{pr}_q,\operatorname{pr}_p:L^2([-1,1];\mathbb{R}^2)\to L^2([-1,1];\mathbb{R})$ denote the first and second coordinate projections, respectively. The \emph{empirical mean} of $(Z_t)_{t\in T}$ is defined by
    \begin{align*}
        \bar{Z} = \frac{1}{|T|} \sum_{t\in T} Z_t,
    \end{align*}
    and the \emph{empirical coordinate scales} $s_q, s_p \geq 0$ are defined by
    \begin{align}\label{eq:domain-std}
        s_q = \frac{1}{|T|} \sum_{t \in T} \left\lVert\operatorname{pr}_q (Z_t - \bar{Z})\right\rVert_{L^2([-1,1]; \mathbb{R})}
    \end{align}
    and
    \begin{align}\label{eq:image-std}
        s_p =\frac{1}{|T|} \sum_{t \in T} \left\lVert\operatorname{pr}_p (Z_t - \bar{Z})\right\rVert_{L^2([-1,1]; \mathbb{R})}.
    \end{align}

\label{defn:asinh-price-transform}
    For a scale parameter $c > 0$, the \emph{inverse hyperbolic sine transformation} $g:\mathbb{R}\to\mathbb{R}$ is defined by
    \begin{align}\label{eq:asinh-transform}
        g(p)=\operatorname{asinh}(p/c).
    \end{align}

\label{defn:coordinate-scaling-operators}
    Let $T$ be a finite non-empty index set, let $(Z_t)_{t\in T}$ be a family in $L^2([-1,1];\mathbb{R}^2)$ with empirical mean $\bar{Z}$, and let $s_q,s_p>0$. The \emph{coordinate scaling operator} $\Upsilon: L^2([-1,1]; \mathbb{R}^2) \to L^2([-1,1]; \mathbb{R}^2)$ and its inverse $\Upsilon^{-1}: L^2([-1,1]; \mathbb{R}^2) \to L^2([-1,1]; \mathbb{R}^2)$ are defined by
    \begin{align}\label{eq:standardizing-operator}
        \Upsilon f = x \mapsto \begin{bmatrix}
            s_q & 0\\
            0 & s_p
        \end{bmatrix} f(x),
        \qquad
        \Upsilon^{-1} f  = x \mapsto \begin{bmatrix}
            \frac{1}{s_q} & 0\\
            0 & \frac{1}{s_p}
        \end{bmatrix} f(x).
    \end{align}
    For each $t\in T$, the \emph{normalised deviation} of $Z_t$ from $\bar{Z}$ is defined by
    \begin{align*}
        \xi_t =  \Upsilon^{-1}(Z_t - \bar{Z}),
    \end{align*}
    so that $Z_t = \bar{Z} + \Upsilon \xi_t$.

\label{defn:rolling-coordinate-scales}
    Let $\mathcal{D}\subseteq\mathbb{Z}$, let $T=\mathcal{D}\times\{1,\dots,24\}$, let $(Z_{d,h})_{(d,h)\in T}$ be a family in $L^2([-1,1];\mathbb{R}^2)$, and let $\operatorname{pr}_q,\operatorname{pr}_p:L^2([-1,1];\mathbb{R}^2)\to L^2([-1,1];\mathbb{R})$ denote the first and second coordinate projections, respectively. For each $(d,h) \in T$ with $d-1\in\mathcal{D}$, the \emph{first difference} is defined by
    \begin{align*}
        \Delta Z_{d,h} = Z_{d,h}-Z_{d-1,h},
    \end{align*}
    and the mean squared coordinate norms at index $d$ are given by
    \begin{align*}
        s_{\Delta q,d}^2 = \frac{1}{24} \sum_{h=1}^{24} \lVert \operatorname{pr}_q \Delta Z_{d,h}\rVert^2,
        \qquad
        s_{\Delta p,d}^2 = \frac{1}{24} \sum_{h=1}^{24} \lVert \operatorname{pr}_p \Delta Z_{d,h}\rVert^2.
    \end{align*}
    Fix a decay parameter $\alpha\in(0,1)$. The \emph{rolling coordinate scales} at index $d$ are defined by
    \begin{align}\label{eq:domain-variation-rolling}
        \widehat{s}_{\Delta q,d}^2=\frac{\sum_{m=1}^{5}(1-\alpha)^m s_{\Delta q,d-m}^2}{\sum_{m=1}^{5}(1-\alpha)^m}
    \end{align}
    and
    \begin{align}\label{eq:image-variation-rolling}
        \widehat{s}_{\Delta p,d}^2=\frac{\sum_{m=1}^{5}(1-\alpha)^m s_{\Delta p,d-m}^2}{\sum_{m=1}^{5}(1-\alpha)^m},
    \end{align}
    and for $t=(d,h)\in T$ with $\widehat{s}_{\Delta q,t}=\sqrt{\widehat{s}_{\Delta q,d}^2}>0$ and $\widehat{s}_{\Delta p,t}=\sqrt{\widehat{s}_{\Delta p,d}^2}>0$, the \emph{rolling scaling operators} $\Upsilon_t,\Upsilon_t^{-1}:L^2([-1,1];\mathbb{R}^2)\to L^2([-1,1];\mathbb{R}^2)$ are defined by
    \begin{align}\label{eq:upsilon-t}
        \Upsilon_t f = x \mapsto \begin{bmatrix}
            \widehat{s}_{\Delta q,t} & 0 \\ 0 & \widehat{s}_{\Delta p,t}
        \end{bmatrix}f(x)
    \end{align}
    and
    \begin{align}\label{eq:upsilon-t-inverse}
        \Upsilon_t^{-1} f = x \mapsto \begin{bmatrix}
            \frac{1}{\widehat{s}_{\Delta q,t}} & 0 \\ 0 & \frac{1}{\widehat{s}_{\Delta p,t}}
        \end{bmatrix}f(x),
    \end{align}
    with \emph{rolling-standardised difference}
    \begin{align}\label{eq:delta-xi-series}
        \Delta \xi_t = \Upsilon_t^{-1}\Delta Z_t,
    \end{align}
    so that $Z_{d,h}=Z_{d-1,h}+\Upsilon_{d,h}\Delta\xi_{d,h}$.

\label{defn:rectangular-simple-function}
Let $\mathcal{H}$ be a real separable Hilbert space, let $p\in\mathbb{N}$, and let $X\subseteq\mathbb{R}^p$. A \emph{rectangular simple function}\index{rectangular simple functions}, or \emph{axis-aligned simple function}, on $X$ with values in $\mathcal{H}$ is a function $r:X\to\mathcal{H}$ of the form
\begin{align*}
    r(x) = \sum_{k = 1}^K c_k \mathbbm{1}_{R_k}(x),
\end{align*}
where $K\in\mathbb{N}$, $c_1,\dots,c_K\in\mathcal{H}$, and each $R_k=(I_{k,1}\times\cdots\times I_{k,p})\cap X$ is an axis-aligned rectangle formed by the product of intervals $I_{k,j}\subseteq\mathbb{R}$.

\label{defn:k-leaf-tree-class}
For a fixed predictor dimension $p\in\mathbb{N}$, let $\mathcal{R}_K$ denote the class of partitions of $\mathbb{R}^p$ obtained from the root cell $\mathbb{R}^p$ by $K-1$ recursive binary splits, where each split replaces a current cell $R$ by the two non-empty cells $R\cap\{x\in\mathbb{R}^p\mid x_j\leq c\}$ and $R\cap\{x\in\mathbb{R}^p\mid x_j>c\}$ for a coordinate $j\in\{1,\dots,p\}$ and threshold $c\in\mathbb{R}$. The \emph{$K$-leaf tree class}\index{decision tree!leaf} with values in a real separable Hilbert space $\mathcal{H}$ is defined by
\begin{align*}
    \mathfrak{T}_K(\mathbb{R}^p,\mathcal{H})
    =\left\{\sum_{k=1}^{K}c_k\mathbbm{1}_{R_k}~\middle|~
      (R_1,\ldots,R_K)\in\mathcal{R}_K,\ c_k\in\mathcal{H}\right\},
\end{align*}
and the class of \emph{finite recursive regression trees} is defined by
\begin{align*}
    \mathfrak{T}(\mathbb{R}^p,\mathcal{H})=\bigcup_{K\in\mathbb{N}}\mathfrak{T}_K(\mathbb{R}^p,\mathcal{H}).
\end{align*}

\label{defn:cell-impurity-split}
Let $\mathcal{H}$ be a real Hilbert space, let $p,n\in\mathbb{N}$, let $(y_i,\bm{x}_i)_{i=1}^n\subseteq\mathcal{H}\times\mathbb{R}^p$ be a finite family of observations, and let $S\subseteq\{1,\dots,n\}$ be a non-empty index set. The \emph{cell mean} on $S$ is defined by
\begin{align*}
    \hat{y}_S=\frac{1}{|S|}\sum_{i\in S}y_i,
\end{align*}
and the \emph{cell impurity} on $S$ under a loss function $\mathfrak{L}:\mathcal{H}\times\mathcal{H}\to[0,\infty)$ is defined by
\begin{align*}
    i(S)=\frac{1}{|S|}\sum_{i\in S}\mathfrak{L}(y_i,\hat{y}_S).
\end{align*}
Given a candidate split $s=(j,c)\in\{1,\dots,p\}\times\mathbb{R}$, let the left and right child index sets be
\begin{align*}
    S_L = \{i \in S \mid x_{i,j} \leq c\},\quad\quad S_R = \{i \in S \mid x_{i,j} > c\}.
\end{align*}
When $S_L$ and $S_R$ are both non-empty, $s$ is called \emph{admissible} on $S$, and the \emph{split impurity reduction} is defined by
\begin{align*}
    \Delta i (s, S) = i(S) - \frac{|S_L|}{|S|} i(S_L) - \frac{|S_R|}{|S|}i(S_R).
\end{align*}

steps.text:
We establish the norm decomposition by expanding the squared distance around $\hat{y}_S$. Fix an arbitrary $\hat{y}\in\mathcal{H}$. Writing $y_i-\hat{y}=(y_i-\hat{y}_S)+(\hat{y}_S-\hat{y})$ for each $i\in S$ and expanding the squared Hilbert norm yields
\begin{align*}
    \sum_{i\in S}\lVert y_i-\hat{y}\rVert_{\mathcal{H}}^2
    =\sum_{i\in S}\lVert y_i-\hat{y}_S\rVert_{\mathcal{H}}^2
    +2\left\langle\sum_{i\in S}(y_i-\hat{y}_S),\,\hat{y}_S-\hat{y}\right\rangle_{\mathcal{H}}
    +|S|\lVert\hat{y}-\hat{y}_S\rVert_{\mathcal{H}}^2.
\end{align*}
By Definition~\ref{defn:cell-impurity-split}, $\sum_{i\in S}(y_i-\hat{y}_S)=\sum_{i\in S}y_i-|S|\hat{y}_S=0$, so the inner-product cross term vanishes and the stated identity holds. Since $|S|>0$ and $\lVert\hat{y}-\hat{y}_S\rVert_{\mathcal{H}}^2\geq 0$ with equality if and only if $\hat{y}=\hat{y}_S$, it follows that $\hat{y}_S$ is the unique minimiser of $\sum_{i\in S}\lVert y_i-\hat{y}\rVert_{\mathcal{H}}^2$ over $\hat{y}\in\mathcal{H}$.

proof.text:
