Since $\hat{y}_S = (|S_L|\hat{y}_{S_L} + |S_R|\hat{y}_{S_R})/|S|$ and $|S_L|+|S_R|=|S|$, expanding $\lVert\hat{y}_S\rVert_{\mathcal{H}}^2$ and collecting terms gives \eqref{eq:compute-split-2}. Because $\lVert y_i\rVert_{\mathcal{H}}^2=(\bm{G})_{i,i}$ and $\langle\sum_{i\in A}y_i,\sum_{j\in B}y_j\rangle_{\mathcal{H}}=\bm{1}_A^\top\bm{G}\bm{1}_B$ for all $A,B\subseteq\{1,\dots,n\}$, the Gram-matrix expressions for $i(S)$ and $\Delta i(s,S)$ follow immediately.

Finally, define the vector $\bm{w}\in\mathbb{R}^n$ by
\begin{align*}
    \bm{w} = \frac{\sqrt{|S_L||S_R|}}{|S|}\left(\frac{1}{|S_L|}\bm{1}_{S_L} - \frac{1}{|S_R|}\bm{1}_{S_R}\right).
\end{align*}
By construction, $\Delta i(s,S)=\bm{w}^\top\bm{G}\bm{w}$ and $\Delta\tilde{i}(s,S)=\bm{w}^\top\bm{G}_r\bm{w}$. Since $S_L$ and $S_R$ are disjoint, the Euclidean squared norm of $\bm{w}$ is
\begin{align*}
    \lVert\bm{w}\rVert_2^2 = \frac{|S_L||S_R|}{|S|^2}\left(\frac{|S_L|}{|S_L|^2} + \frac{|S_R|}{|S_R|^2}\right) = \frac{|S_L|+|S_R|}{|S|^2} = \frac{1}{|S|}.
\end{align*}
The residual matrix $\bm{G}-\bm{G}_r$ is symmetric positive semidefinite with largest eigenvalue $\lambda_{r+1}$, so the Rayleigh quotient bound gives $0 \leq \bm{w}^\top(\bm{G}-\bm{G}_r)\bm{w} \leq \lambda_{r+1}\lVert\bm{w}\rVert_2^2 = \lambda_{r+1}/|S|$, completing the proof.

results.statement:
\label{prop:gram-split-gain-bound}
Let $\mathcal{H}$ be a real Hilbert space, let $n\in\mathbb{N}$, and let $(y_i)_{i=1}^n\subseteq\mathcal{H}$ have Gram matrix $\bm{G}\in\mathbb{R}^{n\times n}$ given by $(\bm{G})_{i,j}=\langle y_i,y_j\rangle_{\mathcal{H}}$ for all $i,j\in\{1,\dots,n\}$. For any non-empty subset $A\subseteq\{1,\dots,n\}$, write $\hat{y}_A=\frac{1}{|A|}\sum_{i\in A}y_i$ and $i(A)=\frac{1}{|A|}\sum_{i\in A}\lVert y_i-\hat{y}_A\rVert_{\mathcal{H}}^2$. Then for any non-empty cell $S\subseteq\{1,\dots,n\}$ and any split $s$ partitioning $S$ into non-empty disjoint child sets $S_L$ and $S_R$, the cell impurity $i(S)$ and the split impurity reduction $\Delta i(s,S)=i(S)-\frac{|S_L|}{|S|}i(S_L)-\frac{|S_R|}{|S|}i(S_R)$ satisfy
\begin{align}\label{eq:compute-split-1}
    i(S) = \frac{1}{|S|}\sum_{i\in S}\lVert y_i\rVert_{\mathcal{H}}^2 - \left\lVert\hat{y}_S\right\rVert_{\mathcal{H}}^2
    = \frac{1}{2|S|^2}\sum_{i,j\in S} \lVert y_i -y_j\rVert_{\mathcal{H}}^2,
\end{align}
and
\begin{align}\label{eq:compute-split-2}
    \Delta i (s, S) = \frac{|S_L||S_R|}{|S|^2}\left\lVert\hat{y}_{S_L} - \hat{y}_{S_R}\right\rVert_{\mathcal{H}}^2.
\end{align}
In terms of $\bm{G}$ and the indicator vectors $\bm{1}_A\in\mathbb{R}^n$ with entries $(\bm{1}_A)_i=1$ for $i\in A$ and $0$ otherwise, these quantities take the form
\begin{align*}
    i(S) = \frac{1}{|S|} \underbrace{\sum_{i \in S} (\bm{G})_{i,i}}_{g_S^{\mathrm{diag}}} - \frac{1}{|S|^2}\underbrace{\bm{1}_S^\top \bm{G}\bm{1}_S}_{\vphantom{\sum_{i \in S} (\bm{G})_{i,i}}g_S^{\mathrm{all}}}
\end{align*}
and
\begin{align*}
    \Delta i(s,S)= \frac{|S_L||S_R|}{|S|^2}\left(\frac{g_{S_L}^{\mathrm{all}}}{|S_L|^2} + \frac{g_{S_R}^{\mathrm{all}}}{|S_R|^2} - \frac{2}{|S_L||S_R|} \bm{1}_{S_L}^\top \bm{G}\bm{1}_{S_R}\right).
\end{align*}
Furthermore, if $\bm{G}_r=\bm{U}_r\bm{\Lambda}_r\bm{U}_r^\top$ is the rank-$r$ spectral truncation of $\bm{G}$ retaining its $r$ largest eigenvalues $\lambda_1\geq\dots\geq\lambda_r\geq 0$ and $\Delta\tilde{i}(s,S)$ denotes the split gain evaluated with $\bm{G}_r$ in place of $\bm{G}$, then
\begin{align*}
    0 \leq \Delta i(s,S) - \Delta\tilde{i}(s,S) \leq \frac{\lambda_{r+1}}{|S|},
\end{align*}
where $\lambda_{r+1}$ is the $(r+1)$th eigenvalue of $\bm{G}$ (with $\lambda_{r+1}=0$ for $r\geq n$).

\label{defn:hilbert-shapley-value}
Let $\mathcal{H}$ be a real separable Hilbert space, let $p\in\mathbb{N}$, and let $V:\wp(\{1,\dots,p\})\to\mathcal{H}$ be a map. For any subset $S\subseteq\{1,\dots,p\}$ and element $s\in\{1,\dots,p\}\setminus S$, the \emph{marginal contribution} of $s$ to $S$ is defined by
\begin{align*}
    \Delta V(S, s) = V(S \cup \{s\}) - V(S),
\end{align*}
and the \emph{Shapley value} of $s$ under $V$ is defined by
\begin{align}\label{eq:Shapley-value}
    \phi_s(V) = \sum_{S \in \wp(\{1,\dots,p\} \setminus \{s\}) } \frac{|S|!(p-|S|-1)!}{p!}\Delta V(S,s).
\end{align}
Let $(\Omega,\mathcal{F},\mathbb{P})$ be a probability space, let $f:\mathbb{R}^p\to\mathcal{H}$ be a Borel-measurable function, let $\bm{X}:\Omega\to\mathbb{R}^p$ be a random vector satisfying $\mathbb{E}[\lVert f(\bm{X})\rVert_{\mathcal{H}}]<\infty$, and for each $S\subseteq\{1,\dots,p\}$, let $\operatorname{pr}_S:\mathbb{R}^p\to\mathbb{R}^{|S|}$ denote the coordinate projection onto $S$, with $\bm{X}_S=\operatorname{pr}_S\bm{X}$ and $\bm{x}_S=\operatorname{pr}_S\bm{x}$ for $\bm{x}\in\mathbb{R}^p$. Given a chosen version of the conditional expectation and a point $\bm{x}\in\mathbb{R}^p$, the \emph{local coalition value} $V_{\bm{x}}:\wp(\{1,\dots,p\})\to\mathcal{H}$ is defined by
\begin{align*}
    V_{\bm{x}}(S)=\mathbb{E}[f(\bm{X})\mid\bm{X}_S=\bm{x}_S]
\end{align*}
for $S\subseteq\{1,\dots,p\}$, with marginal contribution
\begin{align}\label{eq:delta-shap}
    \Delta V_{\bm{x}}(S,s)=V_{\bm{x}}(S\cup\{s\})-V_{\bm{x}}(S)
\end{align}
for $s\in\{1,\dots,p\}\setminus S$, and local Shapley value $\phi_s(V_{\bm{x}})$ obtained by evaluating \eqref{eq:Shapley-value} at $V=V_{\bm{x}}$.

\label{defn:lifted-price-scale-smearing}
Let $c > 0$, let $g:\mathbb{R}\to\mathbb{R}$ be given by $g(p)=\operatorname{asinh}(p/c)$ with inverse $g^{-1}(z)=c\sinh(z)=c(\mathrm{e}^{z}-\mathrm{e}^{-z})/2$, and let $\operatorname{pr}_q,\operatorname{pr}_p:L^2([-1,1];\mathbb{R}^2)\to L^2([-1,1];\mathbb{R})$ denote the first and second coordinate projections, respectively. The \emph{lifted scale operator} $\mathfrak{G}:L^2([-1,1];\mathbb{R}^2)\to L^2([-1,1];\mathbb{R}^2)$ is defined by
\begin{align*}
    \operatorname{pr}_q\mathfrak{G}f=\operatorname{pr}_qf,\qquad
    \operatorname{pr}_p\mathfrak{G}f=g\circ\operatorname{pr}_pf,
\end{align*}
which is well-defined since $|g(p)|\leq|p|/c$, and its inverse $\mathfrak{G}^{-1}$ on the subset of functions $h\in L^2([-1,1];\mathbb{R}^2)$ with $g^{-1}\circ\operatorname{pr}_p h\in L^2([-1,1];\mathbb{R})$ is defined by
\begin{align*}
    \operatorname{pr}_q\mathfrak{G}^{-1}h=\operatorname{pr}_qh,\qquad
    \operatorname{pr}_p\mathfrak{G}^{-1}h=g^{-1}\circ\operatorname{pr}_ph.
\end{align*}
Given $\widehat{M}_{d+1,h}\in L^2([-1,1];\mathbb{R}^2)$ and a finite family $e_1,\dots,e_{n_w}\in L^2([-1,1];\mathbb{R}^2)$ with $\operatorname{pr}_q e_i=0$ such that $\widehat{M}_{d+1,h}+e_i$ belongs to the domain of $\mathfrak{G}^{-1}$ for each $i\in\{1,\dots,n_w\}$, the \emph{smearing estimator} \citep{duan1983smearing} is defined by
\begin{align*}
    \widetilde{Z}_{d+1,h}=\frac{1}{n_w}\sum_{i=1}^{n_w}\mathfrak{G}^{-1}\bigl(\widehat{M}_{d+1,h}+e_i\bigr).
\end{align*}

\label{prop:monotone-decoding-nonexpansive}
Let $(\mathcal{H}_q,\lVert\cdot\rVert_{q,\mathrm{node}})$ and $(\mathcal{H}_p,\lVert\cdot\rVert_{p,\mathrm{num}})$ be finite-dimensional weighted Euclidean spaces of dimension $N_q$ and $N_p$, respectively, and let $-\infty < \underline{p} < \overline{p} < \infty$. Define the monotone subsets
\begin{align*}
    \mathcal{C}_q &= \{z\in\mathcal{H}_q \mid z_1 \leq z_2 \leq \dots \leq z_{N_q}\},\\
    \mathcal{C}_p &= \{p\in\mathcal{H}_p \mid \underline{p} \leq p_1 \leq p_2 \leq \dots \leq p_{N_p} \leq \overline{p}\}.
\end{align*}
Then $\mathcal{C}_q\subseteq\mathcal{H}_q$ and $\mathcal{C}_p\subseteq\mathcal{H}_p$ are non-empty, closed, and convex subsets, and for any $\sigma$-algebra $\mathcal{F}_d$ and any Bochner-integrable random element $W=(\operatorname{pr}_q W,\operatorname{pr}_p W)$ in $\mathcal{H}_q\times\mathcal{H}_p$, that is, $\mathbb{E}[\lVert W\rVert]<\infty$, taking values in $\mathcal{C}_q\times\mathcal{C}_p$ almost surely, the conditional expectation $\mathbb{E}[W\mid\mathcal{F}_d]$ takes values in $\mathcal{C}_q\times\mathcal{C}_p$ almost surely. Consequently, if $\widehat{Z}_{d+1,h}=(\operatorname{pr}_q\widehat{Z}_{d+1,h},\operatorname{pr}_p\widehat{Z}_{d+1,h})$ denotes the componentwise metric projection of $\widetilde{Z}_{d+1,h}\in\mathcal{H}_q\times\mathcal{H}_p$ onto $\mathcal{C}_q\times\mathcal{C}_p$, then for every $Y\in\mathcal{C}_q\times\mathcal{C}_p$,
\begin{align*}
    \left\lVert\operatorname{pr}_p\widehat{Z}_{d+1,h} - \operatorname{pr}_p Y\right\rVert_{p,\mathrm{num}}
    &\leq \left\lVert\operatorname{pr}_p\widetilde{Z}_{d+1,h} - \operatorname{pr}_p Y\right\rVert_{p,\mathrm{num}},\\
    \left\lVert\operatorname{pr}_q\widehat{Z}_{d+1,h} - \operatorname{pr}_q Y\right\rVert_{q,\mathrm{node}}
    &\leq \left\lVert\operatorname{pr}_q\widetilde{Z}_{d+1,h} - \operatorname{pr}_q Y\right\rVert_{q,\mathrm{node}}.
\end{align*}

\label{defn:viability-screen-impact-cost}
Let $T$ be a finite index set, and for each $t\in T$, let $D_t\subseteq\mathbb{R}$ be an interval, let $P_t:D_t\to\mathbb{R}$ be a function, and let $Q_t,\widehat{Q}_t\in[0,\infty)$. Fix a threshold $c\in\mathbb{R}$, and let $T_{\mathrm{pair}}\subseteq\{t\in T \mid 0\in D_t,\ -\widehat{Q}_t\in D_t\}$. For each $t\in T_{\mathrm{pair}}$ and any $q\geq 0$ with $-q\in D_t$, the \emph{threshold screen} is the indicator function
\begin{align*}
    a_t(q)=\begin{cases}
        1,&P_t(-q)\geq c,\\
        0,&P_t(-q)<c.
    \end{cases}
\end{align*}
For each $t\in T_{\mathrm{pair}}$, the \emph{impact payoff proxy} and the \emph{zero-impact payoff proxy} are defined by
\begin{align}
    \mathsf{Payoff}_t
    &=a_t(\widehat{Q}_t)\widehat{Q}_tP_t(-\widehat{Q}_t),
    \label{eq:payoff-with-impact}\\
    \mathsf{Payoff}^0_t
    &=\widehat{Q}_tP_t(0)\mathbbm{1}(P_t(0)\geq c),
    \label{eq:payoff-without-impact}
\end{align}
the \emph{impact-cost proxy} over $T_{\mathrm{pair}}$ is the paired difference $\sum_{t\in T_{\mathrm{pair}}}(\mathsf{Payoff}^0_t-\mathsf{Payoff}_t)$, and the \emph{residual quantity} at index $t$ is
\begin{align*}
    \Delta Q_t=Q_t-a_t(\widehat{Q}_t)\widehat{Q}_t.
\end{align*}

\label{defn:battery-schedule-set}
Let $\eta_{\mathrm{charge}}, \eta_{\mathrm{discharge}} \in (0,1]$. For $\Delta q\in\mathbb{R}$, the \emph{conversion map} $\tau:\mathbb{R}\to\mathbb{R}$ is defined by
\begin{align*}
    \tau(\Delta q) = \begin{cases}
        \eta_{\mathrm{discharge}} \Delta q, &  \Delta q < 0,\\
        \frac{\Delta q}{\eta_{\mathrm{charge}}}, & \Delta q \geq 0.
    \end{cases}
\end{align*}
Let $K > 0$ and $R_{\max} > 0$, let $\mathcal{G}\subseteq[0,K]$ and $\mathcal{R}\subseteq[-R_{\max},R_{\max}]$ be finite sets, let $\bm{P}=(P_h)_{h=1}^{24}$ be a $24$-tuple of functions $P_h:\operatorname{domain}(P_h)\to\mathbb{R}$ with $\operatorname{domain}(P_h)\subseteq\mathbb{R}$, and let $q_{\mathrm{start}},q_{\mathrm{stop}}\in\mathcal{G}$. The \emph{feasible schedule set} is defined by
\begin{align}\label{eq:finite-battery-action-set}
\begin{aligned}
\mathcal{A}_{\mathcal{G}}
&(q_{\mathrm{start}},q_{\mathrm{stop}};\bm{P})\\[-0.2em]
&=
\left\{\Delta\bm{q}\in\mathcal{R}^{24}\ \middle|\
\begin{aligned}
q_h
&=q_{\mathrm{start}}+\sum_{r=1}^h\Delta q_r\in\mathcal{G},
&&h=1,\dots,24,\\
q_{24}&=q_{\mathrm{stop}},\\
\tau(\Delta q_h)&\in\operatorname{domain}(P_h),
&&h=1,\dots,24
\end{aligned}
\right\}.
\end{aligned}
\end{align}
A pair $(q_{\mathrm{start}},q_{\mathrm{stop}})\in\mathcal{G}^2$ is called a \emph{transition}, and it is \emph{feasible} for $\bm{P}$ when $\mathcal{A}_{\mathcal{G}}(q_{\mathrm{start}},q_{\mathrm{stop}};\bm{P})$ is non-empty.

\label{defn:battery-value-functions}
Let $\mathcal{G}$, $\mathcal{R}$, and $\tau$ be as in Definition~\ref{defn:battery-schedule-set}, and let $\lambda\geq 0$. For an index $d$, let $\widehat{\bm{P}}_d=(\widehat{P}_{d,h})_{h=1}^{24}$ and $\bm{P}_d=(P_{d,h})_{h=1}^{24}$ be $24$-tuples of functions on $\mathbb{R}$. For any transition $(q_{\mathrm{start}},q_{\mathrm{stop}})\in\mathcal{G}^2$ that is feasible for $\widehat{\bm{P}}_d$, the \emph{plug-in value function} is defined by
\begin{align}\label{eq:approximate-battery-problem}
\begin{gathered}
\widehat{V}_d(q_{\mathrm{start}},q_{\mathrm{stop}})=\\[-0.35em]
\max_{\substack{\Delta\bm{q}\in\mathcal{A}_{\mathcal{G}}
(q_{\mathrm{start}},q_{\mathrm{stop}};\widehat{\bm{P}}_d)}}
\sum_{h=1}^{24}
\left[-\tau(\Delta q_h)\widehat{P}_{d,h}(\tau(\Delta q_h))-\lambda|\Delta q_h|\right].
\end{gathered}
\end{align}
Let $\Delta\bm{q}^\star=\Delta\bm{q}^\star_d(q_{\mathrm{start}},q_{\mathrm{stop}})$ be the lexicographically first maximiser of \eqref{eq:approximate-battery-problem} with respect to the coordinate order on $\{1,\dots,24\}$ and the standard order on $\mathcal{R}$. Whenever $\Delta\bm{q}^\star\in\mathcal{A}_{\mathcal{G}}(q_{\mathrm{start}},q_{\mathrm{stop}};\bm{P}_d)$, the \emph{realised value} of the selected schedule is defined by
\begin{align}\label{eq:realised-battery-problem}
    V_d(q_{\mathrm{start}},q_{\mathrm{stop}})
    =\sum_{h=1}^{24}
    -\tau(\Delta q_h^\star)\,
    P_{d,h}(\tau(\Delta q_h^\star))
    -\lambda\sum_{h=1}^{24}|\Delta q_h^\star|,
\end{align}
with \emph{unpenalised value} $R_d(q_{\mathrm{start}},q_{\mathrm{stop}})=\sum_{h=1}^{24}-\tau(\Delta q_h^\star)P_{d,h}(\tau(\Delta q_h^\star))$, \emph{total variation} $T_d(q_{\mathrm{start}},q_{\mathrm{stop}})=\sum_{h=1}^{24}|\Delta q_h^\star|$, and \emph{transition value error}
\begin{align*}
    \varepsilon^{(d)}_{i,j} = V_d(q_i, q_j) - \widehat{V}_d(q_i,q_j),
    \qquad q_i,q_j\in\mathcal{G}.
\end{align*}

steps.text:
Next, fix $h \in \{1,\dots,24\}$. Since $\alpha > 1$ and $\widehat{P}_{d,h}$ is non-decreasing, if $\tau(\Delta q_h) \geq 0$, then $0 \leq \tau(\Delta\widetilde{q}_h) \leq \tau(\Delta q_h)$ implies $\widehat{P}_{d,h}(\tau(\Delta\widetilde{q}_h)) \leq \widehat{P}_{d,h}(\tau(\Delta q_h))$; multiplying by the non-positive quantity $-\tau(\Delta q_h) = -\alpha\tau(\Delta\widetilde{q}_h)$ reverses the inequality. Conversely, if $\tau(\Delta q_h) < 0$, then $\tau(\Delta q_h) \leq \tau(\Delta\widetilde{q}_h) < 0$ implies $\widehat{P}_{d,h}(\tau(\Delta q_h)) \leq \widehat{P}_{d,h}(\tau(\Delta\widetilde{q}_h))$; multiplying by the positive quantity $-\tau(\Delta q_h) = -\alpha\tau(\Delta\widetilde{q}_h)$ preserves the inequality. In both cases, we obtain
\begin{align*}
    -\tau(\Delta q_h)\widehat{P}_{d,h}(\tau(\Delta q_h)) - \lambda|\Delta q_h|
    \leq \alpha\left[-\tau(\Delta\widetilde{q}_h)\widehat{P}_{d,h}(\tau(\Delta\widetilde{q}_h)) - \lambda|\Delta\widetilde{q}_h|\right].
\end{align*}
Summing over $h=1,\dots,24$ and taking the maximum over $\Delta\bm{q}$ yields the stated bound.

