\label{prop:everett-lagrangian-separation}
Let $\mathcal{X}$ be a non-empty set, and let $\mathcal{R}:\mathcal{X}\to\mathbb{R}$ and $\mathcal{T}:\mathcal{X}\to[0,\infty)$ be functions. If $\lambda\geq 0$ and $\bm{x}^\lambda\in\argmax_{\bm{x}\in\mathcal{X}}\{\mathcal{R}(\bm{x})-\lambda\mathcal{T}(\bm{x})\}$, then for every $\bm{x}\in\mathcal{X}$ satisfying $\mathcal{T}(\bm{x})\leq\mathcal{T}(\bm{x}^\lambda)$,
\begin{align*}
    \mathcal{R}(\bm{x})\leq\mathcal{R}(\bm{x}^\lambda).
\end{align*}
In particular, $\bm{x}^\lambda$ is a global maximiser of $\mathcal{R}(\bm{x})$ over $\{\bm{x}\in\mathcal{X} \mid \mathcal{T}(\bm{x})\leq\mathcal{T}(\bm{x}^\lambda)\}$.

\label{defn:intraday-order-space}
    Let $U = [-9999, 9999] \times (0,\infty) \times [0,1]$. The \emph{order space} is the disjoint union
    \begin{align}\label{eq:order-space}
        O = \bigsqcup_{\kappa \in \{\mathrm{buy}, \mathrm{sell}\}} U = \bigsqcup_{\kappa \in \{\mathrm{buy}, \mathrm{sell}\}} [-9999, 9999] \times (0,\infty) \times [0,1].
    \end{align}

\label{defn:price-time-priority-metric}
    Let $U = [-9999,9999]\times(0,\infty)\times[0,1]$ and let $O = \bigsqcup_{\kappa\in\{\mathrm{buy},\mathrm{sell}\}} U$. On $U$, the relations $\preceq^{\mathrm{buy}}$ and $\preceq^{\mathrm{sell}}$ are defined for $(p,q,t),(p^\prime,q^\prime,t^\prime)\in U$ by
    \begin{align*}
        (p, q, t) \preceq^{\mathrm{buy}} (p^\prime, q^\prime, t^\prime)
        &\iff (p,q,t)=(p^\prime,q^\prime,t^\prime) \lor (p > p^\prime)\\
        &\qquad\lor ((p = p^\prime) \land (t < t^\prime))
    \end{align*}
    and
    \begin{align*}
        (p, q, t) \preceq^{\mathrm{sell}} (p^\prime, q^\prime, t^\prime)
        &\iff (p,q,t)=(p^\prime,q^\prime,t^\prime) \lor (p < p^\prime)\\
        &\qquad\lor ((p = p^\prime) \land (t < t^\prime)).
    \end{align*}
    On $O$, the relation $\preceq$ is defined for $(o,\kappa),(o^\prime,\kappa^\prime)\in O$ by
    \begin{align}\label{eq:price-time-priority}
        (o, \kappa) \preceq (o^\prime, \kappa^\prime) \iff ((\kappa = \mathrm{buy}) \land (\kappa^\prime = \mathrm{sell})) \lor ((\kappa = \kappa^\prime) \land (o \preceq^{\kappa} o^\prime)).
    \end{align}
    Furthermore, the \emph{order metric} $d_O:O\times O\to[0,\infty]$ is defined by
    \begin{align*}
        d_O(((p,q,t),\kappa), ((p^\prime, q^\prime, t^\prime), \kappa^\prime)) = \begin{cases}
            \infty & \kappa \neq \kappa^\prime,\\
            \lvert p-p^\prime\rvert + \lvert\log(q) - \log(q^\prime)\rvert + \lvert t-t^\prime\rvert  & \kappa = \kappa^\prime.
        \end{cases}
    \end{align*}

steps.text:
Let $\bm{m} \in \mathscr{S}(O, \preceq)$ be given, and for each $\kappa\in\{\mathrm{buy},\mathrm{sell}\}$, define the side index set
    \begin{align*}
        I_\kappa(\bm{m})=\{i\in\operatorname{domain}(\bm{m}) \mid \bm{m}(i) \in \left([-9999,9999]\times (0,\infty) \times [0,1]\right) \times \{\kappa\}\},
    \end{align*}
    and let $n=\ell(\bm{\Pi}_{\mathrm{buy}}\bm{m})$. If a sell order occurred at an index $i$ before a buy order at an index $j$, then $i<j$ and $\bm{m}(j)\prec\bm{m}(i)$ by \eqref{eq:price-time-priority}, contradicting Definition~\ref{defn:sorted-tuples}. Hence,
    \begin{align*}
        I_{\mathrm{buy}}(\bm{m})=\{1,\ldots,n\}
        \qquad\text{and}\qquad
        I_{\mathrm{sell}}(\bm{m})=\{n+1,\ldots,\ell(\bm{m})\}.
    \end{align*}
    Fix $\kappa\in\{\mathrm{buy},\mathrm{sell}\}$, and let $\prec^\kappa$ denote the strict part of $\preceq^\kappa$. Let $r,r^\prime\in\operatorname{domain}(\bm{\Pi}_\kappa\bm{m})$ satisfy $r<r^\prime$. Since $\bm{\Pi}_\kappa\bm{m}=\bm{P}_{\mathrm{element}}(\bm{m}[I_\kappa(\bm{m})])$ by Definition~\ref{defn:separation-operators}, reindexing gives indices $i<j$ in $I_\kappa(\bm{m})$ such that
    \begin{align*}
        (\bm{\Pi}_\kappa\bm{m})(r)=o_i,\qquad
        (\bm{\Pi}_\kappa\bm{m})(r^\prime)=o_j,
        \qquad
        \bm{m}(i)=(o_i,\kappa),\qquad
        \bm{m}(j)=(o_j,\kappa).
    \end{align*}
    Since $\bm{m}$ is sorted, $\neg(\bm{m}(j)\prec\bm{m}(i))$. By \eqref{eq:price-time-priority}, this gives $\neg(o_j\prec^\kappa o_i)$. Consequently, no later entry of $\bm{\Pi}_\kappa\bm{m}$ strictly precedes an earlier entry, which establishes that $\bm{\Pi}_\kappa\bm{m} \in \mathscr{S}([-9999,9999]\times (0,\infty) \times [0,1], \preceq^\kappa)$ by Definition~\ref{defn:sorted-tuples}, as claimed.

proof.text:
Let $\bm{m} \in \mathscr{S}(O, \preceq)$ be given, and for each $\kappa\in\{\mathrm{buy},\mathrm{sell}\}$, define the side index set
    \begin{align*}
        I_\kappa(\bm{m})=\{i\in\operatorname{domain}(\bm{m}) \mid \bm{m}(i) \in \left([-9999,9999]\times (0,\infty) \times [0,1]\right) \times \{\kappa\}\},
    \end{align*}
    and let $n=\ell(\bm{\Pi}_{\mathrm{buy}}\bm{m})$. If a sell order occurred at an index $i$ before a buy order at an index $j$, then $i<j$ and $\bm{m}(j)\prec\bm{m}(i)$ by \eqref{eq:price-time-priority}, contradicting Definition~\ref{defn:sorted-tuples}. Hence,
