\label{prop:separation-preserves-price-time}
    Let $U = [-9999,9999]\times (0,\infty) \times [0,1]$, let $O = \bigsqcup_{\kappa\in\{\mathrm{buy},\mathrm{sell}\}} U$, and let $\preceq^{\mathrm{buy}}$, $\preceq^{\mathrm{sell}}$, and $\preceq$ be as in Definition~\ref{defn:price-time-priority-metric}. Then, for each $\kappa \in \{\mathrm{buy}, \mathrm{sell}\}$, the separation operator $\bm{\Pi}_\kappa$ of Definition~\ref{defn:separation-operators} maps $\mathscr{S}(O, \preceq)$ into $\mathscr{S}(U, \preceq^\kappa)$, that is,
    \begin{align*}
        \bm{\Pi}_\kappa : \mathscr{S}(O, \preceq) \to \mathscr{S}([-9999,9999]\times (0,\infty) \times [0,1], \preceq^\kappa).
    \end{align*}

\label{defn:best-price-and-tradeprice}
    Let $U = [-9999,9999]\times\allowbreak (0,\infty) \times [0,1]$ and $O = \bigsqcup_{\kappa\in\{\mathrm{buy},\mathrm{sell}\}} U$, let $\preceq$ be as in Definition~\ref{defn:price-time-priority-metric}, and let $\mathsf{price} : U \to [-9999,9999]$, $\mathsf{quantity} : U \to (0,\infty)$, and $\mathsf{time} : U \to [0,1]$ denote the first, second, and third coordinate projections on $U$, respectively. For each $\kappa \in \{\mathrm{buy}, \mathrm{sell}\}$, the \emph{best-price functional} $\mathsf{best}_\kappa:\mathscr{T}(U) \to [-10000, 10000]$ is defined by
    \begin{align*}
        \mathsf{best}_\kappa(\bm{x}) = \begin{cases}
            10000 & \bm{x} = \bm{e} \land \kappa = \mathrm{sell},\\
            -10000 & \bm{x} = \bm{e} \land \kappa = \mathrm{buy},\\
            \mathsf{price}(\bm{x}(1)) & \text{otherwise}.
        \end{cases}
    \end{align*}
    For any $\bm{m} \in \mathscr{S}(O, \preceq)$ with $\bm{b} = \bm{\Pi}_{\mathrm{buy}}(\bm{m})$ and $\bm{s} = \bm{\Pi}_{\mathrm{sell}}(\bm{m})$ satisfying
    \begin{align*}
        \mathsf{best}_{\mathrm{buy}}(\bm{b}) \geq \mathsf{best}_{\mathrm{sell}}(\bm{s}),
    \end{align*}
    the \emph{matched quantity} is $\min(\mathsf{quantity}(\bm{b}(1)), \mathsf{quantity}(\bm{s}(1)))$, and for $\kappa\in\{\mathrm{buy},\mathrm{sell}\}$, the \emph{transaction price} is defined by
    \begin{align*}
        \mathsf{tradeprice}(\bm{b},\bm{s};\kappa)
        =\begin{cases}
            \mathsf{price}(\bm{s}(1)) & \kappa=\mathrm{buy},\\
            \mathsf{price}(\bm{b}(1)) & \kappa=\mathrm{sell}.
        \end{cases}
    \end{align*}

steps.text:
To show that $T$ is closed in the product space $\mathscr{S}(U,\preceq^{\mathrm{buy}})\times\mathscr{S}(U,\preceq^{\mathrm{sell}})$, define the closed half-space
    \begin{align*}
        H = \{(p, p^\prime) \in [-10000,10000] \times [-10000,10000] \mid p \geq p^\prime\},
    \end{align*}
    which is closed in $[-10000,10000] \times [-10000,10000]$. Moreover, the map $G:\mathscr{S}(U,\preceq^{\mathrm{buy}})\times\mathscr{S}(U,\preceq^{\mathrm{sell}}) \to [-10000,10000]\times [-10000,10000]$ defined by
    \begin{align*}
        G(\bm{b}, \bm{s}) = (\mathsf{best}_{\mathrm{buy}}(\bm{b}), \mathsf{best}_{\mathrm{sell}}(\bm{s})) 
    \end{align*}
    is continuous; each component is continuous by the standard machinery (Theorem~\ref{thm:the-standard-machinery}), since $\mathsf{best}_\kappa$ is given on each fixed-length layer by a continuous function. Since $H$ is closed and $G$ is continuous, the preimage $G^{-1}(H)$ is closed in $\mathscr{S}(U,\preceq^{\mathrm{buy}}) \times\mathscr{S}(U,\preceq^{\mathrm{sell}})$. Since $T = G^{-1}(H)$ by construction, it follows that $T$ is closed in $\mathscr{S}(U,\preceq^{\mathrm{buy}}) \times\mathscr{S}(U,\preceq^{\mathrm{sell}})$, as required.

proof.text:
To show that $T$ is closed in the product space $\mathscr{S}(U,\preceq^{\mathrm{buy}})\times\mathscr{S}(U,\preceq^{\mathrm{sell}})$, define the closed half-space
    \begin{align*}
        H = \{(p, p^\prime) \in [-10000,10000] \times [-10000,10000] \mid p \geq p^\prime\},
    \end{align*}
    which is closed in $[-10000,10000] \times [-10000,10000]$. Moreover, the map $G:\mathscr{S}(U,\preceq^{\mathrm{buy}})\times\mathscr{S}(U,\preceq^{\mathrm{sell}}) \to [-10000,10000]\times [-10000,10000]$ defined by
    \begin{align*}
        G(\bm{b}, \bm{s}) = (\mathsf{best}_{\mathrm{buy}}(\bm{b}), \mathsf{best}_{\mathrm{sell}}(\bm{s})) 
    \end{align*}
    is continuous; each component is continuous by the standard machinery (Theorem~\ref{thm:the-standard-machinery}), since $\mathsf{best}_\kappa$ is given on each fixed-length layer by a continuous function. Since $H$ is closed and $G$ is continuous, the preimage $G^{-1}(H)$ is closed in $\mathscr{S}(U,\preceq^{\mathrm{buy}}) \times\mathscr{S}(U,\preceq^{\mathrm{sell}})$. Since $T = G^{-1}(H)$ by construction, it follows that $T$ is closed in $\mathscr{S}(U,\preceq^{\mathrm{buy}}) \times\mathscr{S}(U,\preceq^{\mathrm{sell}})$, as required.

results.statement:
\label{prop:crossing-set-closed}
    Let $U = [-9999,9999]\times(0,\infty)\times[0,1]$, and let $\preceq^{\mathrm{buy}}$, $\preceq^{\mathrm{sell}}$, $\mathsf{best}_{\mathrm{buy}}$, and $\mathsf{best}_{\mathrm{sell}}$ be as in Definitions~\ref{defn:price-time-priority-metric} and~\ref{defn:best-price-and-tradeprice}. Then the set 
    \begin{align}\label{eq:trade-equation}
        T = \{(\bm{b},\bm{s}) \in \mathscr{S}(U,\preceq^{\mathrm{buy}})\times\mathscr{S}(U,\preceq^{\mathrm{sell}}) \mid 
    \mathsf{best}_{\mathrm{buy}}(\bm{b})\geq\mathsf{best}_{\mathrm{sell}}(\bm{s})\}
    \end{align}
    is closed in $\mathscr{S}(U,\preceq^{\mathrm{buy}})\times\mathscr{S}(U,\preceq^{\mathrm{sell}})$ endowed with the product of the tuple Hausdorff metrics.

steps.text:
Set
    \begin{align*}
        E=\mathscr{S}(U,\preceq^{\mathrm{buy}})\times\mathscr{S}(U,\preceq^{\mathrm{sell}});
    \end{align*}
    we prove the Borel measurability of $\Phi$ by decomposing $E$ into a finite measurable partition on each piece of which $\Phi$ is continuous. By Proposition~\ref{prop:crossing-set-closed}, $T$ is Borel measurable in $E$. The empty-side conventions in Definition~\ref{defn:best-price-and-tradeprice} imply that both tuples are non-empty on $T$. Thus, on $T$, evaluation at the first coordinate and the projections $\mathsf{price}$, $\mathsf{quantity}$, and $\mathsf{time}$ show that
    \begin{align*}
        (\bm{b},\bm{s})&\mapsto(p_{\bm{b}},q_{\bm{b}},t_{\bm{b}}),\\
        (\bm{b},\bm{s})&\mapsto(p_{\bm{s}},q_{\bm{s}},t_{\bm{s}})
    \end{align*}
    are continuous. Hence,
    \begin{align*}
        T_{<} &= T\cap\{(\bm{b},\bm{s}) \mid q_{\bm{b}}<q_{\bm{s}}\},\\
        T_{>} &= T\cap\{(\bm{b},\bm{s}) \mid q_{\bm{b}}>q_{\bm{s}}\},\\
        T_{=} &= T\cap\{(\bm{b},\bm{s}) \mid q_{\bm{b}}=q_{\bm{s}}\}
    \end{align*}
    are Borel measurable, and $T^{\mathtt{C}},T_{>},T_{<},T_{=}$ form a measurable partition of $E$. Define
    \begin{align*}
        h_{<}:T_{<}&\to\mathscr{L}(U),
        &
        h_{<}(\bm{b},\bm{s})
        &=\{(1,(p_{\bm{s}},q_{\bm{s}}-q_{\bm{b}},t_{\bm{s}}))\},\\
        h_{>}:T_{>}&\to\mathscr{L}(U),
        &
        h_{>}(\bm{b},\bm{s})
        &=\{(1,(p_{\bm{b}},q_{\bm{b}}-q_{\bm{s}},t_{\bm{b}}))\}.
    \end{align*}
    Both maps are continuous. Indeed, $(\bm{b},\bm{s})\mapsto(p_{\bm{s}},q_{\bm{s}}-q_{\bm{b}},t_{\bm{s}})$ is continuous on $T_{<}$, and $(\bm{b},\bm{s})\mapsto(p_{\bm{b}},q_{\bm{b}}-q_{\bm{s}},t_{\bm{b}})$ is continuous on $T_{>}$. Composing each map with $x\mapsto\{(1,x)\}$, which is continuous from $U$ to $\mathscr{L}(U)$, gives $h_{<}$ and $h_{>}$, respectively. By Theorem~\ref{thm:analytic-properties-actions}, $\ominus$ and $\circledast$ are continuous. Therefore,
    \begin{align*}
        \Phi\restriction_{T_{<}}(\bm{b},\bm{s})
        &=\left(\bm{b}\ominus\{1\},\bm{s}\circledast h_{<}(\bm{b},\bm{s})\right),\\
        \Phi\restriction_{T_{>}}(\bm{b},\bm{s})
        &=\left(\bm{b}\circledast h_{>}(\bm{b},\bm{s}),\bm{s}\ominus\{1\}\right),\\
        \Phi\restriction_{T_{=}}(\bm{b},\bm{s})
        &=\left(\bm{b}\ominus\{1\},\bm{s}\ominus\{1\}\right)
    \end{align*}
    are continuous. The remaining restriction $\Phi\restriction_{T^{\mathtt{C}}}$ coincides with the identity map on $T^{\mathtt{C}}$ and is therefore continuous as well. Applying Theorem~\ref{thm:measurable-partition} to the finite measurable partition $\{T^{\mathtt{C}}, T_{<}, T_{>}, T_{=}\}$ of $E$, we conclude that $\Phi$ is Borel measurable on $E$.

proof.text:
Set
    \begin{align*}
        E=\mathscr{S}(U,\preceq^{\mathrm{buy}})\times\mathscr{S}(U,\preceq^{\mathrm{sell}});
    \end{align*}
    we prove the Borel measurability of $\Phi$ by decomposing $E$ into a finite measurable partition on each piece of which $\Phi$ is continuous. By Proposition~\ref{prop:crossing-set-closed}, $T$ is Borel measurable in $E$. The empty-side conventions in Definition~\ref{defn:best-price-and-tradeprice} imply that both tuples are non-empty on $T$. Thus, on $T$, evaluation at the first coordinate and the projections $\mathsf{price}$, $\mathsf{quantity}$, and $\mathsf{time}$ show that
