    are continuous. The remaining restriction $\Phi\restriction_{T^{\mathtt{C}}}$ coincides with the identity map on $T^{\mathtt{C}}$ and is therefore continuous as well. Applying Theorem~\ref{thm:measurable-partition} to the finite measurable partition $\{T^{\mathtt{C}}, T_{<}, T_{>}, T_{=}\}$ of $E$, we conclude that $\Phi$ is Borel measurable on $E$.

results.statement:
\label{defn:iterated-single-stage-clearing}
    Let $U = [-9999,9999]\times(0,\infty)\times[0,1]$ and let $\Phi$ be as in Definition~\ref{defn:single-stage-clearing-map}. For each $i\in\mathbb{N}_0$, the \emph{$i$-fold iterated single-stage clearing map}
    \begin{align*}
        \Phi^{(i)} : \mathscr{S}(U,\preceq^{\mathrm{buy}})\times\mathscr{S}(U,\preceq^{\mathrm{sell}}) \to \mathscr{S}(U,\preceq^{\mathrm{buy}})\times\mathscr{S}(U,\preceq^{\mathrm{sell}})
    \end{align*}
    is defined recursively by
    \begin{align*}
        \Phi^{(0)} &= \mathrm{Id},\\
        \Phi^{(1)} &= \Phi, \\
        \Phi^{(i)} &= \Phi^{(i-1)} \circ \Phi, \qquad i > 1.
    \end{align*}

\label{defn:retagging}
    Let $(X_\alpha)_{\alpha\in A}$ be a family of non-empty sets and let $X=\bigsqcup_{\alpha\in A}X_\alpha$. For each $\alpha\in A$, define the \emph{$\alpha$-retagging map}
    \begin{align*}
        \iota_\alpha:X_\alpha&\to X,\\
        x&\mapsto(x,\alpha),
    \end{align*}
    and its tuple-wise extension $\bm{\iota}_\alpha:\mathscr{T}(X_\alpha)\to\mathscr{T}(X)$ by
    \begin{align*}
        \bm{\iota}_\alpha\bm{x}=\iota_\alpha\circ\bm{x}.
    \end{align*}

steps.text:
Fix $\alpha\in A$, and let $x,y\in X_\alpha$ be arbitrary. By Definition~\ref{defn:disjoint-union-metrisation} of the disjoint-union metric, we have
    \begin{align*}
        d(\iota_\alpha(x),\iota_\alpha(y))=d_\alpha(x,y).
    \end{align*}
    Hence, the map $(i,x)\mapsto(i,\iota_\alpha(x))$ preserves the metric on the graphs of tuples. By the definition of the induced tuple Hausdorff metrics, for all $\bm{x},\bm{y}\in\mathscr{T}(X_\alpha)$,
    \begin{align*}
        \mathscr{d}_H(\bm{\iota}_\alpha\bm{x},\bm{\iota}_\alpha\bm{y})
        =\mathscr{d}_{H,\alpha}(\bm{x},\bm{y}).
    \end{align*}
    Thus, $\bm{\iota}_\alpha$ is an isometry from $(\mathscr{T}(X_\alpha),\mathscr{d}_{H,\alpha})$ into $(\mathscr{T}(X),\mathscr{d}_H)$, and it is therefore continuous and Borel measurable, as claimed.

proof.text:
Fix $\alpha\in A$, and let $x,y\in X_\alpha$ be arbitrary. By Definition~\ref{defn:disjoint-union-metrisation} of the disjoint-union metric, we have
    \begin{align*}
        d(\iota_\alpha(x),\iota_\alpha(y))=d_\alpha(x,y).
    \end{align*}
    Hence, the map $(i,x)\mapsto(i,\iota_\alpha(x))$ preserves the metric on the graphs of tuples. By the definition of the induced tuple Hausdorff metrics, for all $\bm{x},\bm{y}\in\mathscr{T}(X_\alpha)$,
    \begin{align*}
        \mathscr{d}_H(\bm{\iota}_\alpha\bm{x},\bm{\iota}_\alpha\bm{y})
        =\mathscr{d}_{H,\alpha}(\bm{x},\bm{y}).
    \end{align*}
    Thus, $\bm{\iota}_\alpha$ is an isometry from $(\mathscr{T}(X_\alpha),\mathscr{d}_{H,\alpha})$ into $(\mathscr{T}(X),\mathscr{d}_H)$, and it is therefore continuous and Borel measurable, as claimed.

results.statement:
\label{cor:retagging-measurable}
    Let $(X_\alpha,d_\alpha)_{\alpha\in A}$ be a countable family of metric spaces, and let $X=\bigsqcup_{\alpha\in A}X_\alpha$ be endowed with the disjoint-union metric $d:X\times X\to[0,\infty]$. Moreover, let $(\mathscr{T}(X_\alpha),\mathscr{d}_{H,\alpha})$ be the tuple Hausdorff space induced by $d_\alpha$, and let $(\mathscr{T}(X),\mathscr{d}_H)$ be the tuple Hausdorff space induced by $d$. Then, for every $\alpha\in A$, the tuple-wise retagging map
    \begin{align*}
        \bm{\iota}_\alpha:(\mathscr{T}(X_\alpha),\mathscr{d}_{H,\alpha})\to(\mathscr{T}(X),\mathscr{d}_H)
    \end{align*}
    is continuous, and hence Borel measurable.

\label{defn:clearing-operator}
    Let $O$ and $\preceq$ be as in Definition~\ref{defn:price-time-priority-metric}, let $\bm{\Pi}_{\mathrm{buy}}$ and $\bm{\Pi}_{\mathrm{sell}}$ be the separation operators of Definition~\ref{defn:separation-operators}, let $\Phi^{(i)}$ be as in Definition~\ref{defn:iterated-single-stage-clearing}, and let $\bm{\iota}_{\mathrm{buy}}$ and $\bm{\iota}_{\mathrm{sell}}$ be the retagging maps of Definition~\ref{defn:retagging}. The \emph{clearing operator}
    \begin{align*}
        \mathsf{C}: \mathscr{S}(O,\preceq) \to \mathscr{S}(O,\preceq)
    \end{align*}
    is defined for $\bm{m}\in\mathscr{S}(O,\preceq)$ by setting
    \begin{align*}
        (\bm{b}^\star,\bm{s}^\star)
        &=
        \Phi^{(\max\{\ell(\bm{m})-1,0\})}
        \left(\bm{\Pi}_{\mathrm{buy}}\bm{m},
        \bm{\Pi}_{\mathrm{sell}}\bm{m}\right),\\
        \mathsf{C}(\bm{m})
        &=(\bm{\iota}_{\mathrm{buy}}\bm{b}^\star)
        \oplus(\bm{\iota}_{\mathrm{sell}}\bm{s}^\star).
    \end{align*}

steps.text:
To establish the Borel measurability of $\mathsf{C}$, we partition $\mathscr{S}(O,\preceq)$ by tuple length. For each $n\in\mathbb{N}_0$, set
    \begin{align*}
        S_n=\mathscr{S}(O,\preceq)\cap O^n.
    \end{align*}
    The sets $(S_n)_{n\in\mathbb{N}_0}$ form a countable measurable partition of $\mathscr{S}(O,\preceq)$. Indeed, the fixed-length layers are open and closed in the tuple topology by the standard machinery (Theorem~\ref{thm:the-standard-machinery}), and hence their intersections with $\mathscr{S}(O,\preceq)$ are Borel measurable in the relative topology.

Define the merging map
    \begin{align*}
        G:\mathscr{S}(U,\preceq^{\mathrm{buy}})\times\mathscr{S}(U,\preceq^{\mathrm{sell}})&\to\mathscr{S}(O,\preceq),\\
        G(\bm{b},\bm{s})&=(\bm{\iota}_{\mathrm{buy}}\bm{b})\oplus(\bm{\iota}_{\mathrm{sell}}\bm{s}).
    \end{align*}
    By Proposition~\ref{prop:separation-continuous}, the separation map
    \begin{align*}
        \bm{m}\mapsto\left(\bm{\Pi}_{\mathrm{buy}}\bm{m},\bm{\Pi}_{\mathrm{sell}}\bm{m}\right)
    \end{align*}
    is continuous. The map $G$ is continuous by Corollary~\ref{cor:retagging-measurable} and the continuity of concatenation. For $\bm{m}\in S_n$, we have $\ell(\bm{m})=n$, and hence
    \begin{align*}
        \mathsf{C}\restriction_{S_n}
        =G\circ\Phi^{(\max\{n-1,0\})}\circ
        \left(\bm{\Pi}_{\mathrm{buy}},\bm{\Pi}_{\mathrm{sell}}\right)
        \restriction_{S_n}.
    \end{align*}
    Corollary~\ref{cor:iterated-single-stage-measurable} gives the measurability of $\Phi^{(\max\{n-1,0\})}$ for every $n\in\mathbb{N}_0$. Thus, $\mathsf{C}\restriction_{S_n}$ is Borel measurable for every $n\in\mathbb{N}_0$. Since the sets $(S_n)_{n\in\mathbb{N}_0}$ form a countable measurable partition of $\mathscr{S}(O,\preceq)$, the measurable pasting property of the standard machinery (Theorem~\ref{thm:the-standard-machinery}) implies that $\mathsf{C}$ is Borel measurable on $\mathscr{S}(O,\preceq)$.

proof.text:
To establish the Borel measurability of $\mathsf{C}$, we partition $\mathscr{S}(O,\preceq)$ by tuple length. For each $n\in\mathbb{N}_0$, set
    \begin{align*}
        S_n=\mathscr{S}(O,\preceq)\cap O^n.
    \end{align*}
    The sets $(S_n)_{n\in\mathbb{N}_0}$ form a countable measurable partition of $\mathscr{S}(O,\preceq)$. Indeed, the fixed-length layers are open and closed in the tuple topology by the standard machinery (Theorem~\ref{thm:the-standard-machinery}), and hence their intersections with $\mathscr{S}(O,\preceq)$ are Borel measurable in the relative topology.

