{kunen2014set}}]\label{thm:no-universal-set}
    There is no universal set. That is,
    \begin{align*}
        \neg(\exists y \forall x( x \in y)).
    \end{align*}

{kunen2014set}}]\label{axiom:pairing}\index{axioms!pairing}
    For any sets $x$ and $y$, there is a set whose elements are exactly $x$ and $y$. That is,
    \begin{align*}
        \forall x \forall y \exists z \forall w(w \in z \iff (w = x \lor w = y)).
    \end{align*}

{kunen2014set}}]\label{axiom:union}\index{axioms!union}
    For any family $F$ of sets, there is a set whose elements are exactly the elements of members of $F$. That is,
    \begin{align*}
        \forall F \exists U \forall x(x \in U \iff \exists X(X \in F \land x \in X)).
    \end{align*}

{kunen2014set}}]\label{axiom:power-set}\index{axioms!power set}
    For any set $x$, there is a set whose elements are exactly the subsets of $x$. That is,
    \begin{align*}
        \forall x \exists y \forall z(z \in y \iff z \subseteq x).
    \end{align*}

{kunen2014set}}]\label{defn:power-set}
    Let $X$ be a set. Then, we define the set
    \begin{align*}
        \wp(X) = \{B \mid B \subseteq X\},
    \end{align*}
    and we call $\wp(X)$ the power set of $X$.

{kunen2014set}}]\label{axiom:replacement}\index{axioms!replacement}
    For any formula $\phi \equiv \phi(x, y, X, w_1, \dots, w_n)$ whose free variables are among $x,y, X, w_1,\dots, w_n$, the corresponding axiom is
    \begin{align*}
        \forall X \forall w_1, \dots, w_n \left((\forall x \in X \exists! y:\phi) \implies \exists Y \forall y\left(y \in Y \iff \exists x \in X:\phi\right)\right).
    \end{align*}

{kunen2014set}}]\label{axiom:infinity}\index{axioms!infinity}
    There exists an inductive set, that is, a set containing $\emptyset$ and closed under $x\mapsto x\cup\{x\}$. Formally,
    \begin{align*}
        \exists X\left(\emptyset \in X \land \forall x\left(x \in X \implies (x \cup \{x\}) \in X\right)\right).
    \end{align*}

{kunen2014set}}]\label{defn:product-space}\index{product space}
    Let $X$ and $Y$ be sets. For elements $x \in X$ and $y \in Y$ we call $(x,y) = \{\{x\}, \{x,y\}\}$ the (Kuratowski) ordered pair of $x$ and $y$. Moreover, we call the set
    \begin{align*}
        X\times Y = \{(x,y) \mid x \in X, y \in Y\}
    \end{align*}
    the Cartesian product of $X$ and $Y$.

{kunen2014set}}]\label{defn:relation}
    Let $X$ and $Y$ be sets. We call any $R \subseteq X \times Y$ a relation and for any $(x,y) \in R$ we say that $x$ is $R$-related to $y$ and we write $x R y$. Moreover, we define the \emph{domain} of $R$ by
    \begin{align*}
        \mathrm{domain}(R) = \{x \in X \mid \exists y \in Y: (x,y) \in R\},
    \end{align*}
    and the \emph{image}, or range, of $R$ by
    \begin{align*}
        \mathrm{image}(R) = \{y \in Y \mid \exists x \in X: (x,y) \in R\}.
    \end{align*}

\label{defn:equivalence-class}
    Let $X$ be a set and let $\sim\subseteq X\times X$ be an equivalence relation. For each $x \in X$ define
    \begin{align*}
        [x]_{\sim} =\{x^\prime \in X \mid x^\prime \sim x\}.
    \end{align*}
The set $[x]_{\sim}$ is called an equivalence class\index{equivalence class} of $X$ with respect to $\sim$; we write $[x]$ when $\sim$ is clear from context. Moreover, we denote the quotient set of $X$ by $\sim$, the set of all equivalence classes, by
    \begin{align*}
        X_\sim = \{[x] \mid x \in X\}.
    \end{align*}

\label{defn:graph}
    Let $X$ and $Y$ be sets and let $f:X \to Y$ be a function. Then, the set
    \begin{align*}
        \Gamma(f) = \{(x,f(x)) \mid x \in X\}
    \end{align*}
    is called the graph of $f$.

steps.text:
We must show that $f=f^\prime$. Because the domain $\emptyset$ has no elements, Definition~\ref{defn:graph} gives
    \begin{align*}
        \emptyset = \Gamma(f) = \Gamma(f^\prime),
    \end{align*}
    and the result now follows from Proposition~\ref{prop:graph-defines}.

proof.text:
We must show that $f=f^\prime$. Because the domain $\emptyset$ has no elements, Definition~\ref{defn:graph} gives
    \begin{align*}
        \emptyset = \Gamma(f) = \Gamma(f^\prime),
    \end{align*}
    and the result now follows from Proposition~\ref{prop:graph-defines}.

results.statement:
\label{defn:arbitrary-product-space}
     Let $(X_\alpha)_{\alpha \in A}$ be a family of sets indexed by a set $A$. Define
    \begin{align*}
        \prod_{\alpha \in A} X_\alpha = \left\{x:A \to \bigcup_{\alpha \in A}X_\alpha ~\middle\lvert~\forall \alpha \in A:x(\alpha) \in X_\alpha \right\}.
    \end{align*}
    We call $\prod_{\alpha \in A} X_\alpha$ the Cartesian product of $(X_\alpha)_{\alpha \in A}$.

\label{prop:binary-product-space}
    Let $X_1$ and $X_2$ be sets. Then the map $(x_1,x_2)\mapsto\{(1,x_1),(2,x_2)\}$ is a bijection from the Cartesian product of Definition~\ref{defn:product-space} onto the Cartesian product of the family $(X_i)_{i\in\{1,2\}}$ of Definition~\ref{defn:arbitrary-product-space}; that is,
    \begin{align*}
        X_1 \times X_2 \cong \prod_{i=1}^2 X_i.
    \end{align*}

{jech2008axiom}}]\label{axiom:choice}
    For any set of non-empty sets, there is a function that picks an element of each set. That is,
    \begin{align*}
        \forall X\left( \emptyset \notin X \implies \exists f:X \to \bigcup_{A \in X} A: \forall A \in X( f(A) \in A)\right).
    \end{align*}

\label{defn:ordered-sets}
    Let $X$ be a set and let $\leq \subseteq X\times X$ be a relation such that, for all $x, x^\prime, x^\ast \in X$:
    \begin{enumerate}[(i)]
        \item $x \leq x$,
        \item $x \leq x^\prime$ and $x^\prime \leq x$ implies $x = x^\prime$, and
        \item $x \leq x^\prime$ and $x^\prime \leq x^\ast$ implies $x\leq x^\ast$.
    \end{enumerate}
    Then $(X,\leq)$ is called a partially ordered set. Now, let
    \begin{align*}
         \mathord{<}\;:=\;\leq \setminus \{(x,x) \mid x \in X\}.
    \end{align*}
    If, in addition, $\leq$ satisfies
    \begin{enumerate}[(i)]
        \addtocounter{enumi}{3}
        \item $x \neq x^\prime$ implies $x < x^\prime$ or $x^\prime < x$,
    \end{enumerate}
    then we call $(X, \leq)$ a totally ordered set and we say that $\leq$ is a total order. Finally, if $(X,\leq)$ is a totally ordered set in which each non-empty subset has a least element, i.e.,
    \begin{align*}
        \forall S\left((S\subseteq X \land S\neq\emptyset) \implies \exists x\in S \forall x^\prime \in S(x\leq x^\prime)\right),
    \end{align*}
    then we call $(X,\leq)$ a well-ordered set and we say that $\leq$ is a well-order.

{jech2008axiom}}]\label{thm:zorns-lemma}
    Let $(X,\leq)$ be a non-empty partially ordered set, and suppose that every subset $C\subseteq X$ that is totally ordered by $\leq$ has an upper bound in $X$, i.e.,
    \begin{align*}
        \forall C\left((C\subseteq X \land \text{$C$ is totally ordered by }\leq) \implies \exists x \in X \forall c \in C(c \leq x)\right).
    \end{align*}
    Then, there exists a maximal element $x^\ast \in X$, i.e.,
    \begin{align*}
        \forall x \in X(x^\ast \leq x \implies x = x^\ast).
    \end{align*}

{kunen2014set}}]\label{thm:recursion}\index{recursion}
    Let $X$ be a set and let $G:\bigcup_{n\in\mathbb{N}_0}X^n\to X$ be a function. Then there is a unique function $f:\mathbb{N}\to X$ such that
    \begin{align*}
        f(n)=G\bigl(f\restriction_{\{1,\dots,n-1\}}\bigr)\quad\text{for all }n\in\mathbb{N},
    \end{align*}
    where $\{1,\dots,0\}=\emptyset$.

\label{defn:sequence}
 Let $X$ be a set. Then any map $x:\mathbb{N} \to X$ is called an $X$-sequence, and we write
    \begin{align*}
        x_n := x(n),
    \end{align*}
    for all $n \in \mathbb{N}$. Moreover, we usually denote the sequence by $(x_n)_{n\in\mathbb{N}}$ rather than by $x$. Finally, we write $X^{\mathbb{N}}$ for the set of all $X$-sequences.

{weibel2013k}}] \label{defn:abelian-monoid}\index{abelian monoid}
    Let $(X,+)$ be a monoid for which
    \begin{align*}
        x + x^\prime = x^\prime + x,
    \end{align*}
    for all $x,x^\prime \in X$. Then, the operation $+$ is called commutative and $(X,+)$ is called a commutative (or abelian) monoid.

{weibel2013k}}] \label{defn:cancellation-property}
    Let $(X,+)$ be a monoid for which
    \begin{align*}
        \forall x,x^\prime,x^\ast \in X: x^\prime + x = x^\ast + x \implies x^\prime = x^\ast,
    \end{align*}
    and
    \begin{align*}
        \forall x,x^\prime,x^\ast \in X: x + x^\prime = x + x^\ast \implies x^\prime = x^\ast.
    \end{align*}
    Then $(X,+)$ is said to satisfy the cancellation property, and such a monoid is called cancellative.

{lang2012algebra}}] \label{defn:abelian-group}\index{abelian group}
    Let $(G, +)$ be an abelian monoid which satisfies
    \begin{align*}
        \forall g \in G\; \exists h \in G: g + h = e,
    \end{align*}
where $e$ is the identity element of $(G,+)$. Then $(G,+)$ is called an abelian group. The element $h$ is unique (if $h$ and $h^\prime$ both satisfy $g+h=g+h^\prime=e$, then $h=h+(g+h^\prime)=(h+g)+h^\prime=h^\prime$), and we denote it by $-g$.

steps.text:
We must show that $\sim$ is reflexive, symmetric, and transitive on $X\times X$, and that it is compatible with componentwise addition. Reflexivity ($x+y=x+y$) and symmetry ($x+y^\prime=x^\prime+y\iff x^\prime+y=x+y^\prime$) are immediate from commutativity. For transitivity, suppose that $(x,y)\sim(x^\prime,y^\prime)$ and $(x^\prime,y^\prime)\sim(x^\ast,y^\ast)$. Associativity, commutativity, and the two defining equalities give
    \begin{align*}
        (x+y^\ast)+y^\prime&=(x+y^\prime)+y^\ast=(x^\prime+y)+y^\ast\\
        &=(x^\prime+y^\ast)+y=(x^\ast+y^\prime)+y=(x^\ast+y)+y^\prime,
    \end{align*}
    and cancelling $y^\prime$ yields $x+y^\ast=x^\ast+y$, so $(x,y)\sim(x^\ast,y^\ast)$. For the second claim, suppose that $(x,y)\sim(x^\prime,y^\prime)$ and $(u,v)\sim(u^\prime,v^\prime)$; then
    \begin{align*}
        (x+u)+(y^\prime+v^\prime)=(x+y^\prime)+(u+v^\prime)=(x^\prime+y)+(u^\prime+v)=(x^\prime+u^\prime)+(y+v),
    \end{align*}
    which proves that $(x+u,y+v)\sim(x^\prime+u^\prime,y^\prime+v^\prime)$, as desired.

proof.text:
We must show that $\sim$ is reflexive, symmetric, and transitive on $X\times X$, and that it is compatible with componentwise addition. Reflexivity ($x+y=x+y$) and symmetry ($x+y^\prime=x^\prime+y\iff x^\prime+y=x+y^\prime$) are immediate from commutativity. For transitivity, suppose that $(x,y)\sim(x^\prime,y^\prime)$ and $(x^\prime,y^\prime)\sim(x^\ast,y^\ast)$. Associativity, commutativity, and the two defining equalities give
    \begin{align*}
        (x+y^\ast)+y^\prime&=(x+y^\prime)+y^\ast=(x^\prime+y)+y^\ast\\
        &=(x^\prime+y^\ast)+y=(x^\ast+y^\prime)+y=(x^\ast+y)+y^\prime,
    \end{align*}
    and cancelling $y^\prime$ yields $x+y^\ast=x^\ast+y$, so $(x,y)\sim(x^\ast,y^\ast)$. For the second claim, suppose that $(x,y)\sim(x^\prime,y^\prime)$ and $(u,v)\sim(u^\prime,v^\prime)$; then
    \begin{align*}
        (x+u)+(y^\prime+v^\prime)=(x+y^\prime)+(u+v^\prime)=(x^\prime+y)+(u^\prime+v)=(x^\prime+u^\prime)+(y+v),
    \end{align*}
    which proves that $(x+u,y+v)\sim(x^\prime+u^\prime,y^\prime+v^\prime)$, as desired.

results.statement:
\label{prop:grothendieck-relation}
    Let $(X,+)$ be a cancellative abelian monoid, and define the relation $\sim$ on $X\times X$ by
    \begin{align*}
        (x,y) \sim (x^\prime, y^\prime) \iff x+y^\prime = x^\prime + y.
    \end{align*}
    Then $\sim$ is an equivalence relation, and $(x,y)\sim(x^\prime,y^\prime)$ and $(u,v)\sim(u^\prime,v^\prime)$ imply $(x+u,y+v)\sim(x^\prime+u^\prime,y^\prime+v^\prime)$.

{weibel2013k}}]\label{defn:grothendieck-group}
    Let $(X,+)$ be a cancellative abelian monoid with identity element $e$, and let $\sim$ be the equivalence relation of Proposition~\ref{prop:grothendieck-relation}. The quotient set $G(X)=(X\times X)_\sim$, endowed with the operation
    \begin{align*}
        [(x,y)] + [(x^\prime, y^\prime)] = [(x + x^\prime, y + y^\prime)],
    \end{align*}
    is called the Grothendieck group, or group completion, of $(X,+)$, and the map $\iota:X\to G(X)$ given by $\iota(x)=[(x,e)]$ is called its canonical map.

\label{prop:grothendieck-universal}
    Let $(X,+)$ be a cancellative abelian monoid with identity element $e$, and let $G(X)$ and $\iota$ be as in Definition~\ref{defn:grothendieck-group}. Then
    \begin{enumerate}[(i)]
        \item $(G(X),+)$ is an abelian group with identity element $[(e,e)]$, and $-[(x,y)]=[(y,x)]$ for all $x,y\in X$;
        \item $\iota$ is an injective monoid homomorphism, and $[(x,y)]=\iota(x)-\iota(y)$ for all $x,y\in X$;
        \item for every abelian group $(H,+)$ and every monoid homomorphism $\psi:X\to H$, there is a unique monoid homomorphism $\bar{\psi}:G(X)\to H$ such that $\bar{\psi}\circ\iota=\psi$, namely $\bar{\psi}([(x,y)])=\psi(x)-\psi(y)$.
    \end{enumerate}

{lang2012algebra}}]\label{defn:field}
    Let $\mathbb{K}$ be a set with two binary operations $+:\mathbb{K}\times\mathbb{K}\to\mathbb{K}$ and $\cdot:\mathbb{K}\times\mathbb{K}\to\mathbb{K}$ such that
    \begin{enumerate}[(i)]
        \item $(\mathbb{K},+)$ is an abelian group, whose identity element we denote by $0$;
        \item $\cdot$ maps $(\mathbb{K}\setminus\{0\})\times(\mathbb{K}\setminus\{0\})$ into $\mathbb{K}\setminus\{0\}$, and $(\mathbb{K}\setminus\{0\},\cdot)$ is an abelian group, whose identity element we denote by $1$ and in which we write $a^{-1}$ for the inverse of $a$;
        \item $a\cdot(b+c)=a\cdot b+a\cdot c$ and $(a+b)\cdot c=a\cdot c+b\cdot c$ for all $a,b,c\in\mathbb{K}$.
    \end{enumerate}
    Then $(\mathbb{K},+,\cdot)$ is called a field.

\label{prop:vector-space-extension}\index{vector space!extension}
    Let $(V, +, \cdot)$ be a vector space over a field $\mathbb{K}$. Let $X$ be a set, and define
    \begin{align*}
        F(X; V) = \{f \mid f:X \to V\}.
    \end{align*}
    Define $+:F(X; V) \times F(X; V) \to F(X; V)$ by
    \begin{align*}
        (f + g)(x) = f(x) + g(x),
    \end{align*}
    and define $\cdot:\mathbb{K}\times F(X; V) \to F(X; V)$ by
    \begin{align*}
        (a\cdot f)(x) = a\cdot f(x).
    \end{align*}
    Then $(F(X; V), +, \cdot)$ is a vector space over $\mathbb{K}$.

Let $X$ be a set. A topology on $X$ is a set $\mathcal{T} \subseteq \wp(X)$ satisfying the following conditions:
    \begin{enumerate}[(i)]
        \item $\emptyset \in \mathcal{T}$ and $X \in \mathcal{T}$; \label{itm:top-1}
        \item $\bigcap_{u \in U} u \in \mathcal{T}$ for all non-empty finite sets $U \subseteq \mathcal{T}$; \label{itm:top-2}
        \item $\bigcup_{o \in O} o \in \mathcal{T}$ for all sets $O \subseteq \mathcal{T}$. \label{itm:top-3}
    \end{enumerate}
    The elements of $\mathcal{T}$ are called open sets, and the pair $(X,\mathcal{T})$ is called a topological space.

\index{topological base}
    Let $X$ be a set. A family $\mathcal{B}$ of subsets of $X$ is called a topological base if
    \begin{enumerate}[(i)]
        \item for every $x \in X$ there exists $B \in \mathcal{B}$ such that $x \in B$;
        \item for every $B, B^\prime \in \mathcal{B}$ and $x \in B \cap B^\prime$ there exists $B^\ast \in \mathcal{B}$ such that $x \in B^\ast \subseteq B \cap B^\prime$.
    \end{enumerate}

steps.text:
Now let $B = B_X \times B_Y$ and $B^\prime = B_X^\prime \times B_Y^\prime$ be elements of $\mathcal{B}_X \otimes \mathcal{B}_Y$, and suppose $(x,y) \in B \cap B^\prime$. Then $x \in B_X \cap B_X^\prime$ and $y \in B_Y \cap B_Y^\prime$. By the base property, there exist $B_X^\ast \in \mathcal{B}_X$ and $B_Y^\ast \in \mathcal{B}_Y$ such that
    \begin{align*}
        x \in B_X^\ast \subseteq B_X \cap B_X^\prime
        \qquad \text{and} \qquad
        y \in B_Y^\ast \subseteq B_Y \cap B_Y^\prime.
    \end{align*}
    Therefore
    \begin{align*}
        (x,y) \in B_X^\ast \times B_Y^\ast \subseteq (B_X \times B_Y) \cap (B_X^\prime \times B_Y^\prime) = B \cap B^\prime,
    \end{align*}
    and $B_X^\ast \times B_Y^\ast \in \mathcal{B}_X \otimes \mathcal{B}_Y$.

proof.text:
We verify the two defining properties. Let $(x,y) \in X \times Y$. Since $\mathcal{B}_X$ and $\mathcal{B}_Y$ are bases, there exist $B_X \in \mathcal{B}_X$ and $B_Y \in \mathcal{B}_Y$ such that $x \in B_X$ and $y \in B_Y$. Hence $(x,y) \in B_X \times B_Y \in \mathcal{B}_X \otimes \mathcal{B}_Y$.

    Now let $B = B_X \times B_Y$ and $B^\prime = B_X^\prime \times B_Y^\prime$ be elements of $\mathcal{B}_X \otimes \mathcal{B}_Y$, and suppose $(x,y) \in B \cap B^\prime$. Then $x \in B_X \cap B_X^\prime$ and $y \in B_Y \cap B_Y^\prime$. By the base property, there exist $B_X^\ast \in \mathcal{B}_X$ and $B_Y^\ast \in \mathcal{B}_Y$ such that
    \begin{align*}
        x \in B_X^\ast \subseteq B_X \cap B_X^\prime
        \qquad \text{and} \qquad
        y \in B_Y^\ast \subseteq B_Y \cap B_Y^\prime.
    \end{align*}
    Therefore
    \begin{align*}
        (x,y) \in B_X^\ast \times B_Y^\ast \subseteq (B_X \times B_Y) \cap (B_X^\prime \times B_Y^\prime) = B \cap B^\prime,
    \end{align*}
    and $B_X^\ast \times B_Y^\ast \in \mathcal{B}_X \otimes \mathcal{B}_Y$.

results.statement:
Let $X$ and $Y$ be sets, and let $\mathcal{B}_X$ and $\mathcal{B}_Y$ be topological bases on $X$ and $Y$, respectively. Define
    \begin{align*}
        \mathcal{B}_X \otimes \mathcal{B}_Y = \{B_X \times B_Y \mid B_X \in \mathcal{B}_X,\ B_Y \in \mathcal{B}_Y\}.
    \end{align*}
    Then $\mathcal{B}_X \otimes \mathcal{B}_Y$ is a topological base on $X \times Y$.

\label{prop:topology-base}
    Let $X$ be a set and let $\mathcal{B}$ be a topological base on $X$. Define
    \begin{align*}
        \mathcal{T}_{\mathcal{B}} = \left\{\bigcup_{B \in \mathcal{U}} B \,\middle|\, \mathcal{U} \subseteq \mathcal{B}\right\}.
    \end{align*}
    Then $(X,\mathcal{T}_{\mathcal{B}})$ is a topological space, and $\mathcal{T}_{\mathcal{B}}$ is called the topology generated by $\mathcal{B}$.

Let $(X,\mathcal{T})$ and $(Y,\mathcal{S})$ be topological spaces and let $f:X \to Y$ be a function. Then $f$ is called continuous if
    \begin{align*}
        f^{-1}(O) \in \mathcal{T}, \qquad \forall O \in \mathcal{S}.
    \end{align*}

\label{defn:Hausdorff}\index{Hausdorff space}
    Let $(X,\mathcal{T})$ be a topological space. If for every pair of distinct points $x,x^\prime \in X$ there exist $O,O^\prime \in \mathcal{T}$ such that
    \begin{align*}
        x \in O, \qquad x^\prime \in O^\prime, \qquad O \cap O^\prime = \emptyset,
    \end{align*}
    then $(X,\mathcal{T})$ is called Hausdorff.

Let $(X,\mathcal{T})$ be a topological space and let $Y \subseteq X$. The subspace topology on $Y$ is
    \begin{align*}
        \mathcal{T}|_Y = \{Y \cap O \mid O \in \mathcal{T}\}.
    \end{align*}

Let $(X,\mathcal{T})$ be a topological space. A family $\mathcal{U} \subseteq \mathcal{T}$ is called an open cover of $X$ if
    \begin{align*}
        X = \bigcup_{O \in \mathcal{U}} O.
    \end{align*}
    If $\mathcal{V} \subseteq \mathcal{U}$ is also an open cover of $X$, then $\mathcal{V}$ is called a subcover.

\label{defn:metric}
    Let $X$ be a set, and let $d:X \times X \to [0,\infty]$ be a function such that for every $x,x^\prime,x^\ast \in X$:
    \begin{enumerate}[(i)]
        \item $d(x,x^\prime) = 0$ if and only if $x = x^\prime$; \label{eq:metric-1}
        \item $d(x,x^\prime) = d(x^\prime,x)$; \label{eq:metric-2}
        \item $d(x,x^\prime) \leq d(x,x^\ast) + d(x^\ast,x^\prime)$. \label{eq:metric-3}
    \end{enumerate}
    Then $d$ is called a metric, and $(X,d)$ is called a metric space.

\label{rem:extended-metric-convention}\index{extended metric}
    Following \cite{burago2001course}, we allow a metric $d$ throughout to satisfy $d(x,y)=\infty$ for some pairs $(x,y)$. When we prefer to work with an ordinary bounded metric, we may replace $d$ by
    \begin{align*}
        \bar{d}(x,y) = \min\{d(x,y),1\}.
    \end{align*}
    The effect of this truncation is simple:
    \begin{enumerate}[(i)]
        \item Only the numerical values of large point-to-point distances change. In particular, distances that were infinite become equal to $1$, and supremum distances become automatically bounded. The corresponding Hausdorff distance\index{Hausdorff distance}s (Definition~\ref{defn:Hausdorff-distance}; see also below) between non-empty sets become bounded, while the convention $d_H(A,\emptyset)=d_H(\emptyset,A)=\infty$ for $A\neq\emptyset$ remains unchanged.
        \item For every $\varepsilon \in (0,1)$, the $d$-ball and the $\bar{d}$-ball of radius $\varepsilon$ coincide, so $d$ and $\bar{d}$ induce the same topology and therefore the same Borel $\sigma$-algebra.
        \item Convergence, continuity, Cauchy sequence\index{Cauchy sequence}s, completeness, separability, and hence every notion built from these, such as Polishness, do not change either.
    \end{enumerate}
    For example, a $d$-Cauchy sequence is eventually contained in a ball of radius less than $1$, where $d$ and $\bar{d}$ agree on all tail comparisons; the same observation transfers limits and completeness in both directions. Thus, whenever a statement is most naturally phrased for ordinary bounded metrics\index{metrics}, one may pass to $\bar{d}$ without changing any of the analytic or topological content relevant here.

    The finite-distance component of $x\in X$ is the set $\{y\in X\mid d(x,y)<\infty\}$. By the triangle inequality, these components partition $X$, and $d$ is finite on each of them. Each component is open, since it contains every point at distance less than $1$ from one of its points, and closed, since its complement is a union of components. From some index on, the terms of a Cauchy sequence have pairwise distances below $1$, so its tail lies in a single component, and a completeness proof reduces to the ordinary argument within that component. The same reduction applies to any partition of $X$ into pieces at mutual distance at least $1$, and the completeness proofs for disjoint unions (Proposition~\ref{prop:disjoint-union-metric-properties}), labelled finite sets (Theorem~\ref{thm:labelled-properties}), tuples (Theorem~\ref{thm:tuple-space-properties}), and permuted tuples (Theorem~\ref{thm:permuted-tuple-hausdorff-metric-complete-separable}) follow this pattern.

\label{defn:pseudometric}\index{pseudometric}
    Let $X$ be a set, and let $d:X \times X \to [0,\infty]$ be a function such that for every $x,x^\prime,x^\ast \in X$:
    \begin{enumerate}[(i)]
        \item $d(x,x) = 0$; \label{eq:pseudometric-1}
        \item $d(x,x^\prime) = d(x^\prime,x)$; \label{eq:pseudometric-2}
        \item $d(x,x^\prime) \leq d(x,x^\ast) + d(x^\ast,x^\prime)$. \label{eq:pseudometric-3}
    \end{enumerate}
    Then $d$ is called a pseudometric, and $(X,d)$ is called a pseudometric space.

\label{cor:pseudometric-metric-relation}
    Let $X$ be a set and let $d,\rho:X \times X \to [0,\infty]$ be a metric and a pseudometric on $X$, respectively. Then:
    \begin{enumerate}[(i)]
        \item $(X,d)$ is a pseudometric space;
        \item $(X,\rho)$ is a metric space if and only if $\rho(x,x^\prime) = 0$ implies $x = x^\prime$ for all $x,x^\prime \in X$.
    \end{enumerate}

steps.text:
For the second condition, let $x \in B_{\varepsilon^\prime}(x^\prime) \cap B_{\varepsilon^\ast}(x^\ast)$. Then
    \begin{align*}
        d(x^\prime,x) < \varepsilon^\prime
        \qquad \text{and} \qquad
        d(x^\ast,x) < \varepsilon^\ast.
    \end{align*}
    Hence
    \begin{align*}
        r = \frac{1}{2}\min\{\varepsilon^\prime - d(x^\prime,x),\ \varepsilon^\ast - d(x^\ast,x)\}
    \end{align*}
    is strictly positive. If $y \in B_r(x)$, then the triangle inequality gives
    \begin{align*}
        d(x^\prime,y) \leq d(x^\prime,x) + d(x,y) < d(x^\prime,x) + r \leq \varepsilon^\prime,
    \end{align*}
    and similarly $d(x^\ast,y) < \varepsilon^\ast$. Therefore
    \begin{align*}
        B_r(x) \subseteq B_{\varepsilon^\prime}(x^\prime) \cap B_{\varepsilon^\ast}(x^\ast),
    \end{align*}
    which proves the second base condition.

proof.text:
We must show that $\mathcal{B}_d$ satisfies the two defining conditions (i) and (ii) of a topological base. For each $x \in X$ and any $\varepsilon > 0$, we have $d(x,x)=0<\varepsilon$ and hence $x \in B_\varepsilon(x)$, so the first base condition holds.

    For the second condition, let $x \in B_{\varepsilon^\prime}(x^\prime) \cap B_{\varepsilon^\ast}(x^\ast)$. Then
    \begin{align*}
        d(x^\prime,x) < \varepsilon^\prime
        \qquad \text{and} \qquad
        d(x^\ast,x) < \varepsilon^\ast.
    \end{align*}
    Hence
    \begin{align*}
        r = \frac{1}{2}\min\{\varepsilon^\prime - d(x^\prime,x),\ \varepsilon^\ast - d(x^\ast,x)\}
    \end{align*}
    is strictly positive. If $y \in B_r(x)$, then the triangle inequality gives
    \begin{align*}
        d(x^\prime,y) \leq d(x^\prime,x) + d(x,y) < d(x^\prime,x) + r \leq \varepsilon^\prime,
    \end{align*}
    and similarly $d(x^\ast,y) < \varepsilon^\ast$. Therefore
    \begin{align*}
        B_r(x) \subseteq B_{\varepsilon^\prime}(x^\prime) \cap B_{\varepsilon^\ast}(x^\ast),
    \end{align*}
    which proves the second base condition.

results.statement:
\label{prop:topology-extended-pseudometric}
    Let $(X,d)$ be a pseudometric space. For each $x \in X$ and $\varepsilon > 0$, define the open ball
    \begin{align*}
        B_\varepsilon(x) = \{x^\prime \in X \mid d(x,x^\prime) < \varepsilon\}.
    \end{align*}
    Then the family
    \begin{align*}
        \mathcal{B}_d = \{B_\varepsilon(x) \mid x \in X,\ \varepsilon > 0\}
    \end{align*}
    is a topological base. We call $\mathcal{T}_{\mathcal{B}_d}$ the topology induced by $d$.

\label{defn:distance-to-set}\index{distance!point to set}
    Let $(X,d)$ be a pseudometric space, let $x\in X$, and let $B \subseteq X$. We define
    \begin{align*}
        d(x,B) = \inf_{x^\prime \in B} d(x,x^\prime),
    \end{align*}
    with the convention that $d(x,\emptyset) = \infty$.

Let $(X,d)$ be a pseudometric space. For $A,B\subseteq X$, define
    \begin{align*}
        d_H(A,B)
        =
        \max\left\{
            \adjustlimits\sup_{a\in A} d(a,B),
            \adjustlimits\sup_{b\in B} d(b,A)
        \right\},
    \end{align*}
    with $d(x,\emptyset)=\infty$ and $\sup\emptyset=0$. Thus $d_H(\emptyset,\emptyset)=0$, while $d_H(A,\emptyset)=d_H(\emptyset,A)=\infty$ for $A\neq\emptyset$.

steps.text:
First, suppose that $d(x,x^\ast)=0$ implies $x=x^\ast$. Let $x \neq x^\ast$. Then $d(x,x^\ast)>0$. Set $\varepsilon = \frac{1}{2}\min\{d(x,x^\ast),1\}$, which is a finite positive real number. We claim that
    \begin{align*}
        B_\varepsilon(x) \cap B_\varepsilon(x^\ast) = \emptyset.
    \end{align*}
    Indeed, if $y$ belonged to the intersection, then the triangle inequality would give
    \begin{align*}
        d(x,x^\ast) \leq d(x,y) + d(y,x^\ast) < 2\varepsilon = \min\{d(x,x^\ast),1\} \leq d(x,x^\ast),
    \end{align*}
    which is impossible. Hence the induced topology is Hausdorff.

proof.text:
First, suppose that $d(x,x^\ast)=0$ implies $x=x^\ast$. Let $x \neq x^\ast$. Then $d(x,x^\ast)>0$. Set $\varepsilon = \frac{1}{2}\min\{d(x,x^\ast),1\}$, which is a finite positive real number. We claim that
    \begin{align*}
        B_\varepsilon(x) \cap B_\varepsilon(x^\ast) = \emptyset.
    \end{align*}
    Indeed, if $y$ belonged to the intersection, then the triangle inequality would give
    \begin{align*}
        d(x,x^\ast) \leq d(x,y) + d(y,x^\ast) < 2\varepsilon = \min\{d(x,x^\ast),1\} \leq d(x,x^\ast),
    \end{align*}
    which is impossible. Hence the induced topology is Hausdorff.

    Conversely, suppose there exist distinct points $x,x^\ast \in X$ with $d(x,x^\ast)=0$. Let $O$ be any open neighbourhood of $x$. Since $O$ is open, the centred-ball characterisation following Proposition~\ref{prop:topology-extended-pseudometric} shows that there exists $\varepsilon > 0$ such that $B_\varepsilon(x) \subseteq O$. But $d(x,x^\ast)=0$ implies $x^\ast \in B_\varepsilon(x)$, hence $x^\ast \in O$. By symmetry, every open neighbourhood of $x^\ast$ also contains $x$. Therefore no two open neighbourhoods of $x$ and $x^\ast$ can be disjoint, so the topology is not Hausdorff.

results.statement:
Let $(X,d)$ be a pseudometric space, and let $(X,\mathcal{T}_{\mathcal{B}_d})$ be the topological space induced by $d$. Then $(X,\mathcal{T}_{\mathcal{B}_d})$ is Hausdorff if and only if
    \begin{align*}
        d(x,x^\ast) = 0 \implies x = x^\ast
        \qquad \text{for all } x,x^\ast \in X.
    \end{align*}

steps.text:
We must show that $\sim$ is an equivalence relation, that $d_\sim$ is independent of the chosen representatives, and that $(X_\sim,d_\sim)$ satisfies the metric axioms. First, reflexivity and symmetry of $\sim$ follow immediately from the pseudometric axioms~(\ref{eq:pseudometric-1}) and~(\ref{eq:pseudometric-2}), while $x\sim y$ and $y\sim z$ imply $0\leq d(x,z)\leq d(x,y)+d(y,z)=0$, which proves transitivity. Next, if $x\sim y$ and $x^\ast\sim y^\ast$, then the triangle inequality gives
    \begin{align*}
        d(x,x^\ast)\leq d(x,y)+d(y,y^\ast)+d(y^\ast,x^\ast)=d(y,y^\ast),
    \end{align*}
    and exchanging the two representative pairs gives the reverse inequality $d(y,y^\ast)\leq d(x,x^\ast)$. Hence $d(x,x^\ast)=d(y,y^\ast)$, so $d_\sim$ is well-defined. Finally, symmetry and the triangle inequality descend directly from $d$, and $d_\sim([x],[x^\ast])=0$ implies $x\sim x^\ast$ and hence $[x]=[x^\ast]$ by definition of the quotient, as desired.

proof.text:
We must show that $\sim$ is an equivalence relation, that $d_\sim$ is independent of the chosen representatives, and that $(X_\sim,d_\sim)$ satisfies the metric axioms. First, reflexivity and symmetry of $\sim$ follow immediately from the pseudometric axioms~(\ref{eq:pseudometric-1}) and~(\ref{eq:pseudometric-2}), while $x\sim y$ and $y\sim z$ imply $0\leq d(x,z)\leq d(x,y)+d(y,z)=0$, which proves transitivity. Next, if $x\sim y$ and $x^\ast\sim y^\ast$, then the triangle inequality gives
    \begin{align*}
        d(x,x^\ast)\leq d(x,y)+d(y,y^\ast)+d(y^\ast,x^\ast)=d(y,y^\ast),
    \end{align*}
    and exchanging the two representative pairs gives the reverse inequality $d(y,y^\ast)\leq d(x,x^\ast)$. Hence $d(x,x^\ast)=d(y,y^\ast)$, so $d_\sim$ is well-defined. Finally, symmetry and the triangle inequality descend directly from $d$, and $d_\sim([x],[x^\ast])=0$ implies $x\sim x^\ast$ and hence $[x]=[x^\ast]$ by definition of the quotient, as desired.

results.statement:
\label{prop:pseudometric-quotient}
    Let $(X,d)$ be a pseudometric space, and define the relation $\sim$ on $X$ by $x \sim x^\ast$ if and only if $d(x,x^\ast)=0$. Then $\sim$ is an equivalence relation on $X$, and the map $d_\sim\colon X_\sim\times X_\sim\to[0,\infty]$ given by
    \begin{align*}
        d_\sim([x],[x^\ast]) = d(x,x^\ast)
    \end{align*}
    is well-defined and defines a metric on the quotient set $X_\sim=X/{\sim}$.

\label{defn:Cauchy-sequence}
    Let $(X,d)$ be a metric space, and let $(x_n)_{n \in \mathbb{N}}$ be a sequence in $X$. The sequence is called Cauchy if for every $\varepsilon > 0$ there exists $N \in \mathbb{N}$ such that
    \begin{align*}
        m,n \geq N \implies d(x_m,x_n) < \varepsilon.
    \end{align*}

\label{defn:convergent-sequence}\index{convergent sequence}
    Let $(X,d)$ be a metric space and let $(x_n)_{n \in \mathbb{N}}$ be a sequence in $X$. We say that $(x_n)_{n \in \mathbb{N}}$ converges if there exists $x \in X$ such that for every $\varepsilon > 0$ there exists $N \in \mathbb{N}$ for which
    \begin{align*}
        n \geq N \implies d(x_n,x) < \varepsilon.
    \end{align*}
    In that case, $x$ is called the limit of $(x_n)_{n \in \mathbb{N}}$, and we write $x_n \to x$ in $(X,d)$, equivalently $d(x_n,x)\to 0$, or simply $\lim_{n \to \infty} x_n = x$ if the metric is clear from context.

\label{defn:separable}\index{separable metric space}
    Let $(X,d)$ be a metric space. Then $(X,d)$ is called separable if there exists a countable subset $D \subseteq X$ such that for every $x \in X$ and every $\varepsilon > 0$ there exists $y \in D$ with
    \begin{align*}
        d(x,y) < \varepsilon.
    \end{align*}

\label{prop:finite-metric-products}
    Let $n\in\mathbb{N}$ and let $(X_1,d_1),\dots,(X_n,d_n)$ be pseudometric spaces. Then
    \begin{align*}
        (\bm{x},\bm{x}^\prime)\mapsto\max_{i\in\{1,\dots,n\}}d_i(\bm{x}(i),\bm{x}^\prime(i)),\qquad \bm{x},\bm{x}^\prime\in\prod_{i=1}^n X_i,
    \end{align*}
    is a pseudometric on $\prod_{i=1}^n X_i$, called the maximum metric\index{product metric}, and it is a metric if every $d_i$ is. If every $d_i$ is a metric, then the maximum metric induces the product topology of the topologies induced by $d_1,\dots,d_n$, and the product is separable if every factor is separable and complete if every factor is complete.

Let $(X,d)$ and $(Y,\rho)$ be metric spaces. A function $f:X \to Y$ is called continuous if for every $x_0 \in X$ and every $\varepsilon > 0$ there exists $\delta > 0$ such that, for every $x\in X$,
    \begin{align*}
        d(x,x_0) < \delta \implies \rho(f(x),f(x_0)) < \varepsilon.
    \end{align*}

steps.text:
We must show that $d_\infty$ is a metric on $C([a,b];X)$ and that $(C([a,b];X),d_\infty)$ inherits completeness and separability from $(X,d)$. The metric axioms pass from $d$ to $d_\infty$ pointwise in $t$. For the triangle inequality, let $f,g,h\in C([a,b];X)$; then
    \begin{align*}
        d(f(t),h(t))\leq d(f(t),g(t))+d(g(t),h(t))\leq d_\infty(f,g)+d_\infty(g,h)
    \end{align*}
    for every $t\in[a,b]$, and taking the supremum over $t$ gives $d_\infty(f,h)\leq d_\infty(f,g)+d_\infty(g,h)$.

results.statement:
\label{prop:spc-continuous}\index{spaces of continuous functions}
    Let $a,b \in \mathbb{R}$ with $a < b$, and let $(X,d)$ be a metric space. Then
    \begin{align*}
        C([a,b];X) = \{f:[a,b] \to X \mid f \text{ is continuous}\}
    \end{align*}
    endowed with the metric
    \begin{align*}
        d_\infty(f,g) = \sup_{t \in [a,b]} d(f(t),g(t))
    \end{align*}
    is a metric space. Moreover, $(C([a,b];X),d_\infty)$ is complete and separable if $(X,d)$ is.

Let $a,b \in \mathbb{R}$ with $a < b$, let $(X,d)$ be a metric space, and let $f \in C([a,b];X)$. Then the graph
    \begin{align*}
        \Gamma(f) = \{(t,f(t)) \mid t \in [a,b]\}
    \end{align*}
    is compact in $[a,b] \times X$ under the metric
    \begin{align*}
        \rho((s,x),(t,y)) = |s-t| + d(x,y).
    \end{align*}
    In particular, $\Gamma(f)$ is closed and bounded.

\index{cadlag functions@c\`adl\`ag functions}\index{caglad functions@c\`agl\`ad functions}
    Let $a,b \in \mathbb{R}$ with $a < b$, let $(X,d)$ be a metric space, and let $f:[a,b] \to X$ be a function. We say that:
    \begin{enumerate}[(i)]
        \item $f$ is right-continuous if for every $t_0 \in [a,b)$ and every $\varepsilon > 0$ there exists $\delta > 0$ such that
        \begin{align*}
            t \in (t_0,\min\{t_0+\delta,b\}) \implies d(f(t),f(t_0)) < \varepsilon;
        \end{align*}
        \item $f$ is left-continuous if for every $t_0 \in (a,b]$ and every $\varepsilon > 0$ there exists $\delta > 0$ such that
        \begin{align*}
            t \in (\max\{a,t_0-\delta\},t_0) \implies d(f(t),f(t_0)) < \varepsilon;
        \end{align*}
        \item $f$ has right limits if for every $t_0 \in [a,b)$ there exists $R \in X$ such that for every $\varepsilon > 0$ there exists $\delta > 0$ with
        \begin{align*}
            t \in (t_0,\min\{t_0+\delta,b\}) \implies d(f(t),R) < \varepsilon;
        \end{align*}
        \item $f$ has left limits if for every $t_0 \in (a,b]$ there exists $L \in X$ such that for every $\varepsilon > 0$ there exists $\delta > 0$ with
        \begin{align*}
            t \in (\max\{a,t_0-\delta\},t_0) \implies d(f(t),L) < \varepsilon.
        \end{align*}
    \end{enumerate}
    We call $f$ càdlàg if it is right-continuous with left limits, and we write $f \in D^+([a,b];X)$. We call $f$ càglàd if it is left-continuous with right limits, and we write $f \in D^-([a,b];X)$.

\index{increasing interval bijections}
    Let $a,b \in \mathbb{R}$ with $a < b$. Define
    \begin{align*}
        \Lambda([a,b]) = \{\lambda:[a,b] \to [a,b] \mid \lambda \text{ is strictly increasing and bijective}\},
    \end{align*}
    and define $\lVert\cdot\rVert_\circ:\Lambda([a,b]) \to [0,\infty]$ by
    \begin{align*}
        \lVert\lambda\rVert_\circ
        = \sup_{\substack{s,t \in [a,b]\\ s < t}}
        \left|\log\left(\frac{\lambda(t)-\lambda(s)}{t-s}\right)\right|.
    \end{align*}

{billingsley2013convergence}}] \label{prop:skorokhod-metric}
    Let $a,b \in \mathbb{R}$ with $a < b$, let $(X,d)$ be a metric space, and let $D([a,b];X)$ denote either $D^+([a,b];X)$ or $D^-([a,b];X)$. Define
    \begin{align*}
        d_\circ(f,g)
        = \inf_{\lambda \in \Lambda([a,b])}
        \max\left\{\lVert\lambda\rVert_\circ,\ d_\infty(f,g \circ \lambda)\right\},
    \end{align*}
    where $d_\infty$ is the supremum metric induced by $d$. Then $d_\circ$ is a metric on $D([a,b];X)$. Moreover, if $(X,d)$ is complete and separable, then so is $(D([a,b];X),d_\circ)$.

{billingsley2013convergence}}]
    Let $a,b \in \mathbb{R}$ with $a < b$, let $(X,d)$ be a metric space, and let $D([a,b];X)$ denote either $D^+([a,b];X)$ or $D^-([a,b];X)$. A sequence $(f_n)_{n \in \mathbb{N}} \subseteq D([a,b];X)$ converges to $f \in D([a,b];X)$ in $(D([a,b];X),d_\circ)$ if and only if there exists a sequence $(\lambda_n)_{n \in \mathbb{N}} \subseteq \Lambda([a,b])$ such that
    \begin{align*}
        \lim_{n \to \infty} \sup_{t \in [a,b]} |\lambda_n(t)-t| = 0
    \end{align*}
    and
    \begin{align*}
        \lim_{n \to \infty} \sup_{t \in [a,b]} d(f_n(\lambda_n(t)),f(t)) = 0.
    \end{align*}

\label{defn:norm}\index{norm}
    Let $(V,+,\cdot)$ be a real vector space, and let $\lVert\cdot\rVert:V \to [0,\infty)$ be a function such that
    \begin{enumerate}[(i)]
        \item $\lVert v\rVert = 0$ if and only if $v$ is the zero vector of $V$;
        \item $\lVert a \cdot v\rVert = |a|\,\lVert v\rVert$ for all $a \in \mathbb{R}$ and $v \in V$;
        \item $\lVert u + v\rVert \leq \lVert u\rVert + \lVert v\rVert$ for all $u,v \in V$.
    \end{enumerate}
    Then $\lVert\cdot\rVert$ is called a norm, and $(V,\lVert\cdot\rVert)$ is called a normed space.

\label{defn:inner-product}\index{inner product}
    Let $(V,+,\cdot)$ be a real vector space, and let $\langle \cdot,\cdot \rangle:V \times V \to \mathbb{R}$ be a function such that
    \begin{enumerate}[(i)]
        \item $\langle u,v \rangle = \langle v,u \rangle$ for all $u,v \in V$;
        \item $\langle a \cdot u + b \cdot v,w \rangle = a\langle u,w \rangle + b\langle v,w \rangle$ for all $u,v,w \in V$ and $a,b \in \mathbb{R}$;
        \item $\langle v,v \rangle \geq 0$ for all $v \in V$;
        \item $\langle v,v \rangle = 0$ if and only if $v$ is the zero vector of $V$.
    \end{enumerate}
    Then $\langle \cdot,\cdot \rangle$ is called an inner product, and $(V,\langle \cdot,\cdot \rangle)$ is called an inner product space.

steps.text:
We must show that $\lVert\cdot\rVert$ satisfies conditions (i)--(iii) of Definition~\ref{defn:norm}. Conditions (i) and (ii) follow directly from conditions (iv) and (ii) of Definition~\ref{defn:inner-product}. For the triangle inequality (iii), the Cauchy--Schwarz inequality $|\langle u,v\rangle|\leq\lVert u\rVert\,\lVert v\rVert$ \citep[Lemma~3.2-1]{kreyszig1978introductory} yields
    \begin{align*}
        \lVert u+v\rVert^2=\lVert u\rVert^2+2\langle u,v\rangle+\lVert v\rVert^2\leq(\lVert u\rVert+\lVert v\rVert)^2,
    \end{align*}
    and taking square roots proves $\lVert u+v\rVert\leq\lVert u\rVert+\lVert v\rVert$, as desired.

proof.text:
We must show that $\lVert\cdot\rVert$ satisfies conditions (i)--(iii) of Definition~\ref{defn:norm}. Conditions (i) and (ii) follow directly from conditions (iv) and (ii) of Definition~\ref{defn:inner-product}. For the triangle inequality (iii), the Cauchy--Schwarz inequality $|\langle u,v\rangle|\leq\lVert u\rVert\,\lVert v\rVert$ \citep[Lemma~3.2-1]{kreyszig1978introductory} yields
    \begin{align*}
        \lVert u+v\rVert^2=\lVert u\rVert^2+2\langle u,v\rangle+\lVert v\rVert^2\leq(\lVert u\rVert+\lVert v\rVert)^2,
    \end{align*}
    and taking square roots proves $\lVert u+v\rVert\leq\lVert u\rVert+\lVert v\rVert$, as desired.

results.statement:
\label{prop:norm-induced-by-inner-product}
    Let $(V,\langle \cdot,\cdot \rangle)$ be an inner product space, and define $\lVert\cdot\rVert:V \to [0,\infty)$ by
    \begin{align*}
        \lVert v\rVert = \sqrt{\langle v,v \rangle},
    \end{align*}
    for all $v \in V$. Then $\lVert\cdot\rVert$ is a norm on $V$. We call it the norm induced by the inner product $\langle \cdot,\cdot \rangle$.

\label{prop:metric-induced-by-norm}
    Let $(V,\lVert\cdot\rVert)$ be a normed space, and define $d:V \times V \to [0,\infty)$ by
    \begin{align*}
        d(u,v) = \lVert u-v\rVert.
    \end{align*}
    Then $(V,d)$ is a metric space. We call $d$ the metric induced by the norm $\lVert\cdot\rVert$.

\label{cor:metric-induced-by-inner-product}
    Let $(V,\langle \cdot,\cdot \rangle)$ be an inner product space, and define $d:V \times V \to [0,\infty)$ by
    \begin{align*}
        d(u,v) = \sqrt{\langle u-v,u-v \rangle}.
    \end{align*}
    Then $(V,d)$ is a metric space, and we call $d$ the metric induced by the inner product $\langle \cdot,\cdot \rangle$.

\label{defn:banach-hilbert-separable}
    Let $(V,+,\cdot)$ be a real vector space. Then:
    \begin{enumerate}[(i)]
        \item a normed space\index{normed spaces} $(V,\lVert\cdot\rVert)$ is called a Banach space if the metric induced by $\lVert\cdot\rVert$ is complete;
        \item an inner product space $(V,\langle \cdot,\cdot \rangle)$ is called a Hilbert space if the metric induced by $\langle \cdot,\cdot \rangle$ is complete;
        \item a normed or inner product space is called separable if the induced metric space is separable.
    \end{enumerate}

steps.text:
We must show that $\langle\cdot,\cdot\rangle$ is an inner product on $\prod_{i\in I}V_i$ whose induced metric is complete, and separable when every factor is separable. The inner-product axioms hold in each coordinate and hence for the finite sum. For $I=\emptyset$, the zero space is trivially complete and separable. For $I\neq\emptyset$, the induced norm satisfies
    \begin{align*}
        \max_{i\in I}\lVert v_i\rVert_i\leq\lVert v\rVert\leq\lvert I\rvert^{1/2}\max_{i\in I}\lVert v_i\rVert_i,
    \end{align*}
    so its induced metric has the same open sets and the same Cauchy and convergent sequences as the maximum metric of Proposition~\ref{prop:finite-metric-products}. Proposition~\ref{prop:finite-metric-products} therefore yields the product topology, completeness, and separability, as desired.

proof.text:
We must show that $\langle\cdot,\cdot\rangle$ is an inner product on $\prod_{i\in I}V_i$ whose induced metric is complete, and separable when every factor is separable. The inner-product axioms hold in each coordinate and hence for the finite sum. For $I=\emptyset$, the zero space is trivially complete and separable. For $I\neq\emptyset$, the induced norm satisfies
    \begin{align*}
        \max_{i\in I}\lVert v_i\rVert_i\leq\lVert v\rVert\leq\lvert I\rvert^{1/2}\max_{i\in I}\lVert v_i\rVert_i,
    \end{align*}
    so its induced metric has the same open sets and the same Cauchy and convergent sequences as the maximum metric of Proposition~\ref{prop:finite-metric-products}. Proposition~\ref{prop:finite-metric-products} therefore yields the product topology, completeness, and separability, as desired.

results.statement:
\label{prop:finite-products}
    Let $I$ be a finite index set and let $(V_i,\langle\cdot,\cdot\rangle_i)_{i\in I}$ be real Hilbert spaces, where for $I=\emptyset$ the product $\prod_{i\in I}V_i=\{\emptyset\}$ is the zero space. Then $\prod_{i\in I}V_i$ is a Hilbert space under
    \begin{align*}
        \langle u,v\rangle=\sum_{i\in I}\langle u_i,v_i\rangle_i,
    \end{align*}
    and it is separable if every factor is separable.

\label{defn:bounded-linear-operator}\index{bounded linear operator}
    Let $(V,\lVert\cdot\rVert_V)$ and $(W,\lVert\cdot\rVert_W)$ be normed spaces, and let $T:V \to W$ be linear. We say that $T$ is a bounded linear operator if there exists a constant $C \in [0,\infty)$ such that
    \begin{align*}
        \lVert Tv\rVert_W \leq C \lVert v\rVert_V
    \end{align*}
    for all $v \in V$.
    We denote the vector space of bounded linear operators from $V$ to $W$ by $\mathcal{L}(V,W)$.

\label{defn:operator-norm}\index{operator norm}
    Let $(V,\lVert\cdot\rVert_V)$ and $(W,\lVert\cdot\rVert_W)$ be normed spaces, and let $T:V \to W$ be a bounded linear operator. We define the operator norm of $T$ by
    \begin{align*}
        \lVert T\rVert_{\mathrm{op}} = \sup_{\substack{v \in V\\ \lVert v\rVert_V \leq 1}} \lVert Tv\rVert_W.
    \end{align*}
    If $V \neq \{0\}$, then equivalently
    \begin{align*}
        \lVert T\rVert_{\mathrm{op}} = \sup_{\substack{v \in V\\ \lVert v\rVert_V = 1}} \lVert Tv\rVert_W.
    \end{align*}

\label{defn:dual-space}\index{dual space}
    Let $(V,\lVert\cdot\rVert)$ be a normed space. The dual space of $V$ is the vector space
    \begin{align*}
        V^\ast = \mathcal{L}(V,\mathbb{R})
    \end{align*}
    of bounded linear functionals from $V$ into $\mathbb{R}$.

\label{thm:riesz-representation}\index{Riesz representation theorem}
    Let $(\mathcal{H},\langle \cdot, \cdot \rangle)$ be a real Hilbert space. Then for every $\varphi \in \mathcal{H}^\ast$ there exists a unique element $h_\varphi \in \mathcal{H}$ such that
    \begin{align*}
        \varphi(u) = \langle u, h_\varphi \rangle,
    \end{align*}
    for all $u \in \mathcal{H}$. Moreover,
    \begin{align*}
        \lVert\varphi\rVert_{\mathrm{op}} = \lVert h_\varphi\rVert.
    \end{align*}

\label{defn:frechet-derivative}
    Let $\mathcal{H}$ and $\mathcal{G}$ be real Hilbert spaces. Let $f: \mathcal{H} \to \mathcal{G}$ be a function. The function $f$ is said to be \emph{Fréchet} differentiable at $x \in \mathcal{H}$ if there exists a bounded linear operator $A \in \mathcal{L}(\mathcal{H}, \mathcal{G})$ such that
    \begin{align*}
        \lim_{\lVert h\rVert\to 0} \frac{\lVert f(x + h) - f(x) - A h\rVert_{\mathcal{G}}}{\lVert h\rVert_{\mathcal{H}}}   = 0.
    \end{align*}
    Moreover, we call $A$ the Fréchet derivative of $f$ at $x$ and we write $D f(x)=A$. If $f$ is differentiable at every $x \in \mathcal{H}$, we write
    \begin{align*}
        Df &: \mathcal{H} \to \mathcal{L}(\mathcal{H}, \mathcal{G})\\
        x &\mapsto D f(x).
    \end{align*}

steps.text:
We must show that for every $\hat{y}\in\mathcal{H}$, the linear functional $A\colon\mathcal{H}\to\mathbb{R}$ defined by $Ah=2\langle\hat{y}-y,h\rangle$ belongs to $\mathcal{H}^\ast$ and satisfies Definition~\ref{defn:frechet-derivative}. For any $\hat{y},h\in\mathcal{H}$, expanding the squared norm yields
\begin{align*}
    \mathfrak{f}(\hat{y} + h) - \mathfrak{f}(\hat{y}) = \lVert y - \hat{y} - h\rVert^2 - \lVert y - \hat{y}\rVert^2 = 2\langle \hat{y} - y,h\rangle + \lVert h\rVert^2.
\end{align*}
The map $Ah=2\langle \hat{y} - y, h\rangle$ is linear in $h$ and bounded by the Cauchy--Schwarz inequality ($\lvert Ah\rvert\leq 2\lVert\hat{y}-y\rVert\,\lVert h\rVert$), and for $h\neq 0_{\mathcal{H}}$,
\begin{align*}
    \frac{\lvert\mathfrak{f}(\hat{y}+h) - \mathfrak{f}(\hat{y}) - Ah\rvert}{\lVert h\rVert} = \lVert h\rVert \to 0 \quad\text{as } \lVert h\rVert\to 0.
\end{align*}
Consequently, $D\mathfrak{f}(\hat{y})=A$, whose Riesz representer is $\nabla\mathfrak{f}(\hat{y})=2(\hat{y}-y)$, as desired.

proof.text:
We must show that for every $\hat{y}\in\mathcal{H}$, the linear functional $A\colon\mathcal{H}\to\mathbb{R}$ defined by $Ah=2\langle\hat{y}-y,h\rangle$ belongs to $\mathcal{H}^\ast$ and satisfies Definition~\ref{defn:frechet-derivative}. For any $\hat{y},h\in\mathcal{H}$, expanding the squared norm yields
