\end{align*}
Consequently, $D\mathfrak{f}(\hat{y})=A$, whose Riesz representer is $\nabla\mathfrak{f}(\hat{y})=2(\hat{y}-y)$, as desired.

results.statement:
\label{defn:measurable-space}\index{measurable space}\index{sigma-algebra@$\sigma$-algebra}
    Let $\Omega$ be a set and let $\mathcal{F} \subseteq \wp(\Omega)$ satisfy
    \begin{enumerate}[(i)]
        \item $\Omega \in \mathcal{F}$;
        \item $E \in \mathcal{F}$ implies $E^{\mathtt{C}} \in \mathcal{F}$;
        \item if $(E_n)_{n \in \mathbb{N}} \subseteq \mathcal{F}$, then $\bigcup_{n \in \mathbb{N}} E_n \in \mathcal{F}$.
    \end{enumerate}
    Then $\mathcal{F}$ is called a $\sigma$-algebra and $(\Omega,\mathcal{F})$ is called a measurable space.

\label{defn:measure}\index{probability measure}
    Let $(\Omega,\mathcal{F})$ be a measurable space. A map $\mu:\mathcal{F} \to [0,\infty]$ is called a measure if
    \begin{enumerate}[(i)]
        \item $\mu(\emptyset)=0$;
        \item for every pairwise disjoint sequence $(E_n)_{n \in \mathbb{N}} \subseteq \mathcal{F}$,
        \begin{align*}
            \mu\left(\bigcup_{n \in \mathbb{N}} E_n\right) = \sum_{n \in \mathbb{N}} \mu(E_n).
        \end{align*}
    \end{enumerate}
    Then $(\Omega,\mathcal{F},\mu)$ is called a measure space. If in addition $\mu(\Omega)=1$, then $\mu$ is called a probability measure and $(\Omega,\mathcal{F},\mu)$ is called a probability space.

\label{defn:atom-diffuse}\index{diffuse measure}
    Let $(\Omega,\mathcal{F},\mu)$ be a measure space. A set $A \in \mathcal{F}$ is called an atom of $\mu$ if $\mu(A)>0$ and for every $E \in \mathcal{F}$,
    \begin{align*}
        \min\{\mu(A \cap E),\mu(A \setminus E)\}=0.
    \end{align*}
    The measure $\mu$ is called purely atomic if every $E \in \mathcal{F}$ with $\mu(E)>0$ contains an atom. It is called diffuse if it has no atoms.

\label{thm:atomic}
    Let $(\Omega,\mathcal{F},\mu)$ be a $\sigma$-finite measure space. Then there exist unique measures $\alpha$ and $\beta$ on $(\Omega,\mathcal{F})$ such that
    \begin{align*}
        \mu = \alpha + \beta,
    \end{align*}
    where $\alpha$ is diffuse and $\beta$ is purely atomic. If moreover $\Omega$ is a Polish space and $\mathcal{F} = \mathcal{B}(\Omega)$, then there is an index set $I\subseteq\mathbb{N}$, possibly empty, such that
    \begin{align*}
        \beta = \sum_{n\in I} a_n\delta_{x_n},
    \end{align*}
    with $a_n=\beta(\{x_n\})>0$ and pairwise distinct points $x_n$, where every singleton $\{x_n\}$ is a point atom of $\beta$. When $I=\emptyset$, the sum denotes the zero measure.

\label{defn:measurable-function}\index{measurable function}
    Let $(\Omega,\mathcal{F})$ and $(S,\mathcal{S})$ be measurable spaces. A function $f:\Omega \to S$ is called $\mathcal{F}/\mathcal{S}$-measurable if
    \begin{align*}
        f^{-1}(B) \in \mathcal{F}
    \end{align*}
    for all $B \in \mathcal{S}$. If $(\Omega,\mathcal{F},\mathbb{P})$ is a probability space, then such a measurable map is called a random element, and a random variable when it is real-valued.

\label{defn:trace-sigma-algebra}\index{trace sigma-algebra@trace $\sigma$-algebra}
    Let $(\Omega,\mathcal{F})$ be a measurable space and let $E \subseteq \Omega$. Then
    \begin{align*}
        \mathcal{F}\restriction_E = \{F \cap E \mid F \in \mathcal{F}\}
    \end{align*}
    is called the trace $\sigma$-algebra on $E$.

steps.text:
We must show that $f^{-1}(B)\in\mathcal{F}$ for all $B\in\mathcal{S}$ if and only if $(f\restriction_{E_n})^{-1}(B)\in\mathcal{F}\restriction_{E_n}$ for all $n\in\mathbb{N}$ and $B\in\mathcal{S}$. If $f$ is $\mathcal{F}/\mathcal{S}$-measurable and $B \in \mathcal{S}$, then
    \begin{align*}
        (f\restriction_{E_n})^{-1}(B)=f^{-1}(B)\cap E_n \in \mathcal{F}\restriction_{E_n},
    \end{align*}
    so each restriction is measurable.

Conversely, suppose each $f\restriction_{E_n}$ is measurable and let $B \in \mathcal{S}$. For each $n$, there exists $A_n \in \mathcal{F}$ such that
    \begin{align*}
        (f\restriction_{E_n})^{-1}(B)=A_n \cap E_n.
    \end{align*}
    Hence
    \begin{align*}
        f^{-1}(B)
        = f^{-1}(B) \cap \Omega
        = \bigcup_{n \in \mathbb{N}} \left(f^{-1}(B) \cap E_n\right)
        = \bigcup_{n \in \mathbb{N}} (A_n \cap E_n) \in \mathcal{F},
    \end{align*}
    and therefore $f$ is measurable.

proof.text:
We must show that $f^{-1}(B)\in\mathcal{F}$ for all $B\in\mathcal{S}$ if and only if $(f\restriction_{E_n})^{-1}(B)\in\mathcal{F}\restriction_{E_n}$ for all $n\in\mathbb{N}$ and $B\in\mathcal{S}$. If $f$ is $\mathcal{F}/\mathcal{S}$-measurable and $B \in \mathcal{S}$, then
    \begin{align*}
        (f\restriction_{E_n})^{-1}(B)=f^{-1}(B)\cap E_n \in \mathcal{F}\restriction_{E_n},
    \end{align*}
    so each restriction is measurable.

    Conversely, suppose each $f\restriction_{E_n}$ is measurable and let $B \in \mathcal{S}$. For each $n$, there exists $A_n \in \mathcal{F}$ such that
    \begin{align*}
        (f\restriction_{E_n})^{-1}(B)=A_n \cap E_n.
    \end{align*}
    Hence
    \begin{align*}
        f^{-1}(B)
        = f^{-1}(B) \cap \Omega
        = \bigcup_{n \in \mathbb{N}} \left(f^{-1}(B) \cap E_n\right)
        = \bigcup_{n \in \mathbb{N}} (A_n \cap E_n) \in \mathcal{F},
    \end{align*}
    and therefore $f$ is measurable.

results.statement:
\label{prop:measurable-restrictions}
    Let $(\Omega,\mathcal{F})$ and $(S,\mathcal{S})$ be measurable spaces, let $f:\Omega \to S$ be a function, and let $(E_n)_{n \in \mathbb{N}} \subseteq \mathcal{F}$ satisfy $\bigcup_{n \in \mathbb{N}} E_n = \Omega$. Then $f$ is $\mathcal{F}/\mathcal{S}$-measurable if and only if each restriction
    \begin{align*}
        f\restriction_{E_n}: E_n \to S
    \end{align*}
    is $\mathcal{F}\restriction_{E_n}/\mathcal{S}$-measurable.

\label{prop:push-forward}\index{push-forward measure}\index{law}
    Let $(\Omega,\mathcal{F},\mu)$ be a measure space, let $(S,\mathcal{S})$ be a measurable space, and let $f:\Omega \to S$ be $\mathcal{F}/\mathcal{S}$-measurable. Then the map
    \begin{align*}
        \mu \circ f^{-1}: \mathcal{S} \to [0,\infty]
    \end{align*}
    is a measure on $(S,\mathcal{S})$. It is called the push-forward measure induced by $f$. If $\mu$ is a probability measure, then $\mu \circ f^{-1}$ is called the law or distribution of $f$.

\label{defn:simple-function}\index{simple measurable function}
    Let $(\Omega,\mathcal{F})$ and $(V,\mathcal{V})$ be measurable spaces, with $V$ also a vector space. A measurable function $s:\Omega \to V$ is called simple if
    \begin{align*}
        s(\omega) = \sum_{i=1}^n \mathbbm{1}_{E_i}(\omega) v_i
    \end{align*}
    for some $n \in \mathbb{N}$, some measurable sets $E_1,\dots,E_n \in \mathcal{F}$, and some vectors $v_1,\dots,v_n \in V$.

\label{defn:bochner-integral}
    Let $(\Omega,\mathcal{F},\mu)$ be a measure space and let $(V,\lVert\cdot\rVert)$ be a separable Banach space endowed with its Borel $\sigma$-algebra $\mathcal{B}(V)$. A simple $\mathcal{F}/\mathcal{B}(V)$-measurable function represented on a finite measurable partition $(E_i)_{i=1}^n$ by
    \begin{align*}
        s(\omega)=\sum_{i=1}^n \mathbbm{1}_{E_i}(\omega) v_i
    \end{align*}
    is called Bochner integrable if
    \begin{align*}
        \int_\Omega \lVert s(\omega)\rVert \,\mathrm{d}\mu(\omega)
        =
        \sum_{i=1}^n \lVert v_i\rVert \mu(E_i)
        < \infty.
    \end{align*}
    In that case, we define
    \begin{align*}
        \int_\Omega s(\omega) \,\mathrm{d}\mu(\omega)
        =
        \sum_{i=1}^n v_i \mu(E_i).
    \end{align*}
In the scalar norm sum we use $0\cdot\infty:=0$. In the vector sum we omit every term with $v_i=0$; the integrability condition ensures that $\mu(E_i)<\infty$ whenever $v_i\neq0$.
    Any finite simple-function representation may be refined to such a measurable partition, and the resulting value is independent of the chosen partition representation.

    A measurable function $f:\Omega \to V$ is called Bochner integrable if there exists a sequence of Bochner-integrable simple functions $(s_n)_{n \in \mathbb{N}}$ such that
    \begin{align*}
        \int_\Omega \lVert f(\omega)-s_n(\omega)\rVert \,\mathrm{d}\mu(\omega) \to 0.
    \end{align*}
    We then define
    \begin{align*}
        \int_\Omega f(\omega) \,\mathrm{d}\mu(\omega)
        =
        \lim_{n \to \infty} \int_\Omega s_n(\omega) \,\mathrm{d}\mu(\omega),
    \end{align*}
    where the limit is taken in $V$.

{hsing2015theoretical}}] \label{prop:bochner-integrability}
    Let $(\Omega,\mathcal{F},\mu)$ be a measure space and let $(V,\lVert\cdot\rVert)$ be a separable Banach space. If $f:\Omega \to V$ is measurable, then $f$ is Bochner integrable if and only if
    \begin{align*}
        \int_\Omega \lVert f(\omega)\rVert \,\mathrm{d}\mu(\omega) < \infty.
    \end{align*}

\label{defn:expected-value}\index{expected value}
    Let $(\Omega,\mathcal{F},\mathbb{P})$ be a probability space, let $(V,\lVert\cdot\rVert)$ be a separable Banach space, and let $X:\Omega \to V$ be Bochner integrable. Then the expected value of $X$ is defined by
    \begin{align*}
        \mathbb{E}[X] = \int_\Omega X(\omega) \,\mathrm{d}\mathbb{P}(\omega).
    \end{align*}

\label{defn:lp-spaces}
    Let $(\Omega,\mathcal{F},\mu)$ be a measure space and let $(V,\lVert\cdot\rVert)$ be a separable Banach space. For a measurable function $f:\Omega \to V$ and $1 \leq p < \infty$, define
    \begin{align*}
        \lVert f\rVert_{\mathcal{L}^p}
        =
        \left(
            \int_\Omega \lVert f(\omega)\rVert^p \,\mathrm{d}\mu(\omega)
        \right)^{1/p}.
    \end{align*}
    For $p=\infty$, define
    \begin{align*}
        \lVert f\rVert_{\mathcal{L}^\infty}
        =
        \operatorname*{ess\,sup}_{\omega \in \Omega} \lVert f(\omega)\rVert
        :=\inf\{c\in[0,\infty]\mid \lVert f\rVert\leq c\ \mu\text{-a.e.}\}.
    \end{align*}
    Define an equivalence relation on measurable $V$-valued functions by
    \begin{align*}
        f \sim g
        \quad \iff \quad
        f = g \ \mu\text{-a.e.},
    \end{align*}
    and, writing $\mathcal{L}^p(\Omega,\mu;V)=\{f:\Omega \to V \mid f\text{ is measurable and }\lVert f\rVert_{\mathcal{L}^p}<\infty\}$, define
    \begin{align*}
        L^p(\Omega,\mu;V)
        =
        \mathcal{L}^p(\Omega,\mu;V)\big/\sim
    \end{align*}
    for $1 \leq p \leq \infty$. When the $\sigma$-algebra must be displayed, for instance for a sub-$\sigma$-algebra $\mathcal{G}\subseteq\mathcal{F}$ with $\mu$ restricted to $\mathcal{G}$, we write $L^p(\Omega,\mathcal{G},\mu;V)$. Writing $[f]$ for the almost-everywhere equivalence class of $f$, we set
    \begin{align*}
        [f]+[g]:=[f+g],
        \qquad
        c[f]:=[cf],
        \qquad
        \lVert[f]\rVert_{L^p}:=\lVert f\rVert_{\mathcal{L}^p}.
    \end{align*}

\label{prop:lp-banach}
    Let $(\Omega,\mathcal{F},\mu)$ be a measure space and let $(V,\lVert\cdot\rVert)$ be a separable Banach space.
    \begin{enumerate}[(i)]
        \item For every $1 \leq p \leq \infty$, the space $L^p(\Omega,\mu;V)$ of almost-everywhere equivalence classes is a Banach space under the norm defined above, using the essential-supremum norm when $p=\infty$.
        \item If $(V,\langle \cdot,\cdot \rangle)$ is a real Hilbert space, then $L^2(\Omega,\mu;V)$ is a real Hilbert space under
        \begin{align*}
            \langle [f],[g] \rangle_{L^2}
            =
            \int_\Omega \langle f(\omega),g(\omega) \rangle \,\mathrm{d}\mu(\omega).
        \end{align*}
    \end{enumerate}

\label{prop:cadlag-caglad-l2}
    Let $(V,\lVert\cdot\rVert)$ be a separable real Banach space, let $a,b \in \mathbb{R}$ with $a<b$, and let $\lambda$ denote Lebesgue measure on $[a,b]$, with the c\`adl\`ag and c\`agl\`ad spaces $D^\pm([a,b];V)$ as defined in Appendix~\ref{chap:analysis}. Then:
    \begin{enumerate}[(i)]
        \item if $f \in C([a,b];V)$, then $[f] \in L^2([a,b],\lambda;V)$;
        \item if $f \in D^+([a,b];V)$, then $[f] \in L^2([a,b],\lambda;V)$;
        \item if $f \in D^-([a,b];V)$, then $[f] \in L^2([a,b],\lambda;V)$.
    \end{enumerate}

{fremlin2016broad}}] \label{defn:product-measure}
    Let $(S,\mathcal{S},\mu)$ and $(T,\mathcal{T},\nu)$ be $\sigma$-finite measure spaces. The product $\sigma$-algebra is $\mathcal{S}\otimes\mathcal{T}:=\sigma(\{A\times B\mid A\in\mathcal{S},\,B\in\mathcal{T}\})$, and the product measure $\mu\otimes\nu$ is the unique measure on $(S\times T,\mathcal{S}\otimes\mathcal{T})$ such that
    \begin{align*}
        (\mu \otimes \nu)(A \times B)=\mu(A)\nu(B)
    \end{align*}
    for all $A \in \mathcal{S}$ and $B \in \mathcal{T}$, with $0\cdot\infty:=0$.

{kallenberg2017random}}] \label{defn:markov-kernel}\index{Markov kernel}
    Let $(S,\mathcal{S})$ and $(T,\mathcal{T})$ be measurable spaces. A map
    \begin{align*}
        Q:S\times \mathcal{T} \to [0,1]
    \end{align*}
    is called a Markov kernel from $S$ to $T$ if
    \begin{enumerate}[(i)]
        \item for each $s \in S$, the map $B \mapsto Q(s,B)$ is a probability measure on $(T,\mathcal{T})$;
        \item for each $B \in \mathcal{T}$, the map $s \mapsto Q(s,B)$ is $\mathcal{S}/\mathcal{B}([0,1])$-measurable.
    \end{enumerate}

{kallenberg2017random}}] \label{thm:measure-disintegration}\index{standard Borel space}
    Let $(S,\mathcal{S})$ and $(T,\mathcal{T})$ be standard Borel spaces, with $T\neq\emptyset$ whenever $S\neq\emptyset$, and let $\Lambda$ be a finite measure on $(S\times T,\mathcal{S}\otimes\mathcal{T})$. Define the first marginal by
    \begin{align*}
        \Lambda_S(A)=\Lambda(A\times T), \qquad A \in \mathcal{S}.
    \end{align*}
    Then there exists a Markov kernel $Q$ from $S$ to $T$ such that
    \begin{align*}
        \Lambda(A\times B)
        =
        \int_A Q(s,B)\,\mathrm{d}\Lambda_S(s)
    \end{align*}
    for all $A \in \mathcal{S}$ and $B \in \mathcal{T}$. Moreover, $Q$ is unique $\Lambda_S$-almost everywhere.

{kallenberg2002foundations}}] \label{thm:regular-conditional-distribution}\index{regular conditional distribution}
    Let $(S,\mathcal{S})$ be a standard Borel space, let $(T,\mathcal{T})$ be a measurable space, and let $X:\Omega \to S$ and $Y:\Omega \to T$ be random elements. Then there exists a Markov kernel $Q$ from $T$ to $S$, called a regular conditional distribution of $X$ given $Y$, such that
    \begin{align*}
        \mathbb{P}(X \in A, Y \in B)
        =
        \int_B Q(y,A)\,\mathrm{d}(\mathbb{P}\circ Y^{-1})(y)
    \end{align*}
    for all $A \in \mathcal{S}$ and $B \in \mathcal{T}$, and $Q$ is unique $(\mathbb{P}\circ Y^{-1})$-almost everywhere. Moreover, writing $Q_y:=Q(y,\cdot)$, every bounded measurable $g:S \to \mathbb{R}$ satisfies
    \begin{align*}
        \mathbb{E}[g(X)\mid Y]
        =
        \int_S g\,\mathrm{d}Q_Y
        \qquad \text{a.s.}
    \end{align*}

\label{defn:finite-integer-valued-measures}
    Let $(X,d)$ be a complete and separable metric space, endowed with its Borel $\sigma$-algebra $\mathcal{B}(X)$. We write
    \begin{align*}
        \mathcal{M}(X)
        &=
        \{\mu:\mathcal{B}(X) \to {[0,\infty)} \mid \mu \text{ is a finite measure}\},\\
        \mathcal{N}(X)
        &=
        \{\mu\in \mathcal{M}(X) \mid \mu(B)\in\mathbb{N}_0 \text{ for every } B\in\mathcal{B}(X)\}.
    \end{align*}

\label{thm:prokhorov-metric}\index{Prokhorov metric}
    Let $(X,d)$ be a complete and separable extended metric space and let $\bar{d}=\min\{d,1\}$. Define $\rho:\mathcal{M}(X)\times\mathcal{M}(X)\to[0,\infty)$ by
    \begin{align*}
        \rho(\mu,\eta)
        =
        \inf\big\{
            \varepsilon > 0
            \,\big|\,
            \mu(B) \leq \eta(B^\varepsilon)+\varepsilon
            \text{ and }
            \eta(B) \leq \mu(B^\varepsilon)+\varepsilon
            \text{ for all } B \in \mathcal{B}(X)
        \big\},
    \end{align*}
    where
    \begin{align*}
        B^\varepsilon = \{x \in X \mid \exists b \in B: \bar{d}(x,b)<\varepsilon\}.
    \end{align*}
    Then $\rho$ is a metric on $\mathcal{M}(X)$, the space $(\mathcal{M}(X),\rho)$ is complete and separable, and $\rho$ metrises weak convergence on $\mathcal{M}(X)$.

\label{defn:kallenberg-random-measure}
    Let $(\Omega,\mathcal{F},\mathbb{P})$ be a probability space and let $(X,d)$ be a complete and separable metric space with Borel $\sigma$-algebra $\mathcal{B}(X)$. A map
    \begin{align*}
        \xi:\Omega \times \mathcal{B}(X) \to [0,\infty]
    \end{align*}
    is called a random measure if
    \begin{enumerate}[(i)]
        \item for each $B \in \mathcal{B}(X)$, the partial map $\omega \mapsto \xi(\omega,B)$ is measurable;
        \item for each $\omega \in \Omega$, the partial map $B \mapsto \xi(\omega,B)$ is a finite measure on $(X,\mathcal{B}(X))$.
    \end{enumerate}
    If in addition $B \mapsto \xi(\omega,B)$ is integer-valued for every $\omega$, then $\xi$ is called an integer-valued random measure, or (finite) point process, as in Chapter~\ref{chap:stochastic-markets}. Its values $\xi(\omega,\cdot)$ lie in $\mathcal{N}(X)$.

Let $(\Omega,\mathcal{F},\mathbb{P})$ and $(X,d)$ be as in Definition \ref{defn:kallenberg-random-measure}, and let $\xi:\Omega\times\mathcal{B}(X)\to[0,\infty]$ be such that $\xi(\omega,\cdot)$ is a finite Borel measure for every $\omega\in\Omega$. Endow $\mathcal{M}(X)$ with the Borel $\sigma$-algebra induced by the Prokhorov metric. Then the following are equivalent:
    \begin{enumerate}[(i)]
        \item the map $\xi:\Omega \times \mathcal{B}(X) \to [0,\infty]$ is a random measure in the sense of Definition \ref{defn:kallenberg-random-measure};
        \item the map $\Xi:\Omega \to \mathcal{M}(X)$ defined by
        \begin{align*}
            \Xi(\omega)=\xi(\omega,\cdot)
        \end{align*}
        is measurable.
    \end{enumerate}

\label{prop:mean-measure}\index{mean measure}
    Let $\xi$ be a finite random measure on $X$ and assume that
    \begin{align*}
        \mathbb{E}[\xi(X)]<\infty.
    \end{align*}
    Then
    \begin{align*}
        (\mathbb{E}\xi)(B)=\mathbb{E}[\xi(B)],
        \qquad B \in \mathcal{B}(X),
    \end{align*}
    defines a finite measure $\mathbb{E}\xi \in \mathcal{M}(X)$.

\label{defn:frechet-martingale}
    Following the time-discrete theory of \citet{sturm2002nonlinear}, let $(\Omega,\mathcal{F},(\mathcal{F}_n)_{n\in\mathbb{N}_0},\mathbb{P})$ be a filtered probability space and let $Z=(Z_n)_{n\in\mathbb{N}_0}$ be an adapted process with values in a complete separable metric space $(E,d)$. Fix $z_0\in E$, assume $\mathbb{E}[d(Z_n,z_0)^2]<\infty$ for every $n\in\mathbb{N}_0$, and let $\mathcal{L}^2(\mathcal{F}_n;E)$ denote the set of $\mathcal{F}_n$-measurable $E$-valued random elements $Y$ with $\mathbb{E}[d(Y,z_0)^2]<\infty$, modulo almost-sure equality. For every $Y\in\mathcal{L}^2(\mathcal{F}_n;E)$, the loss $d(Z_{n+1},Y)^2$ is measurable and integrable. We call $Z$ a \emph{Fr\'echet martingale} if
    \begin{align}\label{eq:frechet-martingale}
        Z_n \in \argmin_{Y\in\mathcal{L}^2(\mathcal{F}_n;E)} \mathbb{E}\!\left[d(Z_{n+1},Y)^2\right], \qquad n\in\mathbb{N}_0.
    \end{align}

$-Valued $L^2$ Constraint Set and Distribution Selection Map}]\label{defn:cdf-constraint-selection}
    Fix $a<b$ and let $\mathfrak{D}_{[a,b]}$ denote the set of distribution functions on $\mathbb{R}$ supported on $[a,b]$. We define the constraint set $\mathcal{C}\subseteq L^2([a,b])$ by
    \begin{align*}
        \mathcal{C}
        =
        \left\{
        [f]\in L^2([a,b])
        \ \middle|\
        \begin{aligned}
            &0\leq f\leq1\ \text{a.e. and}\\[-0.2em]
            &[f]\text{ admits a non-decreasing representative}
        \end{aligned}
        \right\}.
    \end{align*}
    For each $[f]\in\mathcal{C}$, let $f^{\mathrm{rc}}$ denote its unique non-decreasing right-continuous representative on $[a,b)$, and define the selection map $\mathsf{S}:\mathcal{C}\to\mathfrak{D}_{[a,b]}$, used only in this appendix, by
    \begin{align*}
        \mathsf{S}([f])(x)
        =
        \begin{cases}
            0, & x<a,\\
            f^{\mathrm{rc}}(x), & a\leq x<b,\\
            1, & x\geq b.
        \end{cases}
    \end{align*}

\label{prop:cdf-constraint-properties}
    Let $\mathcal{C}\subseteq L^2([a,b])$ and $\mathsf{S}:\mathcal{C}\to\mathfrak{D}_{[a,b]}$ be as in Definition~\ref{defn:cdf-constraint-selection}. Then:
    \begin{enumerate}[(i)]
        \item the set $\mathcal{C}$ is non-empty, closed, and convex in $L^2([a,b])$, and its metric projection $P_{\mathcal{C}}:L^2([a,b])\to\mathcal{C}$ exists, is unique, and is $1$-Lipschitz;
        \item the conditional expectation satisfies $\mathbb{E}[\chi_t\mid\mathcal{F}_s]=[G_s(\cdot,\cdot)|_{[a,b]}]\in\mathcal{C}$ almost surely;
        \item the map $\mathsf{S}$ is the inverse of the restriction map $F\mapsto[F|_{[a,b]}]$ from $\mathfrak{D}_{[a,b]}$ onto $\mathcal{C}$ and is an isometry from $(\mathcal{C},\lVert\cdot\rVert_{L^2([a,b])})$ onto $\mathfrak{D}_{[a,b]}$ equipped with the Cram\'er distance $(\int_{\mathbb{R}}(F-G)^2\,\mathrm{d}x)^{1/2}$.
    \end{enumerate}
